import json,sys
def fmt(s, ind=0):
    pad='  '*ind
    if not isinstance(s, dict): return pad+json.dumps(s)
    if '$ref' in s: return pad+'$ref '+s['$ref'].split('/')[-1]
    out=[]
    t=s.get('type')
    if 'oneOf' in s or 'anyOf' in s or 'allOf' in s:
        k=[k for k in ('oneOf','anyOf','allOf') if k in s][0]
        out.append(pad+k+':')
        for x in s[k]: out.append(fmt(x,ind+1))
        return '\n'.join(out)
    if t=='object' or 'properties' in s:
        req=set(s.get('required',[]))
        hdr=pad+'object'+(' addl=%s'%json.dumps(s['additionalProperties']) if 'additionalProperties' in s and not s['properties'] if 'properties' in s else 'additionalProperties' in s else '')
        out.append(hdr)
        for k,v in s.get('properties',{}).items():
            mark='*' if k in req else ''
            extra=''
            if isinstance(v,dict):
                e=[]
                for kk in ('enum','format','minimum','maximum','minLength','maxLength','default','minItems','nullable','exclusiveMinimum','description'):
                    if kk in v: e.append(f'{kk}={json.dumps(v[kk])}')
                extra=' '+' '.join(e) if e else ''
            if isinstance(v,dict) and (v.get('type') in ('object','array') or '$ref' in v or 'oneOf' in v or 'anyOf' in v or 'allOf' in v or 'properties' in v):
                if '$ref' in v: out.append(f'{pad}  {mark}{k}: $ref {v["$ref"].split("/")[-1]}{extra}')
                else:
                    out.append(f'{pad}  {mark}{k}:{extra}')
                    out.append(fmt(v,ind+2))
            else:
                out.append(f'{pad}  {mark}{k}: {v.get("type") if isinstance(v,dict) else v}{extra}')
        if 'additionalProperties' in s and s['additionalProperties'] is not False and not s.get('properties'):
            out.append(pad+'  (additionalProperties: '+json.dumps(s['additionalProperties'])+')')
        return '\n'.join(out)
    if t=='array':
        out.append(pad+'array of:')
        out.append(fmt(s.get('items',{}),ind+1))
        return '\n'.join(out)
    e=[]
    for kk in ('enum','format','minimum','maximum','default'):
        if kk in s: e.append(f'{kk}={json.dumps(s[kk])}')
    return pad+str(t)+(' '+' '.join(e) if e else '')
for f in sys.argv[1:]:
    o=json.load(open(f))
    print('='*20, o['operationId'], '='*20)
    if 'description' in o: print('DESC:', o['description'])
    if 'security' in o: print('security:', o['security'])
    if 'parameters' in o:
        for p in o['parameters']: print('PARAM', p.get('in'), p.get('name'), 'req=%s'%p.get('required'), json.dumps(p.get('schema')), p.get('description',''))
    rb=o.get('requestBody')
    if rb:
        for ct,c in rb['content'].items():
            print('REQUEST', ct, 'required=%s'%rb.get('required'))
            print(fmt(c['schema'],1))
    for code,r in o.get('responses',{}).items():
        print('RESP',code, r.get('description',''))
        for ct,c in r.get('content',{}).items():
            print(fmt(c['schema'],1))
EOF
