action.file_text:
// Package store persists application state in PostgreSQL.
//
// Every domain entity is stored as a JSONB document in a per-entity table
// keyed by its id. Append-only logs (audit, events) carry explicit bigint ids
// assigned by the application so the in-memory model and the database agree
// without a round trip.
package store

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// DocTables lists every document table the application owns.
var DocTables = []string{
	"users", "sessions", "locations", "connections", "sample_types", "samples",
	"journeys", "assignments", "handoffs", "reservations", "checkpoints",
	"disruptions", "idempotency_keys",
}

type Store struct {
	pool *pgxpool.Pool
}

func Open(ctx context.Context, url string) (*Store, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, err
	}
	cfg.MaxConns = 8
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, err
	}
	return &Store{pool: pool}, nil
}

func (s *Store) Close() { s.pool.Close() }

func (s *Store) Ping(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	return s.pool.Ping(ctx)
}

func schemaStatements() []string {
	var stmts []string
	stmts = append(stmts, `CREATE TABLE IF NOT EXISTS app_meta (key text PRIMARY KEY, value jsonb NOT NULL)`)
	for _, t := range DocTables {
		stmts = append(stmts, fmt.Sprintf(`CREATE TABLE IF NOT EXISTS %s (id text PRIMARY KEY, doc jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now())`, t))
		stmts = append(stmts, fmt.Sprintf(`CREATE INDEX IF NOT EXISTS %s_updated_at_idx ON %s (updated_at)`, t, t))
	}
	stmts = append(stmts,
		`CREATE UNIQUE INDEX IF NOT EXISTS users_username_idx ON users ((lower(doc->>'username')))`,
		`CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions ((doc->>'userId'))`,
		`CREATE INDEX IF NOT EXISTS samples_requester_idx ON samples ((doc->>'requesterId'))`,
		`CREATE INDEX IF NOT EXISTS samples_status_idx ON samples ((doc->>'status'))`,
		`CREATE INDEX IF NOT EXISTS journeys_status_idx ON journeys ((doc->>'status'))`,
		`CREATE INDEX IF NOT EXISTS assignments_journey_idx ON assignments ((doc->>'journeyId'))`,
		`CREATE INDEX IF NOT EXISTS assignments_worker_idx ON assignments ((doc->>'workerId'))`,
		`CREATE INDEX IF NOT EXISTS handoffs_sample_idx ON handoffs ((doc->>'sampleId'))`,
		`CREATE INDEX IF NOT EXISTS reservations_journey_idx ON reservations ((doc->>'journeyId'))`,
		`CREATE TABLE IF NOT EXISTS audit_log (
			id bigint PRIMARY KEY,
			actor_id text NOT NULL,
			role text NOT NULL,
			action text NOT NULL,
			entity_type text NOT NULL,
			entity_id text NOT NULL,
			success boolean NOT NULL,
			occurred_at timestamptz NOT NULL,
			doc jsonb NOT NULL)`,
		`CREATE INDEX IF NOT EXISTS audit_log_actor_idx ON audit_log (actor_id)`,
		`CREATE INDEX IF NOT EXISTS audit_log_entity_idx ON audit_log (entity_type, entity_id)`,
		`CREATE INDEX IF NOT EXISTS audit_log_action_idx ON audit_log (action)`,
		`CREATE INDEX IF NOT EXISTS audit_log_occurred_idx ON audit_log (occurred_at)`,
		`CREATE INDEX IF NOT EXISTS audit_log_doc_idx ON audit_log USING gin (doc)`,
		`CREATE TABLE IF NOT EXISTS events (
			id bigint PRIMARY KEY,
			type text NOT NULL,
			entity_type text NOT NULL,
			entity_id text NOT NULL,
			created_at timestamptz NOT NULL,
			audience_roles text[] NOT NULL DEFAULT '{}',
			audience_users text[] NOT NULL DEFAULT '{}',
			doc jsonb NOT NULL)`,
		`CREATE INDEX IF NOT EXISTS events_type_idx ON events (type)`,
		`CREATE INDEX IF NOT EXISTS events_created_idx ON events (created_at)`,
	)
	return stmts
}

// Migrate creates every table and index the application needs.
func (s *Store) Migrate(ctx context.Context) error {
	for _, stmt := range schemaStatements() {
		if _, err := s.pool.Exec(ctx, stmt); err != nil {
			return fmt.Errorf("migrate: %w (%s)", err, firstLine(stmt))
		}
	}
	return nil
}

// Reset drops all application-owned tables and recreates them.
func (s *Store) Reset(ctx context.Context) error {
	tables := append([]string{"app_meta", "audit_log", "events"}, DocTables...)
	if _, err := s.pool.Exec(ctx, `DROP TABLE IF EXISTS `+strings.Join(tables, ", ")+` CASCADE`); err != nil {
		return err
	}
	return s.Migrate(ctx)
}

func firstLine(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return s[:i]
	}
	return s
}

// LoadDocs returns the raw documents of a table.
func (s *Store) LoadDocs(ctx context.Context, table string) (map[string]json.RawMessage, error) {
	rows, err := s.pool.Query(ctx, fmt.Sprintf(`SELECT id, doc FROM %s`, table))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]json.RawMessage{}
	for rows.Next() {
		var id string
		var doc []byte
		if err := rows.Scan(&id, &doc); err != nil {
			return nil, err
		}
		out[id] = json.RawMessage(doc)
	}
	return out, rows.Err()
}

type AuditRow struct {
	ID  int64
	Doc json.RawMessage
}

func (s *Store) LoadAudit(ctx context.Context) ([]AuditRow, error) {
	rows, err := s.pool.Query(ctx, `SELECT id, doc FROM audit_log ORDER BY id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []AuditRow
	for rows.Next() {
		var r AuditRow
		var doc []byte
		if err := rows.Scan(&r.ID, &doc); err != nil {
			return nil, err
		}
		r.Doc = doc
		out = append(out, r)
	}
	return out, rows.Err()
}

type EventRow struct {
	ID            int64
	Doc           json.RawMessage
	AudienceRoles []string
	AudienceUsers []string
}

func (s *Store) LoadEvents(ctx context.Context) ([]EventRow, error) {
	rows, err := s.pool.Query(ctx, `SELECT id, doc, audience_roles, audience_users FROM events ORDER BY id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []EventRow
	for rows.Next() {
		var r EventRow
		var doc []byte
		if err := rows.Scan(&r.ID, &doc, &r.AudienceRoles, &r.AudienceUsers); err != nil {
			return nil, err
		}
		r.Doc = doc
		out = append(out, r)
	}
	return out, rows.Err()
}

func (s *Store) LoadMeta(ctx context.Context) (map[string]json.RawMessage, error) {
	rows, err := s.pool.Query(ctx, `SELECT key, value FROM app_meta`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]json.RawMessage{}
	for rows.Next() {
		var k string
		var v []byte
		if err := rows.Scan(&k, &v); err != nil {
			return nil, err
		}
		out[k] = v
	}
	return out, rows.Err()
}

// Batch is a set of writes committed atomically.
type Batch struct {
	Docs    []DocWrite
	Deletes []DocDelete
	Audits  []AuditWrite
	Events  []EventWrite
	Meta    map[string]any
}

type DocWrite struct {
	Table string
	ID    string
	Doc   any
}

type DocDelete struct {
	Table string
	ID    string
}

type AuditWrite struct {
	ID         int64
	ActorID    string
	Role       string
	Action     string
	EntityType string
	EntityID   string
	Success    bool
	OccurredAt time.Time
	Doc        any
}

type EventWrite struct {
	ID            int64
	Type          string
	EntityType    string
	EntityID      string
	CreatedAt     time.Time
	AudienceRoles []string
	AudienceUsers []string
	Doc           any
}

func (b *Batch) Empty() bool {
	return len(b.Docs) == 0 && len(b.Deletes) == 0 && len(b.Audits) == 0 && len(b.Events) == 0 && len(b.Meta) == 0
}

func (s *Store) Commit(ctx context.Context, b *Batch) error {
	if b.Empty() {
		return nil
	}
	tx, err := s.pool.BeginTx(ctx, pgx.TxOptions{})
	if err != nil {
		return err
	}
	defer tx.Rollback(ctx)
	for _, d := range b.Docs {
		raw, err := json.Marshal(d.Doc)
		if err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, fmt.Sprintf(`INSERT INTO %s (id, doc, updated_at) VALUES ($1, $2, now()) ON CONFLICT (id) DO UPDATE SET doc = EXCLUDED.doc, updated_at = now()`, d.Table), d.ID, raw); err != nil {
			return fmt.Errorf("save %s/%s: %w", d.Table, d.ID, err)
		}
	}
	for _, d := range b.Deletes {
		if _, err := tx.Exec(ctx, fmt.Sprintf(`DELETE FROM %s WHERE id = $1`, d.Table), d.ID); err != nil {
			return err
		}
	}
	for _, a := range b.Audits {
		raw, err := json.Marshal(a.Doc)
		if err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `INSERT INTO audit_log (id, actor_id, role, action, entity_type, entity_id, success, occurred_at, doc) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
			a.ID, a.ActorID, a.Role, a.Action, a.EntityType, a.EntityID, a.Success, a.OccurredAt, raw); err != nil {
			return fmt.Errorf("audit: %w", err)
		}
	}
	for _, e := range b.Events {
		raw, err := json.Marshal(e.Doc)
		if err != nil {
			return err
		}
		roles := e.AudienceRoles
		if roles == nil {
			roles = []string{}
		}
		users := e.AudienceUsers
		if users == nil {
			users = []string{}
		}
		if _, err := tx.Exec(ctx, `INSERT INTO events (id, type, entity_type, entity_id, created_at, audience_roles, audience_users, doc) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
			e.ID, e.Type, e.EntityType, e.EntityID, e.CreatedAt, roles, users, raw); err != nil {
			return fmt.Errorf("event: %w", err)
		}
	}
	for k, v := range b.Meta {
		raw, err := json.Marshal(v)
		if err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `INSERT INTO app_meta (key, value) VALUES ($1, $2) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value`, k, raw); err != nil {
			return err
		}
	}
	return tx.Commit(ctx)
}

