		}
	}
	for _, e := range b.Events {
		raw, err := json.Marshal(e.Doc)
		if err != nil {
			return err
		}
		roles := e.AudienceRoles
		if roles == nil {
			roles = []string{}
		}
		users := e.AudienceUsers
		if users == nil {
			users = []string{}
