// Package store persists application state in PostgreSQL.
//
// Every domain entity is stored as a JSONB document in a per-entity table
// keyed by its id. Append-only logs (audit, events) carry explicit bigint ids
// assigned by the application so the in-memory model and the database agree
// without a round trip.
package store

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// DocTables lists every document table the application owns.
var DocTables = []string{
	"users", "sessions", "locations", "connections", "sample_types", "samples",
	"journeys", "assignments", "handoffs", "reservations", "checkpoints",
	"disruptions", "idempotency_keys",
}

type Store struct {
	pool *pgxpool.Pool
}

func Open(ctx context.Context, url string) (*Store, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, err
	}
	cfg.MaxConns = 8
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, err
	}
	return &Store{pool: pool}, nil
}

func (s *Store) Close() { s.pool.Close() }

func (s *Store) Ping(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	return s.pool.Ping(ctx)
}

func schemaStatements() []string {
	var stmts []string
	stmts = append(stmts, `CREATE TABLE IF NOT EXISTS app_meta (key text PRIMARY KEY, value jsonb NOT NULL)`)
	for _, t := range DocTables {
		stmts = append(stmts, fmt.Sprintf(`CREATE TABLE IF NOT EXISTS %s (id text PRIMARY KEY, doc jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now())`, t))
		stmts = append(stmts, fmt.Sprintf(`CREATE INDEX IF NOT EXISTS %s_updated_at_idx ON %s (updated_at)`, t, t))
	}
	stmts = append(stmts,
		`CREATE UNIQUE INDEX IF NOT EXISTS users_username_idx ON users ((lower(doc->>'username')))`,
		`CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions ((doc->>'userId'))`,
		`CREATE INDEX IF NOT EXISTS samples_requester_idx ON samples ((doc->>'requesterId'))`,
		`CREATE INDEX IF NOT EXISTS samples_status_idx ON samples ((doc->>'status'))`,
		`CREATE INDEX IF NOT EXISTS journeys_status_idx ON journeys ((doc->>'status'))`,
		`CREATE INDEX IF NOT EXISTS assignments_journey_idx ON assignments ((doc->>'journeyId'))`,
		`CREATE INDEX IF NOT EXISTS assignments_worker_idx ON assignments ((doc->>'workerId'))`,
		`CREATE INDEX IF NOT EXISTS handoffs_sample_idx ON handoffs ((doc->>'sampleId'))`,
		`CREATE INDEX IF NOT EXISTS reservations_journey_idx ON reservations ((doc->>'journeyId'))`,
		`CREATE TABLE IF NOT EXISTS audit_log (
			id bigint PRIMARY KEY,
			actor_id text NOT NULL,
			role text NOT NULL,
			action text NOT NULL,
			entity_type text NOT NULL,
			entity_id text NOT NULL,
			success boolean NOT NULL,
			occurred_at timestamptz NOT NULL,
			doc jsonb NOT NULL)`,
		`CREATE INDEX IF NOT EXISTS audit_log_actor_idx ON audit_log (actor_id)`,
		`CREATE INDEX IF NOT EXISTS audit_log_entity_idx ON audit_log (entity_type, entity_id)`,
		`CREATE INDEX IF NOT EXISTS audit_log_action_idx ON audit_log (action)`,
		`CREATE INDEX IF NOT EXISTS audit_log_occurred_idx ON audit_log (occurred_at)`,
		`CREATE INDEX IF NOT EXISTS audit_log_doc_idx ON audit_log USING gin (doc)`,
		`CREATE TABLE IF NOT EXISTS events (
			id bigint PRIMARY KEY,
			type text NOT NULL,
			entity_type text NOT NULL,
			entity_id text NOT NULL,
			created_at timestamptz NOT NULL,
			audience_roles text[] NOT NULL DEFAULT '{}',
			audience_users text[] NOT NULL DEFAULT '{}',
			doc jsonb NOT NULL)`,
		`CREATE INDEX IF NOT EXISTS events_type_idx ON events (type)`,
		`CREATE INDEX IF NOT EXISTS events_created_idx ON events (created_at)`,
	)
	return stmts
}

// Migrate creates every table and index the application needs.
func (s *Store) Migrate(ctx context.Context) error {
	for _, stmt := range schemaStatements() {
		if _, err := s.pool.Exec(ctx, stmt); err != nil {
			return fmt.Errorf("migrate: %w (%s)", err, firstLine(stmt))
		}
	}
	return nil
}

// Reset drops all application-owned tables and recreates them.
func (s *Store) Reset(ctx context.Context) error {
	tables := append([]string{"app_meta", "audit_log", "events"}, DocTables...)
	if _, err := s.pool.Exec(ctx, `DROP TABLE IF EXISTS `+strings.Join(tables, ", ")+` CASCADE`); err != nil {
		return err
	}
	return s.Migrate(ctx)
}

func firstLine(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return s[:i]
	}
	return s
}

// LoadDocs returns the raw documents of a table.
func (s *Store) LoadDocs(ctx context.Context, table string) (map[string]json.RawMessage, error) {
	rows, err := s.pool.Query(ctx, fmt.Sprintf(`SELECT id, doc FROM %s`, table))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]json.RawMessage{}
	for rows.Next() {
		var id string
		var doc []byte
		if err := rows.Scan(&id, &doc); err != nil {
			return nil, err
		}
		out[id] = json.RawMessage(doc)
	}
	return out, rows.Err()
}

