	rows, err := s.pool.Query(ctx, `SELECT key, value FROM app_meta`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[string]json.RawMessage{}
	for rows.Next() {
		var k string
		var v []byte
		if err := rows.Scan(&k, &v); err != nil {
			return nil, err
		}
		out[k] = v
	}
	return out, rows.Err()
}

// Batch is a set of writes committed atomically.
type Batch struct {
	Docs    []DocWrite
	Deletes []DocDelete
	Audits  []AuditWrite
	Events  []EventWrite
	Meta    map[string]any
}

type DocWrite struct {
