package app

import (
	"context"
	"crypto/rand"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"labsample/internal/store"
)

type Config struct {
	Port                 string
	AdminUsername        string
	AdminPassword        string
	MapAssetsDir         string
	FrontendDir          string
	OfferTimeout         time.Duration
	NoWorkerTimeout      time.Duration
	StaleLocationAfter   time.Duration
	SessionTTL           time.Duration
	OriginSpeedKmH       float64
}

func ConfigFromEnv() Config {
	c := Config{
		Port:               envOr("PORT", "8080"),
		AdminUsername:      envOr("ADMIN_USERNAME", "admin"),
		AdminPassword:      envOr("ADMIN_PASSWORD", "admin"),
		MapAssetsDir:       envOr("MAP_ASSETS_DIR", ""),
		FrontendDir:        envOr("FRONTEND_DIR", "frontend/dist"),
		OfferTimeout:       time.Duration(envInt("OFFER_TIMEOUT_SECONDS", 300)) * time.Second,
		NoWorkerTimeout:    time.Duration(envInt("NO_WORKER_TIMEOUT_SECONDS", 45)) * time.Second,
		StaleLocationAfter: time.Duration(envInt("STALE_LOCATION_MINUTES", 15)) * time.Minute,
		SessionTTL:         time.Duration(envInt("SESSION_TTL_HOURS", 24*7)) * time.Hour,
		OriginSpeedKmH:     20,
	}
	return c
}

func envOr(k, d string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return d
}

func envInt(k string, d int) int {
	if v := os.Getenv(k); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			return n
		}
	}
	return d
}

// State is the complete in-memory model. It is guarded by App.mu.
type State struct {
	Users        map[string]*User
	Sessions     map[string]*Session
	Locations    map[string]*Location
	Connections  map[string]*Connection
	SampleTypes  map[string]*SampleType
	Samples      map[string]*Sample
	Journeys     map[string]*Journey
	Assignments  map[string]*Assignment
	Handoffs     map[string]*Handoff
	Reservations map[string]*Reservation
	Checkpoints  map[string]*Checkpoint
	Disruptions  map[string]*Disruption
	Idempotency  map[string]*IdempotencyRecord
	Audit        []*AuditRecord
	Events       []*Event
	NextAuditID  int64
	NextEventID  int64
	NetworkRevision int64
	ServiceabilityVersion int64
}

func newState() *State {
	return &State{
		Users: map[string]*User{}, Sessions: map[string]*Session{}, Locations: map[string]*Location{},
		Connections: map[string]*Connection{}, SampleTypes: map[string]*SampleType{}, Samples: map[string]*Sample{},
		Journeys: map[string]*Journey{}, Assignments: map[string]*Assignment{}, Handoffs: map[string]*Handoff{},
		Reservations: map[string]*Reservation{}, Checkpoints: map[string]*Checkpoint{}, Disruptions: map[string]*Disruption{},
		Idempotency: map[string]*IdempotencyRecord{}, NextAuditID: 1, NextEventID: 1,
	}
}

type App struct {
	cfg   Config
	store *store.Store
	mu    sync.Mutex
	st    *State
	ready atomic.Bool
	snapshot atomic.Pointer[Snapshot]
	hub   *Hub
	stopCh chan struct{}
}

func New(cfg Config, st *store.Store) *App {
	a := &App{cfg: cfg, store: st, st: newState(), hub: newHub(), stopCh: make(chan struct{})}
	return a
}

// Start loads durable state, provisions the first administrator and seeds
// default sample types.
func (a *App) Start(ctx context.Context) error {
	if err := a.store.Migrate(ctx); err != nil {
		return err
	}
	if err := a.reload(ctx); err != nil {
		return err
	}
	a.mu.Lock()
	u := a.newUoW(time.Now().UTC())
	a.bootstrapData(u)
	a.mu.Unlock()
	if err := a.commit(ctx, u); err != nil {
		return err
	}
	a.mu.Lock()
	a.publishSnapshot(time.Now().UTC())
	a.mu.Unlock()
	a.ready.Store(true)
	go a.backgroundLoop()
	return nil
}

func (a *App) Stop() {
	close(a.stopCh)
	a.ready.Store(false)
}

func (a *App) Ready(ctx context.Context) bool {
	if !a.ready.Load() {
		return false
	}
	return a.store.Ping(ctx) == nil
}

func (a *App) bootstrapData(u *UoW) {
	st := a.st
	if len(st.Users) == 0 {
		now := u.now
		admin := &User{
			UserID: newID(), Username: a.cfg.AdminUsername, PasswordHash: hashPassword(a.cfg.AdminPassword),
			FullName: "Initial Administrator", Roles: []string{RoleAdministrator}, Qualifications: []string{},
			Certifications: []Certification{}, Active: true, Available: true, CapacityUnits: defaultWorkerCapacity, CreatedAt: now,
		}
		st.Users[admin.UserID] = admin
		u.save("users", admin.UserID, admin)
		u.audit(systemActor, "system", "user.bootstrap_admin", "user", admin.UserID, true, map[string]any{"username": admin.Username})
		log.Printf("created initial administrator %q", admin.Username)
	}
	if len(st.SampleTypes) == 0 {
		defs := []SampleType{
			{Name: "Amber", QualifiedCollectorRequired: true, RequiredQualification: "amber", ContainerType: "standard_tube", TemperatureMinC: 15, TemperatureMaxC: 25, BatchingAllowed: true},
			{Name: "Indigo", QualifiedCollectorRequired: true, RequiredQualification: "indigo", ContainerType: "indigo_vial", TemperatureMinC: 15, TemperatureMaxC: 25, BatchingAllowed: true},
			{Name: "Frost", QualifiedCollectorRequired: true, RequiredQualification: "frost", ContainerType: "cooled_box", TemperatureMinC: 2, TemperatureMaxC: 8, RequiresCooledRoute: true, BatchingAllowed: true},
			{Name: "Pulse", QualifiedCollectorRequired: true, RequiredQualification: "pulse", ContainerType: "pulse_tube", TemperatureMinC: 15, TemperatureMaxC: 25, BatchingAllowed: false},
		}
		created := map[string]*SampleType{}
		for i := range defs {
			t := defs[i]
			t.SampleTypeID = newID()
			t.IncompatibleSampleTypes = []string{}
			t.CreatedAt = u.now
			st.SampleTypes[t.SampleTypeID] = &t
			created[t.Name] = &t
		}
		created["Indigo"].IncompatibleSampleTypes = []string{created["Amber"].SampleTypeID}
		created["Amber"].IncompatibleSampleTypes = []string{created["Indigo"].SampleTypeID}
		for _, t := range created {
			u.save("sample_types", t.SampleTypeID, t)
			u.audit(systemActor, "system", "sample_type.created", "sample_type", t.SampleTypeID, true, map[string]any{"name": t.Name, "default": true})
			u.event("sample_type.created", "sample_type", t.SampleTypeID, sampleTypeView(t), nil, nil)
		}
	}
}

const systemActor = "system"
const defaultWorkerCapacity = 5
const defaultLocationCapacity = 100
const defaultConnectionCapacity = 100

// reload replaces the in-memory state with the durable state.
func (a *App) reload(ctx context.Context) error {
	st := newState()
	load := func(table string, fn func(id string, raw json.RawMessage) error) error {
		docs, err := a.store.LoadDocs(ctx, table)
		if err != nil {
			return fmt.Errorf("load %s: %w", table, err)
		}
		for id, raw := range docs {
			if err := fn(id, raw); err != nil {
				return fmt.Errorf("decode %s/%s: %w", table, id, err)
			}
		}
		return nil
	}
	steps := []struct {
		table string
		fn    func(id string, raw json.RawMessage) error
	}{
		{"users", func(id string, raw json.RawMessage) error { v := &User{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Users[id] = v; return nil }},
		{"sessions", func(id string, raw json.RawMessage) error { v := &Session{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Sessions[id] = v; return nil }},
		{"locations", func(id string, raw json.RawMessage) error { v := &Location{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Locations[id] = v; return nil }},
		{"connections", func(id string, raw json.RawMessage) error { v := &Connection{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Connections[id] = v; return nil }},
		{"sample_types", func(id string, raw json.RawMessage) error { v := &SampleType{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.SampleTypes[id] = v; return nil }},
		{"samples", func(id string, raw json.RawMessage) error { v := &Sample{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Samples[id] = v; return nil }},
		{"journeys", func(id string, raw json.RawMessage) error { v := &Journey{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Journeys[id] = v; return nil }},
		{"assignments", func(id string, raw json.RawMessage) error { v := &Assignment{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Assignments[id] = v; return nil }},
		{"handoffs", func(id string, raw json.RawMessage) error { v := &Handoff{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Handoffs[id] = v; return nil }},
		{"reservations", func(id string, raw json.RawMessage) error { v := &Reservation{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Reservations[id] = v; return nil }},
		{"checkpoints", func(id string, raw json.RawMessage) error { v := &Checkpoint{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Checkpoints[id] = v; return nil }},
		{"disruptions", func(id string, raw json.RawMessage) error { v := &Disruption{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Disruptions[id] = v; return nil }},
		{"idempotency_keys", func(id string, raw json.RawMessage) error { v := &IdempotencyRecord{}; if err := json.Unmarshal(raw, v); err != nil { return err }; st.Idempotency[id] = v; return nil }},
	}
	for _, s := range steps {
		if err := load(s.table, s.fn); err != nil {
			return err
		}
	}
	audits, err := a.store.LoadAudit(ctx)
	if err != nil {
		return err
	}
	for _, r := range audits {
		v := &AuditRecord{}
		if err := json.Unmarshal(r.Doc, v); err != nil {
			return err
		}
		v.ID = r.ID
		st.Audit = append(st.Audit, v)
		if r.ID >= st.NextAuditID {
			st.NextAuditID = r.ID + 1
		}
	}
	events, err := a.store.LoadEvents(ctx)
	if err != nil {
		return err
	}
	for _, r := range events {
		v := &Event{}
