// UoW collects the writes produced while handling one request.
type UoW struct {
	app     *App
	now     time.Time
	batch   store.Batch
	docs    map[string]struct{}
	newEvents []*Event
	auditRecs []*AuditRecord
	networkChanged bool
	offersChanged  bool
}

func (a *App) newUoW(now time.Time) *UoW {
	return &UoW{app: a, now: now, docs: map[string]struct{}{}, batch: store.Batch{Meta: map[string]any{}}}
}

func (u *UoW) save(table, id string, doc any) {
	key := table + "/" + id
	if _, ok := u.docs[key]; ok {
		// replace earlier write of the same document
		for i := range u.batch.Docs {
			if u.batch.Docs[i].Table == table && u.batch.Docs[i].ID == id {
				u.batch.Docs[i].Doc = doc
				return
			}
		}
	}
	u.docs[key] = struct{}{}
	u.batch.Docs = append(u.batch.Docs, store.DocWrite{Table: table, ID: id, Doc: doc})
}

func (u *UoW) del(table, id string) {
	u.batch.Deletes = append(u.batch.Deletes, store.DocDelete{Table: table, ID: id})
}

func (u *UoW) saveUser(x *User)             { u.save("users", x.UserID, x) }
func (u *UoW) saveSession(x *Session)       { u.save("sessions", x.Token, x) }
func (u *UoW) saveLocation(x *Location)     { u.save("locations", x.LocationID, x); u.networkChanged = true }
func (u *UoW) saveConnection(x *Connection) { u.save("connections", x.ConnectionID, x); u.networkChanged = true }
func (u *UoW) saveSampleType(x *SampleType) { u.save("sample_types", x.SampleTypeID, x); u.networkChanged = true }
func (u *UoW) saveSample(x *Sample)         { x.UpdatedAt = u.now; u.save("samples", x.SampleID, x) }
func (u *UoW) saveJourney(x *Journey)       { x.UpdatedAt = u.now; u.save("journeys", x.JourneyID, x) }
func (u *UoW) saveAssignment(x *Assignment) { x.UpdatedAt = u.now; u.save("assignments", x.AssignmentID, x) }
func (u *UoW) saveHandoff(x *Handoff)       { u.save("handoffs", x.HandoffID, x) }
func (u *UoW) saveReservation(x *Reservation) { u.save("reservations", x.ReservationID, x) }
func (u *UoW) saveCheckpoint(x *Checkpoint) { u.save("checkpoints", x.CheckpointID, x) }
func (u *UoW) saveDisruption(x *Disruption) { u.save("disruptions", x.DisruptionID, x) }

// audit appends an audit record (visible immediately in memory).
func (u *UoW) audit(actorID, role, action, entityType, entityID string, success bool, details map[string]any) *AuditRecord {
	st := u.app.st
	if details == nil {
		details = map[string]any{}
	}
	rec := &AuditRecord{
		ID: st.NextAuditID, ActorID: actorID, Role: role, Action: action, EntityType: entityType, EntityID: entityID,
		Success: success, OccurredAt: u.now, Details: details,
	}
	st.NextAuditID++
	if v, ok := details["sampleId"].(string); ok && v != "" {
		rec.SampleIDs = append(rec.SampleIDs, v)
	}
	if v, ok := details["sampleIds"].([]string); ok {
		for _, s := range v {
			if !contains(rec.SampleIDs, s) {
				rec.SampleIDs = append(rec.SampleIDs, s)
			}
		}
	}
	if entityType == "sample" && !contains(rec.SampleIDs, entityID) {
		rec.SampleIDs = append(rec.SampleIDs, entityID)
	}
	if v, ok := details["journeyId"].(string); ok {
		rec.JourneyID = v
	} else if entityType == "journey" {
		rec.JourneyID = entityID
	}
	if v, ok := details["assignmentId"].(string); ok {
		rec.AssignmentID = v
	} else if entityType == "assignment" {
		rec.AssignmentID = entityID
	}
	st.Audit = append(st.Audit, rec)
	u.auditRecs = append(u.auditRecs, rec)
	u.batch.Audits = append(u.batch.Audits, store.AuditWrite{
		ID: rec.ID, ActorID: actorID, Role: role, Action: action, EntityType: entityType, EntityID: entityID,
		Success: success, OccurredAt: u.now, Doc: rec,
	})
	return rec
}

// event appends a realtime event. Empty audiences mean broadcast.
func (u *UoW) event(typ, entityType, entityID string, payload map[string]any, roles, users []string) *Event {
	st := u.app.st
	if payload == nil {
		payload = map[string]any{}
	}
	ev := &Event{ID: st.NextEventID, Type: typ, EntityType: entityType, EntityID: entityID, Payload: payload, CreatedAt: u.now, AudienceRoles: roles, AudienceUsers: users}
	st.NextEventID++
	st.Events = append(st.Events, ev)
	u.newEvents = append(u.newEvents, ev)
	u.batch.Events = append(u.batch.Events, store.EventWrite{
		ID: ev.ID, Type: typ, EntityType: entityType, EntityID: entityID, CreatedAt: u.now,
		AudienceRoles: roles, AudienceUsers: users, Doc: ev,
	})
	return ev
}

func (u *UoW) meta(key string, value any) { u.batch.Meta[key] = value }

// commit persists the unit of work. On failure, the in-memory state is
// discarded and reloaded from the database so both stay consistent.
func (a *App) commit(ctx context.Context, u *UoW) error {
	if u.networkChanged {
		a.mu.Lock()
		a.st.NetworkRevision++
		u.meta("networkRevision", a.st.NetworkRevision)
		a.mu.Unlock()
	}
	if err := a.store.Commit(ctx, &u.batch); err != nil {
		log.Printf("commit failed, reloading state: %v", err)
		if rerr := a.reload(context.Background()); rerr != nil {
			log.Printf("reload failed: %v", rerr)
		}
		return err
	}
	if u.networkChanged {
		a.mu.Lock()
		a.publishSnapshot(u.now)
		a.mu.Unlock()
	}
	for _, ev := range u.newEvents {
		a.hub.broadcast(ev)
	}
	return nil
}

func newID() string {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic(err)
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func newToken() string {
	var b [32]byte
	if _, err := rand.Read(b[:]); err != nil {
		panic(err)
	}
	return fmt.Sprintf("%x", b[:])
}

func contains(list []string, v string) bool {
	for _, x := range list {
		if x == v {
			return true
		}
	}
	return false
}

func sortedKeys[T any](m map[string]T) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func lower(s string) string { return strings.ToLower(strings.TrimSpace(s)) }

// backgroundLoop handles offer expiry, unstaffed assignments and other
// time-driven transitions.
func (a *App) backgroundLoop() {
	t := time.NewTicker(3 * time.Second)
	defer t.Stop()
	for {
		select {
		case <-a.stopCh:
			return
		case <-t.C:
			a.tick()
		}
	}
}

func (a *App) tick() {
	now := time.Now().UTC()
	a.mu.Lock()
	u := a.newUoW(now)
	a.expireOffers(u)
	a.flagUnstaffedAssignments(u)
	a.mu.Unlock()
	if !u.batch.Empty() {
		if err := a.commit(context.Background(), u); err != nil {
			log.Printf("background commit: %v", err)
		}
	}
}

