package app

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

type apiErr struct {
	status int
	code   string
	msg    string
}

func (e *apiErr) Error() string { return e.code + ": " + e.msg }

func E(status int, code, msg string) *apiErr { return &apiErr{status: status, code: code, msg: msg} }

func errInvalidJSON(msg string) *apiErr { return E(400, "invalid_json", msg) }
func errNotFound(msg string) *apiErr    { return E(404, "not_found", msg) }
func errForbidden(msg string) *apiErr   { return E(403, "forbidden", msg) }
func errConflict(code, msg string) *apiErr { return E(409, code, msg) }

// Ctx carries the per-request context for a handler.
type Ctx struct {
	a    *App
	u    *UoW
	now  time.Time
	user *User
	sess *Session
	role string
	op   string
	r    *http.Request
}

func (c *Ctx) st() *State { return c.a.st }

// roles returns the roles to evaluate permissions against: the selected role,
// or every held role when none is selected and the operation allows it.
func (c *Ctx) roles() []string {
	if c.role != "" {
		return []string{c.role}
	}
	if c.user != nil {
		return c.user.Roles
	}
	return nil
}

func (c *Ctx) hasRole(roles ...string) bool {
	for _, r := range c.roles() {
		for _, want := range roles {
			if r == want {
				return true
			}
		}
	}
	return false
}

func (c *Ctx) isSupervisor() bool { return c.hasRole(RoleAdministrator, RoleDispatcher) }

func (c *Ctx) actorID() string {
	if c.user != nil {
		return c.user.UserID
	}
	return "anonymous"
}

func (c *Ctx) audit(action, entityType, entityID string, success bool, details map[string]any) *AuditRecord {
	role := c.role
	if role == "" {
		role = "unselected"
	}
	return c.u.audit(c.actorID(), role, action, entityType, entityID, success, details)
}

type handlerFn func(c *Ctx, body []byte) (int, any, *apiErr)

type opSpec struct {
	op          string
	method      string
	path        string
	public      bool
	allowNoRole bool
	idempotent  bool // idempotencyKey required
	optionalIdem bool
	roles       []string
	fn          handlerFn
}

func (a *App) Handler() http.Handler {
	mux := http.NewServeMux()
	for _, spec := range a.operations() {
		spec := spec
		mux.HandleFunc(spec.path, a.wrap(spec))
	}
	mux.HandleFunc("/api/events", a.handleEvents)
	mux.HandleFunc("/ready", a.handleReady)
	mux.HandleFunc("/api/", func(w http.ResponseWriter, r *http.Request) {
		writeErr(w, errNotFound("unknown api route"))
	})
	a.registerStatic(mux)
	return mux
}

func (a *App) handleReady(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
	defer cancel()
	w.Header().Set("Content-Type", "application/json")
	if a.Ready(ctx) {
		w.WriteHeader(200)
		_, _ = w.Write([]byte(`{"status":"ready"}`))
		return
	}
	w.WriteHeader(503)
	_, _ = w.Write([]byte(`{"status":"starting"}`))
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(v)
}

func writeErr(w http.ResponseWriter, e *apiErr) {
	writeJSON(w, e.status, map[string]any{"error": e.msg, "code": e.code})
}

func (a *App) authenticate(r *http.Request) (*Session, *User, *apiErr) {
	h := r.Header.Get("Authorization")
	token := ""
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		token = strings.TrimSpace(h[7:])
	}
	if token == "" {
		return nil, nil, E(401, "unauthorized", "missing bearer token")
	}
	return a.sessionByToken(token)
}

// sessionByToken must be called with a.mu held.
func (a *App) sessionByToken(token string) (*Session, *User, *apiErr) {
	sess := a.st.Sessions[token]
	if sess == nil || time.Now().After(sess.ExpiresAt) {
		return nil, nil, E(401, "unauthorized", "invalid or expired session")
	}
	user := a.st.Users[sess.UserID]
	if user == nil || !user.Active {
		return nil, nil, E(401, "unauthorized", "account inactive")
	}
	return sess, user, nil
}

func (a *App) wrap(spec opSpec) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if r.Method != spec.method {
			writeErr(w, E(405, "method_not_allowed", "method not allowed"))
			return
		}
		var body []byte
		if spec.method == http.MethodPost {
			b, err := io.ReadAll(io.LimitReader(r.Body, 4<<20))
			if err != nil {
				writeErr(w, errInvalidJSON("unable to read body"))
				return
			}
			body = bytes.TrimSpace(b)
			if len(body) == 0 {
				body = []byte("{}")
			}
			var probe map[string]json.RawMessage
			if err := json.Unmarshal(body, &probe); err != nil {
				writeErr(w, errInvalidJSON("request body must be a JSON object"))
				return
			}
		}
		now := time.Now().UTC()
		a.mu.Lock()
		defer a.mu.Unlock()
		c := &Ctx{a: a, now: now, op: spec.op, r: r}
		c.u = a.newUoW(now)
		if !spec.public {
			sess, user, e := a.authenticate(r)
			if e != nil {
				c.u.audit("anonymous", "none", spec.op, "session", "", false, map[string]any{"code": e.code, "reason": e.msg})
				a.finish(w, c, e.status, nil, e)
				return
			}
			c.sess, c.user, c.role = sess, user, sess.ActiveRole
			if c.role != "" && !contains(user.Roles, c.role) {
				c.role = ""
			}
			if !spec.allowNoRole && c.role == "" {
				e := errConflict("role_not_selected", "select an active role before performing this action")
				c.audit(spec.op, "session", sess.Token[:8], false, map[string]any{"code": e.code})
				a.finish(w, c, e.status, nil, e)
				return
			}
			if spec.roles != nil && !c.hasRole(spec.roles...) {
				e := errForbidden("the selected role may not perform this action")
				c.audit("permission.denied", "operation", spec.op, false, map[string]any{"code": e.code, "requiredRoles": spec.roles, "role": c.role})
				a.finish(w, c, e.status, nil, e)
				return
			}
		}
		var idemKey string
		if spec.idempotent || spec.optionalIdem {
			var probe struct {
				IdempotencyKey *string `json:"idempotencyKey"`
			}
			_ = json.Unmarshal(body, &probe)
			if probe.IdempotencyKey != nil {
				idemKey = strings.TrimSpace(*probe.IdempotencyKey)
			}
			if spec.idempotent && idemKey == "" {
				e := E(400, "idempotency_required", "idempotencyKey is required")
				a.finish(w, c, e.status, nil, e)
				return
			}
			if idemKey != "" {
				recKey := c.actorID() + "|" + spec.op + "|" + idemKey
				hash := hashBody(body)
				if rec := a.st.Idempotency[recKey]; rec != nil {
					if rec.Hash != hash {
						e := errConflict("idempotency_conflict", "idempotencyKey was already used with a different payload")
						a.finish(w, c, e.status, nil, e)
						return
					}
					w.Header().Set("Idempotent-Replayed", "true")
					w.Header().Set("Content-Type", "application/json")
					w.WriteHeader(rec.Status)
					_, _ = w.Write(rec.Body)
					return
				}
				defer func() {}()
				status, data, e := spec.fn(c, body)
				if e == nil {
					payload, _ := json.Marshal(map[string]any{"data": data})
					rec := &IdempotencyRecord{Key: recKey, Hash: hash, Status: status, Body: payload, CreatedAt: now}
					a.st.Idempotency[recKey] = rec
					c.u.save("idempotency_keys", recKey, rec)
				}
				a.finish(w, c, status, data, e)
				return
			}
		}
		status, data, e := spec.fn(c, body)
		a.finish(w, c, status, data, e)
	}
}

// finish records failures, commits the unit of work and writes the response.
func (a *App) finish(w http.ResponseWriter, c *Ctx, status int, data any, e *apiErr) {
	if e != nil && c.user != nil && e.status != 401 {
		c.audit(c.op+".rejected", "operation", c.op, false, map[string]any{"code": e.code, "reason": e.msg})
	}
	if err := a.commit(context.Background(), c.u); err != nil {
		writeErr(w, E(500, "internal_error", "failed to persist changes"))
		return
	}
	if e != nil {
		writeErr(w, e)
		return
	}
	writeJSON(w, status, map[string]any{"data": data})
}

func hashBody(b []byte) string {
	var m map[string]any
	if err := json.Unmarshal(b, &m); err == nil {
		delete(m, "idempotencyKey")
		if nb, err := json.Marshal(m); err == nil {
			b = nb
		}
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// decode unmarshals a request body; type mismatches become invalid_json.
func decode(body []byte, v any) *apiErr {
	dec := json.NewDecoder(bytes.NewReader(body))
	if err := dec.Decode(v); err != nil {
		var ute *json.UnmarshalTypeError
		if errors.As(err, &ute) {
			return errInvalidJSON("field " + ute.Field + " has the wrong type")
