			}
			c.sess, c.user, c.role = sess, user, sess.ActiveRole
			if c.role != "" && !contains(user.Roles, c.role) {
				c.role = ""
			}
			if !spec.allowNoRole && c.role == "" {
				e := errConflict("role_not_selected", "select an active role before performing this action")
				c.audit(spec.op, "session", sess.Token[:8], false, map[string]any{"code": e.code})
				a.finish(w, c, e.status, nil, e)
				return
			}
			if spec.roles != nil && !c.hasRole(spec.roles...) {
				e := errForbidden("the selected role may not perform this action")
				c.audit("permission.denied", "operation", spec.op, false, map[string]any{"code": e.code, "requiredRoles": spec.roles, "role": c.role})
				a.finish(w, c, e.status, nil, e)
				return
			}
		}
		var idemKey string
		if spec.idempotent || spec.optionalIdem {
			var probe struct {
				IdempotencyKey *string `json:"idempotencyKey"`
			}
			_ = json.Unmarshal(body, &probe)
			if probe.IdempotencyKey != nil {
				idemKey = strings.TrimSpace(*probe.IdempotencyKey)
			}
			if spec.idempotent && idemKey == "" {
				e := E(400, "idempotency_required", "idempotencyKey is required")
				a.finish(w, c, e.status, nil, e)
				return
			}
			if idemKey != "" {
				recKey := c.actorID() + "|" + spec.op + "|" + idemKey
				hash := hashBody(body)
				if rec := a.st.Idempotency[recKey]; rec != nil {
					if rec.Hash != hash {
						e := errConflict("idempotency_conflict", "idempotencyKey was already used with a different payload")
						a.finish(w, c, e.status, nil, e)
						return
					}
					w.Header().Set("Idempotent-Replayed", "true")
					w.Header().Set("Content-Type", "application/json")
					w.WriteHeader(rec.Status)
					_, _ = w.Write(rec.Body)
					return
				}
				defer func() {}()
				status, data, e := spec.fn(c, body)
				if e == nil {
					payload, _ := json.Marshal(map[string]any{"data": data})
					rec := &IdempotencyRecord{Key: recKey, Hash: hash, Status: status, Body: payload, CreatedAt: now}
					a.st.Idempotency[recKey] = rec
					c.u.save("idempotency_keys", recKey, rec)
				}
				a.finish(w, c, status, data, e)
				return
			}
		}
		status, data, e := spec.fn(c, body)
		a.finish(w, c, status, data, e)
	}
}

// finish records failures, commits the unit of work and writes the response.
func (a *App) finish(w http.ResponseWriter, c *Ctx, status int, data any, e *apiErr) {
	if e != nil && c.user != nil && e.status != 401 {
		c.audit(c.op+".rejected", "operation", c.op, false, map[string]any{"code": e.code, "reason": e.msg})
	}
	if err := a.commit(context.Background(), c.u); err != nil {
		writeErr(w, E(500, "internal_error", "failed to persist changes"))
		return
	}
	if e != nil {
		writeErr(w, e)
		return
	}
	writeJSON(w, status, map[string]any{"data": data})
}

func hashBody(b []byte) string {
	var m map[string]any
	if err := json.Unmarshal(b, &m); err == nil {
		delete(m, "idempotencyKey")
		if nb, err := json.Marshal(m); err == nil {
			b = nb
		}
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// decode unmarshals a request body; type mismatches become invalid_json.
func decode(body []byte, v any) *apiErr {
	dec := json.NewDecoder(bytes.NewReader(body))
	if err := dec.Decode(v); err != nil {
		var ute *json.UnmarshalTypeError
		if errors.As(err, &ute) {
			return errInvalidJSON("field " + ute.Field + " has the wrong type")
		}
		return errInvalidJSON("malformed request body")
	}
	return nil
}

func parseTime(s string) (time.Time, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return time.Time{}, false
	}
	for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05Z0700", "2006-01-02T15:04:05"} {
		if t, err := time.Parse(layout, s); err == nil {
			return t.UTC(), true
		}
	}
	return time.Time{}, false
}

func requiredTime(s *string, name string) (time.Time, *apiErr) {
	if s == nil || strings.TrimSpace(*s) == "" {
		return time.Time{}, errInvalidJSON(name + " is required")
	}
	t, ok := parseTime(*s)
	if !ok {
		return time.Time{}, E(400, "invalid_time", name+" is not a valid RFC 3339 timestamp")
	}
	return t, nil
}

func optionalTime(s *string, name string) (*time.Time, *apiErr) {
	if s == nil || strings.TrimSpace(*s) == "" {
		return nil, nil
	}
	t, ok := parseTime(*s)
	if !ok {
		return nil, E(400, "invalid_time", name+" is not a valid RFC 3339 timestamp")
	}
	return &t, nil
}

func fmtTime(t time.Time) string { return t.UTC().Format(time.RFC3339Nano) }

func fmtTimePtr(t *time.Time) any {
	if t == nil {
		return nil
	}
	return fmtTime(*t)
}

// registerStatic serves the built frontend and the local map assets.
func (a *App) registerStatic(mux *http.ServeMux) {
	mapDir := a.cfg.MapAssetsDir
	if mapDir == "" {
		for _, cand := range []string{"map-assets", "/opt/arena/map-assets"} {
			if st, err := os.Stat(filepath.Join(cand, "bangalore.pmtiles")); err == nil && !st.IsDir() {
				mapDir = cand
				break
			}
		}
	}
	if mapDir != "" {
		fs := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapDir)))
		mux.Handle("/map-assets/", corsCache(fs))
		log.Printf("serving map assets from %s", mapDir)
	} else {
		log.Printf("warning: map assets directory not found")
	}
	dist := a.cfg.FrontendDir
	index := filepath.Join(dist, "index.html")
	fileServer := http.FileServer(http.Dir(dist))
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			writeErr(w, E(405, "method_not_allowed", "method not allowed"))
			return
		}
		p := filepath.Clean(r.URL.Path)
		full := filepath.Join(dist, p)
		if st, err := os.Stat(full); err == nil && !st.IsDir() {
			if strings.HasPrefix(p, "/assets/") {
				w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
			}
			fileServer.ServeHTTP(w, r)
			return
		}
		if _, err := os.Stat(index); err != nil {
			http.Error(w, "frontend not built", 404)
			return
		}
		w.Header().Set("Cache-Control", "no-cache")
		http.ServeFile(w, r, index)
	})
}

func corsCache(h http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "public, max-age=86400")
		w.Header().Set("Access-Control-Allow-Origin", "*")
		h.ServeHTTP(w, r)
	})
}

