		return 0, nil, errNotFound("user not found")
	}
	if user.UserID != c.user.UserID && !c.isSupervisor() {
		return 0, nil, errForbidden("only administrators and dispatchers may read other users")
	}
	return 200, userView(user), nil
}

func (a *App) hUpdateUserAccess(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		UserID             *string  `json:"userId"`
		Roles              []string `json:"roles"`
		Qualifications     []string `json:"qualifications"`
		Certifications     []certIn `json:"certifications"`
		Active             *bool    `json:"active"`
		AssignedLocationID *string  `json:"assignedLocationId"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.UserID == nil || req.Active == nil || req.Roles == nil {
		return 0, nil, errInvalidJSON("userId, roles and active are required")
	}
	user := a.st.Users[*req.UserID]
	if user == nil {
		return 0, nil, errNotFound("user not found")
	}
	roles, ok := parseRoles(req.Roles)
	if !ok {
		return 0, nil, errInvalidJSON("roles contains an unknown role")
	}
	certs, e := parseCerts(req.Certifications)
	if e != nil {
		return 0, nil, e
	}
	if req.AssignedLocationID != nil && *req.AssignedLocationID != "" && a.st.Locations[*req.AssignedLocationID] == nil {
		return 0, nil, errNotFound("assignedLocationId does not reference a known location")
	}
	before := map[string]any{"roles": strs(user.Roles), "qualifications": strs(user.Qualifications), "active": user.Active, "assignedLocationId": user.AssignedLocationID}
	user.Roles = roles
	if req.Qualifications != nil {
		user.Qualifications = req.Qualifications
	}
	if req.Certifications != nil {
		user.Certifications = certs
	}
	user.Active = *req.Active
	if req.AssignedLocationID != nil {
		user.AssignedLocationID = *req.AssignedLocationID
	}
	c.u.saveUser(user)
	// sessions whose selected role was removed fall back to unselected
	for _, s := range a.st.Sessions {
		if s.UserID == user.UserID && s.ActiveRole != "" && !contains(user.Roles, s.ActiveRole) {
			s.ActiveRole = defaultActiveRole(user)
			c.u.saveSession(s)
		}
	}
	c.audit("user.access_updated", "user", user.UserID, true, map[string]any{"before": before, "after": map[string]any{"roles": roles, "qualifications": strs(user.Qualifications), "active": user.Active, "assignedLocationId": user.AssignedLocationID}})
	c.u.event("user.updated", "user", user.UserID, userView(user), []string{RoleAdministrator, RoleDispatcher}, nil)
	if !user.Active {
		a.workerBecameUnavailable(c.u, user, "user_deactivated", c)
	} else {
		a.recheckWorkerAssignments(c.u, user, c)
	}
	a.retryPendingOffers(c.u)
	return 201, map[string]any{
		"userId":         user.UserID,
		"roles":          strs(user.Roles),
		"qualifications": strs(user.Qualifications),
		"certifications": certsView(user.Certifications),
		"active":         user.Active,
	}, nil
}

func (a *App) hSetWorkerAvailability(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		WorkerID      *string `json:"workerId"`
		Available     *bool   `json:"available"`
		CapacityUnits *int    `json:"capacityUnits"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.WorkerID == nil || req.Available == nil || req.CapacityUnits == nil {
		return 0, nil, errInvalidJSON("workerId, available and capacityUnits are required")
	}
	if *req.CapacityUnits < 0 {
		return 0, nil, E(400, "invalid_capacity", "capacityUnits must be zero or more")
	}
	worker := a.st.Users[*req.WorkerID]
	if worker == nil {
		return 0, nil, errNotFound("worker not found")
	}
	if worker.UserID != c.user.UserID && !c.isSupervisor() {
		return 0, nil, errForbidden("only the worker, a dispatcher or an administrator may change availability")
	}
	active := a.workerActiveAssignmentCount(worker.UserID)
	if *req.Available && *req.CapacityUnits < active {
		return 0, nil, errConflict("capacity_reserved", "capacity cannot be lowered below the worker's active assignments")
	}
	before := map[string]any{"available": worker.Available, "capacityUnits": worker.CapacityUnits}
	worker.Available = *req.Available
	worker.CapacityUnits = *req.CapacityUnits
	c.u.saveUser(worker)
	c.audit("worker.availability_set", "user", worker.UserID, true, map[string]any{"before": before, "after": map[string]any{"available": worker.Available, "capacityUnits": worker.CapacityUnits}})
	c.u.event("worker.updated", "worker", worker.UserID, map[string]any{"workerId": worker.UserID, "available": worker.Available, "capacityUnits": worker.CapacityUnits}, []string{RoleAdministrator, RoleDispatcher}, []string{worker.UserID})
	if !worker.Available {
		a.workerBecameUnavailable(c.u, worker, "worker_unavailable", c)
	}
	a.retryPendingOffers(c.u)
	return 200, map[string]any{"workerId": worker.UserID, "available": worker.Available, "capacityUnits": worker.CapacityUnits}, nil
}

