}

func (a *App) hCheckServiceability(c *Ctx, body []byte) (int, any, *apiErr) {
	var req requestIn
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	spec, e := a.parseRequestSpec(&req, false, c)
	if e != nil {
		return 0, nil, e
	}
	snap := a.snapshot.Load()
	res := a.evaluateServiceability(snap, spec, nil)
	c.audit("serviceability.checked", "serviceability", spec.sampleTypeID, true, map[string]any{
		"dryRun": true, "serviceable": res.Serviceable, "reason": res.Reason, "origin": coordView(spec.origin), "originType": spec.originType,
	})
