func (a *App) hCreateConnection(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		FromLocationID *string  `json:"fromLocationId"`
		ToLocationID   *string  `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.FromLocationID == nil || req.ToLocationID == nil || req.TravelMinutes == nil || req.CostUnits == nil || req.Active == nil {
		return 0, nil, errInvalidJSON("fromLocationId, toLocationId, travelMinutes, costUnits and active are required")
	}
	if *req.FromLocationID == *req.ToLocationID {
		return 0, nil, E(400, "invalid_connection", "a connection must join two different locations")
	}
	if a.st.Locations[*req.FromLocationID] == nil || a.st.Locations[*req.ToLocationID] == nil {
		return 0, nil, E(400, "invalid_connection", "both locations must exist")
	}
	if *req.TravelMinutes < 1 || *req.CostUnits < 0 || math.IsNaN(*req.CostUnits) {
		return 0, nil, E(400, "invalid_connection", "travelMinutes must be at least 1 and costUnits non-negative")
	}
	cooled := req.Cooled != nil && *req.Cooled
	conn := &Connection{
		ConnectionID: newID(), FromLocationID: *req.FromLocationID, ToLocationID: *req.ToLocationID, TravelMinutes: *req.TravelMinutes,
		CostUnits: *req.CostUnits, Cooled: cooled, Active: *req.Active, CapacityUnits: defaultConnectionCapacity, CreatedAt: c.now,
	}
	if cooled {
		conn.CooledCapacityUnits = defaultConnectionCapacity
	}
	a.st.Connections[conn.ConnectionID] = conn
	c.u.saveConnection(conn)
	c.audit("connection.created", "connection", conn.ConnectionID, true, map[string]any{"connection": connectionView(conn)})
	c.u.event("connection.created", "connection", conn.ConnectionID, connectionView(conn), nil, nil)
