	TemperatureMaxC            *float64 `json:"temperatureMaxC"`
	IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
	RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
	BatchingAllowed            *bool    `json:"batchingAllowed"`
}

func (a *App) validateHandling(req *sampleTypeIn, self string) *apiErr {
	if req.ContainerType == nil || strings.TrimSpace(*req.ContainerType) == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		return errInvalidJSON("containerType, temperatureMinC and temperatureMaxC are required")
	}
	if *req.TemperatureMinC > *req.TemperatureMaxC || math.IsNaN(*req.TemperatureMinC) || math.IsNaN(*req.TemperatureMaxC) {
		return E(400, "invalid_handling_rule", "temperatureMinC must not exceed temperatureMaxC")
	}
	for _, id := range req.IncompatibleSampleTypes {
		if id == self {
			return E(400, "invalid_handling_rule", "a sample type cannot be incompatible with itself")
		}
		if a.st.SampleTypes[id] == nil {
			return E(400, "invalid_handling_rule", "incompatibleSampleTypes references an unknown sample type")
		}
	}
	return nil
}

