package app

import (
	"math"
	"strings"
)

type coordIn struct {
	Latitude  *float64 `json:"latitude"`
	Longitude *float64 `json:"longitude"`
}

func parseCoord(c *coordIn) (Coordinate, bool) {
	if c == nil || c.Latitude == nil || c.Longitude == nil {
		return Coordinate{}, false
	}
	if math.IsNaN(*c.Latitude) || math.IsNaN(*c.Longitude) || *c.Latitude < -90 || *c.Latitude > 90 || *c.Longitude < -180 || *c.Longitude > 180 {
		return Coordinate{}, false
	}
	return Coordinate{Latitude: *c.Latitude, Longitude: *c.Longitude}, true
}

func coordView(c Coordinate) map[string]any {
	return map[string]any{"latitude": c.Latitude, "longitude": c.Longitude}
}

func functionsView(f map[string]bool) map[string]any {
	out := map[string]any{}
	for _, fn := range AllFunctions {
		out[fn] = f[fn]
	}
	return out
}

func locationView(l *Location) map[string]any {
	return map[string]any{
		"locationId":      l.LocationID,
		"name":            l.Name,
		"coordinate":      coordView(l.Coordinate),
		"coverageKm":      l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes,
		"active":          l.Active,
		"functions":       functionsView(l.Functions),
	}
}

func connectionView(c *Connection) map[string]any {
	return map[string]any{
		"connectionId":   c.ConnectionID,
		"fromLocationId": c.FromLocationID,
		"toLocationId":   c.ToLocationID,
		"travelMinutes":  c.TravelMinutes,
		"costUnits":      c.CostUnits,
		"cooled":         c.Cooled,
		"active":         c.Active,
	}
}

func sampleTypeView(t *SampleType) map[string]any {
	return map[string]any{
		"sampleTypeId":               t.SampleTypeID,
		"name":                       t.Name,
		"qualifiedCollectorRequired": t.QualifiedCollectorRequired,
		"requiredQualification":      t.RequiredQualification,
		"containerType":              t.ContainerType,
		"temperatureMinC":            t.TemperatureMinC,
		"temperatureMaxC":            t.TemperatureMaxC,
		"incompatibleSampleTypes":    strs(t.IncompatibleSampleTypes),
		"requiresCooledRoute":        t.RequiresCooledRoute,
		"batchingAllowed":            t.BatchingAllowed,
	}
}

func (a *App) hCreateLocation(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		Name            *string  `json:"name"`
		Coordinate      *coordIn `json:"coordinate"`
		CoverageKm      *float64 `json:"coverageKm"`
		HandlingMinutes *int     `json:"handlingMinutes"`
		Active          *bool    `json:"active"`
		Functions       []string `json:"functions"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.Name == nil || strings.TrimSpace(*req.Name) == "" || req.Active == nil {
		return 0, nil, errInvalidJSON("name and active are required")
	}
	coord, ok := parseCoord(req.Coordinate)
	if !ok {
		return 0, nil, E(400, "invalid_coordinate", "coordinate must contain a valid latitude and longitude")
	}
	coverage := 5.0
	if req.CoverageKm != nil {
		coverage = *req.CoverageKm
	}
	if coverage <= 0 || coverage > 5 || math.IsNaN(coverage) {
		return 0, nil, E(400, "invalid_node_coverage", "coverageKm must be greater than 0 and at most 5")
	}
	handling := 0
	if req.HandlingMinutes != nil {
		handling = *req.HandlingMinutes
	}
	if handling < 0 || handling > 1440 {
		return 0, nil, E(400, "invalid_handling_time", "handlingMinutes must be between 0 and 1440")
	}
	fns, ok := parseFunctions(req.Functions)
	if !ok {
		return 0, nil, E(400, "invalid_location_function", "functions must contain at least one known location function")
	}
	loc := &Location{
		LocationID: newID(), Name: strings.TrimSpace(*req.Name), Coordinate: coord, CoverageKm: coverage, HandlingMinutes: handling,
		Active: *req.Active, Functions: fns, CapacityUnits: defaultLocationCapacity, CooledCapacityUnits: defaultLocationCapacity,
		Acceptances: map[string]string{}, AcceptedTypes: map[string]bool{}, CreatedAt: c.now,
	}
	a.st.Locations[loc.LocationID] = loc
	c.u.saveLocation(loc)
	c.audit("location.created", "location", loc.LocationID, true, map[string]any{"location": locationView(loc)})
	c.u.event("location.created", "location", loc.LocationID, locationView(loc), nil, nil)
	return 201, locationView(loc), nil
}

func parseFunctions(in []string) (map[string]bool, bool) {
	if len(in) == 0 {
		return nil, false
	}
	out := map[string]bool{}
	for _, fn := range AllFunctions {
		out[fn] = false
	}
	for _, f := range in {
		if !contains(AllFunctions, f) {
			return nil, false
		}
		out[f] = true
	}
	return out, true
}

func (a *App) hUpdateLocation(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		LocationID      *string  `json:"locationId"`
		Name            *string  `json:"name"`
		Coordinate      *coordIn `json:"coordinate"`
		CoverageKm      *float64 `json:"coverageKm"`
		HandlingMinutes *int     `json:"handlingMinutes"`
		Functions       []string `json:"functions"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.LocationID == nil || req.Name == nil || strings.TrimSpace(*req.Name) == "" {
		return 0, nil, errInvalidJSON("locationId and name are required")
	}
	loc := a.st.Locations[*req.LocationID]
	if loc == nil {
		return 0, nil, errNotFound("location not found")
	}
	coord, ok := parseCoord(req.Coordinate)
	if !ok {
		return 0, nil, E(400, "invalid_coordinate", "coordinate must contain a valid latitude and longitude")
	}
	if req.CoverageKm != nil && (*req.CoverageKm <= 0 || *req.CoverageKm > 5) {
		return 0, nil, E(400, "invalid_node_coverage", "coverageKm must be greater than 0 and at most 5")
	}
	if req.HandlingMinutes != nil && (*req.HandlingMinutes < 0 || *req.HandlingMinutes > 1440) {
		return 0, nil, E(400, "invalid_handling_time", "handlingMinutes must be between 0 and 1440")
	}
	var fns map[string]bool
	if req.Functions != nil {
		fns, ok = parseFunctions(req.Functions)
		if !ok {
			return 0, nil, E(400, "invalid_location_function", "functions must contain at least one known location function")
		}
	}
	before := locationView(loc)
	loc.Name = strings.TrimSpace(*req.Name)
	loc.Coordinate = coord
	if req.CoverageKm != nil {
		loc.CoverageKm = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		loc.HandlingMinutes = *req.HandlingMinutes
	}
	if fns != nil {
		loc.Functions = fns
	}
	c.u.saveLocation(loc)
	c.audit("location.updated", "location", loc.LocationID, true, map[string]any{"before": before, "after": locationView(loc)})
	c.u.event("location.updated", "location", loc.LocationID, locationView(loc), nil, nil)
	a.replanAfterNetworkChange(c, "location", loc.LocationID, "location_updated")
	return 201, locationView(loc), nil
}

func (a *App) hSetLocationStatus(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		LocationID *string `json:"locationId"`
		Active     *bool   `json:"active"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.LocationID == nil || req.Active == nil {
		return 0, nil, errInvalidJSON("locationId and active are required")
	}
	loc := a.st.Locations[*req.LocationID]
	if loc == nil {
		return 0, nil, errNotFound("location not found")
	}
	before := loc.Active
	loc.Active = *req.Active
	c.u.saveLocation(loc)
	c.audit("location.status_set", "location", loc.LocationID, true, map[string]any{"before": before, "after": loc.Active})
	c.u.event("location.updated", "location", loc.LocationID, locationView(loc), nil, nil)
	if !loc.Active {
		a.replanAfterNetworkChange(c, "location", loc.LocationID, "location_deactivated")
	}
	return 200, map[string]any{"locationId": loc.LocationID, "active": loc.Active}, nil
}

func (a *App) hSetLocationFunctionStatus(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		LocationID *string `json:"locationId"`
		Function   *string `json:"function"`
		Active     *bool   `json:"active"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.LocationID == nil || req.Active == nil || req.Function == nil {
		return 0, nil, errInvalidJSON("locationId, function and active are required")
	}
	if !contains(AllFunctions, *req.Function) {
		return 0, nil, E(400, "invalid_location_function", "unknown location function")
	}
	loc := a.st.Locations[*req.LocationID]
	if loc == nil {
		return 0, nil, errNotFound("location not found")
	}
	before := loc.Functions[*req.Function]
	loc.Functions[*req.Function] = *req.Active
	c.u.saveLocation(loc)
	c.audit("location.function_status_set", "location", loc.LocationID, true, map[string]any{"function": *req.Function, "before": before, "after": *req.Active})
	c.u.event("location.updated", "location", loc.LocationID, locationView(loc), nil, nil)
	if !*req.Active {
		a.replanAfterNetworkChange(c, "location", loc.LocationID, "location_function_deactivated")
	}
	return 200, map[string]any{"locationId": loc.LocationID, "function": *req.Function, "active": *req.Active, "functions": functionsView(loc.Functions)}, nil
}

func (a *App) hCreateConnection(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		FromLocationID *string  `json:"fromLocationId"`
		ToLocationID   *string  `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.FromLocationID == nil || req.ToLocationID == nil || req.TravelMinutes == nil || req.CostUnits == nil || req.Active == nil {
		return 0, nil, errInvalidJSON("fromLocationId, toLocationId, travelMinutes, costUnits and active are required")
	}
	if *req.FromLocationID == *req.ToLocationID {
		return 0, nil, E(400, "invalid_connection", "a connection must join two different locations")
	}
	if a.st.Locations[*req.FromLocationID] == nil || a.st.Locations[*req.ToLocationID] == nil {
		return 0, nil, E(400, "invalid_connection", "both locations must exist")
	}
	if *req.TravelMinutes < 1 || *req.CostUnits < 0 || math.IsNaN(*req.CostUnits) {
		return 0, nil, E(400, "invalid_connection", "travelMinutes must be at least 1 and costUnits non-negative")
	}
	cooled := req.Cooled != nil && *req.Cooled
	conn := &Connection{
		ConnectionID: newID(), FromLocationID: *req.FromLocationID, ToLocationID: *req.ToLocationID, TravelMinutes: *req.TravelMinutes,
		CostUnits: *req.CostUnits, Cooled: cooled, Active: *req.Active, CapacityUnits: defaultConnectionCapacity, CreatedAt: c.now,
	}
	if cooled {
		conn.CooledCapacityUnits = defaultConnectionCapacity
	}
	a.st.Connections[conn.ConnectionID] = conn
	c.u.saveConnection(conn)
	c.audit("connection.created", "connection", conn.ConnectionID, true, map[string]any{"connection": connectionView(conn)})
	c.u.event("connection.created", "connection", conn.ConnectionID, connectionView(conn), nil, nil)
	return 201, connectionView(conn), nil
}

func (a *App) hSetConnectionStatus(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		ConnectionID *string `json:"connectionId"`
		Active       *bool   `json:"active"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.ConnectionID == nil || req.Active == nil {
		return 0, nil, errInvalidJSON("connectionId and active are required")
	}
	conn := a.st.Connections[*req.ConnectionID]
	if conn == nil {
		return 0, nil, errNotFound("connection not found")
	}
	before := conn.Active
	conn.Active = *req.Active
	c.u.saveConnection(conn)
	c.audit("connection.status_set", "connection", conn.ConnectionID, true, map[string]any{"before": before, "after": conn.Active})
	c.u.event("connection.updated", "connection", conn.ConnectionID, connectionView(conn), nil, nil)
	if !conn.Active {
		a.replanAfterNetworkChange(c, "connection", conn.ConnectionID, "connection_deactivated")
	}
	return 200, map[string]any{"connectionId": conn.ConnectionID, "active": conn.Active}, nil
}

func (a *App) hConfigureCapacity(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		ResourceID          *string `json:"resourceId"`
		CapacityUnits       *int    `json:"capacityUnits"`
		CooledCapacityUnits *int    `json:"cooledCapacityUnits"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.ResourceID == nil || req.CapacityUnits == nil {
		return 0, nil, errInvalidJSON("resourceId and capacityUnits are required")
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	if *req.CapacityUnits < 0 || cooled < 0 {
		return 0, nil, E(400, "invalid_capacity", "capacity units must be zero or more")
	}
	loc := a.st.Locations[*req.ResourceID]
	conn := a.st.Connections[*req.ResourceID]
	if loc == nil && conn == nil {
		return 0, nil, E(400, "invalid_capacity", "resourceId does not reference a location or connection")
	}
	if !c.isSupervisor() {
		if loc == nil || c.user.AssignedLocationID != loc.LocationID || !c.hasRole(RoleNodeHandler, RoleLaboratory) {
			return 0, nil, errForbidden("capacity may only be configured for the node or laboratory you are assigned to")
		}
	}
	reserved, cooledReserved := a.reservedUnits(*req.ResourceID)
	if *req.CapacityUnits < reserved || cooled < cooledReserved {
		return 0, nil, errConflict("capacity_reserved", "capacity cannot be lowered below the units currently reserved")
	}
	var before map[string]any
	if loc != nil {
		before = map[string]any{"capacityUnits": loc.CapacityUnits, "cooledCapacityUnits": loc.CooledCapacityUnits}
		loc.CapacityUnits = *req.CapacityUnits
		loc.CooledCapacityUnits = cooled
		c.u.saveLocation(loc)
	} else {
		before = map[string]any{"capacityUnits": conn.CapacityUnits, "cooledCapacityUnits": conn.CooledCapacityUnits}
		conn.CapacityUnits = *req.CapacityUnits
		conn.CooledCapacityUnits = cooled
		c.u.saveConnection(conn)
	}
	c.audit("capacity.configured", "capacity", *req.ResourceID, true, map[string]any{"before": before, "after": map[string]any{"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled}})
	c.u.event("capacity.updated", "capacity", *req.ResourceID, map[string]any{"resourceId": *req.ResourceID, "capacity": a.capacityView(*req.ResourceID)}, nil, nil)
	return 200, map[string]any{"resourceId": *req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled}, nil
}

func (a *App) hConfigureLaboratoryAcceptance(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		LaboratoryID *string `json:"laboratoryId"`
		SampleTypeID *string `json:"sampleTypeId"`
		Accepts      *bool   `json:"accepts"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.LaboratoryID == nil || req.SampleTypeID == nil || req.Accepts == nil {
		return 0, nil, errInvalidJSON("laboratoryId, sampleTypeId and accepts are required")
	}
	lab := a.st.Locations[*req.LaboratoryID]
	if lab == nil {
		return 0, nil, E(400, "invalid_acceptance", "laboratoryId does not reference a known location")
	}
	if !lab.Functions[FnLaboratory] {
		return 0, nil, E(400, "invalid_acceptance", "location does not provide the laboratory function")
	}
	if a.st.SampleTypes[*req.SampleTypeID] == nil {
		return 0, nil, E(400, "invalid_acceptance", "sampleTypeId does not reference a known sample type")
	}
	if lab.Acceptances == nil {
		lab.Acceptances = map[string]string{}
	}
	if lab.AcceptedTypes == nil {
		lab.AcceptedTypes = map[string]bool{}
	}
	accID := lab.Acceptances[*req.SampleTypeID]
	if accID == "" {
		accID = newID()
		lab.Acceptances[*req.SampleTypeID] = accID
	}
	lab.AcceptedTypes[*req.SampleTypeID] = *req.Accepts
	c.u.saveLocation(lab)
	c.audit("laboratory.acceptance_configured", "location", lab.LocationID, true, map[string]any{"sampleTypeId": *req.SampleTypeID, "accepts": *req.Accepts, "acceptanceId": accID})
	c.u.event("location.updated", "location", lab.LocationID, locationView(lab), nil, nil)
	if !*req.Accepts {
		a.replanAfterNetworkChange(c, "laboratory", lab.LocationID, "laboratory_acceptance_removed")
	}
	return 200, map[string]any{"acceptanceId": accID, "accepts": *req.Accepts}, nil
}

type sampleTypeIn struct {
	SampleTypeID               *string  `json:"sampleTypeId"`
	Name                       *string  `json:"name"`
	QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
	RequiredQualification      *string  `json:"requiredQualification"`
	ContainerType              *string  `json:"containerType"`
	TemperatureMinC            *float64 `json:"temperatureMinC"`
	TemperatureMaxC            *float64 `json:"temperatureMaxC"`
	IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
	RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
	BatchingAllowed            *bool    `json:"batchingAllowed"`
}

func (a *App) validateHandling(req *sampleTypeIn, self string) *apiErr {
	if req.ContainerType == nil || strings.TrimSpace(*req.ContainerType) == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		return errInvalidJSON("containerType, temperatureMinC and temperatureMaxC are required")
	}
	if *req.TemperatureMinC > *req.TemperatureMaxC || math.IsNaN(*req.TemperatureMinC) || math.IsNaN(*req.TemperatureMaxC) {
		return E(400, "invalid_handling_rule", "temperatureMinC must not exceed temperatureMaxC")
	}
	for _, id := range req.IncompatibleSampleTypes {
		if id == self {
			return E(400, "invalid_handling_rule", "a sample type cannot be incompatible with itself")
		}
		if a.st.SampleTypes[id] == nil {
			return E(400, "invalid_handling_rule", "incompatibleSampleTypes references an unknown sample type")
		}
	}
	return nil
}

func (a *App) hCreateSampleType(c *Ctx, body []byte) (int, any, *apiErr) {
	var req sampleTypeIn
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.Name == nil || strings.TrimSpace(*req.Name) == "" {
		return 0, nil, errInvalidJSON("name is required")
	}
	if e := a.validateHandling(&req, ""); e != nil {
		return 0, nil, e
	}
	t := &SampleType{
		SampleTypeID: newID(), Name: strings.TrimSpace(*req.Name), ContainerType: strings.TrimSpace(*req.ContainerType),
		TemperatureMinC: *req.TemperatureMinC, TemperatureMaxC: *req.TemperatureMaxC, IncompatibleSampleTypes: strs(req.IncompatibleSampleTypes),
		BatchingAllowed: true, CreatedAt: c.now,
	}
	if req.QualifiedCollectorRequired != nil {
		t.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
	}
	if req.RequiredQualification != nil {
		t.RequiredQualification = strings.TrimSpace(*req.RequiredQualification)
	}
	if t.RequiredQualification != "" && req.QualifiedCollectorRequired == nil {
		t.QualifiedCollectorRequired = true
	}
	if req.RequiresCooledRoute != nil {
		t.RequiresCooledRoute = *req.RequiresCooledRoute
	}
	if req.BatchingAllowed != nil {
		t.BatchingAllowed = *req.BatchingAllowed
	}
	a.st.SampleTypes[t.SampleTypeID] = t
	c.u.saveSampleType(t)
	c.audit("sample_type.created", "sample_type", t.SampleTypeID, true, map[string]any{"sampleType": sampleTypeView(t)})
	c.u.event("sample_type.created", "sample_type", t.SampleTypeID, sampleTypeView(t), nil, nil)
	return 201, sampleTypeView(t), nil
}

func (a *App) hUpdateSampleType(c *Ctx, body []byte) (int, any, *apiErr) {
	var req sampleTypeIn
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.SampleTypeID == nil {
		return 0, nil, errInvalidJSON("sampleTypeId is required")
	}
	t := a.st.SampleTypes[*req.SampleTypeID]
	if t == nil {
		return 0, nil, errNotFound("sample type not found")
	}
	if e := a.validateHandling(&req, t.SampleTypeID); e != nil {
		return 0, nil, e
	}
	before := sampleTypeView(t)
	t.ContainerType = strings.TrimSpace(*req.ContainerType)
	t.TemperatureMinC = *req.TemperatureMinC
	t.TemperatureMaxC = *req.TemperatureMaxC
	if req.IncompatibleSampleTypes != nil {
		t.IncompatibleSampleTypes = req.IncompatibleSampleTypes
	}
	if req.QualifiedCollectorRequired != nil {
		t.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
	}
	if req.RequiredQualification != nil {
		t.RequiredQualification = strings.TrimSpace(*req.RequiredQualification)
	}
	if req.RequiresCooledRoute != nil {
		t.RequiresCooledRoute = *req.RequiresCooledRoute
	}
	if req.BatchingAllowed != nil {
		t.BatchingAllowed = *req.BatchingAllowed
	}
	c.u.saveSampleType(t)
	c.audit("sample_type.updated", "sample_type", t.SampleTypeID, true, map[string]any{"before": before, "after": sampleTypeView(t)})
	c.u.event("sample_type.updated", "sample_type", t.SampleTypeID, sampleTypeView(t), nil, nil)
	return 201, sampleTypeView(t), nil
}

func (a *App) hReadServiceabilitySnapshot(c *Ctx, body []byte) (int, any, *apiErr) {
	snap := a.snapshot.Load()
	return 200, snap.view(), nil
}

func (a *App) hCheckServiceability(c *Ctx, body []byte) (int, any, *apiErr) {
	var req requestIn
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	spec, e := a.parseRequestSpec(&req, false, c)
	if e != nil {
		return 0, nil, e
	}
	snap := a.snapshot.Load()
	res := a.evaluateServiceability(snap, spec, nil)
	c.audit("serviceability.checked", "serviceability", spec.sampleTypeID, true, map[string]any{
		"dryRun": true, "serviceable": res.Serviceable, "reason": res.Reason, "origin": coordView(spec.origin), "originType": spec.originType,
	})
	out := map[string]any{"serviceable": res.Serviceable, "reason": res.Reason, "serviceabilityVersion": snap.Version}
	if res.Serviceable {
		out["targetLaboratoryId"] = res.Route.LabID
		out["estimatedArrivalAt"] = fmtTime(res.ETA)
	}
	return 200, out, nil
}

