package app

import (
	"container/heap"
	"math"
	"sort"
	"time"
)

// Snapshot is one complete, immutable serviceability-calculation version.
// Requests are always evaluated against a fully computed snapshot; a new
// version replaces the previous one atomically once it is complete.
type Snapshot struct {
	Version         int64
	ComputedAt      time.Time
	NetworkRevision int64
	Locations       map[string]*Location
	Connections     map[string]*Connection
	Outgoing        map[string][]*Connection
	SampleTypes     map[string]*SampleType
	Regions         []map[string]any
}

func (s *Snapshot) view() map[string]any {
	regions := s.Regions
	if regions == nil {
		regions = []map[string]any{}
	}
	return map[string]any{
		"version":                   s.Version,
		"status":                    "complete",
		"computedAt":                fmtTime(s.ComputedAt),
		"networkRevision":           s.NetworkRevision,
		"regions":                   regions,
		"activeCollectionPointCount": len(regions),
	}
}

// buildNetwork copies the current network structure. The caller holds a.mu.
func (a *App) buildNetwork(now time.Time) *Snapshot {
	st := a.st
	snap := &Snapshot{ComputedAt: now, NetworkRevision: st.NetworkRevision, Locations: map[string]*Location{}, Connections: map[string]*Connection{}, Outgoing: map[string][]*Connection{}, SampleTypes: map[string]*SampleType{}}
	for id, l := range st.Locations {
		cp := *l
		cp.Functions = map[string]bool{}
		for k, v := range l.Functions {
			cp.Functions[k] = v
		}
		cp.AcceptedTypes = map[string]bool{}
		for k, v := range l.AcceptedTypes {
			cp.AcceptedTypes[k] = v
		}
		snap.Locations[id] = &cp
	}
	for id, c := range st.Connections {
		cp := *c
		snap.Connections[id] = &cp
		snap.Outgoing[c.FromLocationID] = append(snap.Outgoing[c.FromLocationID], &cp)
	}
	for id, t := range st.SampleTypes {
		cp := *t
		snap.SampleTypes[id] = &cp
	}
	for _, id := range sortedKeys(snap.Locations) {
		l := snap.Locations[id]
		if l.Active && l.Functions[FnCollectionPoint] {
			snap.Regions = append(snap.Regions, map[string]any{
				"locationId": l.LocationID, "name": l.Name, "latitude": l.Coordinate.Latitude, "longitude": l.Coordinate.Longitude, "coverageKm": math.Min(l.CoverageKm, 5),
			})
		}
	}
	return snap
}

// publishSnapshot computes a new serviceability version and swaps it in
// only once complete. The caller holds a.mu.
func (a *App) publishSnapshot(now time.Time) {
	snap := a.buildNetwork(now)
	a.st.ServiceabilityVersion++
	snap.Version = a.st.ServiceabilityVersion
	a.snapshot.Store(snap)
	go func(v int64) {
		// persist the version counter outside the request path
		_ = a.store.Commit(contextBackground(), &batchMeta("serviceabilityVersion", v).batch)
	}(snap.Version)
}

func haversineKm(a, b Coordinate) float64 {
	const r = 6371.0088
	la1, la2 := a.Latitude*math.Pi/180, b.Latitude*math.Pi/180
	dla := la2 - la1
	dlo := (b.Longitude - a.Longitude) * math.Pi / 180
	h := math.Sin(dla/2)*math.Sin(dla/2) + math.Cos(la1)*math.Cos(la2)*math.Sin(dlo/2)*math.Sin(dlo/2)
	return 2 * r * math.Asin(math.Min(1, math.Sqrt(h)))
}

func (a *App) originLegMinutes(from Coordinate, to Coordinate) int {
	km := haversineKm(from, to)
	return int(math.Ceil(km / a.cfg.OriginSpeedKmH * 60))
}

// Route is a resolved path through the network.
type Route struct {
	StartLocationID  string
	Path             []string // location ids from start to lab
	ConnectionIDs    []string
	LabID            string
	OriginLegMinutes int
	TotalMinutes     int
	Cost             float64
	ETA              time.Time
}

type startPoint struct {
	locID         string
	offsetMinutes int
}

type routeFilter struct {
	requireCooled bool
	checkCapacity bool
	units         int
	excludeLocs   map[string]bool
	excludeConns  map[string]bool
	skipStartCapacity bool
}

type pqItem struct {
	loc  string
	mins int
	cost float64
	idx  int
}
type pq []*pqItem

func (p pq) Len() int { return len(p) }
func (p pq) Less(i, j int) bool {
	if p[i].mins != p[j].mins {
		return p[i].mins < p[j].mins
	}
	return p[i].cost < p[j].cost
}
func (p pq) Swap(i, j int)       { p[i], p[j] = p[j], p[i]; p[i].idx = i; p[j].idx = j }
func (p *pq) Push(x any)         { it := x.(*pqItem); it.idx = len(*p); *p = append(*p, it) }
func (p *pq) Pop() any           { old := *p; it := old[len(old)-1]; *p = old[:len(old)-1]; return it }

// locationUsable reports whether a location may be traversed.
func (a *App) locationUsable(snap *Snapshot, l *Location, f routeFilter, isStart bool, typ *SampleType) bool {
	if !l.Active || f.excludeLocs[l.LocationID] {
		return false
	}
	if !isStart && !(l.Functions[FnTransferPoint] || l.Functions[FnHub] || l.Functions[FnLaboratory] || l.Functions[FnCollectionPoint]) {
		return false
	}
	if f.checkCapacity && !(isStart && f.skipStartCapacity) {
		units := f.units
		if units <= 0 {
			units = 1
		}
		if typ != nil && typ.RequiresCooledRoute {
			if a.availableUnits(l.LocationID, true) < units {
				return false
			}
		} else if a.availableUnits(l.LocationID, false) < units {
			return false
		}
	}
	return true
}

func (a *App) connectionUsable(c *Connection, f routeFilter, typ *SampleType) bool {
	if !c.Active || f.excludeConns[c.ConnectionID] {
		return false
	}
	if typ != nil && typ.RequiresCooledRoute && !c.Cooled {
		return false
	}
	if f.checkCapacity {
		units := f.units
		if units <= 0 {
			units = 1
		}
		cooled := typ != nil && typ.RequiresCooledRoute
		if a.availableUnits(c.ConnectionID, cooled) < units {
			return false
		}
	}
	return true
}

func (a *App) labAccepts(l *Location, typeIDs []string) bool {
	if !l.Active || !l.Functions[FnLaboratory] {
		return false
	}
	for _, t := range typeIDs {
		if !l.AcceptedTypes[t] {
			return false
		}
	}
	return true
}

// findRoute runs a shortest-time search from every start point to any
// laboratory accepting all the given sample types.
func (a *App) findRoute(snap *Snapshot, starts []startPoint, typeIDs []string, f routeFilter) *Route {
	var typ *SampleType
	cooled := false
	for _, id := range typeIDs {
		if t := snap.SampleTypes[id]; t != nil && t.RequiresCooledRoute {
			cooled = true
			typ = t
		}
	}
	if typ == nil && len(typeIDs) > 0 {
		typ = snap.SampleTypes[typeIDs[0]]
	}
	if cooled {
		f.requireCooled = true
	}
	var best *Route
	for _, sp := range starts {
		start := snap.Locations[sp.locID]
		if start == nil || !a.locationUsable(snap, start, f, true, typ) {
			continue
		}
		dist := map[string]int{sp.locID: sp.offsetMinutes}
		cost := map[string]float64{sp.locID: 0}
		prev := map[string]string{}
		prevConn := map[string]string{}
		h := &pq{}
		heap.Push(h, &pqItem{loc: sp.locID, mins: sp.offsetMinutes})
		visited := map[string]bool{}
		for h.Len() > 0 {
			it := heap.Pop(h).(*pqItem)
			if visited[it.loc] {
				continue
			}
			visited[it.loc] = true
			cur := snap.Locations[it.loc]
			if a.labAccepts(cur, typeIDs) && (f.checkCapacity == false || a.locationUsable(snap, cur, f, false, typ)) {
				total := it.mins + cur.HandlingMinutes
				if it.loc == sp.locID {
					total = it.mins
				}
				if best == nil || total < best.TotalMinutes || (total == best.TotalMinutes && it.cost < best.Cost) {
					r := &Route{StartLocationID: sp.locID, LabID: it.loc, OriginLegMinutes: sp.offsetMinutes, TotalMinutes: total, Cost: it.cost}
					// rebuild path
					path := []string{it.loc}
					conns := []string{}
					for cur := it.loc; cur != sp.locID; cur = prev[cur] {
						conns = append([]string{prevConn[cur]}, conns...)
						path = append([]string{prev[cur]}, path...)
					}
					r.Path = path
					r.ConnectionIDs = conns
					best = r
				}
				continue
			}
			outs := append([]*Connection{}, snap.Outgoing[it.loc]...)
			sort.Slice(outs, func(i, j int) bool { return outs[i].ConnectionID < outs[j].ConnectionID })
			for _, cn := range outs {
				if !a.connectionUsable(cn, f, typ) {
					continue
				}
				nxt := snap.Locations[cn.ToLocationID]
				if nxt == nil || !a.locationUsable(snap, nxt, f, false, typ) {
					continue
				}
				handling := 0
				if it.loc != sp.locID {
					handling = cur.HandlingMinutes
				}
				nd := it.mins + handling + cn.TravelMinutes
				if d, ok := dist[nxt.LocationID]; !ok || nd < d {
					dist[nxt.LocationID] = nd
					cost[nxt.LocationID] = it.cost + cn.CostUnits
					prev[nxt.LocationID] = it.loc
					prevConn[nxt.LocationID] = cn.ConnectionID
					heap.Push(h, &pqItem{loc: nxt.LocationID, mins: nd, cost: cost[nxt.LocationID]})
				}
			}
		}
	}
	return best
}

// RequestSpec is the validated input shared by serviceability checks,
// collection requests and pre-sealed ingestion.
type RequestSpec struct {
	requesterID          string
	origin               Coordinate
	originType           string
	originNodeID         string
	requestedAt          time.Time
	deliveryDeadline     time.Time
	earliestCollectionAt time.Time
	latestCollectionAt   time.Time
	sampleTypeID         string
	containerType        string
	tempMin, tempMax     float64
	incompatible         []string
	hasHandling          bool
}

type requestIn struct {
	RequesterID             *string  `json:"requesterId"`
	Origin                  *coordIn `json:"origin"`
	OriginType              *string  `json:"originType"`
	OriginNodeID            *string  `json:"originNodeId"`
	SampleTypeID            *string  `json:"sampleTypeId"`
	RequestedAt             *string  `json:"requestedAt"`
	DeliveryDeadline        *string  `json:"deliveryDeadline"`
	EarliestCollectionAt    *string  `json:"earliestCollectionAt"`
	LatestCollectionAt      *string  `json:"latestCollectionAt"`
	ContainerType           *string  `json:"containerType"`
	TemperatureMinC         *float64 `json:"temperatureMinC"`
	TemperatureMaxC         *float64 `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string `json:"incompatibleSampleTypes"`
	IdempotencyKey          *string  `json:"idempotencyKey"`
}

func (a *App) parseRequestSpec(req *requestIn, presealed bool, c *Ctx) (*RequestSpec, *apiErr) {
	spec := &RequestSpec{}
	if req.SampleTypeID == nil || req.RequestedAt == nil || req.DeliveryDeadline == nil || req.Origin == nil {
		return nil, errInvalidJSON("origin, sampleTypeId, requestedAt and deliveryDeadline are required")
	}
	origin, ok := parseCoord(req.Origin)
	if !ok {
		return nil, E(400, "invalid_origin", "origin must contain a valid latitude and longitude")
	}
	spec.origin = origin
	spec.originType = "home"
	if presealed {
		spec.originType = "node"
	}
	if req.OriginType != nil {
		spec.originType = *req.OriginType
	}
	switch spec.originType {
	case "home", "clinic", "node":
	default:
		return nil, E(400, "invalid_origin_type", "originType must be home, clinic or node")
	}
	if presealed && spec.originType == "home" {
		return nil, E(400, "invalid_origin_type", "a pre-sealed sample cannot originate from a home")
	}
	if req.OriginNodeID != nil && *req.OriginNodeID != "" {
		spec.originNodeID = *req.OriginNodeID
	}
	if spec.originType == "node" {
		if spec.originNodeID == "" {
			return nil, E(400, "invalid_origin", "originNodeId is required when originType is node")
		}
		node := a.st.Locations[spec.originNodeID]
		if node == nil {
			return nil, errNotFound("origin node not found")
		}
		if !node.Active {
			return nil, E(400, "invalid_origin_state", "origin node is inactive")
		}
		spec.origin = node.Coordinate
	} else if spec.originNodeID != "" {
		if a.st.Locations[spec.originNodeID] == nil {
			return nil, errNotFound("origin node not found")
		}
	}
	var e *apiErr
	if spec.requestedAt, e = requiredTime(req.RequestedAt, "requestedAt"); e != nil {
		return nil, e
	}
	if spec.deliveryDeadline, e = requiredTime(req.DeliveryDeadline, "deliveryDeadline"); e != nil {
		return nil, e
	}
	if !spec.deliveryDeadline.After(spec.requestedAt) {
		return nil, E(400, "invalid_deadline", "deliveryDeadline must be after requestedAt")
	}
	earliest, e := optionalTime(req.EarliestCollectionAt, "earliestCollectionAt")
	if e != nil {
		return nil, e
	}
	latest, e := optionalTime(req.LatestCollectionAt, "latestCollectionAt")
	if e != nil {
		return nil, e
	}
	spec.earliestCollectionAt = spec.requestedAt
	spec.latestCollectionAt = spec.deliveryDeadline
	if earliest != nil {
		spec.earliestCollectionAt = *earliest
	}
	if latest != nil {
		spec.latestCollectionAt = *latest
	}
	if spec.earliestCollectionAt.After(spec.latestCollectionAt) || spec.latestCollectionAt.After(spec.deliveryDeadline) || spec.earliestCollectionAt.After(spec.deliveryDeadline) {
		return nil, E(400, "invalid_collection_window", "collection window must be ordered and end before the delivery deadline")
	}
	typ := a.st.SampleTypes[*req.SampleTypeID]
	if typ == nil {
		return nil, errNotFound("sample type not found")
	}
	spec.sampleTypeID = typ.SampleTypeID
	spec.containerType = typ.ContainerType
	spec.tempMin, spec.tempMax = typ.TemperatureMinC, typ.TemperatureMaxC
	spec.incompatible = strs(typ.IncompatibleSampleTypes)
	if req.ContainerType != nil || req.TemperatureMinC != nil || req.TemperatureMaxC != nil {
		spec.hasHandling = true
		if req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
			return nil, errInvalidJSON("containerType, temperatureMinC and temperatureMaxC are required")
		}
		if lower(*req.ContainerType) != lower(typ.ContainerType) {
			return nil, E(400, "handling_mismatch", "containerType does not match the sample type's container")
		}
		if *req.TemperatureMinC > *req.TemperatureMaxC || *req.TemperatureMinC < typ.TemperatureMinC-1e-9 || *req.TemperatureMaxC > typ.TemperatureMaxC+1e-9 {
			return nil, E(400, "handling_mismatch", "temperature range must lie within the sample type's range")
		}
		spec.containerType = *req.ContainerType
		spec.tempMin, spec.tempMax = *req.TemperatureMinC, *req.TemperatureMaxC
		for _, id := range req.IncompatibleSampleTypes {
			if a.st.SampleTypes[id] == nil {
				return nil, E(400, "handling_mismatch", "incompatibleSampleTypes references an unknown sample type")
			}
			if !contains(spec.incompatible, id) {
				spec.incompatible = append(spec.incompatible, id)
			}
		}
	}
	if c != nil {
		spec.requesterID = c.user.UserID
		if req.RequesterID != nil && *req.RequesterID != "" && *req.RequesterID != c.user.UserID {
			if !c.isSupervisor() {
				return nil, errForbidden("requests may only be created for your own account")
			}
			if a.st.Users[*req.RequesterID] == nil {
				return nil, errNotFound("requester not found")
			}
			spec.requesterID = *req.RequesterID
		}
	}
	return spec, nil
}

type ServiceabilityResult struct {
	Serviceable bool
	Reason      string
	Route       *Route
	ETA         time.Time
}

// candidateStarts returns the collection points usable for an origin.
func (a *App) candidateStarts(snap *Snapshot, spec *RequestSpec) []startPoint {
	var starts []startPoint
	if spec.originType == "node" {
		if l := snap.Locations[spec.originNodeID]; l != nil && l.Active {
			starts = append(starts, startPoint{locID: l.LocationID})
		}
		return starts
	}
	for _, id := range sortedKeys(snap.Locations) {
		l := snap.Locations[id]
		if !l.Active || !l.Functions[FnCollectionPoint] {
			continue
		}
		if haversineKm(spec.origin, l.Coordinate) <= math.Min(l.CoverageKm, 5)+1e-9 {
			starts = append(starts, startPoint{locID: l.LocationID, offsetMinutes: a.originLegMinutes(spec.origin, l.Coordinate)})
		}
	}
	return starts
}

// evaluateServiceability applies the serviceability rules in order and
// returns the first failing reason or the best route.
func (a *App) evaluateServiceability(snap *Snapshot, spec *RequestSpec, f *routeFilter) ServiceabilityResult {
	filter := routeFilter{}
	if f != nil {
		filter = *f
	}
	starts := a.candidateStarts(snap, spec)
	if len(starts) == 0 {
		return ServiceabilityResult{Reason: "outside_service_coverage"}
	}
	typeIDs := []string{spec.sampleTypeID}
	anyLab := false
	for _, l := range snap.Locations {
		if a.labAccepts(l, typeIDs) && !filter.excludeLocs[l.LocationID] {
			anyLab = true
			break
		}
	}
	if !anyLab {
		return ServiceabilityResult{Reason: "no_accepting_laboratory"}
	}
	typ := snap.SampleTypes[spec.sampleTypeID]
	// stage A: structural route ignoring cooling and capacity
	plain := filter
	plain.checkCapacity = false
	plainTypes := typeIDs
	if typ != nil && typ.RequiresCooledRoute {
		// evaluate without the cooling constraint to distinguish no_route from handling failure
		tmp := *typ
		tmp.RequiresCooledRoute = false
		saved := snap.SampleTypes[typ.SampleTypeID]
		snap.SampleTypes[typ.SampleTypeID] = &tmp
		r := a.findRoute(snap, starts, plainTypes, plain)
		snap.SampleTypes[typ.SampleTypeID] = saved
		if r == nil {
			return ServiceabilityResult{Reason: "no_route"}
		}
		if a.findRoute(snap, starts, typeIDs, plain) == nil {
			return ServiceabilityResult{Reason: "handling_rules_unsatisfiable"}
		}
	} else if a.findRoute(snap, starts, typeIDs, plain) == nil {
		return ServiceabilityResult{Reason: "no_route"}
	}
	withCap := filter
	withCap.checkCapacity = true
	route := a.findRoute(snap, starts, typeIDs, withCap)
	if route == nil {
		return ServiceabilityResult{Reason: "insufficient_capacity"}
	}
	start := spec.requestedAt
	if spec.earliestCollectionAt.After(start) {
		start = spec.earliestCollectionAt
	}
	route.ETA = start.Add(time.Duration(route.TotalMinutes) * time.Minute)
	if route.ETA.After(spec.deliveryDeadline) {
		return ServiceabilityResult{Reason: "deadline_unreachable", Route: route, ETA: route.ETA}
	}
	return ServiceabilityResult{Serviceable: true, Reason: "serviceable", Route: route, ETA: route.ETA}
}

// --- capacity -----------------------------------------------------------

func (a *App) reservedUnits(resourceID string) (regular int, cooled int) {
	for _, r := range a.st.Reservations {
		if r.Released || r.ResourceID != resourceID {
			continue
		}
		if r.Cooled {
			cooled += r.Units
		} else {
			regular += r.Units
		}
	}
	return
}

func (a *App) configuredUnits(resourceID string) (regular int, cooled int, ok bool) {
	if l := a.st.Locations[resourceID]; l != nil {
		return l.CapacityUnits, l.CooledCapacityUnits, true
	}
	if c := a.st.Connections[resourceID]; c != nil {
		return c.CapacityUnits, c.CooledCapacityUnits, true
	}
	return 0, 0, false
}

func (a *App) availableUnits(resourceID string, cooled bool) int {
	reg, cool, ok := a.configuredUnits(resourceID)
	if !ok {
		return 0
	}
	rreg, rcool := a.reservedUnits(resourceID)
	if cooled {
		return cool - rcool
	}
	return reg - rreg
}

func (a *App) capacityView(resourceID string) map[string]any {
	reg, cool, _ := a.configuredUnits(resourceID)
	rreg, rcool := a.reservedUnits(resourceID)
	return map[string]any{
		"capacityUnits":        reg,
		"reservedUnits":        rreg,
		"availableUnits":       reg - rreg,
		"cooledCapacityUnits":  cool,
		"cooledReservedUnits":  rcool,
		"cooledAvailableUnits": cool - rcool,
	}
}

// reserveRoute reserves one unit per resource on the route for a sample.
// It returns false (without changes) when any pool would be overbooked.
func (a *App) reserveRoute(u *UoW, journeyID, sampleID string, resources []string, cooled bool) bool {
	for _, rid := range resources {
		if a.availableUnits(rid, cooled) < 1 {
			return false
		}
	}
	for _, rid := range resources {
		rtype := "location"
		if a.st.Connections[rid] != nil {
			rtype = "connection"
		}
		res := &Reservation{ReservationID: newID(), JourneyID: journeyID, SampleID: sampleID, ResourceType: rtype, ResourceID: rid, Cooled: cooled, Units: 1}
		a.st.Reservations[res.ReservationID] = res
		u.saveReservation(res)
	}
	return true
}

func (a *App) releaseReservations(u *UoW, match func(r *Reservation) bool) int {
	n := 0
	for _, r := range a.st.Reservations {
		if !r.Released && match(r) {
			r.Released = true
			u.saveReservation(r)
			n++
		}
	}
	return n
}

func routeResources(r *Route) []string {
	out := append([]string{}, r.Path...)
	out = append(out, r.ConnectionIDs...)
	return out
}

