package app

import (
	"sort"
	"time"
)

// journeyOpts controls how a journey is materialised for a sample.
type journeyOpts struct {
	registrant      *User  // holder of a pre-sealed sample
	registrantRole  string
	parentJourneyID string
	startAt         time.Time
	fromNode        bool // the sample is already at route.StartLocationID
}

// buildJourney creates the journey, its stops, chain of assignments and
// capacity reservations for one sample along a route.
func (a *App) buildJourney(c *Ctx, s *Sample, typ *SampleType, route *Route, opts journeyOpts) *Journey {
	j := &Journey{
		JourneyID: newID(), ParentJourneyID: opts.parentJourneyID, PlanVersion: 1, Status: JourneyPlanned,
		SampleIDs: []string{s.SampleID}, TargetLaboratoryID: route.LabID, StartLocationID: route.StartLocationID,
		TotalCostUnits: route.Cost, Valid: true, CreatedAt: c.now,
	}
	a.populateJourney(c, j, s, typ, route, opts)
	a.st.Journeys[j.JourneyID] = j
	c.u.saveJourney(j)
	return j
}

// populateJourney fills stops, assignments and reservations for a journey
// that carries a single sample.
func (a *App) populateJourney(c *Ctx, j *Journey, s *Sample, typ *SampleType, route *Route, opts journeyOpts) {
	u := c.u
	t := opts.startAt
	seq := 0
	stopSeq := 0
	addStop := func(locID, stopType string, at time.Time, dwell int, coord *Coordinate) {
		j.Stops = append(j.Stops, Stop{StopID: newID(), LocationID: locID, StopType: stopType, Sequence: stopSeq, EstimatedAt: at, DwellMinutes: dwell, Coordinate: coord})
		stopSeq++
	}
	newAsg := func(kind string) *Assignment {
		asg := &Assignment{AssignmentID: newID(), JourneyID: j.JourneyID, Kind: kind, SampleIDs: []string{s.SampleID}, Status: AsgPending, Sequence: seq, Cooled: typ.RequiresCooledRoute, CreatedAt: c.now}
		seq++
		a.st.Assignments[asg.AssignmentID] = asg
		j.AssignmentIDs = append(j.AssignmentIDs, asg.AssignmentID)
		return asg
	}
	preAccept := func(asg *Assignment, w *User, status string) {
		asg.WorkerID = w.UserID
		asg.Status = status
		at := c.now
		asg.AcceptedAt = &at
	}
	reg := opts.registrant
	regRole := opts.registrantRole
	path := route.Path
	lab := route.LabID
	originCoord := s.Origin
	prevLoc := ""
	if !opts.fromNode {
		// collection at a home or clinic
		addStop(s.RequestID, "pickup", t, 0, &originCoord)
		if reg == nil {
			newAsg(KindCollection)
		} else if regRole == RoleCollector {
			preAccept(newAsg(KindCollection), reg, AsgSealed)
		}
		leg := newAsg(KindTransport)
		leg.FromLocationID = s.RequestID
		leg.ToLocationID = path[0]
		leg.TravelMinutes = route.OriginLegMinutes
		if reg != nil && regRole == RoleCourier {
			preAccept(leg, reg, AsgPickedUp)
		}
		t = t.Add(time.Duration(route.OriginLegMinutes) * time.Minute)
		prevLoc = s.RequestID
	} else if reg == nil {
		// a request whose sample sits at a network node still needs collection
		newAsg(KindCollection)
	} else if regRole == RoleCollector {
		preAccept(newAsg(KindCollection), reg, AsgSealed)
	}
	for i, locID := range path {
		loc := a.st.Locations[locID]
		handling := 0
		if loc != nil {
			handling = loc.HandlingMinutes
		}
		isLab := locID == lab && i == len(path)-1
		if isLab {
			if opts.fromNode && i == 0 {
				addStop(locID, "delivery", t, handling, nil)
			} else {
				addStop(locID, "delivery", t, handling, nil)
			}
			labAsg := newAsg(KindLaboratory)
			labAsg.LaboratoryID = locID
			labAsg.FromLocationID = prevLoc
			labAsg.ToLocationID = locID
			if reg != nil && i == 0 && opts.fromNode && regRole == RoleLaboratory {
				preAccept(labAsg, reg, AsgInProgress)
			}
			t = t.Add(time.Duration(handling) * time.Minute)
			break
		}
		if i == 0 && opts.fromNode {
			addStop(locID, "pickup", t, handling, nil)
		} else {
			addStop(locID, "handoff", t, handling, nil)
		}
		skipNode := i == 0 && opts.fromNode && reg != nil && regRole == RoleCourier
		if !skipNode {
			node := newAsg(KindNode)
			node.NodeID = locID
			node.FromLocationID = prevLoc
			node.ToLocationID = path[i+1]
			if reg != nil && i == 0 && opts.fromNode && (regRole == RoleNodeHandler || regRole == RoleLaboratory) {
				preAccept(node, reg, AsgInProgress)
			}
		}
		conn := a.st.Connections[route.ConnectionIDs[i]]
		leg := newAsg(KindTransport)
		leg.FromLocationID = locID
		leg.ToLocationID = path[i+1]
		leg.ConnectionID = route.ConnectionIDs[i]
		if conn != nil {
			leg.TravelMinutes = conn.TravelMinutes
		}
		if skipNode {
			preAccept(leg, reg, AsgPickedUp)
		}
		t = t.Add(time.Duration(handling+leg.TravelMinutes) * time.Minute)
		prevLoc = locID
	}
	j.EstimatedDeliveryAt = t
	j.RouteMode = routeModeFor(j, a)
	for _, id := range j.AssignmentIDs {
		asg := a.st.Assignments[id]
		u.saveAssignment(asg)
		u.audit(c.actorID(), roleOrNone(c.role), "assignment.created", "assignment", asg.AssignmentID, true, map[string]any{
			"journeyId": j.JourneyID, "sampleId": s.SampleID, "kind": asg.Kind, "sequence": asg.Sequence, "fromLocationId": asg.FromLocationID, "toLocationId": asg.ToLocationID, "status": asg.Status,
		})
	}
	a.reserveRoute(u, j.JourneyID, s.SampleID, routeResources(route), typ.RequiresCooledRoute)
	for _, id := range j.AssignmentIDs {
		asg := a.st.Assignments[id]
		if asg.Status == AsgPending {
			a.offerAssignment(c.u, asg, c.actorID(), roleOrNone(c.role))
		}
	}
}

func routeModeFor(j *Journey, a *App) string {
	if len(j.SampleIDs) > 1 {
		return "batched"
	}
	legs := 0
	for _, id := range j.AssignmentIDs {
		if asg := a.st.Assignments[id]; asg != nil && asg.Kind == KindTransport && asg.Status != AsgCancelled {
			legs++
		}
	}
	if legs <= 1 {
		return "direct"
	}
	return "multi_stop"
}

// --- eligibility and fair offering ---------------------------------------

func roleForKind(kind string) string {
	switch kind {
	case KindCollection:
		return RoleCollector
	case KindTransport:
		return RoleCourier
	case KindNode:
		return RoleNodeHandler
	case KindLaboratory:
		return RoleLaboratory
	}
	return ""
}

func (a *App) qualifiedFor(w *User, typ *SampleType, now time.Time) bool {
	if typ == nil || !typ.QualifiedCollectorRequired {
		return true
	}
	codes := []string{lower(typ.RequiredQualification), lower(typ.Name)}
	match := func(v string) bool {
		v = lower(v)
		for _, c := range codes {
			if c != "" && c == v {
				return true
			}
		}
		return false
	}
	for _, q := range w.Qualifications {
		if match(q) {
			return true
		}
	}
	for _, cert := range w.Certifications {
		if match(cert.Code) && cert.Active && (cert.ExpiresAt == nil || cert.ExpiresAt.After(now)) {
			return true
		}
	}
	return false
}

// potentiallyEligible ignores availability and workload.
func (a *App) potentiallyEligible(w *User, asg *Assignment, now time.Time) (bool, string) {
	if !w.Active {
		return false, "inactive"
	}
	role := roleForKind(asg.Kind)
	if !contains(w.Roles, role) {
		return false, "missing_role"
	}
	switch asg.Kind {
	case KindNode:
		if w.AssignedLocationID != asg.NodeID {
			return false, "not_assigned_to_node"
		}
	case KindLaboratory:
		if w.AssignedLocationID != asg.LaboratoryID {
			return false, "not_assigned_to_laboratory"
		}
	case KindCollection:
		for _, sid := range asg.SampleIDs {
			s := a.st.Samples[sid]
			if s == nil {
				continue
			}
			if !a.qualifiedFor(w, a.st.SampleTypes[s.SampleTypeID], now) {
				return false, "not_qualified"
			}
		}
	}
	return true, ""
}

func (a *App) eligible(w *User, asg *Assignment, now time.Time) (bool, string) {
	if ok, reason := a.potentiallyEligible(w, asg, now); !ok {
		return false, reason
	}
	if !w.Available {
		return false, "unavailable"
	}
	count := a.workerActiveAssignmentCountExcluding(w.UserID, asg.AssignmentID)
	if count >= w.CapacityUnits {
		return false, "at_capacity"
	}
	return true, ""
}

func (a *App) workerActiveAssignmentCount(workerID string) int {
	return a.workerActiveAssignmentCountExcluding(workerID, "")
}

func (a *App) workerActiveAssignmentCountExcluding(workerID, exclude string) int {
	n := 0
	for _, asg := range a.st.Assignments {
		if asg.AssignmentID == exclude || !asg.Active() {
			continue
		}
		if asg.WorkerID == workerID || (asg.WorkerID == "" && asg.OfferedWorkerID == workerID) {
			n++
		}
	}
	return n
}

func (a *App) recentDeclines(w *User, now time.Time) int {
	n := 0
	for _, t := range w.Declines {
		if now.Sub(t) < 15*time.Minute {
			n++
		}
	}
	return n
}

// rankedCandidates orders eligible workers fairly: workers under a recent
// decline penalty go last, then lowest workload, then least recently offered.
func (a *App) rankedCandidates(asg *Assignment, now time.Time) []*User {
	var cands []*User
	for _, w := range a.st.Users {
		if ok, _ := a.eligible(w, asg, now); ok {
			cands = append(cands, w)
		}
	}
	sort.Slice(cands, func(i, j int) bool {
		pi, pj := a.recentDeclines(cands[i], now) >= 2, a.recentDeclines(cands[j], now) >= 2
		if pi != pj {
			return !pi
		}
		ci, cj := a.workerActiveAssignmentCountExcluding(cands[i].UserID, asg.AssignmentID), a.workerActiveAssignmentCountExcluding(cands[j].UserID, asg.AssignmentID)
		if ci != cj {
			return ci < cj
		}
		ti, tj := time.Time{}, time.Time{}
		if cands[i].LastOfferedAt != nil {
			ti = *cands[i].LastOfferedAt
		}
		if cands[j].LastOfferedAt != nil {
			tj = *cands[j].LastOfferedAt
		}
		if !ti.Equal(tj) {
			return ti.Before(tj)
		}
		return cands[i].UserID < cands[j].UserID
	})
	return cands
}

// offerAssignment offers a pending assignment to the best candidate who has
// not declined it. Returns the worker offered to, if any.
func (a *App) offerAssignment(u *UoW, asg *Assignment, actorID, actorRole string) *User {
	if asg.Status != AsgPending || asg.WorkerID != "" {
		return nil
	}
	var pick *User
	cands := a.rankedCandidates(asg, u.now)
	for _, w := range cands {
		if !contains(asg.DeclinedBy, w.UserID) {
			pick = w
			break
		}
	}
	if pick == nil && len(cands) > 0 && len(asg.DeclinedBy) > 0 {
		// everyone eligible has declined once; cycle back so nobody is excluded forever
		asg.DeclinedBy = nil
		pick = cands[0]
	}
	if pick == nil {
		asg.OfferedWorkerID = ""
		asg.OfferedAt = nil
		asg.OfferExpiresAt = nil
		if asg.NoWorkerSince == nil {
			t := u.now
			asg.NoWorkerSince = &t
		}
		u.saveAssignment(asg)
		return nil
	}
	now := u.now
	exp := now.Add(a.cfg.OfferTimeout)
	asg.OfferedWorkerID = pick.UserID
	asg.OfferedAt = &now
	asg.OfferExpiresAt = &exp
	asg.NoWorkerSince = nil
	pick.LastOfferedAt = &now
	u.saveUser(pick)
	u.saveAssignment(asg)
	u.audit(actorID, actorRole, "assignment.offered", "assignment", asg.AssignmentID, true, map[string]any{
		"journeyId": asg.JourneyID, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "workerId": pick.UserID, "kind": asg.Kind, "offerExpiresAt": fmtTime(exp),
	})
	u.event("assignment.offered", "assignment", asg.AssignmentID, map[string]any{
		"assignmentId": asg.AssignmentID, "kind": asg.Kind, "workerId": pick.UserID, "sampleIds": asg.SampleIDs, "journeyId": asg.JourneyID, "offerExpiresAt": fmtTime(exp),
	}, []string{RoleAdministrator, RoleDispatcher}, []string{pick.UserID})
	return pick
}

func firstOf(v []string) string {
	if len(v) == 0 {
		return ""
	}
	return v[0]
}

// retryPendingOffers re-offers assignments that currently have nobody.
func (a *App) retryPendingOffers(u *UoW) {
	for _, id := range sortedKeys(a.st.Assignments) {
		asg := a.st.Assignments[id]
		if asg.Status == AsgPending && asg.WorkerID == "" && asg.OfferedWorkerID == "" {
			a.offerAssignment(u, asg, systemActor, "system")
		}
	}
}

// expireOffers treats unanswered offers as declines and re-offers them.
func (a *App) expireOffers(u *UoW) {
	for _, id := range sortedKeys(a.st.Assignments) {
		asg := a.st.Assignments[id]
		if asg.Status != AsgPending || asg.OfferedWorkerID == "" || asg.OfferExpiresAt == nil || u.now.Before(*asg.OfferExpiresAt) {
			continue
		}
		prev := asg.OfferedWorkerID
		asg.DeclinedBy = append(asg.DeclinedBy, prev)
		asg.OfferedWorkerID = ""
		asg.OfferedAt = nil
		asg.OfferExpiresAt = nil
		u.saveAssignment(asg)
		u.audit(systemActor, "system", "assignment.offer_expired", "assignment", asg.AssignmentID, true, map[string]any{"workerId": prev, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "journeyId": asg.JourneyID})
		a.offerAssignment(u, asg, systemActor, "system")
	}
}

// flagUnstaffedAssignments marks samples whose assignment cannot be staffed
// within the configured grace period as exceptions.
func (a *App) flagUnstaffedAssignments(u *UoW) {
	for _, id := range sortedKeys(a.st.Assignments) {
		asg := a.st.Assignments[id]
		if asg.Status != AsgPending || asg.WorkerID != "" || asg.OfferedWorkerID != "" {
			continue
		}
		if asg.NoWorkerSince == nil {
			a.offerAssignment(u, asg, systemActor, "system")
			continue
		}
		anyPotential := false
		for _, w := range a.st.Users {
			if ok, _ := a.potentiallyEligible(w, asg, u.now); ok {
				anyPotential = true
				break
			}
		}
		grace := a.cfg.NoWorkerTimeout
		if anyPotential {
			grace = a.cfg.NoWorkerTimeout * 4
		}
		if u.now.Sub(*asg.NoWorkerSince) < grace {
			continue
		}
		for _, sid := range asg.SampleIDs {
			s := a.st.Samples[sid]
			if s == nil || s.Terminal() {
				continue
			}
			a.flagException(u, s, "no_qualified_worker", map[string]any{"assignmentId": asg.AssignmentID, "kind": asg.Kind}, systemActor, "system")
		}
	}
}

// flagException puts a sample into the exception state and winds down its
// journey without touching confirmed custody.
func (a *App) flagException(u *UoW, s *Sample, reason string, details map[string]any, actorID, actorRole string) {
	if details == nil {
		details = map[string]any{}
	}
	details["reason"] = reason
	details["occurredAt"] = fmtTime(u.now)
	s.Exception = details
	s.Status = SampleException
	u.saveSample(s)
	u.audit(actorID, actorRole, "sample.exception", "sample", s.SampleID, true, map[string]any{"reason": reason, "details": details, "status": s.Status, "journeyId": s.ActiveJourneyID})
	u.event("sample.updated", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "status": s.Status, "exception": details}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
	if j := a.st.Journeys[s.ActiveJourneyID]; j != nil {
		a.windDownJourney(u, j, s.SampleID, JourneyException, actorID, actorRole)
	}
}

// windDownJourney cancels unfinished work for a sample (or the whole journey
// when it is the only sample) and releases its reservations.
func (a *App) windDownJourney(u *UoW, j *Journey, sampleID string, finalStatus string, actorID, actorRole string) {
	a.releaseReservations(u, func(r *Reservation) bool { return r.JourneyID == j.JourneyID && r.SampleID == sampleID })
	remaining := []string{}
	for _, sid := range j.SampleIDs {
		if s := a.st.Samples[sid]; s != nil && !s.Terminal() {
			remaining = append(remaining, sid)
		}
	}
	for _, id := range j.AssignmentIDs {
		asg := a.st.Assignments[id]
		if asg == nil || asg.Terminal() {
			continue
		}
		if len(asg.SampleIDs) > 1 && len(remaining) > 0 {
			// shared assignment keeps serving the remaining samples
			kept := []string{}
			for _, sid := range asg.SampleIDs {
				if sid != sampleID {
					kept = append(kept, sid)
				}
			}
			asg.SampleIDs = kept
			u.saveAssignment(asg)
			continue
		}
		if asg.HasSample(sampleID) {
			a.cancelAssignment(u, asg, "journey_"+finalStatus, actorID, actorRole)
		}
	}
	if len(remaining) == 0 {
		j.Status = finalStatus
		if finalStatus == JourneyException || finalStatus == JourneyExpired {
			j.ReplanStatus = finalStatus
		}
		u.saveJourney(j)
		u.audit(actorID, actorRole, "journey.status_changed", "journey", j.JourneyID, true, map[string]any{"status": finalStatus, "sampleIds": j.SampleIDs})
		u.event("journey.updated", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID, "status": j.Status, "planVersion": j.PlanVersion}, []string{RoleAdministrator, RoleDispatcher}, nil)
	}
}

func (a *App) cancelAssignment(u *UoW, asg *Assignment, reason, actorID, actorRole string) {
	if asg.Terminal() {
		return
	}
	// custody already transferred stays with the holder; the assignment itself ends
	prev := asg.Status
	asg.Status = AsgCancelled
	t := u.now
	asg.CompletedAt = &t
	u.saveAssignment(asg)
	u.audit(actorID, actorRole, "assignment.cancelled", "assignment", asg.AssignmentID, true, map[string]any{"journeyId": asg.JourneyID, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "reason": reason, "previousStatus": prev})
	aud := []string{}
	if asg.WorkerID != "" {
		aud = append(aud, asg.WorkerID)
	}
	if asg.OfferedWorkerID != "" {
		aud = append(aud, asg.OfferedWorkerID)
	}
	u.event("assignment.updated", "assignment", asg.AssignmentID, map[string]any{"assignmentId": asg.AssignmentID, "status": asg.Status, "reason": reason}, []string{RoleAdministrator, RoleDispatcher}, aud)
}

// sampleAudience lists the users entitled to a sample's events.
func (a *App) sampleAudience(s *Sample) []string {
	aud := []string{s.RequesterID}
	if s.CurrentHolderID != "" {
		aud = append(aud, s.CurrentHolderID)
	}
	for _, asg := range a.st.Assignments {
		if asg.HasSample(s.SampleID) {
			if asg.WorkerID != "" && !contains(aud, asg.WorkerID) {
				aud = append(aud, asg.WorkerID)
			}
			if asg.OfferedWorkerID != "" && !contains(aud, asg.OfferedWorkerID) {
				aud = append(aud, asg.OfferedWorkerID)
			}
		}
	}
	return aud
}

// workerBecameUnavailable releases the worker's unstarted work so it can
// be re-offered. Work already in custody is left with the holder.
func (a *App) workerBecameUnavailable(u *UoW, w *User, reason string, c *Ctx) {
	for _, id := range sortedKeys(a.st.Assignments) {
		asg := a.st.Assignments[id]
		if !asg.Active() {
			continue
		}
		if asg.Status == AsgPending && asg.OfferedWorkerID == w.UserID {
			asg.DeclinedBy = append(asg.DeclinedBy, w.UserID)
			asg.OfferedWorkerID = ""
			asg.OfferedAt = nil
			asg.OfferExpiresAt = nil
			u.saveAssignment(asg)
			u.audit(c.actorID(), roleOrNone(c.role), "assignment.offer_withdrawn", "assignment", asg.AssignmentID, true, map[string]any{"workerId": w.UserID, "reason": reason, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "journeyId": asg.JourneyID})
			a.offerAssignment(u, asg, c.actorID(), roleOrNone(c.role))
			continue
		}
		if asg.WorkerID == w.UserID && asg.Status == AsgAccepted && !a.holdsAnySample(w.UserID, asg) {
			asg.WorkerID = ""
			asg.AcceptedAt = nil
			asg.Status = AsgPending
			asg.DeclinedBy = append(asg.DeclinedBy, w.UserID)
			u.saveAssignment(asg)
			u.audit(c.actorID(), roleOrNone(c.role), "assignment.released", "assignment", asg.AssignmentID, true, map[string]any{"workerId": w.UserID, "reason": reason, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "journeyId": asg.JourneyID})
			a.offerAssignment(u, asg, c.actorID(), roleOrNone(c.role))
		}
	}
}

func (a *App) holdsAnySample(workerID string, asg *Assignment) bool {
	for _, sid := range asg.SampleIDs {
		if s := a.st.Samples[sid]; s != nil && s.CurrentHolderID == workerID {
			return true
		}
	}
	return false
}

// recheckWorkerAssignments releases accepted-but-unstarted assignments the
// worker is no longer eligible for (for example after a role change).
func (a *App) recheckWorkerAssignments(u *UoW, w *User, c *Ctx) {
	for _, id := range sortedKeys(a.st.Assignments) {
		asg := a.st.Assignments[id]
		if !asg.Active() {
			continue
		}
		if (asg.OfferedWorkerID == w.UserID && asg.WorkerID == "") || (asg.WorkerID == w.UserID && asg.Status == AsgAccepted) {
			if ok, _ := a.potentiallyEligible(w, asg, u.now); !ok && !a.holdsAnySample(w.UserID, asg) {
				asg.WorkerID = ""
				asg.OfferedWorkerID = ""
				asg.OfferedAt = nil
				asg.OfferExpiresAt = nil
				asg.AcceptedAt = nil
				asg.Status = AsgPending
				u.saveAssignment(asg)
				u.audit(c.actorID(), roleOrNone(c.role), "assignment.released", "assignment", asg.AssignmentID, true, map[string]any{"workerId": w.UserID, "reason": "worker_ineligible", "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "journeyId": asg.JourneyID})
				a.offerAssignment(u, asg, c.actorID(), roleOrNone(c.role))
			}
		}
	}
}

// chainFor returns the ordered custody chain of a sample within a journey.
func (a *App) chainFor(j *Journey, sampleID string) []*Assignment {
	var out []*Assignment
	for _, id := range j.AssignmentIDs {
		asg := a.st.Assignments[id]
		if asg != nil && asg.HasSample(sampleID) && asg.Status != AsgCancelled {
			out = append(out, asg)
		}
	}
	sort.SliceStable(out, func(i, k int) bool { return out[i].Sequence < out[k].Sequence })
	return out
}

func (a *App) journeyAssignments(j *Journey) []*Assignment {
	var out []*Assignment
	for _, id := range j.AssignmentIDs {
		if asg := a.st.Assignments[id]; asg != nil {
			out = append(out, asg)
		}
	}
	sort.SliceStable(out, func(i, k int) bool { return out[i].Sequence < out[k].Sequence })
	return out
}

func (a *App) journeyLegs(j *Journey) []*Assignment {
	var out []*Assignment
	for _, asg := range a.journeyAssignments(j) {
		if asg.Kind == KindTransport && asg.Status != AsgCancelled {
			out = append(out, asg)
		}
	}
	return out
}

func (a *App) activeAssignmentIDs(j *Journey) []string {
	out := []string{}
	for _, asg := range a.journeyAssignments(j) {
		if asg.Active() {
			out = append(out, asg.AssignmentID)
		}
	}
	return out
}

func (a *App) sampleActiveAssignmentIDs(s *Sample) []string {
	out := []string{}
	j := a.st.Journeys[s.ActiveJourneyID]
	if j == nil {
		return out
	}
	for _, asg := range a.journeyAssignments(j) {
		if asg.Active() && asg.HasSample(s.SampleID) {
			out = append(out, asg.AssignmentID)
		}
	}
	return out
}

