package app

import (
	"time"
)

func (a *App) newSampleFromSpec(c *Ctx, spec *RequestSpec) *Sample {
	s := &Sample{
		SampleID: newID(), RequestID: newID(), RequesterID: spec.requesterID, Origin: spec.origin, OriginType: spec.originType,
		OriginNodeID: spec.originNodeID, RequestedAt: spec.requestedAt, DeliveryDeadline: spec.deliveryDeadline,
		EarliestCollectionAt: spec.earliestCollectionAt, LatestCollectionAt: spec.latestCollectionAt, SampleTypeID: spec.sampleTypeID,
		ContainerType: spec.containerType, TemperatureMinC: spec.tempMin, TemperatureMaxC: spec.tempMax,
		IncompatibleSampleTypes: strs(spec.incompatible), Status: SampleRequested, CreatedAt: c.now,
	}
	origin := spec.origin
	s.LatestLocation = &origin
	t := c.now
	s.LocationRecordedAt = &t
	return s
}

func planStart(spec *RequestSpec) time.Time {
	start := spec.requestedAt
	if spec.earliestCollectionAt.After(start) {
		start = spec.earliestCollectionAt
	}
	return start
}

func (a *App) requestResponse(s *Sample, j *Journey) map[string]any {
	out := map[string]any{
		"requestId":            s.RequestID,
		"sampleId":             s.SampleID,
		"serviceability":       s.Serviceability,
		"activeAssignmentIds":  a.sampleActiveAssignmentIDs(s),
		"earliestCollectionAt": fmtTime(s.EarliestCollectionAt),
		"latestCollectionAt":   fmtTime(s.LatestCollectionAt),
		"alreadySealed":        s.Sealed,
		"originType":           s.OriginType,
	}
	if s.ServiceabilityReason != "" {
		out["serviceabilityReason"] = s.ServiceabilityReason
	}
	if j != nil {
		out["journeyId"] = j.JourneyID
		out["targetLaboratoryId"] = j.TargetLaboratoryID
	}
	return out
}

func (a *App) hCreateCollectionRequest(c *Ctx, body []byte) (int, any, *apiErr) {
	var req requestIn
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		return 0, nil, errInvalidJSON("containerType, temperatureMinC and temperatureMaxC are required")
	}
	spec, e := a.parseRequestSpec(&req, false, c)
	if e != nil {
		return 0, nil, e
	}
	s := a.newSampleFromSpec(c, spec)
	typ := a.st.SampleTypes[spec.sampleTypeID]
	snap := a.snapshot.Load()
	res := a.evaluateServiceability(snap, spec, nil)
	s.ServiceabilityVersion = snap.Version
	a.st.Samples[s.SampleID] = s
	c.audit("request.created", "request", s.RequestID, true, map[string]any{
		"sampleId": s.SampleID, "requesterId": s.RequesterID, "originType": s.OriginType, "origin": coordView(s.Origin), "sampleTypeId": s.SampleTypeID,
		"deliveryDeadline": fmtTime(s.DeliveryDeadline), "collectionWindow": map[string]any{"earliest": fmtTime(s.EarliestCollectionAt), "latest": fmtTime(s.LatestCollectionAt)}, "status": s.Status,
	})
	var j *Journey
	if res.Serviceable {
		s.Serviceability = "serviceable"
		s.ServiceabilityReason = "serviceable"
		s.TargetLaboratoryID = res.Route.LabID
		j = a.buildJourney(c, s, typ, res.Route, journeyOpts{startAt: planStart(spec), fromNode: spec.originType == "node"})
		s.ActiveJourneyID = j.JourneyID
		c.audit("journey.created", "journey", j.JourneyID, true, map[string]any{"sampleId": s.SampleID, "routeMode": j.RouteMode, "path": res.Route.Path, "targetLaboratoryId": j.TargetLaboratoryID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "planVersion": j.PlanVersion})
	} else {
		s.Serviceability = "unserviceable"
		s.ServiceabilityReason = res.Reason
		s.Status = SampleUnserviceable
	}
	c.audit("sample.serviceability_evaluated", "sample", s.SampleID, true, map[string]any{"serviceability": s.Serviceability, "reason": s.ServiceabilityReason, "serviceabilityVersion": snap.Version, "status": s.Status})
	c.u.saveSample(s)
	c.u.event("sample.created", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "requestId": s.RequestID, "status": s.Status, "serviceability": s.Serviceability}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
	return 201, a.requestResponse(s, j), nil
}

func (a *App) hIngestPresealed(c *Ctx, body []byte) (int, any, *apiErr) {
	var req requestIn
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		return 0, nil, errInvalidJSON("containerType, temperatureMinC and temperatureMaxC are required")
	}
	spec, e := a.parseRequestSpec(&req, true, nil)
	if e != nil {
		return 0, nil, e
	}
	spec.requesterID = c.user.UserID
	if req.RequesterID != nil && *req.RequesterID != "" {
		if a.st.Users[*req.RequesterID] == nil {
			return 0, nil, errNotFound("requester not found")
		}
		spec.requesterID = *req.RequesterID
	}
	switch c.role {
	case RoleNodeHandler, RoleLaboratory:
		if spec.originType != "node" || c.user.AssignedLocationID != spec.originNodeID {
			return 0, nil, E(400, "invalid_holder", "a node or laboratory worker may only register samples held at their assigned location")
		}
	case RoleCollector, RoleCourier:
	default:
		return 0, nil, errForbidden("only the current holder may register a pre-sealed sample")
	}
	if !c.user.Available {
		return 0, nil, E(400, "invalid_holder", "an unavailable worker cannot hold a sample")
	}
	s := a.newSampleFromSpec(c, spec)
	s.Sealed = true
	s.PreSealed = true
	sealedAt := spec.requestedAt
	s.SealedAt = &sealedAt
	s.CurrentHolderID = c.user.UserID
	s.LastCustodyEventAt = &sealedAt
	typ := a.st.SampleTypes[spec.sampleTypeID]
	snap := a.snapshot.Load()
	res := a.evaluateServiceability(snap, spec, nil)
	s.ServiceabilityVersion = snap.Version
	a.st.Samples[s.SampleID] = s
	c.audit("sample.presealed_registered", "sample", s.SampleID, true, map[string]any{
		"requestId": s.RequestID, "holderId": c.user.UserID, "originType": s.OriginType, "originNodeId": s.OriginNodeID, "sampleTypeId": s.SampleTypeID, "status": SampleSealed,
	})
	var j *Journey
	if res.Serviceable {
		s.Serviceability = "serviceable"
		s.ServiceabilityReason = "serviceable"
		s.TargetLaboratoryID = res.Route.LabID
		switch c.role {
		case RoleCourier:
			s.Status = SampleInTransit
		case RoleNodeHandler:
			s.Status = SampleAtNode
		case RoleLaboratory:
			if res.Route.LabID == spec.originNodeID {
				s.Status = SampleAtLaboratory
			} else {
				s.Status = SampleAtNode
			}
		default:
			s.Status = SampleSealed
		}
		j = a.buildJourney(c, s, typ, res.Route, journeyOpts{registrant: c.user, registrantRole: c.role, startAt: spec.requestedAt, fromNode: spec.originType == "node"})
		s.ActiveJourneyID = j.JourneyID
		c.audit("journey.created", "journey", j.JourneyID, true, map[string]any{"sampleId": s.SampleID, "routeMode": j.RouteMode, "path": res.Route.Path, "targetLaboratoryId": j.TargetLaboratoryID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "planVersion": j.PlanVersion, "presealed": true})
		if c.user.LatestLocation != nil {
			s.LatestLocation = c.user.LatestLocation
			s.LocationRecordedAt = c.user.LocationRecordedAt
		}
	} else {
		s.Serviceability = "unserviceable"
		s.ServiceabilityReason = res.Reason
		s.Status = SampleUnserviceable
	}
	c.audit("sample.serviceability_evaluated", "sample", s.SampleID, true, map[string]any{"serviceability": s.Serviceability, "reason": s.ServiceabilityReason, "serviceabilityVersion": snap.Version, "status": s.Status})
	c.u.saveSample(s)
	c.u.event("sample.created", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "requestId": s.RequestID, "status": s.Status, "serviceability": s.Serviceability, "presealed": true}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
	return 201, a.requestResponse(s, j), nil
}

// canSeeSample applies data-level access control for a sample.
func (a *App) canSeeSample(c *Ctx, s *Sample) bool {
	if c.isSupervisor() {
		return true
	}
	if c.hasRole(RoleRequester) && s.RequesterID == c.user.UserID {
		return true
	}
	if s.CurrentHolderID == c.user.UserID {
		return true
	}
	for _, asg := range a.st.Assignments {
		if asg.HasSample(s.SampleID) && (asg.WorkerID == c.user.UserID || asg.OfferedWorkerID == c.user.UserID) {
			return true
		}
	}
	for _, h := range a.st.Handoffs {
		if h.SampleID == s.SampleID && (h.SenderID == c.user.UserID || h.ReceiverID == c.user.UserID) {
			return true
		}
	}
	return false
}

func (a *App) hReadSampleState(c *Ctx, body []byte) (int, any, *apiErr) {
	s := a.st.Samples[c.r.PathValue("sampleId")]
	if s == nil {
		return 0, nil, errNotFound("sample not found")
	}
	if !a.canSeeSample(c, s) {
		return 0, nil, errForbidden("you are not permitted to view this sample")
	}
	return 200, a.sampleStateView(s), nil
}

func (a *App) hReadSampleLifecycle(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID *string `json:"sampleId"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.SampleID == nil {
		return 0, nil, errInvalidJSON("sampleId is required")
	}
	s := a.st.Samples[*req.SampleID]
	if s == nil {
		return 0, nil, errNotFound("sample not found")
	}
	if !a.canSeeSample(c, s) {
		return 0, nil, errForbidden("you are not permitted to view this sample")
	}
	return 200, a.sampleLifecycleView(s), nil
}

func (a *App) hReadJourneyPlan(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		JourneyID *string `json:"journeyId"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.JourneyID == nil {
		return 0, nil, errInvalidJSON("journeyId is required")
	}
	j := a.st.Journeys[*req.JourneyID]
	if j == nil {
		return 0, nil, errNotFound("journey not found")
	}
	if c.isSupervisor() {
		return 200, a.journeyPlanView(j, true), nil
	}
	if c.role == RoleRequester {
		for _, sid := range j.SampleIDs {
			if s := a.st.Samples[sid]; s != nil && s.RequesterID == c.user.UserID {
				return 200, a.requesterJourneyView(j), nil
			}
		}
		return 0, nil, errForbidden("you are not permitted to view this journey")
	}
	mine := []*Assignment{}
	for _, asg := range a.journeyAssignments(j) {
		if asg.WorkerID == c.user.UserID || asg.OfferedWorkerID == c.user.UserID {
			mine = append(mine, asg)
		}
	}
	if len(mine) == 0 {
		return 0, nil, errForbidden("you are not assigned to this journey")
	}
	return 200, a.workerJourneyView(j, mine), nil
}

func (a *App) hListRoleWork(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		Role   *string `json:"role"`
		Status *string `json:"status"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	role := c.role
	if req.Role != nil && *req.Role != "" {
		if !validRole(*req.Role) {
			return 0, nil, E(400, "invalid_role", "unknown role")
		}
		if !contains(c.user.Roles, *req.Role) {
			return 0, nil, errForbidden("the account does not hold this role")
		}
		role = *req.Role
	}
	status := ""
	if req.Status != nil {
		status = *req.Status
	}
	return 200, a.roleWork(c.user, role, status), nil
}

