package app

import (
	"sort"
	"strings"
	"time"
)

func (a *App) isStale(recordedAt *time.Time, now time.Time) bool {
	if recordedAt == nil {
		return true
	}
	return now.Sub(*recordedAt) > a.cfg.StaleLocationAfter
}

func timelineEntry(r *AuditRecord) map[string]any {
	details := r.Details
	if details == nil {
		details = map[string]any{}
	}
	return map[string]any{
		"eventId":    r.ID,
		"action":     r.Action,
		"actorId":    r.ActorID,
		"role":       r.Role,
		"entityType": r.EntityType,
		"entityId":   r.EntityID,
		"success":    r.Success,
		"occurredAt": fmtTime(r.OccurredAt),
		"details":    details,
	}
}

func (a *App) sampleTimeline(sampleID string) []map[string]any {
	out := []map[string]any{}
	for _, r := range a.st.Audit {
		if r.Success && contains(r.SampleIDs, sampleID) {
			out = append(out, timelineEntry(r))
		}
	}
	return out
}

func (a *App) journeyTimeline(journeyID string) []map[string]any {
	out := []map[string]any{}
	for _, r := range a.st.Audit {
		if r.Success && r.JourneyID == journeyID {
			out = append(out, timelineEntry(r))
		}
	}
	return out
}

func (a *App) assignmentTimeline(assignmentID string) []map[string]any {
	out := []map[string]any{}
	for _, r := range a.st.Audit {
		if r.Success && r.AssignmentID == assignmentID {
			out = append(out, timelineEntry(r))
		}
	}
	return out
}

func (a *App) sampleStateView(s *Sample) map[string]any {
	now := time.Now().UTC()
	v := map[string]any{
		"sampleId":                s.SampleID,
		"requestId":               s.RequestID,
		"requesterId":             s.RequesterID,
		"origin":                  coordView(s.Origin),
		"originType":              s.OriginType,
		"requestedAt":             fmtTime(s.RequestedAt),
		"deliveryDeadline":        fmtTime(s.DeliveryDeadline),
		"sampleTypeId":            s.SampleTypeID,
		"containerType":           s.ContainerType,
		"temperatureMinC":         s.TemperatureMinC,
		"temperatureMaxC":         s.TemperatureMaxC,
		"incompatibleSampleTypes": strs(s.IncompatibleSampleTypes),
		"serviceability":          s.Serviceability,
		"activeAssignmentIds":     a.sampleActiveAssignmentIDs(s),
		"state":                   map[string]any{"status": s.Status},
		"timeline":                a.sampleTimeline(s.SampleID),
		"locationStale":           a.isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != "" {
		v["activeJourneyId"] = s.ActiveJourneyID
	}
	if s.TargetLaboratoryID != "" {
		v["targetLaboratoryId"] = s.TargetLaboratoryID
	}
	if s.LatestLocation != nil {
		v["latestLocation"] = coordView(*s.LatestLocation)
	}
	if s.LocationRecordedAt != nil {
		v["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	return v
}

func (a *App) completedLegIDs(s *Sample) []string {
	out := []string{}
	for _, asg := range a.sortedAssignments() {
		if asg.HasSample(s.SampleID) && asg.Kind == KindTransport && asg.Status == AsgCompleted {
			out = append(out, asg.AssignmentID)
		}
	}
	return out
}

func (a *App) sortedAssignments() []*Assignment {
	out := make([]*Assignment, 0, len(a.st.Assignments))
	for _, asg := range a.st.Assignments {
		out = append(out, asg)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		if out[i].Sequence != out[j].Sequence {
			return out[i].Sequence < out[j].Sequence
		}
		return out[i].AssignmentID < out[j].AssignmentID
	})
	return out
}

func (a *App) sampleLifecycleView(s *Sample) map[string]any {
	now := time.Now().UTC()
	replacement := []string{}
	for _, id := range sortedKeys(a.st.Journeys) {
		j := a.st.Journeys[id]
		if j.ParentJourneyID != "" && !j.Terminal() && contains(j.SampleIDs, s.SampleID) {
			replacement = append(replacement, j.JourneyID)
		}
	}
	v := map[string]any{
		"sampleId":                 s.SampleID,
		"status":                   s.Status,
		"sealed":                   s.Sealed,
		"completedLegIds":          a.completedLegIDs(s),
		"activeReplacementPlanIds": replacement,
		"timeline":                 a.sampleTimeline(s.SampleID),
		"locationStale":            a.isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != "" {
		v["activeJourneyId"] = s.ActiveJourneyID
	}
	if s.CurrentHolderID != "" {
		v["currentHolderId"] = s.CurrentHolderID
	}
	if s.ReceivedLaboratoryID != "" {
		v["receivedLaboratoryId"] = s.ReceivedLaboratoryID
	}
	if s.Exception != nil {
		v["exception"] = s.Exception
	}
	if s.PendingHandoffID != "" {
		v["pendingHandoffId"] = s.PendingHandoffID
		if h := a.st.Handoffs[s.PendingHandoffID]; h != nil {
			v["pendingHandoff"] = handoffView(h)
		}
	}
	if s.LatestLocation != nil {
		v["latestLocation"] = coordView(*s.LatestLocation)
	}
	if s.LocationRecordedAt != nil {
		v["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	return v
}

func handoffView(h *Handoff) map[string]any {
	v := map[string]any{
		"handoffId": h.HandoffID, "sampleId": h.SampleID, "journeyId": h.JourneyID, "fromAssignmentId": h.FromAssignmentID, "toAssignmentId": h.ToAssignmentID,
		"senderId": h.SenderID, "receiverId": h.ReceiverID, "status": h.Status, "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed,
		"initiatedAt": fmtTime(h.InitiatedAt),
	}
	if h.ConfirmedAt != nil {
		v["confirmedAt"] = fmtTime(*h.ConfirmedAt)
	}
	return v
}

func stopView(s Stop) map[string]any {
	v := map[string]any{
		"stopId": s.StopID, "locationId": s.LocationID, "stopType": s.StopType, "sequence": s.Sequence, "estimatedAt": fmtTime(s.EstimatedAt), "dwellMinutes": s.DwellMinutes,
	}
	if s.Coordinate != nil {
		v["coordinate"] = coordView(*s.Coordinate)
	}
	if s.CompletedAt != nil {
		v["completedAt"] = fmtTime(*s.CompletedAt)
	}
	return v
}

func (a *App) stopsView(j *Journey) []map[string]any {
	out := []map[string]any{}
	for _, s := range j.Stops {
		sv := stopView(s)
		if s.Coordinate == nil {
			if loc := a.st.Locations[s.LocationID]; loc != nil {
				sv["coordinate"] = coordView(loc.Coordinate)
			}
		}
		out = append(out, sv)
	}
	return out
}

func legView(asg *Assignment, seq int) map[string]any {
	v := map[string]any{"assignmentId": asg.AssignmentID, "sequence": seq, "status": asg.Status}
	if asg.FromLocationID != "" {
		v["fromLocationId"] = asg.FromLocationID
	}
	if asg.ToLocationID != "" {
		v["toLocationId"] = asg.ToLocationID
	}
	if asg.WorkerID != "" {
		v["workerId"] = asg.WorkerID
	}
	if len(asg.SampleIDs) == 1 {
		v["sampleId"] = asg.SampleIDs[0]
	}
	return v
}

func (a *App) legsView(legs []*Assignment) []map[string]any {
	out := []map[string]any{}
	for i, l := range legs {
		out = append(out, legView(l, i+1))
	}
	return out
}

func (a *App) journeyPlanView(j *Journey, nested bool) map[string]any {
	legs := a.journeyLegs(j)
	collection, nodes, labs, workers := []string{}, []string{}, []string{}, []string{}
	for _, asg := range a.journeyAssignments(j) {
		if asg.Status == AsgCancelled {
			continue
		}
		switch asg.Kind {
		case KindCollection:
			collection = append(collection, asg.AssignmentID)
		case KindNode:
			nodes = append(nodes, asg.AssignmentID)
		case KindLaboratory:
			labs = append(labs, asg.AssignmentID)
		}
		if asg.WorkerID != "" && !contains(workers, asg.WorkerID) {
			workers = append(workers, asg.WorkerID)
		}
	}
	used := 0
	for _, r := range a.st.Reservations {
		if !r.Released && r.JourneyID == j.JourneyID {
			used += r.Units
		}
	}
	avail := 0
	if j.TargetLaboratoryID != "" {
		cooled := false
		for _, sid := range j.SampleIDs {
			if s := a.st.Samples[sid]; s != nil {
				if t := a.st.SampleTypes[s.SampleTypeID]; t != nil && t.RequiresCooledRoute {
					cooled = true
				}
			}
		}
		avail = a.availableUnits(j.TargetLaboratoryID, cooled)
		if avail < 0 {
			avail = 0
		}
	}
	v := map[string]any{
		"journeyId":               j.JourneyID,
		"planVersion":             j.PlanVersion,
		"routeMode":               j.RouteMode,
		"status":                  j.Status,
		"estimatedDeliveryAt":     fmtTime(j.EstimatedDeliveryAt),
		"totalCostUnits":          j.TotalCostUnits,
		"capacityUsed":            used,
		"capacityAvailable":       avail,
		"sampleIds":               strs(j.SampleIDs),
		"orderedStops":            a.stopsView(j),
		"legs":                    a.legsView(legs),
		"assignedWorkerIds":       workers,
		"collectionAssignmentIds": collection,
		"nodeAssignmentIds":       nodes,
		"laboratoryAssignmentIds": labs,
		"valid":                   j.Valid,
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	if len(collection) > 0 {
		v["collectionAssignmentId"] = collection[0]
	}
	if len(legs) > 0 {
		v["firstTransportAssignmentId"] = legs[0].AssignmentID
		v["finalTransportAssignmentId"] = legs[len(legs)-1].AssignmentID
		if len(legs) >= 3 {
			v["middleTransportAssignmentId"] = legs[1].AssignmentID
		}
	}
	if j.ReplanStatus != "" {
		v["replanStatus"] = j.ReplanStatus
	}
	if nested {
		if j.SplitJourneyID != "" {
			if sj := a.st.Journeys[j.SplitJourneyID]; sj != nil {
				v["splitJourney"] = a.journeyPlanView(sj, false)
			}
		}
		if j.ReplacementJourneyID != "" {
			if rj := a.st.Journeys[j.ReplacementJourneyID]; rj != nil {
				v["replacementJourney"] = a.journeyPlanView(rj, false)
			}
		}
	}
	return v
}

func (a *App) requesterJourneyView(j *Journey) map[string]any {
	legs := []map[string]any{}
	for i, l := range a.journeyLegs(j) {
		lv := map[string]any{"sequence": i + 1, "status": l.Status}
		if l.FromLocationID != "" {
			lv["fromLocationId"] = l.FromLocationID
		}
		if l.ToLocationID != "" {
			lv["toLocationId"] = l.ToLocationID
		}
		legs = append(legs, lv)
	}
	v := map[string]any{
		"journeyId":           j.JourneyID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt),
		"totalCostUnits":      j.TotalCostUnits,
		"sampleIds":           strs(j.SampleIDs),
		"orderedStops":        a.stopsView(j),
		"legs":                legs,
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	return v
}

func (a *App) workerJourneyView(j *Journey, mine []*Assignment) map[string]any {
	ids := []string{}
	legs := []map[string]any{}
	sampleIDs := []string{}
	stopLocs := map[string]bool{}
	for i, asg := range mine {
		ids = append(ids, asg.AssignmentID)
		legs = append(legs, legView(asg, i+1))
		for _, sid := range asg.SampleIDs {
			if !contains(sampleIDs, sid) {
				sampleIDs = append(sampleIDs, sid)
			}
		}
		for _, l := range []string{asg.FromLocationID, asg.ToLocationID, asg.NodeID, asg.LaboratoryID} {
			if l != "" {
				stopLocs[l] = true
			}
		}
	}
	stops := []map[string]any{}
	for _, s := range j.Stops {
		if stopLocs[s.LocationID] {
			sv := stopView(s)
			if s.Coordinate == nil {
				if loc := a.st.Locations[s.LocationID]; loc != nil {
					sv["coordinate"] = coordView(loc.Coordinate)
				}
			}
			stops = append(stops, sv)
		}
	}
	v := map[string]any{
		"journeyId":           j.JourneyID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt),
		"scope":               "assigned_legs",
		"assignmentIds":       ids,
		"sampleIds":           sampleIDs,
		"legs":                legs,
		"orderedStops":        stops,
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	return v
}

