func (a *App) roleWork(user *User, role string, statusFilter string) map[string]any {
	pending, inProgress, completed := []any{}, []any{}, []any{}
	add := func(bucket *[]any, status string, item map[string]any) {
		if statusFilter != "" && !strings.EqualFold(statusFilter, status) {
			return
		}
		*bucket = append(*bucket, item)
	}
	switch role {
	case RoleRequester:
		for _, id := range sortedKeys(a.st.Samples) {
			s := a.st.Samples[id]
			if s.RequesterID != user.UserID {
				continue
			}
			item := a.sampleWorkItem(s)
			switch s.Status {
			case SampleRequested:
				add(&pending, s.Status, item)
			case SampleReceived, SampleException, SampleExpired, SampleCancelled, SampleUnserviceable:
				add(&completed, s.Status, item)
			default:
				add(&inProgress, s.Status, item)
			}
		}
	case RoleDispatcher, RoleAdministrator:
		for _, j := range a.sortedJourneys() {
			item := a.journeyWorkItem(j)
			switch j.Status {
			case JourneyPlanned:
				add(&pending, j.Status, item)
			case JourneyActive:
				add(&inProgress, j.Status, item)
			default:
				add(&completed, j.Status, item)
			}
		}
	default:
		kind := ""
		for k, r := range map[string]string{KindCollection: RoleCollector, KindTransport: RoleCourier, KindNode: RoleNodeHandler, KindLaboratory: RoleLaboratory} {
			if r == role {
				kind = k
			}
		}
		for _, asg := range a.sortedAssignments() {
			if asg.Kind != kind {
				continue
			}
			mine := asg.WorkerID == user.UserID || (asg.WorkerID == "" && asg.OfferedWorkerID == user.UserID)
			if !mine {
				continue
			}
			item := a.assignmentWorkItem(asg)
			switch asg.Status {
			case AsgPending:
				add(&pending, asg.Status, item)
			case AsgCompleted, AsgCancelled, AsgException:
				add(&completed, asg.Status, item)
			default:
				add(&inProgress, asg.Status, item)
			}
		}
	}
	return map[string]any{"pending": pending, "inProgress": inProgress, "completed": completed}
}

func (a *App) sortedJourneys() []*Journey {
	out := make([]*Journey, 0, len(a.st.Journeys))
	for _, j := range a.st.Journeys {
		out = append(out, j)
	}
	sort.Slice(out, func(i, k int) bool {
		if !out[i].CreatedAt.Equal(out[k].CreatedAt) {
			return out[i].CreatedAt.Before(out[k].CreatedAt)
		}
		return out[i].JourneyID < out[k].JourneyID
	})
	return out
}

// --- operations state -------------------------------------------------------

func (a *App) operationsState(sampleTypeFilter string) map[string]any {
	now := time.Now().UTC()
	samples := []any{}
	exceptions := []any{}
	delays := []any{}
	for _, id := range sortedKeys(a.st.Samples) {
		s := a.st.Samples[id]
		if sampleTypeFilter != "" && s.SampleTypeID != sampleTypeFilter {
			continue
		}
		sv := map[string]any{
			"sampleId":         s.SampleID,
			"status":           s.Status,
			"requestId":        s.RequestID,
			"origin":           coordView(s.Origin),
			"deliveryDeadline": fmtTime(s.DeliveryDeadline),
			"locationStale":    a.isStale(s.LocationRecordedAt, now),
		}
		if s.CurrentHolderID != "" {
			sv["currentHolderId"] = s.CurrentHolderID
		}
		if s.ActiveJourneyID != "" {
			sv["activeJourneyId"] = s.ActiveJourneyID
		}
		if s.LatestLocation != nil {
			sv["latestLocation"] = coordView(*s.LatestLocation)
		}
		if s.LocationRecordedAt != nil {
			sv["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
		}
		samples = append(samples, sv)
		if s.Exception != nil {
			exceptions = append(exceptions, map[string]any{"sampleId": s.SampleID, "status": s.Status, "exception": s.Exception, "journeyId": s.ActiveJourneyID, "sampleTypeId": s.SampleTypeID})
		}
		if j := a.st.Journeys[s.ActiveJourneyID]; j != nil && !j.Terminal() && !s.Terminal() {
			if j.EstimatedDeliveryAt.After(s.DeliveryDeadline) {
				delays = append(delays, map[string]any{"sampleId": s.SampleID, "journeyId": j.JourneyID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "deliveryDeadline": fmtTime(s.DeliveryDeadline), "reason": "estimated_after_deadline"})
			} else if now.After(s.DeliveryDeadline) {
				delays = append(delays, map[string]any{"sampleId": s.SampleID, "journeyId": j.JourneyID, "deliveryDeadline": fmtTime(s.DeliveryDeadline), "reason": "deadline_passed"})
			}
		}
	}
	workers := []any{}
	minCount, maxCount := -1, 0
	for _, id := range sortedKeys(a.st.Users) {
		w := a.st.Users[id]
		isWorker := false
		for _, r := range WorkerRoles {
			if contains(w.Roles, r) {
				isWorker = true
			}
		}
		if !isWorker {
			continue
		}
		count := a.workerActiveAssignmentCount(w.UserID)
		if minCount < 0 || count < minCount {
			minCount = count
		}
		if count > maxCount {
			maxCount = count
		}
		status := "available"
		if !w.Available || !w.Active {
			status = "unavailable"
		}
		wv := map[string]any{
			"workerId":        w.UserID,
			"roles":           strs(w.Roles),
			"available":       w.Available && w.Active,
			"status":          status,
			"capacityUnits":   w.CapacityUnits,
			"assignmentCount": count,
			"locationStale":   a.isStale(w.LocationRecordedAt, now),
		}
		if w.FullName != "" {
			wv["fullName"] = w.FullName
		}
		if w.LatestLocation != nil {
			wv["latestLocation"] = coordView(*w.LatestLocation)
		}
		if w.LocationRecordedAt != nil {
			wv["locationRecordedAt"] = fmtTime(*w.LocationRecordedAt)
		}
		workers = append(workers, wv)
	}
	if minCount < 0 {
		minCount = 0
	}
	locations := []any{}
	for _, id := range sortedKeys(a.st.Locations) {
		l := a.st.Locations[id]
		accepted := []string{}
		for _, tid := range sortedKeys(l.AcceptedTypes) {
			if l.AcceptedTypes[tid] {
				accepted = append(accepted, tid)
			}
		}
		locations = append(locations, map[string]any{
			"id": l.LocationID, "locationId": l.LocationID, "name": l.Name, "coordinate": coordView(l.Coordinate), "active": l.Active,
			"coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes, "functions": functionsView(l.Functions),
			"capacity": a.capacityView(l.LocationID), "acceptedSampleTypeIds": accepted,
		})
	}
	connections := []any{}
	for _, id := range sortedKeys(a.st.Connections) {
		c := a.st.Connections[id]
		connections = append(connections, map[string]any{
			"id": c.ConnectionID, "connectionId": c.ConnectionID, "fromLocationId": c.FromLocationID, "toLocationId": c.ToLocationID,
			"travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active, "capacity": a.capacityView(c.ConnectionID),
		})
	}
	routes := []any{}
	for _, j := range a.sortedJourneys() {
		if sampleTypeFilter != "" {
			match := false
			for _, sid := range j.SampleIDs {
				if s := a.st.Samples[sid]; s != nil && s.SampleTypeID == sampleTypeFilter {
					match = true
				}
			}
			if !match {
				continue
			}
		}
		locs := []string{}
		for _, st := range j.Stops {
			locs = append(locs, st.LocationID)
		}
		routes = append(routes, map[string]any{
			"journeyId": j.JourneyID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": strs(j.SampleIDs),
			"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "targetLaboratoryId": j.TargetLaboratoryID, "stopLocationIds": locs,
			"legs": a.legsView(a.journeyLegs(j)), "orderedStops": a.stopsView(j), "active": !j.Terminal(),
		})
	}
	handoffs := []any{}
	for _, id := range sortedKeys(a.st.Handoffs) {
		h := a.st.Handoffs[id]
		if sampleTypeFilter != "" {
			if s := a.st.Samples[h.SampleID]; s == nil || s.SampleTypeID != sampleTypeFilter {
				continue
			}
		}
		handoffs = append(handoffs, handoffView(h))
	}
	ineligible := 0
	for _, asg := range a.st.Assignments {
		if !asg.Active() {
			continue
		}
		wid := asg.WorkerID
		if wid == "" {
			wid = asg.OfferedWorkerID
		}
		if wid == "" {
			if asg.Status == AsgPending {
				ineligible++
			}
			continue
		}
		w := a.st.Users[wid]
		if w == nil {
			ineligible++
			continue
		}
		if ok, _ := a.potentiallyEligible(w, asg, now); !ok {
			ineligible++
		}
	}
	return map[string]any{
		"samples":                  samples,
		"workers":                  workers,
		"locations":                locations,
		"connections":              connections,
		"routes":                   routes,
		"handoffs":                 handoffs,
		"delays":                   delays,
		"exceptions":               exceptions,
		"assignmentCountSpread":    maxCount - minCount,
		"ineligibleAssignmentCount": ineligible,
	}
}

