package app

import (
	"sort"
	"strings"
	"time"
)

func (a *App) isStale(recordedAt *time.Time, now time.Time) bool {
	if recordedAt == nil {
		return true
	}
	return now.Sub(*recordedAt) > a.cfg.StaleLocationAfter
}

func timelineEntry(r *AuditRecord) map[string]any {
	details := r.Details
	if details == nil {
		details = map[string]any{}
	}
	return map[string]any{
		"eventId":    r.ID,
		"action":     r.Action,
		"actorId":    r.ActorID,
		"role":       r.Role,
		"entityType": r.EntityType,
		"entityId":   r.EntityID,
		"success":    r.Success,
		"occurredAt": fmtTime(r.OccurredAt),
		"details":    details,
	}
}

func (a *App) sampleTimeline(sampleID string) []map[string]any {
	out := []map[string]any{}
	for _, r := range a.st.Audit {
		if r.Success && contains(r.SampleIDs, sampleID) {
			out = append(out, timelineEntry(r))
		}
	}
	return out
}

func (a *App) journeyTimeline(journeyID string) []map[string]any {
	out := []map[string]any{}
	for _, r := range a.st.Audit {
		if r.Success && r.JourneyID == journeyID {
			out = append(out, timelineEntry(r))
		}
	}
	return out
}

func (a *App) assignmentTimeline(assignmentID string) []map[string]any {
	out := []map[string]any{}
	for _, r := range a.st.Audit {
		if r.Success && r.AssignmentID == assignmentID {
			out = append(out, timelineEntry(r))
		}
	}
	return out
}

func (a *App) sampleStateView(s *Sample) map[string]any {
	now := time.Now().UTC()
	v := map[string]any{
		"sampleId":                s.SampleID,
		"requestId":               s.RequestID,
		"requesterId":             s.RequesterID,
		"origin":                  coordView(s.Origin),
		"originType":              s.OriginType,
		"requestedAt":             fmtTime(s.RequestedAt),
		"deliveryDeadline":        fmtTime(s.DeliveryDeadline),
		"sampleTypeId":            s.SampleTypeID,
		"containerType":           s.ContainerType,
		"temperatureMinC":         s.TemperatureMinC,
		"temperatureMaxC":         s.TemperatureMaxC,
		"incompatibleSampleTypes": strs(s.IncompatibleSampleTypes),
		"serviceability":          s.Serviceability,
		"activeAssignmentIds":     a.sampleActiveAssignmentIDs(s),
		"state":                   map[string]any{"status": s.Status},
		"timeline":                a.sampleTimeline(s.SampleID),
		"locationStale":           a.isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != "" {
		v["activeJourneyId"] = s.ActiveJourneyID
	}
	if s.TargetLaboratoryID != "" {
		v["targetLaboratoryId"] = s.TargetLaboratoryID
	}
	if s.LatestLocation != nil {
		v["latestLocation"] = coordView(*s.LatestLocation)
	}
	if s.LocationRecordedAt != nil {
		v["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	return v
}

func (a *App) completedLegIDs(s *Sample) []string {
	out := []string{}
	for _, asg := range a.sortedAssignments() {
		if asg.HasSample(s.SampleID) && asg.Kind == KindTransport && asg.Status == AsgCompleted {
			out = append(out, asg.AssignmentID)
		}
	}
	return out
}

func (a *App) sortedAssignments() []*Assignment {
	out := make([]*Assignment, 0, len(a.st.Assignments))
	for _, asg := range a.st.Assignments {
		out = append(out, asg)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		if out[i].Sequence != out[j].Sequence {
			return out[i].Sequence < out[j].Sequence
		}
		return out[i].AssignmentID < out[j].AssignmentID
	})
	return out
}

func (a *App) sampleLifecycleView(s *Sample) map[string]any {
	now := time.Now().UTC()
	replacement := []string{}
	for _, id := range sortedKeys(a.st.Journeys) {
		j := a.st.Journeys[id]
		if j.ParentJourneyID != "" && !j.Terminal() && contains(j.SampleIDs, s.SampleID) {
			replacement = append(replacement, j.JourneyID)
		}
	}
	v := map[string]any{
		"sampleId":                 s.SampleID,
		"status":                   s.Status,
		"sealed":                   s.Sealed,
		"completedLegIds":          a.completedLegIDs(s),
		"activeReplacementPlanIds": replacement,
		"timeline":                 a.sampleTimeline(s.SampleID),
		"locationStale":            a.isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != "" {
		v["activeJourneyId"] = s.ActiveJourneyID
	}
	if s.CurrentHolderID != "" {
		v["currentHolderId"] = s.CurrentHolderID
	}
	if s.ReceivedLaboratoryID != "" {
		v["receivedLaboratoryId"] = s.ReceivedLaboratoryID
	}
	if s.Exception != nil {
		v["exception"] = s.Exception
	}
	if s.PendingHandoffID != "" {
		v["pendingHandoffId"] = s.PendingHandoffID
		if h := a.st.Handoffs[s.PendingHandoffID]; h != nil {
			v["pendingHandoff"] = handoffView(h)
		}
	}
	if s.LatestLocation != nil {
		v["latestLocation"] = coordView(*s.LatestLocation)
	}
	if s.LocationRecordedAt != nil {
		v["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	return v
}

func handoffView(h *Handoff) map[string]any {
	v := map[string]any{
		"handoffId": h.HandoffID, "sampleId": h.SampleID, "journeyId": h.JourneyID, "fromAssignmentId": h.FromAssignmentID, "toAssignmentId": h.ToAssignmentID,
		"senderId": h.SenderID, "receiverId": h.ReceiverID, "status": h.Status, "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed,
		"initiatedAt": fmtTime(h.InitiatedAt),
	}
	if h.ConfirmedAt != nil {
		v["confirmedAt"] = fmtTime(*h.ConfirmedAt)
	}
	return v
}

func stopView(s Stop) map[string]any {
	v := map[string]any{
		"stopId": s.StopID, "locationId": s.LocationID, "stopType": s.StopType, "sequence": s.Sequence, "estimatedAt": fmtTime(s.EstimatedAt), "dwellMinutes": s.DwellMinutes,
	}
	if s.Coordinate != nil {
		v["coordinate"] = coordView(*s.Coordinate)
	}
	if s.CompletedAt != nil {
		v["completedAt"] = fmtTime(*s.CompletedAt)
	}
	return v
}

func (a *App) stopsView(j *Journey) []map[string]any {
	out := []map[string]any{}
	for _, s := range j.Stops {
		sv := stopView(s)
		if s.Coordinate == nil {
			if loc := a.st.Locations[s.LocationID]; loc != nil {
				sv["coordinate"] = coordView(loc.Coordinate)
			}
		}
		out = append(out, sv)
	}
	return out
}

func legView(asg *Assignment, seq int) map[string]any {
	v := map[string]any{"assignmentId": asg.AssignmentID, "sequence": seq, "status": asg.Status}
	if asg.FromLocationID != "" {
		v["fromLocationId"] = asg.FromLocationID
	}
	if asg.ToLocationID != "" {
		v["toLocationId"] = asg.ToLocationID
	}
	if asg.WorkerID != "" {
		v["workerId"] = asg.WorkerID
	}
	if len(asg.SampleIDs) == 1 {
		v["sampleId"] = asg.SampleIDs[0]
	}
	return v
}

func (a *App) legsView(legs []*Assignment) []map[string]any {
	out := []map[string]any{}
	for i, l := range legs {
		out = append(out, legView(l, i+1))
	}
	return out
}

func (a *App) journeyPlanView(j *Journey, nested bool) map[string]any {
	legs := a.journeyLegs(j)
	collection, nodes, labs, workers := []string{}, []string{}, []string{}, []string{}
	for _, asg := range a.journeyAssignments(j) {
		if asg.Status == AsgCancelled {
			continue
		}
		switch asg.Kind {
		case KindCollection:
			collection = append(collection, asg.AssignmentID)
		case KindNode:
			nodes = append(nodes, asg.AssignmentID)
		case KindLaboratory:
			labs = append(labs, asg.AssignmentID)
		}
		if asg.WorkerID != "" && !contains(workers, asg.WorkerID) {
			workers = append(workers, asg.WorkerID)
		}
	}
	used := 0
	for _, r := range a.st.Reservations {
		if !r.Released && r.JourneyID == j.JourneyID {
			used += r.Units
		}
	}
	avail := 0
	if j.TargetLaboratoryID != "" {
		cooled := false
		for _, sid := range j.SampleIDs {
			if s := a.st.Samples[sid]; s != nil {
				if t := a.st.SampleTypes[s.SampleTypeID]; t != nil && t.RequiresCooledRoute {
					cooled = true
				}
			}
		}
		avail = a.availableUnits(j.TargetLaboratoryID, cooled)
		if avail < 0 {
			avail = 0
		}
	}
	v := map[string]any{
		"journeyId":               j.JourneyID,
		"planVersion":             j.PlanVersion,
		"routeMode":               j.RouteMode,
		"status":                  j.Status,
		"estimatedDeliveryAt":     fmtTime(j.EstimatedDeliveryAt),
		"totalCostUnits":          j.TotalCostUnits,
		"capacityUsed":            used,
		"capacityAvailable":       avail,
		"sampleIds":               strs(j.SampleIDs),
		"orderedStops":            a.stopsView(j),
		"legs":                    a.legsView(legs),
		"assignedWorkerIds":       workers,
		"collectionAssignmentIds": collection,
		"nodeAssignmentIds":       nodes,
		"laboratoryAssignmentIds": labs,
		"valid":                   j.Valid,
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	if len(collection) > 0 {
		v["collectionAssignmentId"] = collection[0]
	}
	if len(legs) > 0 {
		v["firstTransportAssignmentId"] = legs[0].AssignmentID
		v["finalTransportAssignmentId"] = legs[len(legs)-1].AssignmentID
		if len(legs) >= 3 {
			v["middleTransportAssignmentId"] = legs[1].AssignmentID
		}
	}
	if j.ReplanStatus != "" {
		v["replanStatus"] = j.ReplanStatus
	}
	if nested {
		if j.SplitJourneyID != "" {
			if sj := a.st.Journeys[j.SplitJourneyID]; sj != nil {
				v["splitJourney"] = a.journeyPlanView(sj, false)
			}
		}
		if j.ReplacementJourneyID != "" {
			if rj := a.st.Journeys[j.ReplacementJourneyID]; rj != nil {
				v["replacementJourney"] = a.journeyPlanView(rj, false)
			}
		}
	}
	return v
}

func (a *App) requesterJourneyView(j *Journey) map[string]any {
	legs := []map[string]any{}
	for i, l := range a.journeyLegs(j) {
		lv := map[string]any{"sequence": i + 1, "status": l.Status}
		if l.FromLocationID != "" {
			lv["fromLocationId"] = l.FromLocationID
		}
		if l.ToLocationID != "" {
			lv["toLocationId"] = l.ToLocationID
		}
		legs = append(legs, lv)
	}
	v := map[string]any{
		"journeyId":           j.JourneyID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt),
		"totalCostUnits":      j.TotalCostUnits,
		"sampleIds":           strs(j.SampleIDs),
		"orderedStops":        a.stopsView(j),
		"legs":                legs,
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	return v
}

func (a *App) workerJourneyView(j *Journey, mine []*Assignment) map[string]any {
	ids := []string{}
	legs := []map[string]any{}
	sampleIDs := []string{}
	stopLocs := map[string]bool{}
	for i, asg := range mine {
		ids = append(ids, asg.AssignmentID)
		legs = append(legs, legView(asg, i+1))
		for _, sid := range asg.SampleIDs {
			if !contains(sampleIDs, sid) {
				sampleIDs = append(sampleIDs, sid)
			}
		}
		for _, l := range []string{asg.FromLocationID, asg.ToLocationID, asg.NodeID, asg.LaboratoryID} {
			if l != "" {
				stopLocs[l] = true
			}
		}
	}
	stops := []map[string]any{}
	for _, s := range j.Stops {
		if stopLocs[s.LocationID] {
			sv := stopView(s)
			if s.Coordinate == nil {
				if loc := a.st.Locations[s.LocationID]; loc != nil {
					sv["coordinate"] = coordView(loc.Coordinate)
				}
			}
			stops = append(stops, sv)
		}
	}
	v := map[string]any{
		"journeyId":           j.JourneyID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt),
		"scope":               "assigned_legs",
		"assignmentIds":       ids,
		"sampleIds":           sampleIDs,
		"legs":                legs,
		"orderedStops":        stops,
	}
	if j.ParentJourneyID != "" {
		v["parentJourneyId"] = j.ParentJourneyID
	}
	return v
}

// --- role work -------------------------------------------------------------

func (a *App) sampleWorkItem(s *Sample) map[string]any {
	now := time.Now().UTC()
	v := map[string]any{
		"kind":             "sample",
		"sampleId":         s.SampleID,
		"requestId":        s.RequestID,
		"status":           s.Status,
		"serviceability":   s.Serviceability,
		"requestedAt":      fmtTime(s.RequestedAt),
		"deliveryDeadline": fmtTime(s.DeliveryDeadline),
		"earliestCollectionAt": fmtTime(s.EarliestCollectionAt),
		"latestCollectionAt":   fmtTime(s.LatestCollectionAt),
		"requesterId":      s.RequesterID,
		"history":          a.sampleTimeline(s.SampleID),
		"locationStale":    a.isStale(s.LocationRecordedAt, now),
	}
	if s.ActiveJourneyID != "" {
		v["journeyId"] = s.ActiveJourneyID
		v["activeJourneyId"] = s.ActiveJourneyID
	}
	if s.TargetLaboratoryID != "" {
		v["laboratoryId"] = s.TargetLaboratoryID
	}
	if s.CurrentHolderID != "" {
		v["currentHolderId"] = s.CurrentHolderID
	}
	if s.LocationRecordedAt != nil {
		v["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	return v
}

func (a *App) journeyWorkItem(j *Journey) map[string]any {
	count := 0
	for _, asg := range a.journeyAssignments(j) {
		if asg.Status != AsgCancelled {
			count++
		}
	}
	return map[string]any{
		"kind":                "journey",
		"journeyId":           j.JourneyID,
		"status":              j.Status,
		"routeMode":           j.RouteMode,
		"planVersion":         j.PlanVersion,
		"sampleIds":           strs(j.SampleIDs),
		"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt),
		"assignmentCount":     count,
		"history":             a.journeyTimeline(j.JourneyID),
	}
}

func (a *App) assignmentWorkItem(asg *Assignment) map[string]any {
	v := map[string]any{
		"kind":         asg.Kind,
		"assignmentId": asg.AssignmentID,
		"sampleId":     firstOf(asg.SampleIDs),
		"status":       asg.Status,
		"journeyId":    asg.JourneyID,
		"sequence":     asg.Sequence,
		"history":      a.assignmentTimeline(asg.AssignmentID),
	}
	if asg.FromLocationID != "" {
		v["fromLocationId"] = asg.FromLocationID
	}
	if asg.ToLocationID != "" {
		v["toLocationId"] = asg.ToLocationID
	}
	if asg.OfferExpiresAt != nil && asg.Status == AsgPending {
		v["offerExpiresAt"] = fmtTime(*asg.OfferExpiresAt)
	}
	switch asg.Kind {
	case KindTransport:
		if asg.ToLocationID != "" && a.st.Locations[asg.ToLocationID] != nil {
			v["destinationCapacity"] = a.capacityView(asg.ToLocationID)
		}
	case KindNode:
		v["nodeId"] = asg.NodeID
		if asg.FromLocationID != "" {
			v["incomingFromLocationId"] = asg.FromLocationID
		}
		if asg.ToLocationID != "" {
			v["outgoingToLocationId"] = asg.ToLocationID
		}
		v["destinationCapacity"] = a.capacityView(asg.NodeID)
	case KindLaboratory:
		v["laboratoryId"] = asg.LaboratoryID
		v["destinationCapacity"] = a.capacityView(asg.LaboratoryID)
		if s := a.st.Samples[firstOf(asg.SampleIDs)]; s != nil {
			v["expectedSampleTypeId"] = s.SampleTypeID
		}
	}
	return v
}

func (a *App) roleWork(user *User, role string, statusFilter string) map[string]any {
	pending, inProgress, completed := []any{}, []any{}, []any{}
	add := func(bucket *[]any, status string, item map[string]any) {
		if statusFilter != "" && !strings.EqualFold(statusFilter, status) {
			return
		}
		*bucket = append(*bucket, item)
	}
	switch role {
	case RoleRequester:
		for _, id := range sortedKeys(a.st.Samples) {
			s := a.st.Samples[id]
			if s.RequesterID != user.UserID {
				continue
			}
			item := a.sampleWorkItem(s)
			switch s.Status {
			case SampleRequested:
				add(&pending, s.Status, item)
			case SampleReceived, SampleException, SampleExpired, SampleCancelled, SampleUnserviceable:
				add(&completed, s.Status, item)
			default:
				add(&inProgress, s.Status, item)
			}
		}
	case RoleDispatcher, RoleAdministrator:
		for _, j := range a.sortedJourneys() {
			item := a.journeyWorkItem(j)
			switch j.Status {
			case JourneyPlanned:
				add(&pending, j.Status, item)
			case JourneyActive:
				add(&inProgress, j.Status, item)
			default:
				add(&completed, j.Status, item)
			}
		}
	default:
		kind := ""
		for k, r := range map[string]string{KindCollection: RoleCollector, KindTransport: RoleCourier, KindNode: RoleNodeHandler, KindLaboratory: RoleLaboratory} {
			if r == role {
				kind = k
			}
		}
		for _, asg := range a.sortedAssignments() {
			if asg.Kind != kind {
				continue
			}
			mine := asg.WorkerID == user.UserID || (asg.WorkerID == "" && asg.OfferedWorkerID == user.UserID)
			if !mine {
				continue
			}
			item := a.assignmentWorkItem(asg)
			switch asg.Status {
			case AsgPending:
				add(&pending, asg.Status, item)
			case AsgCompleted, AsgCancelled, AsgException:
				add(&completed, asg.Status, item)
			default:
				add(&inProgress, asg.Status, item)
			}
		}
	}
	return map[string]any{"pending": pending, "inProgress": inProgress, "completed": completed}
}

func (a *App) sortedJourneys() []*Journey {
	out := make([]*Journey, 0, len(a.st.Journeys))
	for _, j := range a.st.Journeys {
		out = append(out, j)
	}
	sort.Slice(out, func(i, k int) bool {
		if !out[i].CreatedAt.Equal(out[k].CreatedAt) {
			return out[i].CreatedAt.Before(out[k].CreatedAt)
		}
		return out[i].JourneyID < out[k].JourneyID
	})
	return out
}

// --- operations state -------------------------------------------------------

func (a *App) operationsState(sampleTypeFilter string) map[string]any {
	now := time.Now().UTC()
	samples := []any{}
	exceptions := []any{}
	delays := []any{}
	for _, id := range sortedKeys(a.st.Samples) {
		s := a.st.Samples[id]
		if sampleTypeFilter != "" && s.SampleTypeID != sampleTypeFilter {
			continue
		}
		sv := map[string]any{
			"sampleId":         s.SampleID,
			"status":           s.Status,
			"requestId":        s.RequestID,
			"origin":           coordView(s.Origin),
			"deliveryDeadline": fmtTime(s.DeliveryDeadline),
			"locationStale":    a.isStale(s.LocationRecordedAt, now),
		}
		if s.CurrentHolderID != "" {
			sv["currentHolderId"] = s.CurrentHolderID
		}
		if s.ActiveJourneyID != "" {
			sv["activeJourneyId"] = s.ActiveJourneyID
		}
		if s.LatestLocation != nil {
			sv["latestLocation"] = coordView(*s.LatestLocation)
		}
		if s.LocationRecordedAt != nil {
			sv["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
		}
		samples = append(samples, sv)
		if s.Exception != nil {
			exceptions = append(exceptions, map[string]any{"sampleId": s.SampleID, "status": s.Status, "exception": s.Exception, "journeyId": s.ActiveJourneyID, "sampleTypeId": s.SampleTypeID})
		}
		if j := a.st.Journeys[s.ActiveJourneyID]; j != nil && !j.Terminal() && !s.Terminal() {
			if j.EstimatedDeliveryAt.After(s.DeliveryDeadline) {
				delays = append(delays, map[string]any{"sampleId": s.SampleID, "journeyId": j.JourneyID, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "deliveryDeadline": fmtTime(s.DeliveryDeadline), "reason": "estimated_after_deadline"})
			} else if now.After(s.DeliveryDeadline) {
				delays = append(delays, map[string]any{"sampleId": s.SampleID, "journeyId": j.JourneyID, "deliveryDeadline": fmtTime(s.DeliveryDeadline), "reason": "deadline_passed"})
			}
		}
	}
	workers := []any{}
	minCount, maxCount := -1, 0
	for _, id := range sortedKeys(a.st.Users) {
		w := a.st.Users[id]
		isWorker := false
		for _, r := range WorkerRoles {
			if contains(w.Roles, r) {
				isWorker = true
			}
		}
		if !isWorker {
			continue
		}
		count := a.workerActiveAssignmentCount(w.UserID)
		if minCount < 0 || count < minCount {
			minCount = count
		}
		if count > maxCount {
			maxCount = count
		}
		status := "available"
		if !w.Available || !w.Active {
			status = "unavailable"
		}
		wv := map[string]any{
			"workerId":        w.UserID,
			"roles":           strs(w.Roles),
			"available":       w.Available && w.Active,
			"status":          status,
			"capacityUnits":   w.CapacityUnits,
			"assignmentCount": count,
			"locationStale":   a.isStale(w.LocationRecordedAt, now),
		}
		if w.FullName != "" {
			wv["fullName"] = w.FullName
		}
		if w.LatestLocation != nil {
			wv["latestLocation"] = coordView(*w.LatestLocation)
		}
		if w.LocationRecordedAt != nil {
			wv["locationRecordedAt"] = fmtTime(*w.LocationRecordedAt)
		}
		workers = append(workers, wv)
	}
	if minCount < 0 {
		minCount = 0
	}
	locations := []any{}
	for _, id := range sortedKeys(a.st.Locations) {
		l := a.st.Locations[id]
		accepted := []string{}
		for _, tid := range sortedKeys(l.AcceptedTypes) {
			if l.AcceptedTypes[tid] {
				accepted = append(accepted, tid)
			}
		}
		locations = append(locations, map[string]any{
			"id": l.LocationID, "locationId": l.LocationID, "name": l.Name, "coordinate": coordView(l.Coordinate), "active": l.Active,
			"coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes, "functions": functionsView(l.Functions),
			"capacity": a.capacityView(l.LocationID), "acceptedSampleTypeIds": accepted,
		})
	}
	connections := []any{}
	for _, id := range sortedKeys(a.st.Connections) {
		c := a.st.Connections[id]
		connections = append(connections, map[string]any{
			"id": c.ConnectionID, "connectionId": c.ConnectionID, "fromLocationId": c.FromLocationID, "toLocationId": c.ToLocationID,
			"travelMinutes": c.TravelMinutes, "costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active, "capacity": a.capacityView(c.ConnectionID),
		})
	}
	routes := []any{}
	for _, j := range a.sortedJourneys() {
		if sampleTypeFilter != "" {
			match := false
			for _, sid := range j.SampleIDs {
				if s := a.st.Samples[sid]; s != nil && s.SampleTypeID == sampleTypeFilter {
					match = true
				}
			}
			if !match {
				continue
			}
		}
		locs := []string{}
		for _, st := range j.Stops {
			locs = append(locs, st.LocationID)
		}
		routes = append(routes, map[string]any{
			"journeyId": j.JourneyID, "status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion, "sampleIds": strs(j.SampleIDs),
			"estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "targetLaboratoryId": j.TargetLaboratoryID, "stopLocationIds": locs,
			"legs": a.legsView(a.journeyLegs(j)), "orderedStops": a.stopsView(j), "active": !j.Terminal(),
		})
	}
	handoffs := []any{}
	for _, id := range sortedKeys(a.st.Handoffs) {
		h := a.st.Handoffs[id]
		if sampleTypeFilter != "" {
			if s := a.st.Samples[h.SampleID]; s == nil || s.SampleTypeID != sampleTypeFilter {
				continue
			}
		}
		handoffs = append(handoffs, handoffView(h))
	}
	ineligible := 0
	for _, asg := range a.st.Assignments {
		if !asg.Active() {
			continue
		}
		wid := asg.WorkerID
		if wid == "" {
			wid = asg.OfferedWorkerID
		}
		if wid == "" {
			if asg.Status == AsgPending {
				ineligible++
			}
			continue
		}
		w := a.st.Users[wid]
		if w == nil {
			ineligible++
			continue
		}
		if ok, _ := a.potentiallyEligible(w, asg, now); !ok {
			ineligible++
		}
	}
	return map[string]any{
		"samples":                  samples,
		"workers":                  workers,
		"locations":                locations,
		"connections":              connections,
		"routes":                   routes,
		"handoffs":                 handoffs,
		"delays":                   delays,
		"exceptions":               exceptions,
		"assignmentCountSpread":    maxCount - minCount,
		"ineligibleAssignmentCount": ineligible,
	}
}

