package app

import (
	"strings"
	"time"
)

func (a *App) markJourneyActive(u *UoW, j *Journey, c *Ctx) {
	if j.Status == JourneyPlanned {
		j.Status = JourneyActive
		u.saveJourney(j)
		u.audit(c.actorID(), roleOrNone(c.role), "journey.status_changed", "journey", j.JourneyID, true, map[string]any{"status": j.Status, "sampleIds": j.SampleIDs})
		u.event("journey.updated", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID, "status": j.Status, "planVersion": j.PlanVersion}, []string{RoleAdministrator, RoleDispatcher}, nil)
	}
}

func (a *App) hAcceptAssignment(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		AssignmentID *string `json:"assignmentId"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.AssignmentID == nil {
		return 0, nil, errInvalidJSON("assignmentId is required")
	}
	asg := a.st.Assignments[*req.AssignmentID]
	if asg == nil {
		return 0, nil, errNotFound("assignment not found")
	}
	if asg.Terminal() {
		return 0, nil, errConflict("assignment_inactive", "assignment is no longer active")
	}
	me := c.user.UserID
	if asg.WorkerID != "" {
		if asg.WorkerID == me {
			return 201, map[string]any{"assignmentId": asg.AssignmentID, "workerId": me, "status": "accepted"}, nil
		}
		return 0, nil, errConflict("assignment_taken", "assignment was already accepted by another worker")
	}
	if roleForKind(asg.Kind) != c.role {
		return 0, nil, errForbidden("the selected role cannot accept this kind of assignment")
	}
	if asg.OfferedWorkerID == "" {
		return 0, nil, errConflict("offer_not_available", "assignment is not currently offered")
	}
	if asg.OfferedWorkerID != me {
		return 0, nil, errConflict("offer_not_offered", "assignment was offered to a different worker")
	}
	if asg.OfferExpiresAt != nil && c.now.After(*asg.OfferExpiresAt) {
		return 0, nil, errConflict("offer_not_available", "the offer has expired")
	}
	if !c.user.Available || !c.user.Active {
		return 0, nil, errConflict("worker_unavailable", "worker is marked unavailable")
	}
	if ok, reason := a.potentiallyEligible(c.user, asg, c.now); !ok {
		return 0, nil, E(403, "ineligible_worker", "worker is not eligible: "+reason)
	}
	if a.workerActiveAssignmentCountExcluding(me, asg.AssignmentID) >= c.user.CapacityUnits {
		return 0, nil, errConflict("worker_unavailable", "worker has no remaining capacity")
	}
	asg.WorkerID = me
	asg.Status = AsgAccepted
	t := c.now
	asg.AcceptedAt = &t
	asg.OfferExpiresAt = nil
	asg.NoWorkerSince = nil
	c.u.saveAssignment(asg)
	c.audit("assignment.accepted", "assignment", asg.AssignmentID, true, map[string]any{"journeyId": asg.JourneyID, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "workerId": me, "kind": asg.Kind, "status": asg.Status})
	c.u.event("assignment.updated", "assignment", asg.AssignmentID, map[string]any{"assignmentId": asg.AssignmentID, "status": asg.Status, "workerId": me, "kind": asg.Kind, "journeyId": asg.JourneyID}, []string{RoleAdministrator, RoleDispatcher}, []string{me})
	if j := a.st.Journeys[asg.JourneyID]; j != nil {
		a.markJourneyActive(c.u, j, c)
	}
	return 201, map[string]any{"assignmentId": asg.AssignmentID, "workerId": me, "status": "accepted"}, nil
}

func (a *App) hDeclineAssignment(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		AssignmentID *string `json:"assignmentId"`
		Reason       string  `json:"reason"`
		DeclinedAt   *string `json:"declinedAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.AssignmentID == nil {
		return 0, nil, errInvalidJSON("assignmentId is required")
	}
	declinedAt, e := optionalTime(req.DeclinedAt, "declinedAt")
	if e != nil {
		return 0, nil, e
	}
	at := c.now
	if declinedAt != nil {
		at = *declinedAt
	}
	asg := a.st.Assignments[*req.AssignmentID]
	if asg == nil {
		return 0, nil, errNotFound("assignment not found")
	}
	me := c.user.UserID
	if asg.Terminal() || asg.WorkerID != "" || asg.OfferedWorkerID != me {
		return 0, nil, errConflict("offer_not_available", "no open offer for this worker on the assignment")
	}
	asg.DeclinedBy = append(asg.DeclinedBy, me)
	asg.OfferedWorkerID = ""
	asg.OfferedAt = nil
	asg.OfferExpiresAt = nil
	c.user.Declines = append(c.user.Declines, c.now)
	if len(c.user.Declines) > 50 {
		c.user.Declines = c.user.Declines[len(c.user.Declines)-50:]
	}
	c.u.saveUser(c.user)
	c.u.saveAssignment(asg)
	c.audit("assignment.declined", "assignment", asg.AssignmentID, true, map[string]any{"journeyId": asg.JourneyID, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "workerId": me, "reason": req.Reason, "declinedAt": fmtTime(at)})
	next := a.offerAssignment(c.u, asg, c.actorID(), c.role)
	out := map[string]any{"assignmentId": asg.AssignmentID, "status": "pending", "declinedBy": me, "declinedAt": fmtTime(at)}
	if next != nil {
		out["reofferedTo"] = next.UserID
	}
	return 201, out, nil
}

func completeStop(j *Journey, locID string, at time.Time, u *UoW, sampleID string) {
	changed := false
	for i := range j.Stops {
		st := &j.Stops[i]
		if st.LocationID == locID && st.CompletedAt == nil && (st.SampleID == "" || st.SampleID == sampleID) {
			t := at
			st.CompletedAt = &t
			changed = true
			break
		}
	}
	if changed {
		u.saveJourney(j)
	}
}

func (a *App) hCollectAndSeal(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID             *string  `json:"sampleId"`
		AssignmentID         *string  `json:"assignmentId"`
		CollectedAt          *string  `json:"collectedAt"`
		ContainerType        *string  `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.SampleID == nil || req.AssignmentID == nil || req.ContainerType == nil || req.ObservedTemperatureC == nil {
		return 0, nil, errInvalidJSON("sampleId, assignmentId, collectedAt, containerType and observedTemperatureC are required")
	}
	collectedAt, e := requiredTime(req.CollectedAt, "collectedAt")
	if e != nil {
		return 0, nil, e
	}
	if strings.TrimSpace(*req.ContainerType) == "" {
		return 0, nil, E(400, "handling_noncompliant", "containerType must be provided")
	}
	s := a.st.Samples[*req.SampleID]
	if s == nil {
		return 0, nil, errNotFound("sample not found")
	}
	asg := a.st.Assignments[*req.AssignmentID]
	if asg == nil || !asg.HasSample(s.SampleID) || asg.Kind != KindCollection {
		return 0, nil, errNotFound("collection assignment not found for this sample")
	}
	if asg.WorkerID != c.user.UserID {
		return 0, nil, errForbidden("only the worker who accepted the collection may record it")
	}
	if asg.Terminal() {
		return 0, nil, errConflict("assignment_inactive", "collection assignment is no longer active")
	}
	if asg.Status == AsgPending {
		return 0, nil, errConflict("collection_not_ready", "accept the assignment before recording collection")
	}
	if s.Sealed || s.Terminal() {
		return 0, nil, errConflict("invalid_sample_state", "sample is already sealed or closed")
	}
	if collectedAt.Before(s.RequestedAt) {
		return 0, nil, errConflict("invalid_collection_time", "collectedAt is before the request was made")
	}
	if collectedAt.Before(s.EarliestCollectionAt) || collectedAt.After(s.LatestCollectionAt) {
		return 0, nil, errConflict("outside_collection_window", "collectedAt is outside the collection window")
	}
	typ := a.st.SampleTypes[s.SampleTypeID]
	if typ != nil && typ.QualifiedCollectorRequired && !a.qualifiedFor(c.user, typ, c.now) {
		return 0, nil, errConflict("certification_inactive", "the collector's qualification for this sample type is not active")
	}
	compliant := lower(*req.ContainerType) == lower(s.ContainerType) && *req.ObservedTemperatureC >= s.TemperatureMinC-1e-9 && *req.ObservedTemperatureC <= s.TemperatureMaxC+1e-9
	s.Sealed = true
	s.SealedAt = &collectedAt
	s.Status = SampleSealed
	s.CurrentHolderID = c.user.UserID
	s.LastCustodyEventAt = &collectedAt
	if c.user.LatestLocation != nil {
		s.LatestLocation = c.user.LatestLocation
		s.LocationRecordedAt = c.user.LocationRecordedAt
	} else {
		o := s.Origin
		s.LatestLocation = &o
		t := c.now
		s.LocationRecordedAt = &t
	}
	asg.Status = AsgSealed
	asg.LastProgressAt = &collectedAt
	c.u.saveAssignment(asg)
	details := map[string]any{"assignmentId": asg.AssignmentID, "journeyId": asg.JourneyID, "collectedAt": fmtTime(collectedAt), "containerType": *req.ContainerType, "observedTemperatureC": *req.ObservedTemperatureC, "handlingCompliant": compliant, "status": s.Status, "holderId": c.user.UserID}
	c.audit("sample.collected_and_sealed", "sample", s.SampleID, true, details)
	c.audit("custody.established", "sample", s.SampleID, true, map[string]any{"holderId": c.user.UserID, "assignmentId": asg.AssignmentID, "journeyId": asg.JourneyID})
	if !compliant {
		s.Exception = map[string]any{"reason": "handling_noncompliant", "stage": "collection", "containerType": *req.ContainerType, "observedTemperatureC": *req.ObservedTemperatureC, "occurredAt": fmtTime(collectedAt)}
		c.audit("sample.handling_noncompliant", "sample", s.SampleID, true, map[string]any{"stage": "collection", "containerType": *req.ContainerType, "observedTemperatureC": *req.ObservedTemperatureC})
	}
	c.u.saveSample(s)
	if j := a.st.Journeys[asg.JourneyID]; j != nil {
		completeStop(j, s.RequestID, collectedAt, c.u, s.SampleID)
		if s.OriginType == "node" {
			completeStop(j, s.OriginNodeID, collectedAt, c.u, s.SampleID)
		}
		a.markJourneyActive(c.u, j, c)
	}
	c.u.event("sample.updated", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "status": s.Status, "currentHolderId": s.CurrentHolderID, "sealed": true}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
	return 201, map[string]any{"sampleId": s.SampleID, "status": "sealed", "currentHolderId": s.CurrentHolderID, "sealedAt": fmtTime(collectedAt), "handlingCompliant": compliant}, nil
}

var transportOrder = map[string]int{AsgAccepted: 0, AsgAtPickup: 1, AsgPickedUp: 2, AsgInTransit: 3, AsgArrived: 4, AsgDelivered: 5, AsgCompleted: 6}
var stationaryOrder = map[string]int{AsgAccepted: 0, AsgSealed: 1, AsgInProgress: 1, AsgCompleted: 2}

func (a *App) hUpdateAssignmentProgress(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		AssignmentID *string `json:"assignmentId"`
		Status       *string `json:"status"`
		OccurredAt   *string `json:"occurredAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.AssignmentID == nil || req.Status == nil {
		return 0, nil, errInvalidJSON("assignmentId, status and occurredAt are required")
	}
	switch *req.Status {
	case AsgAtPickup, AsgPickedUp, AsgInTransit, AsgArrived, AsgDelivered, AsgInProgress, AsgCompleted:
	default:
		return 0, nil, errInvalidJSON("status is not a recognised progress status")
	}
	occurredAt, e := requiredTime(req.OccurredAt, "occurredAt")
	if e != nil {
		return 0, nil, e
	}
	asg := a.st.Assignments[*req.AssignmentID]
	if asg == nil {
		return 0, nil, errNotFound("assignment not found")
	}
	if asg.WorkerID != c.user.UserID {
		return 0, nil, E(403, "ineligible_worker", "only the assigned worker may update progress")
	}
	if asg.Terminal() {
		return 0, nil, errConflict("assignment_inactive", "assignment is no longer active")
	}
	if asg.Status == AsgPending {
		return 0, nil, errConflict("assignment_not_ready", "assignment has not been accepted")
	}
	if asg.LastProgressAt != nil && occurredAt.Before(*asg.LastProgressAt) {
		return 0, nil, errConflict("invalid_progress_time", "occurredAt is earlier than the previous progress update")
	}
	samples := []*Sample{}
	for _, sid := range asg.SampleIDs {
		if s := a.st.Samples[sid]; s != nil {
			if s.Terminal() {
				return 0, nil, errConflict("invalid_sample_state", "sample is closed")
			}
			samples = append(samples, s)
		}
	}
	j := a.st.Journeys[asg.JourneyID]
	newStatus := *req.Status
	if asg.Kind == KindTransport {
		cur, ok := transportOrder[asg.Status]
		nxt, ok2 := transportOrder[newStatus]
		if !ok || !ok2 {
			return 0, nil, errConflict("invalid_transition", "status is not valid for a transport leg")
		}
		if nxt < cur {
			return 0, nil, errConflict("invalid_transition", "progress cannot move backwards")
		}
		if nxt >= transportOrder[AsgPickedUp] && cur < transportOrder[AsgPickedUp] {
			for _, s := range samples {
				if !s.Sealed {
					return 0, nil, errConflict("collection_required", "sample must be collected and sealed before pickup")
				}
				if s.CurrentHolderID != c.user.UserID {
					if s.PendingHandoffID != "" {
						return 0, nil, errConflict("custody_required", "custody handoff to this worker is still pending")
					}
					if j != nil {
						chain := a.chainFor(j, s.SampleID)
						for i, x := range chain {
							if x.AssignmentID == asg.AssignmentID && i > 0 && !chain[i-1].Terminal() && chain[i-1].Kind == KindTransport {
								return 0, nil, errConflict("prior_leg_incomplete", "the previous transport leg has not completed")
							}
						}
					}
					return 0, nil, errConflict("custody_required", "worker does not hold custody of the sample")
				}
			}
		}
		if nxt == cur {
			return 201, map[string]any{"assignmentId": asg.AssignmentID, "sampleId": firstOf(asg.SampleIDs), "status": asg.Status}, nil
		}
		asg.Status = newStatus
		asg.LastProgressAt = &occurredAt
		if newStatus == AsgCompleted {
			asg.CompletedAt = &occurredAt
		}
		c.u.saveAssignment(asg)
		for _, s := range samples {
			if newStatus == AsgPickedUp || newStatus == AsgInTransit {
				s.Status = SampleInTransit
			}
			if (newStatus == AsgArrived || newStatus == AsgDelivered || newStatus == AsgCompleted) && asg.ToLocationID != "" {
				if loc := a.st.Locations[asg.ToLocationID]; loc != nil {
					co := loc.Coordinate
					s.LatestLocation = &co
					s.LocationRecordedAt = &occurredAt
				}
				if j != nil && newStatus != AsgArrived {
					completeStop(j, asg.ToLocationID, occurredAt, c.u, s.SampleID)
				}
			}
			c.u.saveSample(s)
		}
	} else {
		cur, ok := stationaryOrder[asg.Status]
		nxt, ok2 := stationaryOrder[newStatus]
		if !ok || !ok2 || newStatus == AsgSealed {
			return 0, nil, errConflict("invalid_transition", "status is not valid for this assignment")
		}
		if nxt < cur {
			return 0, nil, errConflict("invalid_transition", "progress cannot move backwards")
		}
		if asg.Kind == KindCollection && newStatus == AsgCompleted {
			for _, s := range samples {
				if !s.Sealed {
					return 0, nil, errConflict("collection_required", "record collection and sealing before completing")
				}
			}
		}
		if nxt == cur && asg.Status == newStatus {
			return 201, map[string]any{"assignmentId": asg.AssignmentID, "sampleId": firstOf(asg.SampleIDs), "status": asg.Status}, nil
		}
		asg.Status = newStatus
		asg.LastProgressAt = &occurredAt
		if newStatus == AsgCompleted {
			asg.CompletedAt = &occurredAt
		}
		c.u.saveAssignment(asg)
	}
	c.audit("assignment.progress", "assignment", asg.AssignmentID, true, map[string]any{"journeyId": asg.JourneyID, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "status": newStatus, "occurredAt": fmtTime(occurredAt), "workerId": c.user.UserID})
	c.u.event("assignment.updated", "assignment", asg.AssignmentID, map[string]any{"assignmentId": asg.AssignmentID, "status": asg.Status, "workerId": c.user.UserID, "journeyId": asg.JourneyID}, []string{RoleAdministrator, RoleDispatcher}, []string{c.user.UserID})
	if j != nil {
		a.markJourneyActive(c.u, j, c)
	}
	return 201, map[string]any{"assignmentId": asg.AssignmentID, "sampleId": firstOf(asg.SampleIDs), "status": asg.Status}, nil
}

func (a *App) hRecordWorkerLocation(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		AssignmentID *string  `json:"assignmentId"`
		Coordinate   *coordIn `json:"coordinate"`
		Sequence     *int     `json:"sequence"`
		RecordedAt   *string  `json:"recordedAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.AssignmentID == nil || req.Sequence == nil || req.Coordinate == nil {
		return 0, nil, errInvalidJSON("assignmentId, coordinate, sequence and recordedAt are required")
	}
	coord, ok := parseCoord(req.Coordinate)
	if !ok {
		return 0, nil, E(400, "invalid_coordinate", "coordinate must contain a valid latitude and longitude")
	}
	if *req.Sequence < 1 {
		return 0, nil, E(400, "invalid_sequence", "sequence must be at least 1")
	}
	recordedAt, e := requiredTime(req.RecordedAt, "recordedAt")
	if e != nil {
		return 0, nil, e
	}
	asg := a.st.Assignments[*req.AssignmentID]
	if asg == nil {
		return 0, nil, errNotFound("assignment not found")
	}
	if asg.WorkerID != c.user.UserID && asg.OfferedWorkerID != c.user.UserID {
		return 0, nil, errForbidden("location updates may only be recorded for your own assignments")
	}
	if *req.Sequence <= asg.LastLocationSeq {
		return 0, nil, E(400, "invalid_sequence", "sequence must increase with every update")
	}
	if c.user.LocationRecordedAt != nil && recordedAt.Before(*c.user.LocationRecordedAt) {
		return 0, nil, errConflict("stale_location", "a newer location has already been recorded")
	}
	asg.LastLocationSeq = *req.Sequence
	c.u.saveAssignment(asg)
	c.user.LatestLocation = &coord
	c.user.LocationRecordedAt = &recordedAt
	c.u.saveUser(c.user)
	aud := []string{c.user.UserID}
	for _, sid := range asg.SampleIDs {
		if s := a.st.Samples[sid]; s != nil && s.CurrentHolderID == c.user.UserID {
			s.LatestLocation = &coord
			s.LocationRecordedAt = &recordedAt
			c.u.saveSample(s)
			if !contains(aud, s.RequesterID) {
				aud = append(aud, s.RequesterID)
			}
		}
	}
	c.audit("worker.location_recorded", "assignment", asg.AssignmentID, true, map[string]any{"journeyId": asg.JourneyID, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "coordinate": coordView(coord), "sequence": *req.Sequence, "recordedAt": fmtTime(recordedAt), "workerId": c.user.UserID})
	c.u.event("worker.location", "worker", c.user.UserID, map[string]any{"workerId": c.user.UserID, "assignmentId": asg.AssignmentID, "coordinate": coordView(coord), "recordedAt": fmtTime(recordedAt), "sequence": *req.Sequence}, []string{RoleAdministrator, RoleDispatcher}, aud)
	return 201, map[string]any{"assignmentId": asg.AssignmentID, "coordinate": coordView(coord), "sequence": *req.Sequence, "recordedAt": fmtTime(recordedAt)}, nil
}

func (a *App) hInitiateHandoff(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID         *string `json:"sampleId"`
		FromAssignmentID *string `json:"fromAssignmentId"`
		ToAssignmentID   *string `json:"toAssignmentId"`
		ReceiverID       *string `json:"receiverId"`
		InitiatedAt      *string `json:"initiatedAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.SampleID == nil || req.FromAssignmentID == nil || req.ToAssignmentID == nil || req.ReceiverID == nil {
		return 0, nil, errInvalidJSON("sampleId, fromAssignmentId, toAssignmentId, receiverId and initiatedAt are required")
	}
	initiatedAt, e := requiredTime(req.InitiatedAt, "initiatedAt")
	if e != nil {
		return 0, nil, e
	}
	s := a.st.Samples[*req.SampleID]
	if s == nil {
		return 0, nil, errNotFound("sample not found")
	}
	from := a.st.Assignments[*req.FromAssignmentID]
	to := a.st.Assignments[*req.ToAssignmentID]
	if from == nil || to == nil {
		return 0, nil, errNotFound("assignment not found")
	}
	receiver := a.st.Users[*req.ReceiverID]
	if receiver == nil {
		return 0, nil, errNotFound("receiver not found")
	}
	me := c.user.UserID
	if *req.ReceiverID == me {
		return 0, nil, E(400, "invalid_receiver", "a sample cannot be handed off to its current holder")
	}
	if s.Terminal() {
		return 0, nil, errConflict("invalid_assignment_state", "sample is closed")
	}
	if !s.Sealed {
		return 0, nil, errConflict("invalid_assignment_state", "sample must be collected and sealed before handoff")
	}
	if s.CurrentHolderID != me {
		return 0, nil, errConflict("not_current_holder", "only the current holder may initiate a handoff")
	}
	if from.WorkerID != me || !from.HasSample(s.SampleID) {
		return 0, nil, E(403, "sender_assignment_mismatch", "fromAssignmentId is not the sender's assignment for this sample")
	}
	j := a.st.Journeys[s.ActiveJourneyID]
	if j == nil || from.JourneyID != j.JourneyID || to.JourneyID != j.JourneyID || !to.HasSample(s.SampleID) {
		return 0, nil, errConflict("invalid_handoff_route", "assignments do not belong to the sample's active journey")
	}
	if s.PendingHandoffID != "" {
		if h := a.st.Handoffs[s.PendingHandoffID]; h != nil && h.Status == "pending" {
			return 0, nil, errConflict("pending_handoff_exists", "a handoff for this sample is already awaiting confirmation")
		}
		s.PendingHandoffID = ""
	}
	if to.Terminal() {
		return 0, nil, errConflict("invalid_assignment_state", "receiving assignment is no longer active")
	}
	if to.WorkerID == "" {
		if to.OfferedWorkerID == receiver.UserID {
			return 0, nil, errConflict("offer_not_available", "the receiver has not accepted the receiving assignment yet")
		}
		return 0, nil, errConflict("receiver_assignment_mismatch", "receiving assignment has not been accepted by the receiver")
	}
	if to.WorkerID != receiver.UserID {
		return 0, nil, errConflict("receiver_assignment_mismatch", "receiving assignment belongs to a different worker")
	}
	if !receiver.Available || !receiver.Active {
		return 0, nil, errConflict("receiver_unavailable", "receiver is unavailable")
	}
	chain := a.chainFor(j, s.SampleID)
	fi, ti := -1, -1
	for i, x := range chain {
		if x.AssignmentID == from.AssignmentID {
			fi = i
		}
		if x.AssignmentID == to.AssignmentID {
			ti = i
		}
	}
	if fi < 0 || ti < 0 || ti <= fi {
		return 0, nil, errConflict("nonadjacent_handoff", "handoff must follow the journey's custody order")
	}
	for i := fi + 1; i < ti; i++ {
		if chain[i].Kind != KindNode {
			if chain[i].Kind == KindTransport {
				return 0, nil, errConflict("transport_leg_incomplete", "an intervening transport leg has not been completed")
			}
			return 0, nil, errConflict("nonadjacent_handoff", "handoff skips a required custody step")
		}
	}
	if to.Kind == KindNode && from.Kind == KindTransport && to.NodeID != from.ToLocationID {
		return 0, nil, errConflict("node_assignment_mismatch", "the receiving node handler is not at this leg's destination")
	}
	if to.Kind == KindLaboratory && from.Kind == KindTransport && to.LaboratoryID != from.ToLocationID {
		return 0, nil, errConflict("invalid_handoff_route", "the receiving laboratory is not this leg's destination")
	}
	if s.LastCustodyEventAt != nil && initiatedAt.Before(*s.LastCustodyEventAt) {
		return 0, nil, errConflict("invalid_handoff_time", "initiatedAt is before the previous custody event")
	}
	h := &Handoff{HandoffID: newID(), SampleID: s.SampleID, JourneyID: j.JourneyID, FromAssignmentID: from.AssignmentID, ToAssignmentID: to.AssignmentID, SenderID: me, ReceiverID: receiver.UserID, Status: "pending", InitiatedAt: initiatedAt, CreatedAt: c.now}
	a.st.Handoffs[h.HandoffID] = h
	c.u.saveHandoff(h)
	s.PendingHandoffID = h.HandoffID
	c.u.saveSample(s)
	c.audit("handoff.initiated", "handoff", h.HandoffID, true, map[string]any{"sampleId": s.SampleID, "journeyId": j.JourneyID, "fromAssignmentId": from.AssignmentID, "toAssignmentId": to.AssignmentID, "senderId": me, "receiverId": receiver.UserID, "initiatedAt": fmtTime(initiatedAt), "status": "pending"})
	c.u.event("handoff.updated", "handoff", h.HandoffID, handoffView(h), []string{RoleAdministrator, RoleDispatcher}, []string{me, receiver.UserID, s.RequesterID})
	return 201, map[string]any{"handoffId": h.HandoffID, "senderId": me, "receiverId": receiver.UserID, "currentHolderId": s.CurrentHolderID, "status": "pending"}, nil
}

func handoffResponse(h *Handoff, holder string) map[string]any {
	return map[string]any{"handoffId": h.HandoffID, "status": h.Status, "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed, "currentHolderId": holder}
}

func (a *App) hConfirmHandoff(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		HandoffID        *string `json:"handoffId"`
		ConfirmationSide *string `json:"confirmationSide"`
		ConfirmedAt      *string `json:"confirmedAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.HandoffID == nil || req.ConfirmationSide == nil {
		return 0, nil, errInvalidJSON("handoffId, confirmationSide and confirmedAt are required")
	}
	side := *req.ConfirmationSide
	if side != "sender" && side != "receiver" {
		return 0, nil, E(400, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
	}
	confirmedAt, e := requiredTime(req.ConfirmedAt, "confirmedAt")
	if e != nil {
		return 0, nil, e
	}
	h := a.st.Handoffs[*req.HandoffID]
	if h == nil {
		return 0, nil, errNotFound("handoff not found")
	}
	s := a.st.Samples[h.SampleID]
	if s == nil {
		return 0, nil, errNotFound("sample not found")
	}
	me := c.user.UserID
	if (side == "sender" && h.SenderID != me) || (side == "receiver" && h.ReceiverID != me) {
		return 0, nil, errForbidden("only the named party may confirm this side of the handoff")
	}
	if h.Status == "cancelled" {
		return 0, nil, errConflict("handoff_inactive", "handoff was cancelled")
	}
	if confirmedAt.Before(h.InitiatedAt) {
		return 0, nil, errConflict("invalid_confirmation_time", "confirmedAt is before the handoff was initiated")
	}
	if h.Status == "confirmed" {
		return 201, handoffResponse(h, s.CurrentHolderID), nil
	}
	if s.CurrentHolderID != h.SenderID {
		return 0, nil, errConflict("custody_conflict", "the sender no longer holds the sample")
	}
	already := (side == "sender" && h.SenderConfirmed) || (side == "receiver" && h.ReceiverConfirmed)
	if already {
		return 201, handoffResponse(h, s.CurrentHolderID), nil
	}
	if side == "sender" {
		h.SenderConfirmed = true
	} else {
		h.ReceiverConfirmed = true
	}
	c.u.saveHandoff(h)
	c.audit("handoff.confirmed", "handoff", h.HandoffID, true, map[string]any{"sampleId": s.SampleID, "journeyId": h.JourneyID, "side": side, "confirmedAt": fmtTime(confirmedAt), "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed, "status": h.Status})
	if h.SenderConfirmed && h.ReceiverConfirmed {
		a.completeHandoff(c, h, s, confirmedAt)
	}
	c.u.event("handoff.updated", "handoff", h.HandoffID, handoffView(h), []string{RoleAdministrator, RoleDispatcher}, []string{h.SenderID, h.ReceiverID, s.RequesterID})
	return 201, handoffResponse(h, s.CurrentHolderID), nil
}

// completeHandoff transfers custody exactly once and advances both
// assignments and the journey's stops.
func (a *App) completeHandoff(c *Ctx, h *Handoff, s *Sample, at time.Time) {
	u := c.u
	h.Status = "confirmed"
	h.ConfirmedAt = &at
	u.saveHandoff(h)
	from := a.st.Assignments[h.FromAssignmentID]
	to := a.st.Assignments[h.ToAssignmentID]
	j := a.st.Journeys[h.JourneyID]
	prevHolder := s.CurrentHolderID
	s.CurrentHolderID = h.ReceiverID
	s.PendingHandoffID = ""
	s.LastCustodyEventAt = &at
	if from != nil && !from.Terminal() {
		stillHolding := false
		for _, sid := range from.SampleIDs {
			if sid != s.SampleID {
				if other := a.st.Samples[sid]; other != nil && other.CurrentHolderID == h.SenderID && !other.Terminal() {
					stillHolding = true
				}
			}
		}
		if !stillHolding {
			from.Status = AsgCompleted
			from.CompletedAt = &at
			from.LastProgressAt = &at
			u.saveAssignment(from)
			u.audit(c.actorID(), roleOrNone(c.role), "assignment.completed", "assignment", from.AssignmentID, true, map[string]any{"journeyId": from.JourneyID, "sampleIds": from.SampleIDs, "sampleId": s.SampleID, "status": from.Status, "via": "handoff"})
		}
		if from.Kind == KindTransport && from.ConnectionID != "" {
			a.releaseReservations(u, func(r *Reservation) bool { return r.SampleID == s.SampleID && r.ResourceID == from.ConnectionID })
		}
		if from.Kind == KindNode {
			a.releaseReservations(u, func(r *Reservation) bool { return r.SampleID == s.SampleID && r.ResourceID == from.NodeID })
		}
	}
	if to != nil {
		switch to.Kind {
		case KindTransport:
			if transportOrder[to.Status] < transportOrder[AsgPickedUp] {
				to.Status = AsgPickedUp
			}
			s.Status = SampleInTransit
			if recv := a.st.Users[h.ReceiverID]; recv != nil && recv.LatestLocation != nil {
				s.LatestLocation = recv.LatestLocation
				s.LocationRecordedAt = recv.LocationRecordedAt
			}
		case KindNode:
			if to.Status == AsgAccepted {
				to.Status = AsgInProgress
			}
			s.Status = SampleAtNode
			if loc := a.st.Locations[to.NodeID]; loc != nil {
				co := loc.Coordinate
				s.LatestLocation = &co
				s.LocationRecordedAt = &at
			}
			if j != nil {
				completeStop(j, to.NodeID, at, u, s.SampleID)
			}
		case KindLaboratory:
			if to.Status == AsgAccepted {
				to.Status = AsgInProgress
			}
			s.Status = SampleAtLaboratory
			if loc := a.st.Locations[to.LaboratoryID]; loc != nil {
				co := loc.Coordinate
				s.LatestLocation = &co
				s.LocationRecordedAt = &at
			}
		}
		to.LastProgressAt = &at
		u.saveAssignment(to)
	}
	if from != nil && from.Kind == KindTransport && j != nil && from.ToLocationID != "" {
		completeStop(j, from.ToLocationID, at, u, s.SampleID)
	}
	u.saveSample(s)
	u.audit(c.actorID(), roleOrNone(c.role), "custody.transferred", "sample", s.SampleID, true, map[string]any{
		"handoffId": h.HandoffID, "journeyId": h.JourneyID, "fromHolderId": prevHolder, "toHolderId": h.ReceiverID, "fromAssignmentId": h.FromAssignmentID, "toAssignmentId": h.ToAssignmentID, "status": s.Status, "confirmedAt": fmtTime(at),
	})
	u.event("sample.updated", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "status": s.Status, "currentHolderId": s.CurrentHolderID}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
	if j != nil {
		a.markJourneyActive(u, j, c)
	}
}

func (a *App) hConfirmLaboratoryReceipt(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID     *string `json:"sampleId"`
		LaboratoryID *string `json:"laboratoryId"`
		ReceivedAt   *string `json:"receivedAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.SampleID == nil || req.LaboratoryID == nil {
		return 0, nil, errInvalidJSON("sampleId, laboratoryId and receivedAt are required")
	}
	receivedAt, e := requiredTime(req.ReceivedAt, "receivedAt")
	if e != nil {
		return 0, nil, e
	}
	s := a.st.Samples[*req.SampleID]
	if s == nil {
		return 0, nil, errNotFound("sample not found")
	}
	lab := a.st.Locations[*req.LaboratoryID]
	if lab == nil {
		return 0, nil, errNotFound("laboratory not found")
	}
	if c.user.AssignedLocationID != lab.LocationID {
		return 0, nil, E(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
	}
	if !lab.Active || !lab.Functions[FnLaboratory] {
		return 0, nil, errConflict("laboratory_unavailable", "laboratory is not active")
	}
	if s.Status == SampleReceived {
		if s.ReceivedLaboratoryID == lab.LocationID {
			return 201, map[string]any{"sampleId": s.SampleID, "laboratoryId": lab.LocationID, "status": "received", "receivedAt": fmtTimePtr(s.ReceivedAt)}, nil
		}
		return 0, nil, errConflict("receipt_not_ready", "sample was received elsewhere")
	}
	if s.Terminal() {
		return 0, nil, errConflict("receipt_not_ready", "sample is closed")
	}
	if s.TargetLaboratoryID != lab.LocationID {
		return 0, nil, errConflict("receipt_not_ready", "sample is not routed to this laboratory")
	}
	if s.PendingHandoffID != "" {
		if h := a.st.Handoffs[s.PendingHandoffID]; h != nil && h.Status == "pending" {
			return 0, nil, errConflict("pending_handoff_exists", "a custody handoff is still awaiting confirmation")
		}
	}
	if s.CurrentHolderID == "" || !s.Sealed {
		return 0, nil, errConflict("receipt_not_ready", "sample has not arrived at the laboratory")
	}
	if s.CurrentHolderID != c.user.UserID {
		holder := a.st.Users[s.CurrentHolderID]
		if holder != nil && contains(holder.Roles, RoleLaboratory) && holder.AssignedLocationID == lab.LocationID {
			return 0, nil, errConflict("custody_conflict", "another laboratory operator currently holds the sample")
		}
		return 0, nil, errConflict("receipt_not_ready", "custody has not been transferred to you")
	}
	if s.LastCustodyEventAt != nil && receivedAt.Before(*s.LastCustodyEventAt) {
		return 0, nil, errConflict("invalid_receipt_time", "receivedAt is before the sample arrived")
	}
	if receivedAt.After(s.DeliveryDeadline) {
		s.Exception = map[string]any{"reason": "delivery_deadline_exceeded", "deliveryDeadline": fmtTime(s.DeliveryDeadline), "receivedAt": fmtTime(receivedAt), "occurredAt": fmtTime(receivedAt), "laboratoryId": lab.LocationID}
		c.u.saveSample(s)
		c.audit("sample.deadline_missed", "sample", s.SampleID, true, map[string]any{"laboratoryId": lab.LocationID, "receivedAt": fmtTime(receivedAt), "deliveryDeadline": fmtTime(s.DeliveryDeadline), "journeyId": s.ActiveJourneyID})
		return 0, nil, errConflict("delivery_deadline_exceeded", "the sample arrived after its delivery deadline")
	}
	s.Status = SampleReceived
	s.ReceivedAt = &receivedAt
	s.ReceivedLaboratoryID = lab.LocationID
	s.LastCustodyEventAt = &receivedAt
	co := lab.Coordinate
	s.LatestLocation = &co
	s.LocationRecordedAt = &receivedAt
	c.u.saveSample(s)
	j := a.st.Journeys[s.ActiveJourneyID]
	if j != nil {
		for _, asg := range a.journeyAssignments(j) {
			if asg.HasSample(s.SampleID) && asg.Active() {
				if asg.Kind == KindLaboratory && asg.WorkerID == c.user.UserID {
					asg.Status = AsgCompleted
					asg.CompletedAt = &receivedAt
					c.u.saveAssignment(asg)
					c.audit("assignment.completed", "assignment", asg.AssignmentID, true, map[string]any{"journeyId": j.JourneyID, "sampleId": s.SampleID, "sampleIds": asg.SampleIDs, "status": asg.Status, "via": "laboratory_receipt"})
				} else if len(asg.SampleIDs) == 1 {
					a.cancelAssignment(c.u, asg, "sample_received", c.actorID(), roleOrNone(c.role))
				}
			}
		}
		completeStop(j, lab.LocationID, receivedAt, c.u, s.SampleID)
		a.releaseReservations(c.u, func(r *Reservation) bool { return r.SampleID == s.SampleID })
		allDone := true
		for _, sid := range j.SampleIDs {
			if other := a.st.Samples[sid]; other != nil && !other.Terminal() {
				allDone = false
			}
		}
		if allDone {
			j.Status = JourneyCompleted
			c.u.saveJourney(j)
			c.audit("journey.completed", "journey", j.JourneyID, true, map[string]any{"sampleIds": j.SampleIDs, "status": j.Status})
			c.u.event("journey.updated", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID, "status": j.Status, "planVersion": j.PlanVersion}, []string{RoleAdministrator, RoleDispatcher}, nil)
		}
	}
	c.audit("sample.received", "sample", s.SampleID, true, map[string]any{"laboratoryId": lab.LocationID, "receivedAt": fmtTime(receivedAt), "status": s.Status, "journeyId": s.ActiveJourneyID, "operatorId": c.user.UserID})
	c.u.event("sample.updated", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "status": s.Status, "receivedLaboratoryId": lab.LocationID}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
	return 201, map[string]any{"sampleId": s.SampleID, "laboratoryId": lab.LocationID, "status": "received", "receivedAt": fmtTime(receivedAt)}, nil
}

func (a *App) hRecordLaboratoryException(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID     *string `json:"sampleId"`
		LaboratoryID *string `json:"laboratoryId"`
		Reason       *string `json:"reason"`
		ObservedAt   *string `json:"observedAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.SampleID == nil || req.LaboratoryID == nil || req.Reason == nil || strings.TrimSpace(*req.Reason) == "" {
		return 0, nil, errInvalidJSON("sampleId, laboratoryId, reason and observedAt are required")
	}
	observedAt, e := requiredTime(req.ObservedAt, "observedAt")
	if e != nil {
		return 0, nil, e
	}
	s := a.st.Samples[*req.SampleID]
	if s == nil {
		return 0, nil, errNotFound("sample not found")
	}
	lab := a.st.Locations[*req.LaboratoryID]
	if lab == nil {
		return 0, nil, errNotFound("laboratory not found")
	}
	if c.user.AssignedLocationID != lab.LocationID {
		return 0, nil, E(403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
	}
	if s.Terminal() {
		return 0, nil, errConflict("journey_inactive", "sample is already closed")
	}
	if s.TargetLaboratoryID != "" && s.TargetLaboratoryID != lab.LocationID {
		return 0, nil, errConflict("wrong_laboratory", "sample is routed to a different laboratory")
	}
	if !s.Sealed {
		return 0, nil, errConflict("laboratory_not_ready", "sample has not entered the transport network")
	}
	if observedAt.Before(s.RequestedAt) {
		return 0, nil, errConflict("invalid_exception_time", "observedAt is before the request was made")
	}
	excID := newID()
	a.flagException(c.u, s, strings.TrimSpace(*req.Reason), map[string]any{"exceptionId": excID, "laboratoryId": lab.LocationID, "observedAt": fmtTime(observedAt), "recordedBy": c.user.UserID, "stage": "laboratory"}, c.actorID(), c.role)
	return 201, map[string]any{"exceptionId": excID, "sampleId": s.SampleID, "status": "exception", "reason": strings.TrimSpace(*req.Reason)}, nil
}

func (a *App) hRecordHandlingCheckpoint(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID             *string  `json:"sampleId"`
		AssignmentID         *string  `json:"assignmentId"`
		LocationID           *string  `json:"locationId"`
		ContainerType        *string  `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt           *string  `json:"recordedAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.SampleID == nil || req.AssignmentID == nil || req.ContainerType == nil || req.ObservedTemperatureC == nil {
		return 0, nil, errInvalidJSON("sampleId, assignmentId, containerType, observedTemperatureC and recordedAt are required")
	}
	recordedAt, e := requiredTime(req.RecordedAt, "recordedAt")
	if e != nil {
		return 0, nil, e
	}
	s := a.st.Samples[*req.SampleID]
	if s == nil {
		return 0, nil, errNotFound("sample not found")
	}
	asg := a.st.Assignments[*req.AssignmentID]
	if asg == nil || !asg.HasSample(s.SampleID) {
		return 0, nil, errNotFound("assignment not found for this sample")
	}
	if asg.WorkerID != c.user.UserID {
		return 0, nil, errForbidden("checkpoints may only be recorded on your own assignment")
	}
	if s.Terminal() {
		return 0, nil, errConflict("terminal_sample", "sample is closed")
	}
	if j := a.st.Journeys[s.ActiveJourneyID]; j == nil || j.Terminal() {
		return 0, nil, errConflict("journey_inactive", "the sample has no active journey")
	}
	if asg.Terminal() {
		return 0, nil, errConflict("assignment_inactive", "assignment is no longer active")
	}
	if s.CurrentHolderID != c.user.UserID {
		return 0, nil, errForbidden("only the current holder may record a handling checkpoint")
	}
	if s.LastCustodyEventAt != nil && recordedAt.Before(*s.LastCustodyEventAt) {
		return 0, nil, errConflict("invalid_checkpoint_time", "recordedAt is before the current custody began")
	}
	if req.LocationID != nil && *req.LocationID != "" && a.st.Locations[*req.LocationID] == nil {
		return 0, nil, errNotFound("location not found")
	}
	compliant := lower(*req.ContainerType) == lower(s.ContainerType) && *req.ObservedTemperatureC >= s.TemperatureMinC-1e-9 && *req.ObservedTemperatureC <= s.TemperatureMaxC+1e-9
	cp := &Checkpoint{CheckpointID: newID(), SampleID: s.SampleID, AssignmentID: asg.AssignmentID, ContainerType: *req.ContainerType, ObservedTemperatureC: *req.ObservedTemperatureC, Compliant: compliant, RecordedAt: recordedAt, RecordedBy: c.user.UserID}
	if req.LocationID != nil {
		cp.LocationID = *req.LocationID
	}
	a.st.Checkpoints[cp.CheckpointID] = cp
	c.u.saveCheckpoint(cp)
	c.audit("sample.handling_checkpoint", "sample", s.SampleID, true, map[string]any{"checkpointId": cp.CheckpointID, "assignmentId": asg.AssignmentID, "journeyId": asg.JourneyID, "containerType": cp.ContainerType, "observedTemperatureC": cp.ObservedTemperatureC, "compliant": compliant, "recordedAt": fmtTime(recordedAt), "locationId": cp.LocationID})
	if !compliant {
		a.flagException(c.u, s, "handling_noncompliant", map[string]any{"checkpointId": cp.CheckpointID, "assignmentId": asg.AssignmentID, "containerType": cp.ContainerType, "observedTemperatureC": cp.ObservedTemperatureC, "requiredContainerType": s.ContainerType, "temperatureMinC": s.TemperatureMinC, "temperatureMaxC": s.TemperatureMaxC, "stage": "checkpoint"}, c.actorID(), c.role)
	}
	return 201, map[string]any{"checkpointId": cp.CheckpointID, "sampleId": s.SampleID, "compliant": compliant, "sampleStatus": s.Status}, nil
}

