type journeyOpts struct {
	entry           *Assignment // existing assignment of the current holder, relinked as the chain start
	registrant      *User       // worker who already holds the sample and needs a fresh entry assignment
	registrantRole  string
	parentJourneyID string
	startAt         time.Time
	fromNode        bool // the sample is (or will be handed) at route.StartLocationID
	positionKnown   bool // the sample is physically at route.StartLocationID already
	needsCollection bool // a collection assignment must exist (sample not yet sealed)
}

// buildJourney creates the journey, its stops, chain of assignments and
// capacity reservations for one sample along a route.
func (a *App) buildJourney(c *Ctx, s *Sample, typ *SampleType, route *Route, opts journeyOpts) *Journey {
	j := &Journey{
		JourneyID: newID(), ParentJourneyID: opts.parentJourneyID, PlanVersion: 1, Status: JourneyPlanned,
		SampleIDs: []string{s.SampleID}, TargetLaboratoryID: route.LabID, StartLocationID: route.StartLocationID,
		TotalCostUnits: route.Cost, Valid: true, CreatedAt: c.now,
	}
	a.st.Journeys[j.JourneyID] = j
	a.populateJourney(c, j, s, typ, route, opts)
	c.u.saveJourney(j)
	return j
}

// populateJourney appends stops, the chain of assignments and reservations
// for one sample along a route. The chain is:
//
//	[collection] -> [origin leg] -> node@P0 -> leg P0->P1 -> node@P1 ... -> laboratory
//
// Entry assignments (an existing in-progress assignment or a fresh
// pre-accepted one for the registrant of a pre-sealed sample) replace the
// matching generated step so custody is never re-created.
func (a *App) populateJourney(c *Ctx, j *Journey, s *Sample, typ *SampleType, route *Route, opts journeyOpts) {
	u := c.u
	t := opts.startAt
	seq := 0
	for _, id := range j.AssignmentIDs {
		if asg := a.st.Assignments[id]; asg != nil && asg.Sequence >= seq {
			seq = asg.Sequence + 1
		}
	}
	stopSeq := len(j.Stops)
	addStop := func(locID, stopType string, at time.Time, dwell int, coord *Coordinate, completed bool) {
		st := Stop{StopID: newID(), LocationID: locID, StopType: stopType, Sequence: stopSeq, EstimatedAt: at, DwellMinutes: dwell, Coordinate: coord}
		if completed {
			done := at
			st.CompletedAt = &done
		}
		if coord != nil {
			st.SampleID = s.SampleID
		}
		j.Stops = append(j.Stops, st)
		stopSeq++
	}
	newAsg := func(kind string) *Assignment {
		asg := &Assignment{AssignmentID: newID(), JourneyID: j.JourneyID, Kind: kind, SampleIDs: []string{s.SampleID}, Status: AsgPending, Sequence: seq, Cooled: typ.RequiresCooledRoute, CreatedAt: c.now}
		seq++
		a.st.Assignments[asg.AssignmentID] = asg
		j.AssignmentIDs = append(j.AssignmentIDs, asg.AssignmentID)
		return asg
	}
	relink := func(asg *Assignment) {
		asg.JourneyID = j.JourneyID
		asg.Sequence = seq
		seq++
		j.AssignmentIDs = append(j.AssignmentIDs, asg.AssignmentID)
		u.saveAssignment(asg)
	}
	preAccept := func(asg *Assignment, w *User, status string) {
		asg.WorkerID = w.UserID
		asg.Status = status
		at := c.now
		asg.AcceptedAt = &at
	}
	entry := opts.entry
	entryKind := ""
	if entry != nil {
		entryKind = entry.Kind
	}
	reg := opts.registrant
	regRole := opts.registrantRole
	path := route.Path
	lab := route.LabID
	originCoord := s.Origin
	prevLoc := ""
	// collection step
	switch {
	case entryKind == KindCollection:
		relink(entry)
	case reg != nil && regRole == RoleCollector:
		preAccept(newAsg(KindCollection), reg, AsgSealed)
	case opts.needsCollection:
		newAsg(KindCollection)
	}
	if !opts.fromNode {
		addStop(s.RequestID, "pickup", t, 0, &originCoord, s.Sealed)
		var leg *Assignment
		if entryKind == KindTransport {
			relink(entry)
			leg = entry
		} else {
			leg = newAsg(KindTransport)
			leg.FromLocationID = s.RequestID
			leg.ToLocationID = path[0]
			leg.TravelMinutes = route.OriginLegMinutes
			if reg != nil && regRole == RoleCourier {
				preAccept(leg, reg, AsgPickedUp)
			}
		}
		t = t.Add(time.Duration(route.OriginLegMinutes) * time.Minute)
		prevLoc = s.RequestID
	} else if entryKind == KindTransport {
		// courier already carrying the sample towards path[0]
		relink(entry)
		prevLoc = entry.FromLocationID
		t = t.Add(time.Duration(entry.TravelMinutes) * time.Minute)
	}
	for i, locID := range path {
		loc := a.st.Locations[locID]
		handling := 0
		if loc != nil {
			handling = loc.HandlingMinutes
		}
		atPosition := i == 0 && opts.fromNode && opts.positionKnown && entryKind != KindTransport
		isLab := i == len(path)-1 && locID == lab
		if isLab {
			addStop(locID, "delivery", t, handling, nil, false)
			if i == 0 && entryKind == KindLaboratory && entry.LaboratoryID == locID {
				relink(entry)
			} else {
				labAsg := newAsg(KindLaboratory)
				labAsg.LaboratoryID = locID
				labAsg.FromLocationID = prevLoc
				labAsg.ToLocationID = locID
				if reg != nil && i == 0 && opts.fromNode && regRole == RoleLaboratory {
					preAccept(labAsg, reg, AsgInProgress)
				}
			}
			t = t.Add(time.Duration(handling) * time.Minute)
			break
		}
		if i == 0 && opts.fromNode {
			addStop(locID, "pickup", t, handling, nil, atPosition)
		} else {
			addStop(locID, "handoff", t, handling, nil, false)
		}
		skipNode := i == 0 && opts.fromNode && reg != nil && regRole == RoleCourier
		if i == 0 && (entryKind == KindNode || entryKind == KindLaboratory) && (entry.NodeID == locID || entry.LaboratoryID == locID) {
			relink(entry)
		} else if !skipNode {
			node := newAsg(KindNode)
			node.NodeID = locID
			node.FromLocationID = prevLoc
			node.ToLocationID = path[i+1]
			if reg != nil && i == 0 && opts.fromNode && (regRole == RoleNodeHandler || regRole == RoleLaboratory) {
				preAccept(node, reg, AsgInProgress)
			}
		}
		conn := a.st.Connections[route.ConnectionIDs[i]]
		leg := newAsg(KindTransport)
		leg.FromLocationID = locID
		leg.ToLocationID = path[i+1]
		leg.ConnectionID = route.ConnectionIDs[i]
		if conn != nil {
			leg.TravelMinutes = conn.TravelMinutes
		}
		if skipNode {
			preAccept(leg, reg, AsgPickedUp)
		}
		t = t.Add(time.Duration(handling+leg.TravelMinutes) * time.Minute)
		prevLoc = locID
	}
	j.EstimatedDeliveryAt = t
	j.TotalCostUnits = route.Cost
	j.TargetLaboratoryID = lab
	j.StartLocationID = route.StartLocationID
	j.RouteMode = routeModeFor(j, a)
	for _, id := range j.AssignmentIDs {
		asg := a.st.Assignments[id]
		if asg.CreatedAt.Equal(c.now) && asg.JourneyID == j.JourneyID {
			u.saveAssignment(asg)
			u.audit(c.actorID(), roleOrNone(c.role), "assignment.created", "assignment", asg.AssignmentID, true, map[string]any{
				"journeyId": j.JourneyID, "sampleId": s.SampleID, "kind": asg.Kind, "sequence": asg.Sequence, "fromLocationId": asg.FromLocationID, "toLocationId": asg.ToLocationID, "nodeId": asg.NodeID, "laboratoryId": asg.LaboratoryID, "status": asg.Status,
			})
		}
	}
	a.reserveRoute(u, j.JourneyID, s.SampleID, routeResources(route), typ.RequiresCooledRoute)
	for _, id := range j.AssignmentIDs {
		asg := a.st.Assignments[id]
		if asg.Status == AsgPending && asg.OfferedWorkerID == "" {
			a.offerAssignment(c.u, asg, c.actorID(), roleOrNone(c.role))
		}
	}
}

