package app

import (
	"encoding/json"
	"sort"
	"strings"
	"time"
)

// position describes where a sample currently is for replanning purposes.
type position struct {
	locID          string // network node the sample is at or heading to; "" when at origin coordinates
	entry          *Assignment
	registrant     *User
	registrantRole string
	startAt        time.Time
	fromNode       bool
	positionKnown  bool
	needsCollection bool
	cancelEntry    *Assignment // in-progress leg whose destination became unusable
}

func (a *App) holderAssignment(j *Journey, s *Sample) *Assignment {
	var best *Assignment
	for _, asg := range a.chainFor(j, s.SampleID) {
		if asg.Active() && asg.WorkerID == s.CurrentHolderID {
			best = asg
		}
	}
	return best
}

func (a *App) positionOf(j *Journey, s *Sample, exclude map[string]bool) position {
	pos := position{startAt: s.RequestedAt}
	if s.EarliestCollectionAt.After(pos.startAt) {
		pos.startAt = s.EarliestCollectionAt
	}
	if s.LastCustodyEventAt != nil && s.LastCustodyEventAt.After(pos.startAt) {
		pos.startAt = *s.LastCustodyEventAt
	}
	if !s.Sealed {
		for _, asg := range a.chainFor(j, s.SampleID) {
			if asg.Kind == KindCollection && asg.Active() {
				pos.entry = asg
			}
		}
		pos.needsCollection = pos.entry == nil
		if s.OriginType == "node" {
			pos.fromNode, pos.positionKnown, pos.locID = true, true, s.OriginNodeID
		}
		return pos
	}
	ha := a.holderAssignment(j, s)
	if ha == nil {
		if s.OriginType == "node" {
			pos.fromNode, pos.positionKnown, pos.locID = true, true, s.OriginNodeID
		}
		if holder := a.st.Users[s.CurrentHolderID]; holder != nil {
			pos.registrant = holder
			for _, r := range []string{RoleCollector, RoleCourier, RoleNodeHandler, RoleLaboratory} {
				if contains(holder.Roles, r) {
					pos.registrantRole = r
					break
				}
			}
		}
		return pos
	}
	switch ha.Kind {
	case KindCollection:
		pos.entry = ha
		if s.OriginType == "node" {
			pos.fromNode, pos.positionKnown, pos.locID = true, true, s.OriginNodeID
		}
	case KindTransport:
		dest := a.st.Locations[ha.ToLocationID]
		if dest != nil && dest.Active && !exclude[dest.LocationID] {
			pos.entry = ha
			pos.fromNode, pos.locID = true, dest.LocationID
		} else {
			pos.cancelEntry = ha
			pos.registrant = a.st.Users[s.CurrentHolderID]
			pos.registrantRole = RoleCourier
			if from := a.st.Locations[ha.FromLocationID]; from != nil {
				pos.fromNode, pos.positionKnown, pos.locID = true, true, from.LocationID
			}
		}
	case KindNode:
		pos.entry = ha
		pos.fromNode, pos.positionKnown, pos.locID = true, true, ha.NodeID
	case KindLaboratory:
		pos.entry = ha
		pos.fromNode, pos.positionKnown, pos.locID = true, true, ha.LaboratoryID
	}
	return pos
}

func specFromSample(s *Sample) *RequestSpec {
	return &RequestSpec{origin: s.Origin, originType: s.OriginType, originNodeID: s.OriginNodeID, requestedAt: s.RequestedAt, deliveryDeadline: s.DeliveryDeadline, earliestCollectionAt: s.EarliestCollectionAt, latestCollectionAt: s.LatestCollectionAt, sampleTypeID: s.SampleTypeID}
}

// routeFromPosition searches for a route for a sample from its position.
// It returns the route or a reason: no_valid_route, insufficient_capacity,
// deadline_unreachable.
func (a *App) routeFromPosition(net *Snapshot, s *Sample, pos position, exclude map[string]bool, units int) (*Route, string) {
	var starts []startPoint
	if pos.fromNode {
		starts = []startPoint{{locID: pos.locID}}
	} else {
		starts = a.candidateStarts(net, specFromSample(s))
	}
	if len(starts) == 0 {
		return nil, "no_valid_route"
	}
	base := routeFilter{excludeLocs: exclude, allowInactiveStart: pos.positionKnown, skipStartCapacity: pos.positionKnown, units: units}
	if !pos.positionKnown {
		base.allowInactiveStart = false
	}
	types := []string{s.SampleTypeID}
	if a.findRoute(net, starts, types, base) == nil {
		return nil, "no_valid_route"
	}
	withCap := base
	withCap.checkCapacity = true
	route := a.findRoute(net, starts, types, withCap)
	if route == nil {
		return nil, "insufficient_capacity"
	}
	route.ETA = pos.startAt.Add(time.Duration(route.TotalMinutes) * time.Minute)
	if route.ETA.After(s.DeliveryDeadline) {
		return route, "deadline_unreachable"
	}
	return route, ""
}

func (a *App) remainingPath(j *Journey, s *Sample) []string {
	out := []string{}
	for _, st := range j.Stops {
		if st.SampleID != "" && st.SampleID != s.SampleID {
			continue
		}
		if a.st.Locations[st.LocationID] == nil {
			continue
		}
		if st.CompletedAt == nil || st.StopType == "pickup" {
			out = append(out, st.LocationID)
		}
	}
	return out
}

func sameStrings(x, y []string) bool {
	if len(x) != len(y) {
		return false
	}
	for i := range x {
		if x[i] != y[i] {
			return false
		}
	}
	return true
}

// replanSample replans the unfinished work of one sample. Completed work and
// the current holder are preserved. Returns replaced | expired | exception |
// not_required and the replacement journey when one was created.
func (a *App) replanSample(c *Ctx, j *Journey, s *Sample, reason string, exclude map[string]bool, force bool) (string, *Journey) {
	if s.Terminal() || j.Terminal() {
		return "not_required", nil
	}
	typ := a.st.SampleTypes[s.SampleTypeID]
	pos := a.positionOf(j, s, exclude)
	net := a.buildNetwork(c.now)
	a.releaseReservations(c.u, func(r *Reservation) bool { return r.SampleID == s.SampleID })
	route, why := a.routeFromPosition(net, s, pos, exclude, 1)
	if why != "" {
		if why == "deadline_unreachable" {
			s.Status = SampleExpired
			s.Exception = map[string]any{"reason": "deadline_unreachable", "trigger": reason, "occurredAt": fmtTime(c.now), "deliveryDeadline": fmtTime(s.DeliveryDeadline)}
			if route != nil {
				s.Exception["bestEstimatedArrival"] = fmtTime(route.ETA)
			}
			c.u.saveSample(s)
			c.audit("sample.expired", "sample", s.SampleID, true, map[string]any{"reason": "deadline_unreachable", "trigger": reason, "journeyId": j.JourneyID, "status": s.Status})
			c.u.event("sample.updated", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "status": s.Status}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
			a.windDownJourney(c.u, j, s.SampleID, JourneyExpired, c.actorID(), roleOrNone(c.role))
			return "expired", nil
		}
		a.flagException(c.u, s, why, map[string]any{"trigger": reason, "journeyId": j.JourneyID}, c.actorID(), roleOrNone(c.role))
		return "exception", nil
	}
	resources := routeResources(route)
	if pos.positionKnown && pos.entry != nil && pos.entry.Kind != KindTransport {
		// the sample already occupies its current node
		resources = append([]string{pos.locID}, resources...)
	}
	if !force && pos.cancelEntry == nil && sameStrings(a.remainingPath(j, s), route.Path) && route.LabID == j.TargetLaboratoryID && len(j.SampleIDs) == 1 {
		a.reserveRoute(c.u, j.JourneyID, s.SampleID, routeResources(route), typ.RequiresCooledRoute)
		c.audit("journey.replan_evaluated", "journey", j.JourneyID, true, map[string]any{"sampleId": s.SampleID, "replanStatus": "not_required", "trigger": reason})
		return "not_required", nil
	}
	if pos.cancelEntry != nil {
		a.cancelAssignment(c.u, pos.cancelEntry, "destination_unavailable", c.actorID(), roleOrNone(c.role))
	}
	// detach the carried-over assignment from the old journey
	if pos.entry != nil {
		kept := []string{}
		for _, id := range j.AssignmentIDs {
			if id != pos.entry.AssignmentID {
				kept = append(kept, id)
			}
		}
		j.AssignmentIDs = kept
	}
	newJ := &Journey{
		JourneyID: newID(), ParentJourneyID: j.JourneyID, PlanVersion: 1, Status: JourneyPlanned, SampleIDs: []string{s.SampleID},
		TargetLaboratoryID: route.LabID, StartLocationID: route.StartLocationID, TotalCostUnits: route.Cost, Valid: true, CreatedAt: c.now,
	}
	if j.Status == JourneyActive || s.Sealed {
		newJ.Status = JourneyActive
	}
	a.st.Journeys[newJ.JourneyID] = newJ
	a.populateJourney(c, newJ, s, typ, route, journeyOpts{
		entry: pos.entry, registrant: pos.registrant, registrantRole: pos.registrantRole, parentJourneyID: j.JourneyID,
		startAt: pos.startAt, fromNode: pos.fromNode, positionKnown: pos.positionKnown, needsCollection: pos.needsCollection,
	})
	c.u.saveJourney(newJ)
	// wind down the sample's remaining work in the old journey
	remaining := []string{}
	for _, sid := range j.SampleIDs {
		if sid != s.SampleID {
			if other := a.st.Samples[sid]; other != nil && !other.Terminal() && other.ActiveJourneyID == j.JourneyID {
				remaining = append(remaining, sid)
			}
		}
	}
	for _, id := range j.AssignmentIDs {
		asg := a.st.Assignments[id]
		if asg == nil || asg.Terminal() || !asg.HasSample(s.SampleID) {
			continue
		}
		if len(asg.SampleIDs) > 1 && len(remaining) > 0 {
			kept := []string{}
			for _, sid := range asg.SampleIDs {
				if sid != s.SampleID {
					kept = append(kept, sid)
				}
			}
			asg.SampleIDs = kept
			c.u.saveAssignment(asg)
			continue
		}
		a.cancelAssignment(c.u, asg, "journey_replaced", c.actorID(), roleOrNone(c.role))
	}
	if len(remaining) == 0 {
		j.Status = JourneyReplaced
		j.ReplanStatus = "replaced"
		j.ReplacementJourneyID = newJ.JourneyID
	}
	j.PlanVersion++
	c.u.saveJourney(j)
	s.ActiveJourneyID = newJ.JourneyID
	s.TargetLaboratoryID = route.LabID
	c.u.saveSample(s)
	c.audit("journey.replaced", "journey", j.JourneyID, true, map[string]any{"sampleId": s.SampleID, "replacementJourneyId": newJ.JourneyID, "trigger": reason, "replanStatus": "replaced"})
	c.audit("journey.created", "journey", newJ.JourneyID, true, map[string]any{"sampleId": s.SampleID, "parentJourneyId": j.JourneyID, "routeMode": newJ.RouteMode, "path": route.Path, "targetLaboratoryId": newJ.TargetLaboratoryID, "estimatedDeliveryAt": fmtTime(newJ.EstimatedDeliveryAt), "planVersion": newJ.PlanVersion, "trigger": reason})
	c.u.event("journey.updated", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID, "status": j.Status, "replacementJourneyId": newJ.JourneyID, "planVersion": j.PlanVersion}, []string{RoleAdministrator, RoleDispatcher}, nil)
	c.u.event("sample.updated", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "status": s.Status, "activeJourneyId": newJ.JourneyID}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
	return "replaced", newJ
}

func aggregateReplan(statuses []string) string {
	if len(statuses) == 0 {
		return "not_required"
	}
	has := map[string]bool{}
	for _, s := range statuses {
		has[s] = true
	}
	switch {
	case has["exception"]:
		return "exception"
	case has["expired"]:
		return "expired"
	case has["replaced"]:
		return "replaced"
	}
	return "not_required"
}

// affectedSamples lists non-terminal samples whose unfinished work depends on a resource.
func (a *App) affectedSamples(resourceType, id string) []*Sample {
	var out []*Sample
	for _, sid := range sortedKeys(a.st.Samples) {
		s := a.st.Samples[sid]
		if s.Terminal() || s.ActiveJourneyID == "" {
			continue
		}
		j := a.st.Journeys[s.ActiveJourneyID]
		if j == nil || j.Terminal() {
			continue
		}
		hit := false
		switch resourceType {
		case "location":
			for _, st := range j.Stops {
				if st.LocationID == id && st.CompletedAt == nil && (st.SampleID == "" || st.SampleID == s.SampleID) {
					hit = true
				}
			}
			for _, asg := range a.chainFor(j, s.SampleID) {
				if asg.Active() && (asg.ToLocationID == id || asg.NodeID == id || asg.LaboratoryID == id) {
					hit = true
				}
			}
		case "connection":
			for _, asg := range a.chainFor(j, s.SampleID) {
				if asg.Active() && asg.ConnectionID == id && transportOrder[asg.Status] < transportOrder[AsgDelivered] {
					hit = true
				}
			}
		case "journey":
			hit = j.JourneyID == id
		}
		if hit {
			out = append(out, s)
		}
	}
	return out
}

// replanAfterNetworkChange replans every journey that depends on a resource
// that just became unavailable.
func (a *App) replanAfterNetworkChange(c *Ctx, resourceType, id, reason string) ([]string, []string, string) {
	exclude := map[string]bool{}
	if resourceType == "location" {
		exclude[id] = true
	}
	affected, plans, statuses := []string{}, []string{}, []string{}
	for _, s := range a.affectedSamples(resourceType, id) {
		j := a.st.Journeys[s.ActiveJourneyID]
		status, newJ := a.replanSample(c, j, s, reason, exclude, false)
		affected = append(affected, s.SampleID)
		statuses = append(statuses, status)
		if newJ != nil {
			plans = append(plans, newJ.JourneyID)
		}
	}
	return affected, plans, aggregateReplan(statuses)
}

type planReq struct {
	JourneyID           *string `json:"journeyId"`
	TargetJourneyID     *string `json:"targetJourneyId"`
	ExpectedPlanVersion *int    `json:"expectedPlanVersion"`
	Reason              string  `json:"reason"`
	SampleIDs           []string `json:"sampleIds"`
	SourceJourneyIDs    []string `json:"sourceJourneyIds"`
}

func (a *App) loadJourneyForEdit(id *string, version *int) (*Journey, *apiErr) {
	if id == nil || version == nil {
		return nil, errInvalidJSON("journeyId and expectedPlanVersion are required")
	}
	if *version < 1 {
		return nil, E(400, "invalid_plan_version", "expectedPlanVersion must be at least 1")
	}
	j := a.st.Journeys[*id]
	if j == nil {
		return nil, errNotFound("journey not found")
	}
	if j.Terminal() {
		return nil, errConflict("inactive_plan", "journey is no longer active")
	}
	if j.PlanVersion != *version {
		return nil, errConflict("stale_plan", "expectedPlanVersion does not match the current plan version")
	}
	return j, nil
}

func (a *App) cancelJourney(c *Ctx, j *Journey, reason string) {
	for _, sid := range j.SampleIDs {
		s := a.st.Samples[sid]
		if s == nil || s.Terminal() || s.ActiveJourneyID != j.JourneyID {
			continue
		}
		s.Status = SampleCancelled
		c.u.saveSample(s)
		c.audit("sample.cancelled", "sample", s.SampleID, true, map[string]any{"journeyId": j.JourneyID, "reason": reason, "status": s.Status})
		c.u.event("sample.updated", "sample", s.SampleID, map[string]any{"sampleId": s.SampleID, "status": s.Status}, []string{RoleAdministrator, RoleDispatcher}, a.sampleAudience(s))
		a.windDownJourney(c.u, j, s.SampleID, JourneyCancelled, c.actorID(), roleOrNone(c.role))
	}
	if j.Status != JourneyCancelled {
		j.Status = JourneyCancelled
		for _, asg := range a.journeyAssignments(j) {
			a.cancelAssignment(c.u, asg, "journey_cancelled", c.actorID(), roleOrNone(c.role))
		}
		a.releaseReservations(c.u, func(r *Reservation) bool { return r.JourneyID == j.JourneyID })
	}
	j.PlanVersion++
	c.u.saveJourney(j)
	c.audit("journey.cancelled", "journey", j.JourneyID, true, map[string]any{"reason": reason, "sampleIds": j.SampleIDs, "status": j.Status})
}

func (a *App) hCancelJourney(c *Ctx, body []byte) (int, any, *apiErr) {
	var req planReq
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	j, e := a.loadJourneyForEdit(req.JourneyID, req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	a.cancelJourney(c, j, req.Reason)
	return 201, map[string]any{"journeyId": j.JourneyID, "status": "cancelled", "sampleIds": strs(j.SampleIDs)}, nil
}

func (a *App) rerouteJourney(c *Ctx, j *Journey, reason string) (string, *Journey) {
	statuses := []string{}
	var replacement *Journey
	for _, sid := range append([]string{}, j.SampleIDs...) {
		s := a.st.Samples[sid]
		if s == nil || s.Terminal() || s.ActiveJourneyID != j.JourneyID {
			continue
		}
		status, newJ := a.replanSample(c, j, s, reason, nil, false)
		statuses = append(statuses, status)
		if newJ != nil && replacement == nil {
			replacement = newJ
		}
	}
	return aggregateReplan(statuses), replacement
}

func (a *App) hRerouteJourney(c *Ctx, body []byte) (int, any, *apiErr) {
	var req planReq
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	j, e := a.loadJourneyForEdit(req.JourneyID, req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	reason := req.Reason
	if reason == "" {
		reason = "dispatcher_reroute"
	}
	status, replacement := a.rerouteJourney(c, j, reason)
	out := map[string]any{"journeyId": j.JourneyID, "replanStatus": status}
	if replacement != nil {
		out["replacementPlanId"] = replacement.JourneyID
		out["replacementJourney"] = a.journeyPlanView(replacement, false)
	}
	c.audit("journey.rerouted", "journey", j.JourneyID, true, map[string]any{"replanStatus": status, "reason": reason, "sampleIds": j.SampleIDs})
	return 201, out, nil
}

func (a *App) hReportDisruption(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		ResourceType *string `json:"resourceType"`
		ResourceID   *string `json:"resourceId"`
		Reason       string  `json:"reason"`
		OccurredAt   *string `json:"occurredAt"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.ResourceType == nil || req.ResourceID == nil {
		return 0, nil, errInvalidJSON("resourceType, resourceId and occurredAt are required")
	}
	occurredAt, e := requiredTime(req.OccurredAt, "occurredAt")
	if e != nil {
		return 0, nil, e
	}
	rt := *req.ResourceType
	id := *req.ResourceID
	affected, plans := []string{}, []string{}
	status := "not_required"
	switch rt {
	case "location", "node", "laboratory":
		loc := a.st.Locations[id]
		if loc == nil {
			return 0, nil, errNotFound("location not found")
		}
		if loc.Active {
			loc.Active = false
			c.u.saveLocation(loc)
			c.audit("location.status_set", "location", loc.LocationID, true, map[string]any{"before": true, "after": false, "trigger": "disruption"})
			c.u.event("location.updated", "location", loc.LocationID, locationView(loc), nil, nil)
		}
		affected, plans, status = a.replanAfterNetworkChange(c, "location", id, "disruption:"+rt)
	case "connection", "route":
		if conn := a.st.Connections[id]; conn != nil {
			if conn.Active {
				conn.Active = false
				c.u.saveConnection(conn)
				c.audit("connection.status_set", "connection", conn.ConnectionID, true, map[string]any{"before": true, "after": false, "trigger": "disruption"})
				c.u.event("connection.updated", "connection", conn.ConnectionID, connectionView(conn), nil, nil)
			}
			affected, plans, status = a.replanAfterNetworkChange(c, "connection", id, "disruption:"+rt)
		} else if j := a.st.Journeys[id]; j != nil && rt == "route" {
			if !j.Terminal() {
				status, newJ := a.rerouteJourney(c, j, "disruption:route")
				affected = append(affected, j.SampleIDs...)
				if newJ != nil {
					plans = append(plans, newJ.JourneyID)
				}
				_ = status
			}
		} else {
			return 0, nil, errNotFound("connection not found")
		}
	case "worker":
		w := a.st.Users[id]
		if w == nil {
			return 0, nil, errNotFound("worker not found")
		}
		for _, asg := range a.st.Assignments {
			if asg.Active() && (asg.WorkerID == w.UserID || asg.OfferedWorkerID == w.UserID) {
				for _, sid := range asg.SampleIDs {
					if !contains(affected, sid) {
						affected = append(affected, sid)
					}
				}
			}
		}
		sort.Strings(affected)
		if w.Available {
			w.Available = false
			c.u.saveUser(w)
			c.audit("worker.availability_set", "user", w.UserID, true, map[string]any{"before": map[string]any{"available": true}, "after": map[string]any{"available": false}, "trigger": "disruption"})
		}
		a.workerBecameUnavailable(c.u, w, "disruption:worker", c)
		if len(affected) > 0 {
			status = "replaced"
		}
	case "capacity":
		loc := a.st.Locations[id]
		conn := a.st.Connections[id]
		if loc == nil && conn == nil {
			return 0, nil, errNotFound("capacity pool not found")
		}
		if loc != nil {
			loc.CapacityUnits, loc.CooledCapacityUnits = 0, 0
			c.u.saveLocation(loc)
			affected, plans, status = a.replanAfterNetworkChange(c, "location", id, "disruption:capacity")
		} else {
			conn.CapacityUnits, conn.CooledCapacityUnits = 0, 0
			c.u.saveConnection(conn)
			affected, plans, status = a.replanAfterNetworkChange(c, "connection", id, "disruption:capacity")
		}
		c.audit("capacity.configured", "capacity", id, true, map[string]any{"after": map[string]any{"capacityUnits": 0, "cooledCapacityUnits": 0}, "trigger": "disruption"})
		c.u.event("capacity.updated", "capacity", id, map[string]any{"resourceId": id, "capacity": a.capacityView(id)}, nil, nil)
	default:
		return 0, nil, E(400, "invalid_resource_type", "resourceType is not recognised")
	}
	d := &Disruption{DisruptionID: newID(), ResourceType: rt, ResourceID: id, Reason: req.Reason, OccurredAt: occurredAt, ReportedBy: c.user.UserID, AffectedSampleIDs: affected, ReplacementPlanIDs: plans, ReplanStatus: status}
	a.st.Disruptions[d.DisruptionID] = d
	c.u.saveDisruption(d)
	c.audit("disruption.reported", "disruption", d.DisruptionID, true, map[string]any{"resourceType": rt, "resourceId": id, "reason": req.Reason, "occurredAt": fmtTime(occurredAt), "affectedSampleIds": affected, "replacementPlanIds": plans, "replanStatus": status, "sampleIds": affected})
	c.u.event("disruption.reported", "disruption", d.DisruptionID, map[string]any{"disruptionId": d.DisruptionID, "resourceType": rt, "resourceId": id, "replanStatus": status, "affectedSampleIds": affected}, []string{RoleAdministrator, RoleDispatcher}, nil)
	return 201, map[string]any{"disruptionId": d.DisruptionID, "affectedSampleIds": affected, "replacementPlanIds": plans, "replanStatus": status}, nil
}

// --- split -------------------------------------------------------------------

func (a *App) sharedStarted(j *Journey) bool {
	for _, asg := range a.journeyAssignments(j) {
		if !asg.Active() || len(asg.SampleIDs) < 1 {
			continue
		}
		if asg.Kind == KindTransport && asg.ConnectionID != "" && transportOrder[asg.Status] >= transportOrder[AsgPickedUp] {
			return true
		}
		if (asg.Kind == KindNode || asg.Kind == KindLaboratory) && asg.Status == AsgInProgress {
			return true
		}
	}
	return false
}

func (a *App) splitJourney(c *Ctx, j *Journey, sampleIDs []string) (*Journey, *apiErr) {
	if len(sampleIDs) == 0 {
		return nil, errConflict("invalid_split", "sampleIds must list the samples to split off")
	}
	split := map[string]bool{}
	for _, sid := range sampleIDs {
		if !contains(j.SampleIDs, sid) {
			return nil, errConflict("invalid_split", "sample does not belong to the journey")
		}
		split[sid] = true
	}
	if len(split) >= len(j.SampleIDs) {
		return nil, errConflict("invalid_split", "a split must leave at least one sample in the journey")
	}
	if j.SplitJourneyID != "" {
		if sj := a.st.Journeys[j.SplitJourneyID]; sj != nil && !sj.Terminal() && sj.PlanVersion == 1 && sj.CreatedAt.Equal(c.now) {
			return nil, errConflict("split_in_progress", "a split of this journey is already in progress")
		}
	}
	if a.sharedStarted(j) {
		return nil, errConflict("work_in_progress", "shared transport legs are already in custody; split is not possible")
	}
	newJ := &Journey{
		JourneyID: newID(), ParentJourneyID: j.JourneyID, PlanVersion: 1, Status: j.Status, SampleIDs: []string{}, TargetLaboratoryID: j.TargetLaboratoryID,
		StartLocationID: j.StartLocationID, EstimatedDeliveryAt: j.EstimatedDeliveryAt, TotalCostUnits: j.TotalCostUnits, Valid: true, CreatedAt: c.now,
	}
	remaining := []string{}
	for _, sid := range j.SampleIDs {
		if split[sid] {
			newJ.SampleIDs = append(newJ.SampleIDs, sid)
		} else {
			remaining = append(remaining, sid)
		}
	}
	a.st.Journeys[newJ.JourneyID] = newJ
	// stops: per-sample stops follow their sample, shared stops are copied
	keptStops := []Stop{}
	for _, st := range j.Stops {
		if st.SampleID != "" && split[st.SampleID] {
			cp := st
			newJ.Stops = append(newJ.Stops, cp)
			continue
		}
		if st.SampleID == "" {
			cp := st
			cp.StopID = newID()
			newJ.Stops = append(newJ.Stops, cp)
		}
		keptStops = append(keptStops, st)
	}
	j.Stops = keptStops
	for i := range newJ.Stops {
		newJ.Stops[i].Sequence = i
	}
	for i := range j.Stops {
		j.Stops[i].Sequence = i
	}
	keptAsg := []string{}
	for _, asg := range a.journeyAssignments(j) {
		if !asg.Active() {
			keptAsg = append(keptAsg, asg.AssignmentID)
			continue
		}
		mine, theirs := []string{}, []string{}
		for _, sid := range asg.SampleIDs {
			if split[sid] {
				mine = append(mine, sid)
			} else {
				theirs = append(theirs, sid)
			}
		}
		if len(mine) == 0 {
			keptAsg = append(keptAsg, asg.AssignmentID)
			continue
		}
		if len(theirs) == 0 {
			asg.JourneyID = newJ.JourneyID
			newJ.AssignmentIDs = append(newJ.AssignmentIDs, asg.AssignmentID)
			c.u.saveAssignment(asg)
			continue
		}
		asg.SampleIDs = theirs
		c.u.saveAssignment(asg)
		keptAsg = append(keptAsg, asg.AssignmentID)
		clone := *asg
		clone.AssignmentID = newID()
		clone.JourneyID = newJ.JourneyID
		clone.SampleIDs = mine
		clone.Status = AsgPending
		clone.WorkerID, clone.OfferedWorkerID = "", ""
		clone.OfferedAt, clone.OfferExpiresAt, clone.AcceptedAt, clone.LastProgressAt = nil, nil, nil, nil
		clone.DeclinedBy = nil
		clone.LastLocationSeq = 0
		clone.CreatedAt = c.now
		a.st.Assignments[clone.AssignmentID] = &clone
		newJ.AssignmentIDs = append(newJ.AssignmentIDs, clone.AssignmentID)
		c.u.saveAssignment(&clone)
		c.audit("assignment.created", "assignment", clone.AssignmentID, true, map[string]any{"journeyId": newJ.JourneyID, "sampleIds": mine, "sampleId": firstOf(mine), "kind": clone.Kind, "sequence": clone.Sequence, "via": "split"})
		a.offerAssignment(c.u, &clone, c.actorID(), roleOrNone(c.role))
	}
	j.AssignmentIDs = keptAsg
	for _, r := range a.st.Reservations {
		if !r.Released && r.JourneyID == j.JourneyID && split[r.SampleID] {
			r.JourneyID = newJ.JourneyID
			c.u.saveReservation(r)
		}
	}
	j.SampleIDs = remaining
	j.PlanVersion++
	j.SplitJourneyID = newJ.JourneyID
	j.RouteMode = routeModeFor(j, a)
	newJ.RouteMode = routeModeFor(newJ, a)
	for _, sid := range newJ.SampleIDs {
		if s := a.st.Samples[sid]; s != nil {
			s.ActiveJourneyID = newJ.JourneyID
			c.u.saveSample(s)
		}
	}
	c.u.saveJourney(j)
	c.u.saveJourney(newJ)
	c.audit("journey.split", "journey", j.JourneyID, true, map[string]any{"splitJourneyId": newJ.JourneyID, "sampleIds": newJ.SampleIDs, "remainingSampleIds": remaining, "planVersion": j.PlanVersion})
	c.audit("journey.created", "journey", newJ.JourneyID, true, map[string]any{"parentJourneyId": j.JourneyID, "sampleIds": newJ.SampleIDs, "routeMode": newJ.RouteMode, "via": "split"})
	c.u.event("journey.updated", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID, "status": j.Status, "planVersion": j.PlanVersion, "splitJourneyId": newJ.JourneyID}, []string{RoleAdministrator, RoleDispatcher}, nil)
	return newJ, nil
}

func (a *App) hSplitJourney(c *Ctx, body []byte) (int, any, *apiErr) {
	var req planReq
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	j, e := a.loadJourneyForEdit(req.JourneyID, req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	if req.SampleIDs == nil {
		return 0, nil, errInvalidJSON("sampleIds is required")
	}
	newJ, e := a.splitJourney(c, j, req.SampleIDs)
	if e != nil {
		return 0, nil, e
	}
	return 201, map[string]any{"journey": a.journeyPlanView(j, false), "splitJourney": a.journeyPlanView(newJ, false)}, nil
}

// --- merge -------------------------------------------------------------------

func (a *App) typesCompatible(samples []*Sample) *apiErr {
	for i, x := range samples {
		tx := a.st.SampleTypes[x.SampleTypeID]
		if tx != nil && !tx.BatchingAllowed {
			return errConflict("pulse_no_batch", "sample type "+tx.Name+" must not be batched")
		}
		for k, y := range samples {
			if k <= i {
				continue
			}
			ty := a.st.SampleTypes[y.SampleTypeID]
			if contains(x.IncompatibleSampleTypes, y.SampleTypeID) || contains(y.IncompatibleSampleTypes, x.SampleTypeID) ||
				(tx != nil && contains(tx.IncompatibleSampleTypes, y.SampleTypeID)) || (ty != nil && contains(ty.IncompatibleSampleTypes, x.SampleTypeID)) {
				return errConflict("incompatible_batch", "samples are not allowed to travel together")
			}
			lo := x.TemperatureMinC
			if y.TemperatureMinC > lo {
				lo = y.TemperatureMinC
			}
			hi := x.TemperatureMaxC
			if y.TemperatureMaxC < hi {
				hi = y.TemperatureMaxC
			}
			if lo > hi {
				return errConflict("incompatible_batch", "temperature requirements do not overlap")
			}
		}
	}
	return nil
}

// rebuildSharedChain replaces the shared (post entry node) part of a batched
// journey with a fresh chain along the route for all its samples.
func (a *App) rebuildSharedChain(c *Ctx, j *Journey, samples []*Sample, route *Route, startAt time.Time) {
	u := c.u
	// cancel existing shared, unfinished assignments
	kept := []string{}
	for _, asg := range a.journeyAssignments(j) {
		shared := asg.Kind == KindNode || asg.Kind == KindLaboratory || (asg.Kind == KindTransport && asg.ConnectionID != "")
		if shared && asg.Active() {
			a.cancelAssignment(u, asg, "batch_rebuilt", c.actorID(), roleOrNone(c.role))
		}
		kept = append(kept, asg.AssignmentID)
	}
	j.AssignmentIDs = kept
	// stops: keep per-sample pickup stops, rebuild shared ones
	stops := []Stop{}
	for _, st := range j.Stops {
		if st.SampleID != "" {
			stops = append(stops, st)
		}
	}
	j.Stops = stops
	sampleIDs := []string{}
	cooled := false
	for _, s := range samples {
		sampleIDs = append(sampleIDs, s.SampleID)
		if t := a.st.SampleTypes[s.SampleTypeID]; t != nil && t.RequiresCooledRoute {
			cooled = true
		}
	}
	seq := 2
	for _, id := range j.AssignmentIDs {
		if asg := a.st.Assignments[id]; asg != nil && asg.Sequence >= seq {
			seq = asg.Sequence + 1
		}
	}
	t := startAt
	stopSeq := len(j.Stops)
	newAsg := func(kind string) *Assignment {
		asg := &Assignment{AssignmentID: newID(), JourneyID: j.JourneyID, Kind: kind, SampleIDs: append([]string{}, sampleIDs...), Status: AsgPending, Sequence: seq, Cooled: cooled, CreatedAt: c.now}
		seq++
		a.st.Assignments[asg.AssignmentID] = asg
		j.AssignmentIDs = append(j.AssignmentIDs, asg.AssignmentID)
		u.saveAssignment(asg)
		u.audit(c.actorID(), roleOrNone(c.role), "assignment.created", "assignment", asg.AssignmentID, true, map[string]any{"journeyId": j.JourneyID, "sampleIds": sampleIDs, "sampleId": firstOf(sampleIDs), "kind": kind, "sequence": asg.Sequence, "via": "batch"})
		return asg
	}
	prevLoc := ""
	for i, locID := range route.Path {
		loc := a.st.Locations[locID]
		handling := 0
		if loc != nil {
			handling = loc.HandlingMinutes
		}
		if i == len(route.Path)-1 {
			j.Stops = append(j.Stops, Stop{StopID: newID(), LocationID: locID, StopType: "delivery", Sequence: stopSeq, EstimatedAt: t, DwellMinutes: handling})
			stopSeq++
			lab := newAsg(KindLaboratory)
			lab.LaboratoryID = locID
			lab.FromLocationID = prevLoc
			lab.ToLocationID = locID
			t = t.Add(time.Duration(handling) * time.Minute)
			break
		}
		j.Stops = append(j.Stops, Stop{StopID: newID(), LocationID: locID, StopType: "handoff", Sequence: stopSeq, EstimatedAt: t, DwellMinutes: handling})
		stopSeq++
		node := newAsg(KindNode)
		node.NodeID = locID
		node.FromLocationID = prevLoc
		node.ToLocationID = route.Path[i+1]
		leg := newAsg(KindTransport)
		leg.FromLocationID = locID
		leg.ToLocationID = route.Path[i+1]
		leg.ConnectionID = route.ConnectionIDs[i]
		if conn := a.st.Connections[leg.ConnectionID]; conn != nil {
			leg.TravelMinutes = conn.TravelMinutes
		}
		t = t.Add(time.Duration(handling+leg.TravelMinutes) * time.Minute)
		prevLoc = locID
	}
	j.EstimatedDeliveryAt = t
	j.TotalCostUnits = route.Cost
	j.TargetLaboratoryID = route.LabID
	for _, s := range samples {
		typ := a.st.SampleTypes[s.SampleTypeID]
		a.reserveRoute(u, j.JourneyID, s.SampleID, routeResources(route), typ != nil && typ.RequiresCooledRoute)
		s.TargetLaboratoryID = route.LabID
		s.ActiveJourneyID = j.JourneyID
		u.saveSample(s)
	}
	for _, id := range j.AssignmentIDs {
		asg := a.st.Assignments[id]
		if asg.Status == AsgPending && asg.OfferedWorkerID == "" {
			a.offerAssignment(u, asg, c.actorID(), roleOrNone(c.role))
		}
	}
}

func (a *App) mergeJourneys(c *Ctx, target *Journey, sourceIDs []string) *apiErr {
	if len(sourceIDs) == 0 {
		return errConflict("invalid_merge", "sourceJourneyIds must not be empty")
	}
	sources := []*Journey{}
	seen := map[string]bool{target.JourneyID: true}
	for _, id := range sourceIDs {
		if seen[id] {
			return errConflict("invalid_merge", "journeys to merge must be distinct")
		}
		seen[id] = true
		src := a.st.Journeys[id]
		if src == nil {
			return errNotFound("source journey not found")
		}
		if src.Terminal() {
			return errConflict("invalid_merge", "source journey is no longer active")
		}
		sources = append(sources, src)
	}
	all := append([]*Journey{target}, sources...)
	samples := []*Sample{}
	for _, j := range all {
		if a.sharedStarted(j) {
			return errConflict("partial_journey_merge", "a journey with transport already under way cannot be merged")
		}
		if j.StartLocationID != target.StartLocationID {
			return errConflict("invalid_merge", "journeys must enter the network at the same node to be merged")
		}
		for _, sid := range j.SampleIDs {
			s := a.st.Samples[sid]
			if s == nil || s.Terminal() {
				return errConflict("invalid_merge", "journey contains a closed sample")
			}
			samples = append(samples, s)
		}
	}
	if e := a.typesCompatible(samples); e != nil {
		return e
	}
	typeIDs := []string{}
	for _, s := range samples {
		if !contains(typeIDs, s.SampleTypeID) {
			typeIDs = append(typeIDs, s.SampleTypeID)
		}
	}
	// release every shared reservation, then search with the batch size
	for _, s := range samples {
		a.releaseReservations(c.u, func(r *Reservation) bool { return r.SampleID == s.SampleID })
	}
	net := a.buildNetwork(c.now)
	starts := []startPoint{{locID: target.StartLocationID}}
	plain := routeFilter{}
	if a.findRoute(net, starts, typeIDs, plain) == nil {
		a.restoreReservations(c, all)
		return errConflict("no_valid_route", "no laboratory accepts every sample in the batch along an active route")
	}
	withCap := routeFilter{checkCapacity: true, units: len(samples)}
	route := a.findRoute(net, starts, typeIDs, withCap)
	if route == nil {
		a.restoreReservations(c, all)
		return errConflict("capacity_exhausted", "not enough capacity for the combined batch")
	}
	// the batch departs once the last sample has reached the entry node
	start := time.Time{}
	for _, j := range all {
		for _, st := range j.Stops {
			if st.LocationID == target.StartLocationID && st.EstimatedAt.After(start) {
				start = st.EstimatedAt
			}
		}
	}
	eta := start.Add(time.Duration(route.TotalMinutes) * time.Minute)
	for _, s := range samples {
		if eta.After(s.DeliveryDeadline) {
			a.restoreReservations(c, all)
			return errConflict("deadline_exceeded", "the batch cannot reach the laboratory before every deadline")
		}
	}
	// move per-sample work of the sources into the target
	for _, src := range sources {
		for _, asg := range a.journeyAssignments(src) {
			shared := asg.Kind == KindNode || asg.Kind == KindLaboratory || (asg.Kind == KindTransport && asg.ConnectionID != "")
			if shared {
				if asg.Active() {
					a.cancelAssignment(c.u, asg, "merged_into_"+target.JourneyID, c.actorID(), roleOrNone(c.role))
				}
				continue
			}
			asg.JourneyID = target.JourneyID
			target.AssignmentIDs = append(target.AssignmentIDs, asg.AssignmentID)
			c.u.saveAssignment(asg)
		}
		for _, st := range src.Stops {
			if st.SampleID != "" {
				target.Stops = append(target.Stops, st)
			}
		}
		target.SampleIDs = append(target.SampleIDs, src.SampleIDs...)
		src.Status = JourneyMerged
		src.ReplanStatus = "replaced"
		src.ReplacementJourneyID = target.JourneyID
		src.PlanVersion++
		c.u.saveJourney(src)
		c.audit("journey.merged", "journey", src.JourneyID, true, map[string]any{"targetJourneyId": target.JourneyID, "sampleIds": src.SampleIDs})
		c.u.event("journey.updated", "journey", src.JourneyID, map[string]any{"journeyId": src.JourneyID, "status": src.Status, "replacementJourneyId": target.JourneyID}, []string{RoleAdministrator, RoleDispatcher}, nil)
	}
	for i := range target.Stops {
		target.Stops[i].Sequence = i
	}
	a.rebuildSharedChain(c, target, samples, route, start)
	target.PlanVersion++
	target.RouteMode = "batched"
	target.SplitJourneyID = ""
	c.u.saveJourney(target)
	c.audit("journey.batch_formed", "journey", target.JourneyID, true, map[string]any{"sampleIds": target.SampleIDs, "sourceJourneyIds": sourceIDs, "planVersion": target.PlanVersion, "path": route.Path, "estimatedDeliveryAt": fmtTime(target.EstimatedDeliveryAt)})
	c.u.event("journey.updated", "journey", target.JourneyID, map[string]any{"journeyId": target.JourneyID, "status": target.Status, "planVersion": target.PlanVersion, "routeMode": target.RouteMode}, []string{RoleAdministrator, RoleDispatcher}, nil)
	return nil
}

// restoreReservations re-reserves the current routes of journeys after a
// rejected merge so the existing plans stay intact.
func (a *App) restoreReservations(c *Ctx, journeys []*Journey) {
	for _, j := range journeys {
		resources := []string{}
		for _, st := range j.Stops {
			if st.SampleID == "" && st.CompletedAt == nil && a.st.Locations[st.LocationID] != nil {
				resources = append(resources, st.LocationID)
			}
		}
		for _, asg := range a.journeyAssignments(j) {
			if asg.Active() && asg.ConnectionID != "" {
				resources = append(resources, asg.ConnectionID)
			}
		}
		for _, sid := range j.SampleIDs {
			s := a.st.Samples[sid]
			if s == nil {
				continue
			}
			typ := a.st.SampleTypes[s.SampleTypeID]
			a.reserveRoute(c.u, j.JourneyID, sid, resources, typ != nil && typ.RequiresCooledRoute)
		}
	}
}

func (a *App) hMergeJourneys(c *Ctx, body []byte) (int, any, *apiErr) {
	var req planReq
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	j, e := a.loadJourneyForEdit(req.TargetJourneyID, req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	if req.SourceJourneyIDs == nil {
		return 0, nil, errInvalidJSON("sourceJourneyIds is required")
	}
	if e := a.mergeJourneys(c, j, req.SourceJourneyIDs); e != nil {
		return 0, nil, e
	}
	return 201, a.journeyPlanView(j, true), nil
}

// --- edit active plan --------------------------------------------------------

func (a *App) hEditActivePlan(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		JourneyID           *string         `json:"journeyId"`
		ExpectedPlanVersion *int            `json:"expectedPlanVersion"`
		ChangeType          *string         `json:"changeType"`
		Changes             json.RawMessage `json:"changes"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.ChangeType == nil {
		return 0, nil, errInvalidJSON("changeType is required")
	}
	switch *req.ChangeType {
	case "add_stop", "remove_stop", "reorder_stops", "replace_worker", "reassign_worker", "merge_samples", "split_samples", "split_batch", "cancel_work", "reroute", "replace_route":
	default:
		return 0, nil, E(400, "invalid_change_type", "changeType is not supported")
	}
	j, e := a.loadJourneyForEdit(req.JourneyID, req.ExpectedPlanVersion)
	if e != nil {
		return 0, nil, e
	}
	var ch struct {
		Reason           string   `json:"reason"`
		SourceJourneyIDs []string `json:"sourceJourneyIds"`
		SampleIDs        []string `json:"sampleIds"`
		AssignmentID     string   `json:"assignmentId"`
		WorkerID         string   `json:"workerId"`
		LocationID       string   `json:"locationId"`
		StopID           string   `json:"stopId"`
		StopIDs          []string `json:"stopIds"`
		LocationIDs      []string `json:"locationIds"`
		DwellMinutes     *int     `json:"dwellMinutes"`
		AfterStopID      string   `json:"afterStopId"`
		AfterSequence    *int     `json:"afterSequence"`
	}
	if len(req.Changes) > 0 {
		if err := json.Unmarshal(req.Changes, &ch); err != nil {
			return 0, nil, errInvalidJSON("changes has the wrong shape")
		}
	} else {
		return 0, nil, errInvalidJSON("changes is required")
	}
	switch *req.ChangeType {
	case "cancel_work":
		a.cancelJourney(c, j, ch.Reason)
	case "reroute", "replace_route":
		reason := ch.Reason
		if reason == "" {
			reason = "dispatcher_" + *req.ChangeType
		}
		if len(ch.LocationIDs) > 0 {
			if e := a.replaceRemainingRoute(c, j, ch.LocationIDs, 0, *req.ChangeType); e != nil {
				return 0, nil, e
			}
		} else {
			status, replacement := a.rerouteJourney(c, j, reason)
			if replacement != nil {
				return 201, a.journeyPlanView(replacement, true), nil
			}
			if status == "expired" || status == "exception" {
				return 201, a.journeyPlanView(j, true), nil
			}
		}
	case "merge_samples":
		if e := a.mergeJourneys(c, j, ch.SourceJourneyIDs); e != nil {
			return 0, nil, e
		}
	case "split_samples", "split_batch":
		if _, e := a.splitJourney(c, j, ch.SampleIDs); e != nil {
			return 0, nil, e
		}
	case "replace_worker", "reassign_worker":
		if e := a.reassignWorker(c, j, ch.AssignmentID, ch.WorkerID); e != nil {
			return 0, nil, e
		}
	case "add_stop", "remove_stop", "reorder_stops":
		dwell := 0
		if ch.DwellMinutes != nil {
			dwell = *ch.DwellMinutes
		}
		locs, e := a.editedStopList(j, *req.ChangeType, ch.LocationID, ch.StopID, ch.StopIDs, ch.LocationIDs, ch.AfterStopID, ch.AfterSequence)
		if e != nil {
			return 0, nil, e
		}
		if e := a.replaceRemainingRoute(c, j, locs, dwell, *req.ChangeType); e != nil {
			return 0, nil, e
		}
	}
	c.audit("journey.plan_edited", "journey", j.JourneyID, true, map[string]any{"changeType": *req.ChangeType, "changes": json.RawMessage(req.Changes), "planVersion": j.PlanVersion, "sampleIds": j.SampleIDs})
	return 201, a.journeyPlanView(j, true), nil
}

func (a *App) reassignWorker(c *Ctx, j *Journey, assignmentID, workerID string) *apiErr {
	if assignmentID == "" || workerID == "" {
		return errInvalidJSON("changes.assignmentId and changes.workerId are required")
	}
	asg := a.st.Assignments[assignmentID]
	if asg == nil || asg.JourneyID != j.JourneyID {
		return errConflict("invalid_assignment", "assignment does not belong to this journey")
	}
	if asg.Terminal() {
		return errConflict("completed_work_immutable", "completed or cancelled work cannot be reassigned")
	}
	if a.holdsAnySample(asg.WorkerID, asg) {
		return errConflict("work_in_progress", "the current worker holds custody of the sample")
	}
	w := a.st.Users[workerID]
	if w == nil {
		return E(400, "invalid_worker", "worker not found")
	}
	if ok, reason := a.potentiallyEligible(w, asg, c.now); !ok {
		return errConflict("ineligible_worker", "worker is not eligible: "+reason)
	}
	if !w.Available || a.workerActiveAssignmentCountExcluding(w.UserID, asg.AssignmentID) >= w.CapacityUnits {
		return errConflict("worker_unavailable", "worker is unavailable or at capacity")
	}
	prev := asg.WorkerID
	if prev == "" {
		prev = asg.OfferedWorkerID
	}
	asg.WorkerID = ""
	asg.AcceptedAt = nil
	asg.Status = AsgPending
	asg.DeclinedBy = nil
	now := c.now
	exp := now.Add(a.cfg.OfferTimeout)
	asg.OfferedWorkerID = w.UserID
	asg.OfferedAt = &now
	asg.OfferExpiresAt = &exp
	w.LastOfferedAt = &now
	c.u.saveUser(w)
	c.u.saveAssignment(asg)
	j.PlanVersion++
	c.u.saveJourney(j)
	c.audit("assignment.reassigned", "assignment", asg.AssignmentID, true, map[string]any{"journeyId": j.JourneyID, "sampleIds": asg.SampleIDs, "sampleId": firstOf(asg.SampleIDs), "previousWorkerId": prev, "workerId": w.UserID, "override": true})
	c.u.event("assignment.offered", "assignment", asg.AssignmentID, map[string]any{"assignmentId": asg.AssignmentID, "kind": asg.Kind, "workerId": w.UserID, "journeyId": j.JourneyID, "offerExpiresAt": fmtTime(exp)}, []string{RoleAdministrator, RoleDispatcher}, []string{w.UserID, prev})
	return nil
}

// editedStopList derives the new ordered list of remaining intermediate
// locations for a stop edit.
func (a *App) editedStopList(j *Journey, change, locationID, stopID string, stopIDs, locationIDs []string, afterStopID string, afterSeq *int) ([]string, *apiErr) {
	var current []Stop
	for _, st := range j.Stops {
		if st.SampleID == "" && st.CompletedAt == nil && st.StopType == "handoff" {
			current = append(current, st)
		}
	}
	locs := []string{}
	for _, st := range current {
		locs = append(locs, st.LocationID)
	}
	switch change {
	case "add_stop":
		if locationID == "" {
			return nil, errInvalidJSON("changes.locationId is required")
		}
		if contains(locs, locationID) || locationID == j.TargetLaboratoryID || locationID == j.StartLocationID {
			return nil, errConflict("ambiguous_stop", "the location is already part of the route")
		}
		idx := len(locs)
		if afterStopID != "" {
			found := false
			for i, st := range current {
				if st.StopID == afterStopID {
					idx = i + 1
					found = true
				}
			}
			if !found {
				for _, st := range j.Stops {
					if st.StopID == afterStopID {
						if st.CompletedAt != nil && st.StopType != "pickup" {
							return nil, errConflict("completed_work_immutable", "cannot insert after a completed stop")
						}
						idx = 0
						found = true
					}
				}
			}
			if !found {
				return nil, errConflict("invalid_stop", "afterStopId does not reference a stop on this journey")
			}
		} else if afterSeq != nil {
			idx = *afterSeq
			if idx < 0 || idx > len(locs) {
				return nil, errConflict("invalid_stop_order", "afterSequence is out of range")
			}
		}
		locs = append(locs[:idx], append([]string{locationID}, locs[idx:]...)...)
	case "remove_stop":
		if stopID == "" {
			return nil, errInvalidJSON("changes.stopId is required")
		}
		idx := -1
		for i, st := range current {
			if st.StopID == stopID {
				idx = i
			}
		}
		if idx < 0 {
			for _, st := range j.Stops {
				if st.StopID == stopID {
					if st.CompletedAt != nil {
						return nil, errConflict("completed_work_immutable", "completed stops cannot be removed")
					}
					return nil, errConflict("invalid_stop", "pickup and delivery stops cannot be removed")
				}
			}
			return nil, errConflict("invalid_stop", "stop not found on this journey")
		}
		locs = append(locs[:idx], locs[idx+1:]...)
	case "reorder_stops":
		ids := stopIDs
		if len(ids) == 0 && len(locationIDs) > 0 {
			for _, lid := range locationIDs {
				found := false
				for _, st := range current {
					if st.LocationID == lid {
						ids = append(ids, st.StopID)
						found = true
					}
				}
				if !found {
					return nil, errConflict("invalid_stop_order", "location is not a remaining intermediate stop")
				}
			}
		}
		if len(ids) != len(current) {
			return nil, errConflict("ambiguous_stop_order", "stopIds must list every remaining intermediate stop exactly once")
		}
		seen := map[string]bool{}
		locs = []string{}
		for _, id := range ids {
			if seen[id] {
				return nil, errConflict("ambiguous_stop_order", "stop listed more than once")
			}
			seen[id] = true
			found := false
			for _, st := range current {
				if st.StopID == id {
					locs = append(locs, st.LocationID)
					found = true
				}
			}
			if !found {
				for _, st := range j.Stops {
					if st.StopID == id {
						return nil, errConflict("invalid_stop_order", "completed, pickup or delivery stops cannot be reordered")
					}
				}
				return nil, errConflict("invalid_stop_order", "stop not found on this journey")
			}
		}
	}
	return locs, nil
}

// replaceRemainingRoute rebuilds the unfinished part of a journey so that it
// passes through the given intermediate locations in order. The change is
// rejected (leaving the plan untouched) when any leg, reservation or deadline
// check fails.
func (a *App) replaceRemainingRoute(c *Ctx, j *Journey, intermediates []string, dwell int, change string) *apiErr {
	if dwell < 0 || dwell > 1440 {
		return E(400, "invalid_dwell", "dwellMinutes must be between 0 and 1440")
	}
	if a.sharedStarted(j) {
		return errConflict("work_in_progress", "the shared route is already under way")
	}
	samples := []*Sample{}
	typeIDs := []string{}
	cooled := false
	for _, sid := range j.SampleIDs {
		s := a.st.Samples[sid]
		if s == nil || s.Terminal() {
			continue
		}
		samples = append(samples, s)
		if !contains(typeIDs, s.SampleTypeID) {
			typeIDs = append(typeIDs, s.SampleTypeID)
		}
		if t := a.st.SampleTypes[s.SampleTypeID]; t != nil {
			if t.RequiresCooledRoute {
				cooled = true
			}
			if !t.BatchingAllowed && dwell > 0 {
				return errConflict("pulse_no_wait", "time-critical samples cannot wait at an added stop")
			}
		}
	}
	if len(samples) == 0 {
		return errConflict("inactive_plan", "journey has no active samples")
	}
	start := j.StartLocationID
	lab := j.TargetLaboratoryID
	path := append([]string{start}, intermediates...)
	path = append(path, lab)
	seen := map[string]bool{}
	for _, l := range path {
		if seen[l] {
			return errConflict("ambiguous_stop", "a location appears twice on the route")
		}
		seen[l] = true
		loc := a.st.Locations[l]
		if loc == nil || !loc.Active {
			return errConflict("invalid_stop", "route location is unknown or inactive")
		}
		if l != start && l != lab && !(loc.Functions[FnTransferPoint] || loc.Functions[FnHub]) {
			return errConflict("invalid_stop", "intermediate stops must be transfer points or hubs")
		}
	}
	labLoc := a.st.Locations[lab]
	if labLoc == nil || !a.labAccepts(labLoc, typeIDs) {
		return errConflict("invalid_destination", "the laboratory does not accept every sample in the journey")
	}
	connIDs := []string{}
	total := 0
	cost := 0.0
	for i := 0; i+1 < len(path); i++ {
		var best *Connection
		for _, cid := range sortedKeys(a.st.Connections) {
			cn := a.st.Connections[cid]
			if cn.Active && cn.FromLocationID == path[i] && cn.ToLocationID == path[i+1] && (!cooled || cn.Cooled) {
				if best == nil || cn.TravelMinutes < best.TravelMinutes {
					best = cn
				}
			}
		}
		if best == nil {
			return errConflict("invalid_route", "no active connection between consecutive stops")
		}
		connIDs = append(connIDs, best.ConnectionID)
		total += best.TravelMinutes
		cost += best.CostUnits
		if i+1 < len(path)-1 {
			total += a.st.Locations[path[i+1]].HandlingMinutes + dwell
		}
	}
	// the shared part begins once the last sample has reached the start node
	begin := time.Time{}
	for _, st := range j.Stops {
		if st.LocationID == start && st.EstimatedAt.After(begin) {
			begin = st.EstimatedAt
		}
	}
	if begin.IsZero() {
		begin = c.now
	}
	eta := begin.Add(time.Duration(total+labLoc.HandlingMinutes) * time.Minute)
	for _, s := range samples {
		if eta.After(s.DeliveryDeadline) {
			return errConflict("deadline_exceeded", "the edited route cannot meet every delivery deadline")
		}
	}
	route := &Route{StartLocationID: start, Path: path, ConnectionIDs: connIDs, LabID: lab, TotalMinutes: total, Cost: cost, ETA: eta}
	// capacity: release the current shared reservations, verify, then rebuild
	for _, s := range samples {
		a.releaseReservations(c.u, func(r *Reservation) bool { return r.SampleID == s.SampleID })
	}
	for _, rid := range routeResources(route) {
		if a.availableUnits(rid, cooled) < len(samples) {
			a.restoreReservations(c, []*Journey{j})
			if cooled {
				return errConflict("cooled_capacity_exhausted", "not enough cooled capacity on the edited route")
			}
			return errConflict("capacity_exhausted", "not enough capacity on the edited route")
		}
	}
	a.rebuildSharedChain(c, j, samples, route, begin)
	if dwell > 0 {
		for i := range j.Stops {
			if j.Stops[i].StopType == "handoff" && j.Stops[i].SampleID == "" {
				j.Stops[i].DwellMinutes += dwell
			}
		}
	}
	j.PlanVersion++
	j.RouteMode = routeModeFor(j, a)
	c.u.saveJourney(j)
	c.audit("journey.route_changed", "journey", j.JourneyID, true, map[string]any{"changeType": change, "path": path, "planVersion": j.PlanVersion, "estimatedDeliveryAt": fmtTime(j.EstimatedDeliveryAt), "sampleIds": j.SampleIDs})
	c.u.event("journey.updated", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID, "status": j.Status, "planVersion": j.PlanVersion}, []string{RoleAdministrator, RoleDispatcher}, nil)
	return nil
}

