package app

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

const wsSubprotocol = "lab-logistics-v1"

type subscriber struct {
	ch     chan *Event
	userID string
	role   string
}

// Hub fans realtime events out to websocket subscribers.
type Hub struct {
	mu   sync.Mutex
	subs map[*subscriber]struct{}
}

func newHub() *Hub { return &Hub{subs: map[*subscriber]struct{}{}} }

func (h *Hub) add(s *subscriber) {
	h.mu.Lock()
	h.subs[s] = struct{}{}
	h.mu.Unlock()
}

func (h *Hub) remove(s *subscriber) {
	h.mu.Lock()
	delete(h.subs, s)
	h.mu.Unlock()
}

func (h *Hub) broadcast(ev *Event) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for s := range h.subs {
		if !eventVisible(ev, s.userID, s.role) {
			continue
		}
		select {
		case s.ch <- ev:
		default:
		}
	}
}

// eventVisible applies audience filtering: broadcast events are visible to
// everyone, role-addressed events only to sessions acting in that role, and
// user-addressed events to the named users.
func eventVisible(ev *Event, userID, role string) bool {
	if len(ev.AudienceRoles) == 0 && len(ev.AudienceUsers) == 0 {
		return true
	}
	if role != "" && contains(ev.AudienceRoles, role) {
		return true
	}
	return contains(ev.AudienceUsers, userID)
}

func eventView(ev *Event) map[string]any {
	payload := ev.Payload
	if payload == nil {
		payload = map[string]any{}
	}
	return map[string]any{
		"id": ev.ID, "type": ev.Type, "entityType": ev.EntityType, "entityId": ev.EntityID, "payload": payload, "createdAt": fmtTime(ev.CreatedAt),
	}
}

var upgrader = websocket.Upgrader{
	CheckOrigin:  func(r *http.Request) bool { return true },
	Subprotocols: []string{wsSubprotocol},
}

func tokenFromSubprotocols(r *http.Request) string {
	for _, p := range websocket.Subprotocols(r) {
		if strings.HasPrefix(p, "bearer.") {
			raw := strings.TrimPrefix(p, "bearer.")
			if b, err := base64.RawURLEncoding.DecodeString(raw); err == nil {
				return string(b)
			}
			if b, err := base64.URLEncoding.DecodeString(raw); err == nil {
				return string(b)
			}
			return raw
		}
	}
	return ""
}

func (a *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeErr(w, E(405, "method_not_allowed", "method not allowed"))
		return
	}
	since := int64(0)
	if v := r.URL.Query().Get("since"); v != "" {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || n < 0 {
			writeErr(w, E(400, "invalid_json", "since must be a non-negative integer"))
			return
		}
		since = n
	}
	token := ""
	if h := r.Header.Get("Authorization"); strings.HasPrefix(strings.ToLower(h), "bearer ") {
		token = strings.TrimSpace(h[7:])
	}
	if token == "" {
		token = tokenFromSubprotocols(r)
	}
	if token == "" {
		token = r.URL.Query().Get("token")
	}
	a.mu.Lock()
	sess, user, e := a.sessionByToken(token)
	if e != nil {
		a.mu.Unlock()
		writeErr(w, e)
		return
	}
	role := sess.ActiveRole
	userID := user.UserID
	backlog := []*Event{}
	for _, ev := range a.st.Events {
		if ev.ID > since && eventVisible(ev, userID, role) {
			backlog = append(backlog, ev)
		}
	}
	cursor := a.st.NextEventID - 1
	a.mu.Unlock()

	if !websocket.IsWebSocketUpgrade(r) {
		const max = 2000
		events := []any{}
		for i, ev := range backlog {
			if i >= max {
				cursor = backlog[i-1].ID
				break
			}
			events = append(events, eventView(ev))
		}
		writeJSON(w, 200, map[string]any{"data": map[string]any{"events": events, "cursor": cursor}})
		return
	}
	sub := &subscriber{ch: make(chan *Event, 256), userID: userID, role: role}
	a.hub.add(sub)
	defer a.hub.remove(sub)
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()
	write := func(ev *Event) error {
		b, _ := json.Marshal(eventView(ev))
		conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
		return conn.WriteMessage(websocket.TextMessage, b)
	}
	for _, ev := range backlog {
		if err := write(ev); err != nil {
			return
		}
	}
	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()
	ping := time.NewTicker(25 * time.Second)
	defer ping.Stop()
	for {
		select {
		case <-done:
			return
		case <-a.stopCh:
			return
		case ev := <-sub.ch:
			// the session's selected role may have changed since subscribing
			a.mu.Lock()
			if s := a.st.Sessions[token]; s != nil {
				sub.role = s.ActiveRole
			}
			a.mu.Unlock()
			if !eventVisible(ev, sub.userID, sub.role) {
				continue
			}
			if err := write(ev); err != nil {
				return
			}
		case <-ping.C:
			conn.SetWriteDeadline(time.Now().Add(10 * time.Second))
			if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}
}

