// Command server runs the Lab Sample Pickup & Delivery backend.
//
//	server          start the HTTP server (foreground)
//	server reset    drop and recreate all application-owned database state
//	server migrate  create tables and indexes without starting
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"labsample/internal/app"
	"labsample/internal/store"
)

func main() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds)
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	ctx := context.Background()
	st, err := store.Open(ctx, dbURL)
	if err != nil {
		log.Fatalf("open database: %v", err)
	}
	defer st.Close()
	if err := waitForDB(ctx, st, 60*time.Second); err != nil {
		log.Fatalf("database unavailable: %v", err)
	}
	if len(os.Args) > 1 {
		switch os.Args[1] {
		case "reset":
			if err := st.Reset(ctx); err != nil {
				log.Fatalf("reset: %v", err)
			}
			fmt.Println("database reset complete")
			return
		case "migrate":
			if err := st.Migrate(ctx); err != nil {
				log.Fatalf("migrate: %v", err)
			}
			fmt.Println("migration complete")
			return
		default:
			log.Fatalf("unknown command %q", os.Args[1])
		}
	}
	cfg := app.ConfigFromEnv()
	a := app.New(cfg, st)
	if err := a.Start(ctx); err != nil {
		log.Fatalf("start: %v", err)
	}
	srv := &http.Server{
		Addr:              net.JoinHostPort("0.0.0.0", cfg.Port),
		Handler:           a.Handler(),
		ReadHeaderTimeout: 10 * time.Second,
	}
	go func() {
		log.Printf("listening on http://127.0.0.1:%s", cfg.Port)
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatalf("listen: %v", err)
		}
	}()
	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGINT, syscall.SIGTERM)
	<-sig
	log.Printf("shutting down")
	a.Stop()
	shutdownCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	_ = srv.Shutdown(shutdownCtx)
}

func waitForDB(ctx context.Context, st *store.Store, timeout time.Duration) error {
	deadline := time.Now().Add(timeout)
	for {
		err := st.Ping(ctx)
		if err == nil {
			return nil
		}
		if time.Now().After(deadline) {
			return err
		}
		time.Sleep(500 * time.Millisecond)
	}
}

