// registerStatic serves the built frontend and the local map assets.
func (a *App) registerStatic(mux *http.ServeMux) {
        mapDir := a.cfg.MapAssetsDir
        if mapDir == "" {
                for _, cand := range []string{"map-assets", "/opt/arena/map-assets"} {
                        if st, err := os.Stat(filepath.Join(cand, "bangalore.pmtiles")); err == nil && !st.IsDir() {
                                mapDir = cand
                                break
                        }
                }
        }
        if mapDir != "" {
                fs := http.StripPrefix("/map-assets/", http.FileServer(http.Dir(mapDir)))
                mux.Handle("/map-assets/", corsCache(fs))
                log.Printf("serving map assets from %s", mapDir)
        } else {
                log.Printf("warning: map assets directory not found")
        }
        dist := a.cfg.FrontendDir
        index := filepath.Join(dist, "index.html")
        fileServer := http.FileServer(http.Dir(dist))
        mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
                if r.Method != http.MethodGet && r.Method != http.MethodHead {
                        writeErr(w, E(405, "method_not_allowed", "method not allowed"))
                        return
                }
                p := filepath.Clean(r.URL.Path)
                full := filepath.Join(dist, p)
                if st, err := os.Stat(full); err == nil && !st.IsDir() {
                        if strings.HasPrefix(p, "/assets/") {
                                w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
                        }
                        fileServer.ServeHTTP(w, r)
                        return
                }
                if _, err := os.Stat(index); err != nil {
                        http.Error(w, "frontend not built", 404)
                        return
                }
                w.Header().Set("Cache-Control", "no-cache")
                http.ServeFile(w, r, index)
        })
}

func corsCache(h http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
                w.Header().Set("Cache-Control", "public, max-age=86400")
                w.Header().Set("Access-Control-Allow-Origin", "*")
                h.ServeHTTP(w, r)
        })
}

