export interface Coordinate {
  latitude: number;
  longitude: number;
}

export interface SessionUser {
  userId: string;
  username: string;
  fullName?: string;
  roles: string[];
  activeRole: string;
  roleSelectionRequired: boolean;
}

export interface Capacity {
  capacityUnits: number;
  reservedUnits: number;
  availableUnits: number;
  cooledCapacityUnits: number;
  cooledReservedUnits: number;
  cooledAvailableUnits: number;
}

export interface OpsLocation {
  id: string;
  locationId: string;
  name: string;
  coordinate: Coordinate;
  active: boolean;
  coverageKm: number;
  handlingMinutes: number;
  functions: Record<string, boolean>;
  capacity?: Capacity;
  acceptedSampleTypeIds?: string[];
}

export interface OpsConnection {
  id: string;
  connectionId: string;
  fromLocationId: string;
  toLocationId: string;
  travelMinutes: number;
  costUnits: number;
  cooled: boolean;
  active: boolean;
  capacity?: Capacity;
}

export interface OpsWorker {
  workerId: string;
  fullName?: string;
  roles?: string[];
  available: boolean;
  status: string;
  capacityUnits: number;
  assignmentCount: number;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

export interface OpsSample {
  sampleId: string;
  status: string;
  requestId?: string;
  origin?: Coordinate;
  deliveryDeadline?: string;
  currentHolderId?: string;
  activeJourneyId?: string;
  latestLocation?: Coordinate;
  locationRecordedAt?: string;
  locationStale: boolean;
}

export interface OperationsState {
  samples: OpsSample[];
  workers: OpsWorker[];
  locations: OpsLocation[];
  connections: OpsConnection[];
  routes: any[];
  handoffs: any[];
  delays: any[];
  exceptions: any[];
  assignmentCountSpread: number;
  ineligibleAssignmentCount: number;
}

export interface TimelineEntry {
  eventId: number;
  action: string;
  actorId: string;
  role: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details: Record<string, any>;
}

export interface WorkItem {
  kind: string;
  status: string;
  history: TimelineEntry[];
  [key: string]: any;
}

export interface RoleWork {
  pending: WorkItem[];
  inProgress: WorkItem[];
  completed: WorkItem[];
}

export interface Bootstrap {
  user: SessionUser;
  serverTime: string;
  requesterSamples?: WorkItem[];
  operations?: OperationsState;
}

