import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from "react";
import { ApiError, base64url, get, getToken, post, setToken } from "./api";
import type { Bootstrap } from "./types";

interface SessionState {
  boot: Bootstrap | null;
  loading: boolean;
  refresh: () => Promise<void>;
  login: (username: string, password: string) => Promise<void>;
  logout: () => void;
  selectRole: (role: string) => Promise<void>;
  eventTick: number;
}

const Ctx = createContext<SessionState>(null as any);

export function useSession() {
  return useContext(Ctx);
}

export function SessionProvider({ children }: { children: ReactNode }) {
  const [boot, setBoot] = useState<Bootstrap | null>(null);
  const [loading, setLoading] = useState<boolean>(!!getToken());
  const [eventTick, setEventTick] = useState(0);
  const wsRef = useRef<WebSocket | null>(null);

  const refresh = useCallback(async () => {
    if (!getToken()) {
      setBoot(null);
      setLoading(false);
      return;
    }
    try {
      const data = await get<Bootstrap>("/api/ui/bootstrap");
      setBoot(data);
    } catch (e) {
      if (e instanceof ApiError && e.status === 401) {
        setToken(null);
        setBoot(null);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // realtime stream: any durable event triggers a refresh tick for open views
  useEffect(() => {
    const token = getToken();
    if (!boot || !token) return;
    let closed = false;
    let since = 0;
    let timer: number | undefined;
    const connect = () => {
      if (closed) return;
      const proto = location.protocol === "https:" ? "wss" : "ws";
      const ws = new WebSocket(`${proto}://${location.host}/api/events?since=${since}`, ["lab-logistics-v1", `bearer.${base64url(token)}`]);
      wsRef.current = ws;
      ws.onmessage = (m) => {
        try {
          const ev = JSON.parse(m.data);
          if (typeof ev.id === "number") since = Math.max(since, ev.id);
        } catch {
          /* ignore */
        }
        setEventTick((t) => t + 1);
      };
      ws.onclose = () => {
        if (!closed) timer = window.setTimeout(connect, 3000);
      };
      ws.onerror = () => ws.close();
    };
    connect();
    return () => {
      closed = true;
      if (timer) window.clearTimeout(timer);
      wsRef.current?.close();
    };
  }, [boot?.user.userId, boot?.user.activeRole]);

  const login = useCallback(
    async (username: string, password: string) => {
      const data = await post<{ sessionToken: string }>("/api/authenticate-user", { username, password });
      setToken(data.sessionToken);
      setLoading(true);
      await refresh();
    },
    [refresh],
  );

  const logout = useCallback(() => {
    setToken(null);
    setBoot(null);
    wsRef.current?.close();
    location.hash = "#/";
  }, []);

  const selectRole = useCallback(
    async (role: string) => {
      await post("/api/select-active-role", { role });
      await refresh();
    },
    [refresh],
  );

  return <Ctx.Provider value={{ boot, loading, refresh, login, logout, selectRole, eventTick }}>{children}</Ctx.Provider>;
}

