import { useState, type FormEvent, type ReactNode } from "react";
import { ApiError, fmtTime, short } from "../api";
import type { TimelineEntry } from "../types";

export function Panel({ title, children, actions, id }: { title: string; children: ReactNode; actions?: ReactNode; id?: string }) {
  return (
    <section className="panel" aria-labelledby={id ? `${id}-title` : undefined} id={id}>
      <header className="panel-header">
        <h2 id={id ? `${id}-title` : undefined}>{title}</h2>
        {actions && <div className="panel-actions">{actions}</div>}
      </header>
      <div className="panel-body">{children}</div>
    </section>
  );
}

export function Banner({ kind, children }: { kind: "error" | "success" | "info" | "warning"; children: ReactNode }) {
  return (
    <div className={`banner ${kind}`} role={kind === "error" ? "alert" : "status"}>
      {children}
    </div>
  );
}

export function errorText(e: unknown): string {
  if (e instanceof ApiError) return `${e.message} (${e.code})`;
  if (e instanceof Error) return e.message;
  return String(e);
}

export function StatusBadge({ status }: { status?: string }) {
  if (!status) return null;
  const tone = /exception|expired|cancel|unservice|declined|fail/i.test(status)
    ? "bad"
    : /received|completed|confirmed|delivered|sealed|accepted/i.test(status)
      ? "good"
      : /pending|offered|planned|created/i.test(status)
        ? "neutral"
        : "active";
  return <span className={`badge ${tone}`}>{status.replace(/_/g, " ")}</span>;
}

export function Freshness({ stale, recordedAt }: { stale: boolean; recordedAt?: string }) {
  return (
    <span className={`badge ${stale ? "bad" : "good"}`} aria-label={stale ? "Location stale" : "Location fresh"}>
      {stale ? "Stale" : "Fresh"}
      {recordedAt ? ` · ${fmtTime(recordedAt)}` : ""}
    </span>
  );
}

export function Timeline({ entries, title = "Status timeline" }: { entries: TimelineEntry[]; title?: string }) {
  const sorted = [...entries].sort((a, b) => (a.occurredAt < b.occurredAt ? -1 : a.occurredAt > b.occurredAt ? 1 : a.eventId - b.eventId));
  return (
    <ol className="timeline" aria-label={title}>
      {sorted.length === 0 && <li className="muted">No status changes recorded yet.</li>}
      {sorted.map((e) => (
        <li key={e.eventId} className={e.success ? "" : "failed"}>
          <time dateTime={e.occurredAt}>{fmtTime(e.occurredAt)}</time>
          <strong>{e.action}</strong>
          <span className="muted">
            {e.role ? ` as ${e.role}` : ""} {e.details?.status ? `→ ${String(e.details.status)}` : ""}
            {e.details?.to ? ` → ${String(e.details.to)}` : ""}
          </span>
          {!e.success && <span className="badge bad">failed</span>}
        </li>
      ))}
    </ol>
  );
}

export function KV({ items }: { items: [string, ReactNode][] }) {
  return (
    <dl className="kv">
      {items.map(([k, v]) => (
        <div key={k}>
          <dt>{k}</dt>
          <dd>{v ?? "—"}</dd>
        </div>
      ))}
    </dl>
  );
}

export function Id({ value }: { value?: string | null }) {
  if (!value) return <>—</>;
  return (
    <code title={value} className="id">
      {short(value)}
    </code>
  );
}

export function Table<T>({ rows, columns, caption, empty = "Nothing to show.", rowKey }: { rows: T[]; columns: { header: string; cell: (r: T) => ReactNode }[]; caption: string; empty?: string; rowKey: (r: T) => string }) {
  return (
    <div className="table-wrap">
      <table>
        <caption className="sr-only">{caption}</caption>
        <thead>
          <tr>
            {columns.map((c) => (
              <th key={c.header} scope="col">
                {c.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 && (
            <tr>
              <td colSpan={columns.length} className="muted">
                {empty}
              </td>
            </tr>
          )}
          {rows.map((r) => (
            <tr key={rowKey(r)}>
              {columns.map((c) => (
                <td key={c.header}>{c.cell(r)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) {
  return (
    <label className="field">
      <span className="field-label">{label}</span>
      {children}
      {hint && <span className="hint">{hint}</span>}
    </label>
  );
}

export function useAsyncAction() {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const run = async (fn: () => Promise<string | void>) => {
    setBusy(true);
    setError(null);
    setMessage(null);
    try {
      const m = await fn();
      if (m) setMessage(m);
      return true;
    } catch (e) {
      setError(errorText(e));
      return false;
    } finally {
      setBusy(false);
    }
  };
  const feedback = (
    <>
      {error && <Banner kind="error">{error}</Banner>}
      {message && <Banner kind="success">{message}</Banner>}
    </>
  );
  return { busy, error, message, run, feedback, setError, setMessage };
}

export function Form({ onSubmit, children, submitLabel, busy, className }: { onSubmit: () => void; children: ReactNode; submitLabel: string; busy?: boolean; className?: string }) {
  const handle = (e: FormEvent) => {
    e.preventDefault();
    onSubmit();
  };
  return (
    <form onSubmit={handle} className={`form ${className ?? ""}`}>
      {children}
      <div className="form-actions">
        <button type="submit" disabled={busy}>
          {submitLabel}
        </button>
      </div>
    </form>
  );
}

export function Details({ summary, children }: { summary: string; children: ReactNode }) {
  return (
    <details className="details">
      <summary>{summary}</summary>
      {children}
    </details>
  );
}

