import { useEffect, useState } from "react";
import { ROLE_LABELS } from "./api";
import { useSession } from "./session";
import LoginPage from "./pages/LoginPage";
import RoleWorkPage from "./pages/RoleWorkPage";
import RequesterPage from "./pages/RequesterPage";
import SamplePage from "./pages/SamplePage";
import MonitorPage from "./pages/MonitorPage";
import AuditPage from "./pages/AuditPage";
import AdminPage from "./pages/AdminPage";
import FacilityPage from "./pages/FacilityPage";
import JourneyPage from "./pages/JourneyPage";
import { Banner, errorText } from "./components/ui";

function useHashRoute() {
  const [hash, setHash] = useState(location.hash || "#/");
  useEffect(() => {
    const h = () => setHash(location.hash || "#/");
    window.addEventListener("hashchange", h);
    return () => window.removeEventListener("hashchange", h);
  }, []);
  const path = hash.replace(/^#/, "") || "/";
  return path.split("/").filter(Boolean);
}

interface NavItem {
  href: string;
  label: string;
  roles: string[];
}

const NAV: NavItem[] = [
  { href: "#/requests", label: "My requests", roles: ["requester"] },
  { href: "#/work", label: "My work", roles: ["collection_professional", "delivery_partner", "node_handler", "laboratory_team"] },
  { href: "#/facility", label: "My facility", roles: ["node_handler", "laboratory_team"] },
  { href: "#/monitor", label: "Monitor", roles: ["dispatcher", "administrator"] },
  { href: "#/audit", label: "Audit", roles: ["dispatcher", "administrator"] },
  { href: "#/admin", label: "Administration", roles: ["administrator"] },
];

export default function App() {
  const { boot, loading, logout, selectRole } = useSession();
  const segments = useHashRoute();
  const [roleError, setRoleError] = useState<string | null>(null);

  if (loading) return <main className="centered muted">Loading…</main>;
  if (!boot) return <LoginPage />;

  const role = boot.user.activeRole;
  const nav = NAV.filter((n) => n.roles.includes(role));
  const current = `#/${segments[0] ?? ""}`;

  const onRole = async (r: string) => {
    setRoleError(null);
    try {
      await selectRole(r);
      location.hash = "#/";
    } catch (e) {
      setRoleError(errorText(e));
    }
  };

  let page: React.ReactNode;
  const head = segments[0];
  if (head === "sample" && segments[1]) page = <SamplePage sampleId={segments[1]} />;
  else if (head === "journey" && segments[1]) page = <JourneyPage journeyId={segments[1]} />;
  else if (head === "requests") page = <RequesterPage />;
  else if (head === "work") page = <RoleWorkPage />;
  else if (head === "facility") page = <FacilityPage />;
  else if (head === "monitor") page = <MonitorPage />;
  else if (head === "audit") page = <AuditPage />;
  else if (head === "admin") page = <AdminPage />;
  else page = <Home role={role} roleSelectionRequired={boot.user.roleSelectionRequired} />;

  return (
    <div className="shell">
      <header className="topbar">
        <a href="#/" className="brand">
          Lab Sample Pickup &amp; Delivery
        </a>
        <nav aria-label="Primary">
          {nav.map((n) => (
            <a key={n.href} href={n.href} aria-current={current === n.href ? "page" : undefined}>
              {n.label}
            </a>
          ))}
        </nav>
        <div className="session">
          <span className="user" aria-label="Signed in user">
            {boot.user.fullName || boot.user.username}
          </span>
          <label className="role-select">
            <span className="sr-only">Active role</span>
            <select aria-label="Active role" value={role} onChange={(e) => onRole(e.target.value)}>
              {boot.user.roles.map((r) => (
                <option key={r} value={r}>
                  {ROLE_LABELS[r] ?? r}
                </option>
              ))}
            </select>
          </label>
          <button type="button" onClick={logout}>
            Sign out
          </button>
        </div>
      </header>
      {roleError && <Banner kind="error">{roleError}</Banner>}
      <main className="content">{page}</main>
    </div>
  );
}

function Home({ role, roleSelectionRequired }: { role: string; roleSelectionRequired: boolean }) {
  const { boot } = useSession();
  const nav = NAV.filter((n) => n.roles.includes(role));
  return (
    <section className="home">
      <h1>Working as {ROLE_LABELS[role] ?? role}</h1>
      {roleSelectionRequired && boot && boot.user.roles.length > 1 && (
        <Banner kind="info">You hold several roles. Use the “Active role” selector in the header to choose the role you are working under; permissions and work views follow the selected role.</Banner>
      )}
      <p className="muted">Choose an area to begin:</p>
      <ul className="home-links">
        {nav.map((n) => (
          <li key={n.href}>
            <a href={n.href}>{n.label}</a>
          </li>
        ))}
        {nav.length === 0 && <li className="muted">No work areas are available for this role.</li>}
      </ul>
    </section>
  );
}

