package app

import (
	"crypto/pbkdf2"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"strings"
	"time"
)

func hashPassword(pw string) string {
	salt := make([]byte, 16)
	if _, err := rand.Read(salt); err != nil {
		panic(err)
	}
	key, err := pbkdf2.Key(sha256.New, pw, salt, 60000, 32)
	if err != nil {
		panic(err)
	}
	return "pbkdf2$" + base64.RawStdEncoding.EncodeToString(salt) + "$" + base64.RawStdEncoding.EncodeToString(key)
}

func verifyPassword(hash, pw string) bool {
	parts := strings.Split(hash, "$")
	if len(parts) != 3 || parts[0] != "pbkdf2" {
		return false
	}
	salt, err := base64.RawStdEncoding.DecodeString(parts[1])
	if err != nil {
		return false
	}
	want, err := base64.RawStdEncoding.DecodeString(parts[2])
	if err != nil {
		return false
	}
	key, err := pbkdf2.Key(sha256.New, pw, salt, 60000, len(want))
	if err != nil {
		return false
	}
	return subtle.ConstantTimeCompare(key, want) == 1
}

func (a *App) userByUsername(name string) *User {
	for _, u := range a.st.Users {
		if lower(u.Username) == lower(name) {
			return u
		}
	}
	return nil
}

func defaultActiveRole(u *User) string {
	if len(u.Roles) == 1 {
		return u.Roles[0]
	}
	return ""
}

func (a *App) hAuthenticate(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		Username *string `json:"username"`
		Password *string `json:"password"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.Username == nil || req.Password == nil {
		return 0, nil, errInvalidJSON("username and password are required")
	}
	user := a.userByUsername(*req.Username)
	if user == nil || !user.Active || !verifyPassword(user.PasswordHash, *req.Password) {
		actor := "anonymous"
		if user != nil {
			actor = user.UserID
		}
		c.u.audit(actor, "none", "auth.login", "user", actor, false, map[string]any{"username": *req.Username, "code": "invalid_credentials"})
		return 0, nil, E(401, "invalid_credentials", "invalid username or password")
	}
	sess := &Session{Token: newToken(), UserID: user.UserID, ActiveRole: defaultActiveRole(user), CreatedAt: c.now, ExpiresAt: c.now.Add(a.cfg.SessionTTL)}
	a.st.Sessions[sess.Token] = sess
	c.u.saveSession(sess)
	c.u.audit(user.UserID, roleOrNone(sess.ActiveRole), "auth.login", "user", user.UserID, true, map[string]any{"username": user.Username, "activeRole": sess.ActiveRole})
	return 200, map[string]any{
		"sessionToken": sess.Token,
		"userId":       user.UserID,
		"roles":        strs(user.Roles),
		"activeRole":   sess.ActiveRole,
	}, nil
}

func roleOrNone(r string) string {
	if r == "" {
		return "unselected"
	}
	return r
}

func strs(v []string) []string {
	if v == nil {
		return []string{}
	}
	return v
}

func validRole(r string) bool { return contains(AllRoles, r) }

func (a *App) hSelectActiveRole(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		Role *string `json:"role"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.Role == nil || !validRole(*req.Role) {
		return 0, nil, E(400, "invalid_role", "role must be one of the known roles")
	}
	if !contains(c.user.Roles, *req.Role) {
		c.audit("role.select", "user", c.user.UserID, false, map[string]any{"role": *req.Role, "code": "role_not_held"})
		return 0, nil, E(403, "role_not_held", "the account does not hold this role")
	}
	c.sess.ActiveRole = *req.Role
	c.u.saveSession(c.sess)
	c.role = *req.Role
	c.audit("role.select", "user", c.user.UserID, true, map[string]any{"role": *req.Role})
	return 200, map[string]any{"activeRole": c.sess.ActiveRole, "roles": strs(c.user.Roles)}, nil
}

func (a *App) hBootstrap(c *Ctx, body []byte) (int, any, *apiErr) {
	user := map[string]any{
		"userId":                c.user.UserID,
		"username":              c.user.Username,
		"roles":                 strs(c.user.Roles),
		"activeRole":            c.sess.ActiveRole,
		"roleSelectionRequired": c.sess.ActiveRole == "" && len(c.user.Roles) > 1,
	}
	if c.user.FullName != "" {
		user["fullName"] = c.user.FullName
	}
	data := map[string]any{"user": user, "serverTime": fmtTime(c.now)}
	if c.role == RoleRequester {
		items := []any{}
		for _, id := range sortedKeys(a.st.Samples) {
			s := a.st.Samples[id]
			if s.RequesterID == c.user.UserID {
				items = append(items, a.sampleWorkItem(s))
			}
		}
		data["requesterSamples"] = items
	}
	switch c.role {
	case RoleDispatcher, RoleAdministrator:
		data["operations"] = a.operationsState("")
	case RoleNodeHandler, RoleLaboratory, RoleCollector, RoleCourier:
		data["operations"] = a.workerOperationsView(c.user)
	}
	return 200, data, nil
}

// workerOperationsView is the network subset a field or facility worker may
// see: active locations and connections for orientation (capacity only for
// the worker's own assigned location) and nothing about other people's work.
func (a *App) workerOperationsView(w *User) map[string]any {
	locations := []any{}
	for _, id := range sortedKeys(a.st.Locations) {
		l := a.st.Locations[id]
		lv := map[string]any{
			"id": l.LocationID, "locationId": l.LocationID, "name": l.Name, "coordinate": coordView(l.Coordinate), "active": l.Active,
			"coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes, "functions": functionsView(l.Functions),
		}
		if l.LocationID == w.AssignedLocationID {
			lv["capacity"] = a.capacityView(l.LocationID)
			accepted := []string{}
			for _, tid := range sortedKeys(l.AcceptedTypes) {
				if l.AcceptedTypes[tid] {
					accepted = append(accepted, tid)
				}
			}
			lv["acceptedSampleTypeIds"] = accepted
		}
		locations = append(locations, lv)
	}
	connections := []any{}
	for _, id := range sortedKeys(a.st.Connections) {
		cn := a.st.Connections[id]
		connections = append(connections, map[string]any{
			"id": cn.ConnectionID, "connectionId": cn.ConnectionID, "fromLocationId": cn.FromLocationID, "toLocationId": cn.ToLocationID,
			"travelMinutes": cn.TravelMinutes, "costUnits": cn.CostUnits, "cooled": cn.Cooled, "active": cn.Active,
		})
	}
	return map[string]any{
		"samples": []any{}, "workers": []any{}, "locations": locations, "connections": connections,
		"routes": []any{}, "handoffs": []any{}, "delays": []any{}, "exceptions": []any{},
		"assignmentCountSpread": 0, "ineligibleAssignmentCount": 0,
	}
}

type certIn struct {
	Code      *string `json:"code"`
	Active    *bool   `json:"active"`
	ExpiresAt *string `json:"expiresAt"`
}

func parseCerts(in []certIn) ([]Certification, *apiErr) {
	out := []Certification{}
	for _, ci := range in {
		if ci.Code == nil || strings.TrimSpace(*ci.Code) == "" || ci.Active == nil {
			return nil, E(400, "invalid_certification", "certification requires code and active")
		}
		cert := Certification{Code: strings.TrimSpace(*ci.Code), Active: *ci.Active}
		if ci.ExpiresAt != nil && *ci.ExpiresAt != "" {
			t, ok := parseTime(*ci.ExpiresAt)
			if !ok {
				return nil, E(400, "invalid_certification", "certification expiresAt is not a valid timestamp")
			}
			cert.ExpiresAt = &t
		}
		out = append(out, cert)
	}
	return out, nil
}

func parseRoles(in []string) ([]string, bool) {
	out := []string{}
	for _, r := range in {
		if !validRole(r) {
			return nil, false
		}
		if !contains(out, r) {
			out = append(out, r)
		}
	}
	return out, true
}

func userView(u *User) map[string]any {
	v := map[string]any{
		"userId":         u.UserID,
		"username":       u.Username,
		"roles":          strs(u.Roles),
		"qualifications": strs(u.Qualifications),
		"certifications": certsView(u.Certifications),
		"active":         u.Active,
	}
	if u.Email != "" {
		v["email"] = u.Email
	}
	if u.FullName != "" {
		v["fullName"] = u.FullName
	}
	if u.Phone != "" {
		v["phone"] = u.Phone
	}
	return v
}

func certsView(cs []Certification) []map[string]any {
	out := []map[string]any{}
	for _, c := range cs {
		m := map[string]any{"code": c.Code, "active": c.Active}
		if c.ExpiresAt != nil {
			m["expiresAt"] = fmtTime(*c.ExpiresAt)
		}
		out = append(out, m)
	}
	return out
}

func (a *App) hCreateUser(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		Username           *string  `json:"username"`
		InitialPassword    *string  `json:"initialPassword"`
		Email              string   `json:"email"`
		FullName           string   `json:"fullName"`
		Phone              string   `json:"phone"`
		Roles              []string `json:"roles"`
		Qualifications     []string `json:"qualifications"`
		Certifications     []certIn `json:"certifications"`
		Active             *bool    `json:"active"`
		AssignedLocationID string   `json:"assignedLocationId"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.Username == nil || strings.TrimSpace(*req.Username) == "" || req.InitialPassword == nil || *req.InitialPassword == "" {
		return 0, nil, E(400, "invalid_user", "username and initialPassword are required")
	}
	if req.Active == nil {
		return 0, nil, E(400, "invalid_user", "active is required")
	}
	roles, ok := parseRoles(req.Roles)
	if !ok || len(roles) == 0 {
		return 0, nil, E(400, "invalid_user", "at least one valid role is required")
	}
	certs, e := parseCerts(req.Certifications)
	if e != nil {
		return 0, nil, e
	}
	if req.AssignedLocationID != "" && a.st.Locations[req.AssignedLocationID] == nil {
		return 0, nil, E(400, "invalid_user", "assignedLocationId does not reference a known location")
	}
	if a.userByUsername(*req.Username) != nil {
		return 0, nil, errConflict("username_exists", "username is already taken")
	}
	user := &User{
		UserID: newID(), Username: strings.TrimSpace(*req.Username), PasswordHash: hashPassword(*req.InitialPassword),
		Email: req.Email, FullName: req.FullName, Phone: req.Phone, Roles: roles, Qualifications: strs(req.Qualifications),
		Certifications: certs, Active: *req.Active, AssignedLocationID: req.AssignedLocationID, Available: true,
		CapacityUnits: defaultWorkerCapacity, CreatedAt: c.now,
	}
	a.st.Users[user.UserID] = user
	c.u.saveUser(user)
	c.audit("user.created", "user", user.UserID, true, map[string]any{"username": user.Username, "roles": roles, "assignedLocationId": user.AssignedLocationID})
	c.u.event("user.created", "user", user.UserID, userView(user), []string{RoleAdministrator, RoleDispatcher}, nil)
	a.retryPendingOffers(c.u)
	return 201, userView(user), nil
}

func (a *App) hReadUser(c *Ctx, body []byte) (int, any, *apiErr) {
	id := c.r.PathValue("userId")
	user := a.st.Users[id]
	if user == nil {
		return 0, nil, errNotFound("user not found")
	}
	if user.UserID != c.user.UserID && !c.isSupervisor() {
		return 0, nil, errForbidden("only administrators and dispatchers may read other users")
	}
	return 200, userView(user), nil
}

func (a *App) hUpdateUserAccess(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		UserID             *string  `json:"userId"`
		Roles              []string `json:"roles"`
		Qualifications     []string `json:"qualifications"`
		Certifications     []certIn `json:"certifications"`
		Active             *bool    `json:"active"`
		AssignedLocationID *string  `json:"assignedLocationId"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.UserID == nil || req.Active == nil || req.Roles == nil {
		return 0, nil, errInvalidJSON("userId, roles and active are required")
	}
	user := a.st.Users[*req.UserID]
	if user == nil {
		return 0, nil, errNotFound("user not found")
	}
	roles, ok := parseRoles(req.Roles)
	if !ok {
		return 0, nil, errInvalidJSON("roles contains an unknown role")
	}
	certs, e := parseCerts(req.Certifications)
	if e != nil {
		return 0, nil, e
	}
	if req.AssignedLocationID != nil && *req.AssignedLocationID != "" && a.st.Locations[*req.AssignedLocationID] == nil {
		return 0, nil, errNotFound("assignedLocationId does not reference a known location")
	}
	before := map[string]any{"roles": strs(user.Roles), "qualifications": strs(user.Qualifications), "active": user.Active, "assignedLocationId": user.AssignedLocationID}
	user.Roles = roles
	if req.Qualifications != nil {
		user.Qualifications = req.Qualifications
	}
	if req.Certifications != nil {
		user.Certifications = certs
	}
	user.Active = *req.Active
	if req.AssignedLocationID != nil {
		user.AssignedLocationID = *req.AssignedLocationID
	}
	c.u.saveUser(user)
	// sessions whose selected role was removed fall back to unselected
	for _, s := range a.st.Sessions {
		if s.UserID == user.UserID && s.ActiveRole != "" && !contains(user.Roles, s.ActiveRole) {
			s.ActiveRole = defaultActiveRole(user)
			c.u.saveSession(s)
		}
	}
	c.audit("user.access_updated", "user", user.UserID, true, map[string]any{"before": before, "after": map[string]any{"roles": roles, "qualifications": strs(user.Qualifications), "active": user.Active, "assignedLocationId": user.AssignedLocationID}})
	c.u.event("user.updated", "user", user.UserID, userView(user), []string{RoleAdministrator, RoleDispatcher}, nil)
	if !user.Active {
		a.workerBecameUnavailable(c.u, user, "user_deactivated", c)
	} else {
		a.recheckWorkerAssignments(c.u, user, c)
	}
	a.retryPendingOffers(c.u)
	return 201, map[string]any{
		"userId":         user.UserID,
		"roles":          strs(user.Roles),
		"qualifications": strs(user.Qualifications),
		"certifications": certsView(user.Certifications),
		"active":         user.Active,
	}, nil
}

func (a *App) hSetWorkerAvailability(c *Ctx, body []byte) (int, any, *apiErr) {
	var req struct {
		WorkerID      *string `json:"workerId"`
		Available     *bool   `json:"available"`
		CapacityUnits *int    `json:"capacityUnits"`
	}
	if e := decode(body, &req); e != nil {
		return 0, nil, e
	}
	if req.WorkerID == nil || req.Available == nil || req.CapacityUnits == nil {
		return 0, nil, errInvalidJSON("workerId, available and capacityUnits are required")
	}
	if *req.CapacityUnits < 0 {
		return 0, nil, E(400, "invalid_capacity", "capacityUnits must be zero or more")
	}
	worker := a.st.Users[*req.WorkerID]
	if worker == nil {
		return 0, nil, errNotFound("worker not found")
	}
	if worker.UserID != c.user.UserID && !c.isSupervisor() {
		return 0, nil, errForbidden("only the worker, a dispatcher or an administrator may change availability")
	}
	active := a.workerActiveAssignmentCount(worker.UserID)
	if *req.Available && *req.CapacityUnits < active {
		return 0, nil, errConflict("capacity_reserved", "capacity cannot be lowered below the worker's active assignments")
	}
	before := map[string]any{"available": worker.Available, "capacityUnits": worker.CapacityUnits}
	worker.Available = *req.Available
	worker.CapacityUnits = *req.CapacityUnits
	c.u.saveUser(worker)
	c.audit("worker.availability_set", "user", worker.UserID, true, map[string]any{"before": before, "after": map[string]any{"available": worker.Available, "capacityUnits": worker.CapacityUnits}})
	c.u.event("worker.updated", "worker", worker.UserID, map[string]any{"workerId": worker.UserID, "available": worker.Available, "capacityUnits": worker.CapacityUnits}, []string{RoleAdministrator, RoleDispatcher}, []string{worker.UserID})
	if !worker.Available {
		a.workerBecameUnavailable(c.u, worker, "worker_unavailable", c)
	}
	a.retryPendingOffers(c.u)
	return 200, map[string]any{"workerId": worker.UserID, "available": worker.Available, "capacityUnits": worker.CapacityUnits}, nil
}

// sessionExpiry helper for tests and cleanup.
func sessionExpired(s *Session, now time.Time) bool { return now.After(s.ExpiresAt) }

