import { useEffect, useState } from "react";
import { DEFAULT_SAMPLE_TYPES, fmtTime, fromLocalInput, idempotencyKey, post, toLocalInput } from "../api";
import { useSession } from "../session";
import { Banner, Details, Field, Form, Freshness, Panel, StatusBadge, Table, Timeline, useAsyncAction } from "../components/ui";
import type { RoleWork, WorkItem } from "../types";

const TYPE_DEFAULTS: Record<string, { containerType: string; min: number; max: number }> = {
  "00000000-0000-4000-8000-000000000a01": { containerType: "standard_tube", min: 15, max: 25 },
  "00000000-0000-4000-8000-000000000a02": { containerType: "indigo_vial", min: 15, max: 25 },
  "00000000-0000-4000-8000-000000000a03": { containerType: "cooled_box", min: 2, max: 8 },
  "00000000-0000-4000-8000-000000000a04": { containerType: "pulse_tube", min: 15, max: 25 },
};

interface RequestDraft {
  latitude: string;
  longitude: string;
  originType: "home" | "clinic" | "node";
  originNodeId: string;
  sampleTypeId: string;
  customTypeId: string;
  requestedAt: string;
  earliestCollectionAt: string;
  latestCollectionAt: string;
  deliveryDeadline: string;
  containerType: string;
  temperatureMinC: string;
  temperatureMaxC: string;
}

function initialDraft(): RequestDraft {
  const now = Date.now();
  const d = TYPE_DEFAULTS[DEFAULT_SAMPLE_TYPES[0].id];
  return {
    latitude: "",
    longitude: "",
    originType: "home",
    originNodeId: "",
    sampleTypeId: DEFAULT_SAMPLE_TYPES[0].id,
    customTypeId: "",
    requestedAt: toLocalInput(new Date(now).toISOString()),
    earliestCollectionAt: toLocalInput(new Date(now + 30 * 60000).toISOString()),
    latestCollectionAt: toLocalInput(new Date(now + 3 * 3600000).toISOString()),
    deliveryDeadline: toLocalInput(new Date(now + 8 * 3600000).toISOString()),
    containerType: d.containerType,
    temperatureMinC: String(d.min),
    temperatureMaxC: String(d.max),
  };
}

export default function RequesterPage() {
  const { boot, eventTick } = useSession();
  const [work, setWork] = useState<RoleWork | null>(null);
  const [draft, setDraft] = useState<RequestDraft>(initialDraft);
  const [serviceability, setServiceability] = useState<any>(null);
  const check = useAsyncAction();
  const create = useAsyncAction();
  const [listError, setListError] = useState<string | null>(null);

  const load = async () => {
    try {
      setWork(await post<RoleWork>("/api/list-role-work", { role: "requester" }));
      setListError(null);
    } catch (e: any) {
      setListError(e.message);
    }
  };
  useEffect(() => {
    void load();
  }, [eventTick]);

  const typeId = draft.sampleTypeId === "custom" ? draft.customTypeId : draft.sampleTypeId;
  const set = (patch: Partial<RequestDraft>) => setDraft((d) => ({ ...d, ...patch }));
  const onType = (id: string) => {
    const defaults = TYPE_DEFAULTS[id];
    set({ sampleTypeId: id, ...(defaults ? { containerType: defaults.containerType, temperatureMinC: String(defaults.min), temperatureMaxC: String(defaults.max) } : {}) });
  };

  const base = () => ({
    origin: { latitude: Number(draft.latitude), longitude: Number(draft.longitude) },
    originType: draft.originType,
    ...(draft.originType === "node" && draft.originNodeId ? { originNodeId: draft.originNodeId } : {}),
    sampleTypeId: typeId,
    requestedAt: fromLocalInput(draft.requestedAt),
    deliveryDeadline: fromLocalInput(draft.deliveryDeadline),
    ...(draft.earliestCollectionAt ? { earliestCollectionAt: fromLocalInput(draft.earliestCollectionAt) } : {}),
    ...(draft.latestCollectionAt ? { latestCollectionAt: fromLocalInput(draft.latestCollectionAt) } : {}),
  });

  const samples: WorkItem[] = [...(work?.pending ?? []), ...(work?.inProgress ?? []), ...(work?.completed ?? [])];
  const active = samples.filter((s) => !["received", "exception", "expired", "cancelled", "unserviceable"].includes(s.status));
  const closed = samples.filter((s) => ["received", "exception", "expired", "cancelled", "unserviceable"].includes(s.status));

  return (
    <div className="page">
      <h1>My requests</h1>
      <div className="two-col">
        <Panel title="New collection request" id="new-request">
          <p className="muted">Run a serviceability check first — it is a dry run and creates nothing. Then create the request.</p>
          {check.feedback}
          {serviceability && (
            <Banner kind={serviceability.serviceable ? "success" : "warning"}>
              <strong>{serviceability.serviceable ? "Serviceable" : "Not serviceable"}</strong> — reason: {serviceability.reason}
              {serviceability.estimatedArrivalAt ? ` · estimated arrival ${fmtTime(serviceability.estimatedArrivalAt)}` : ""} · serviceability version {serviceability.serviceabilityVersion}
            </Banner>
          )}
          {create.feedback}
          <Form
            busy={create.busy}
            submitLabel="Create collection request"
            onSubmit={() =>
              create.run(async () => {
                const r = await post("/api/create-collection-request", {
                  ...base(),
                  containerType: draft.containerType,
                  temperatureMinC: Number(draft.temperatureMinC),
                  temperatureMaxC: Number(draft.temperatureMaxC),
                  idempotencyKey: idempotencyKey(),
                });
                await load();
                setServiceability(null);
                return `Request ${r.requestId.slice(0, 8)}… created; sample ${r.sampleId.slice(0, 8)}… is ${r.serviceability}${r.serviceabilityReason ? ` (${r.serviceabilityReason})` : ""}.`;
              })
            }
          >
            <fieldset>
              <legend>Origin</legend>
              <Field label="Origin type">
                <select value={draft.originType} onChange={(e) => set({ originType: e.target.value as RequestDraft["originType"] })}>
                  <option value="home">Patient's home</option>
                  <option value="clinic">Clinic</option>
                  <option value="node">Network node</option>
                </select>
              </Field>
              {draft.originType === "node" && (
                <Field label="Origin node ID">
                  <input value={draft.originNodeId} onChange={(e) => set({ originNodeId: e.target.value })} />
                </Field>
              )}
              <Field label="Latitude">
                <input type="number" step="any" min={-90} max={90} value={draft.latitude} onChange={(e) => set({ latitude: e.target.value })} required />
              </Field>
              <Field label="Longitude">
                <input type="number" step="any" min={-180} max={180} value={draft.longitude} onChange={(e) => set({ longitude: e.target.value })} required />
              </Field>
            </fieldset>
            <fieldset>
              <legend>Sample</legend>
              <Field label="Sample type">
                <select value={draft.sampleTypeId} onChange={(e) => onType(e.target.value)}>
                  {DEFAULT_SAMPLE_TYPES.map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.name}
                    </option>
                  ))}
                  <option value="custom">Other (enter ID)</option>
                </select>
              </Field>
              {draft.sampleTypeId === "custom" && (
                <Field label="Sample type ID">
                  <input value={draft.customTypeId} onChange={(e) => set({ customTypeId: e.target.value })} required />
                </Field>
              )}
              <Field label="Container type">
                <input value={draft.containerType} onChange={(e) => set({ containerType: e.target.value })} required />
              </Field>
              <Field label="Temperature min (°C)">
                <input type="number" step="0.1" value={draft.temperatureMinC} onChange={(e) => set({ temperatureMinC: e.target.value })} required />
              </Field>
              <Field label="Temperature max (°C)">
                <input type="number" step="0.1" value={draft.temperatureMaxC} onChange={(e) => set({ temperatureMaxC: e.target.value })} required />
              </Field>
            </fieldset>
            <fieldset>
              <legend>Timing</legend>
              <Field label="Requested at">
                <input type="datetime-local" value={draft.requestedAt} onChange={(e) => set({ requestedAt: e.target.value })} required />
              </Field>
              <Field label="Earliest collection">
                <input type="datetime-local" value={draft.earliestCollectionAt} onChange={(e) => set({ earliestCollectionAt: e.target.value })} />
              </Field>
              <Field label="Latest collection">
                <input type="datetime-local" value={draft.latestCollectionAt} onChange={(e) => set({ latestCollectionAt: e.target.value })} />
              </Field>
              <Field label="Delivery deadline" hint="Laboratory receipt must happen before this time.">
                <input type="datetime-local" value={draft.deliveryDeadline} onChange={(e) => set({ deliveryDeadline: e.target.value })} required />
              </Field>
            </fieldset>
            <button
              type="button"
              disabled={check.busy}
              onClick={() =>
                check.run(async () => {
                  setServiceability(await post("/api/check-serviceability", base()));
                })
              }
            >
              Check serviceability (dry run)
            </button>
          </Form>
        </Panel>
        <div>
          <Panel title={`Active samples (${active.length})`} id="active-samples">
            {listError && <Banner kind="error">{listError}</Banner>}
            <SampleTable rows={active} />
          </Panel>
          <Panel title={`Completed samples (${closed.length})`} id="completed-samples">
            <SampleTable rows={closed} />
          </Panel>
        </div>
      </div>
    </div>
  );
}

function SampleTable({ rows }: { rows: WorkItem[] }) {
  return (
    <Table
      caption="Samples"
      rows={rows}
      rowKey={(r) => r.sampleId}
      empty="No samples."
      columns={[
