import { useEffect, useMemo, useState } from "react";
import { fmtTime, get, post, sampleTypeName } from "../api";
import { useSession } from "../session";
import { Banner, errorText, Freshness, Id, KV, Panel, StatusBadge, Table, Timeline } from "../components/ui";
import MapView from "../components/MapView";
import type { OpsLocation } from "../types";

export default function SamplePage({ sampleId }: { sampleId: string }) {
  const { boot, eventTick } = useSession();
  const [state, setState] = useState<any>(null);
  const [lifecycle, setLifecycle] = useState<any>(null);
  const [plan, setPlan] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const s = await get(`/api/read-sample-state/${sampleId}`);
        if (cancelled) return;
        setState(s);
        setError(null);
        const lc = await post("/api/read-sample-lifecycle", { sampleId }).catch(() => null);
        if (!cancelled) setLifecycle(lc);
        const jid = s.activeJourneyId ?? lc?.activeJourneyId;
        if (jid) {
          const p = await post("/api/read-journey-plan", { journeyId: jid }).catch(() => null);
          if (!cancelled) setPlan(p);
        } else setPlan(null);
      } catch (e) {
        if (!cancelled) setError(errorText(e));
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [sampleId, eventTick]);

  const locations: OpsLocation[] = boot?.operations?.locations ?? [];
  const locById = useMemo(() => new Map(locations.map((l) => [l.locationId, l])), [locations]);
  const locName = (id?: string) => (id ? (locById.get(id)?.name ?? `${id.slice(0, 8)}…`) : "—");

  if (error) return <Banner kind="error">{error}</Banner>;
  if (!state) return <p className="muted">Loading sample…</p>;

  const timeline = (lifecycle?.timeline?.length ? lifecycle.timeline : state.timeline) ?? [];
  const stops: any[] = plan?.orderedStops ?? [];
  const legs: any[] = plan?.legs ?? [];
  const completedStops = stops.filter((s) => s.completedAt).length;
  const completedLegs = legs.filter((l) => l.status === "completed").length;
  const isException = state.state.status === "exception" || !!lifecycle?.exception;
  const routeCoords = stops.map((s) => s.coordinate ?? locById.get(s.locationId)?.coordinate).filter(Boolean);
  const location = state.latestLocation ?? lifecycle?.latestLocation;
  const custodian = lifecycle?.currentHolderId;

  return (
    <div className="page">
      <h1>
        Sample <Id value={state.sampleId} /> <StatusBadge status={state.state.status} />
      </h1>
      {isException && (
        <Banner kind="error">
          <strong>Exception flagged.</strong> {lifecycle?.exception?.reason ? `Reason: ${String(lifecycle.exception.reason)}` : "This sample requires attention."}
          {lifecycle?.exception?.code ? ` (${String(lifecycle.exception.code)})` : ""}
        </Banner>
      )}
      {state.state.status === "expired" && <Banner kind="warning">This sample expired: no valid route could meet its delivery deadline.</Banner>}
      <div className="two-col">
        <Panel title="Current state" id="sample-state">
          <KV
            items={[
              ["Status", <StatusBadge status={state.state.status} />],
              ["Serviceability", state.serviceability],
              ["Sample type", sampleTypeName(state.sampleTypeId)],
              ["Handling", `${state.containerType} · ${state.temperatureMinC}–${state.temperatureMaxC} °C`],
