import { useEffect, useMemo, useState } from "react";
import { fmtTime, idempotencyKey, post } from "../api";
import { useSession } from "../session";
import { Banner, Details, errorText, Field, Form, Id, KV, Panel, StatusBadge, Table, useAsyncAction } from "../components/ui";
import MapView from "../components/MapView";
import type { OpsLocation } from "../types";

export default function JourneyPage({ journeyId }: { journeyId: string }) {
  const { boot, eventTick, isSupervisor } = useSession();
  const [plan, setPlan] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [version, setVersion] = useState(0);

  useEffect(() => {
    post("/api/read-journey-plan", { journeyId })
      .then((p) => {
        setPlan(p);
        setError(null);
      })
      .catch((e) => setError(errorText(e)));
  }, [journeyId, eventTick, version]);

  const locations: OpsLocation[] = boot?.operations?.locations ?? [];
  const locById = useMemo(() => new Map(locations.map((l) => [l.locationId, l])), [locations]);
  const locName = (id?: string) => (id ? (locById.get(id)?.name ?? `${id.slice(0, 8)}…`) : "—");

  if (error) return <Banner kind="error">{error}</Banner>;
  if (!plan) return <p className="muted">Loading journey…</p>;

  const stops: any[] = plan.orderedStops ?? [];
  const legs: any[] = plan.legs ?? [];
  const routeCoords = stops.map((s) => s.coordinate ?? locById.get(s.locationId)?.coordinate).filter(Boolean);
  const scoped = plan.scope === "assigned_legs";

  return (
    <div className="page">
      <h1>
        Journey <Id value={plan.journeyId} /> <StatusBadge status={plan.status} />
      </h1>
      {scoped && <Banner kind="info">You are viewing only the legs assigned to you.</Banner>}
      <div className="two-col">
        <Panel title="Plan" id="journey-plan">
          <KV
            items={[
              ["Plan version", plan.planVersion],
              ["Route mode", plan.routeMode],
              ["Status", <StatusBadge status={plan.status} />],
              ["Estimated delivery", fmtTime(plan.estimatedDeliveryAt)],
              ["Samples", (plan.sampleIds ?? []).map((s: string) => (
                <a key={s} href={`#/sample/${s}`} style={{ marginRight: 8 }}>
                  {s.slice(0, 8)}…
                </a>
              ))],
              ...(plan.parentJourneyId ? [["Parent journey", <a href={`#/journey/${plan.parentJourneyId}`}>{plan.parentJourneyId}</a>] as [string, React.ReactNode]] : []),
              ...(plan.totalCostUnits !== undefined ? [["Total cost units", plan.totalCostUnits] as [string, React.ReactNode]] : []),
              ...(plan.capacityUsed !== undefined ? [["Capacity used / available", `${plan.capacityUsed} / ${plan.capacityAvailable}`] as [string, React.ReactNode]] : []),
              ...(plan.valid !== undefined ? [["Plan valid", plan.valid ? "Yes" : "No"] as [string, React.ReactNode]] : []),
              ...(plan.replanStatus ? [["Replan status", plan.replanStatus] as [string, React.ReactNode]] : []),
              ...(plan.replacementJourney ? [["Replacement journey", <a href={`#/journey/${plan.replacementJourney.journeyId}`}>{plan.replacementJourney.journeyId}</a>] as [string, React.ReactNode]] : []),
              ...(plan.splitJourney ? [["Split journey", <a href={`#/journey/${plan.splitJourney.journeyId}`}>{plan.splitJourney.journeyId}</a>] as [string, React.ReactNode]] : []),
            ]}
          />
          {plan.collectionAssignmentIds?.length > 0 && (
            <p>
              Collection assignments: {plan.collectionAssignmentIds.map((id: string) => <Id key={id} value={id} />)}
            </p>
          )}
          {plan.nodeAssignmentIds?.length > 0 && (
            <p>
              Node assignments: {plan.nodeAssignmentIds.map((id: string) => <Id key={id} value={id} />)}
            </p>
          )}
          {plan.laboratoryAssignmentIds?.length > 0 && (
            <p>
              Laboratory assignments: {plan.laboratoryAssignmentIds.map((id: string) => <Id key={id} value={id} />)}
            </p>
          )}
        </Panel>
        <Panel title="Map" id="journey-map">
          <MapView locations={locations} routes={routeCoords.length > 1 ? [{ id: plan.journeyId, coordinates: routeCoords }] : []} height={320} />
        </Panel>
      </div>
      <Panel title="Ordered stops" id="journey-stops">
        <Table
          caption="Stops"
          rows={stops}
          rowKey={(s) => s.stopId}
          columns={[
            { header: "#", cell: (s) => s.sequence },
            { header: "Stop ID", cell: (s) => <Id value={s.stopId} /> },
            { header: "Location", cell: (s) => locName(s.locationId) },
            { header: "Type", cell: (s) => s.stopType },
