      .catch((e) => setError(errorText(e)));
  }, [journeyId, eventTick, version]);

  const locations: OpsLocation[] = boot?.operations?.locations ?? [];
  const locById = useMemo(() => new Map(locations.map((l) => [l.locationId, l])), [locations]);
  const locName = (id?: string) => (id ? (locById.get(id)?.name ?? `${id.slice(0, 8)}…`) : "—");

  if (error) return <Banner kind="error">{error}</Banner>;
  if (!plan) return <p className="muted">Loading journey…</p>;

  const stops: any[] = plan.orderedStops ?? [];
  const legs: any[] = plan.legs ?? [];
  const routeCoords = stops.map((s) => s.coordinate ?? locById.get(s.locationId)?.coordinate).filter(Boolean);
  const scoped = plan.scope === "assigned_legs";

  return (
    <div className="page">
      <h1>
        Journey <Id value={plan.journeyId} /> <StatusBadge status={plan.status} />
      </h1>
      {scoped && <Banner kind="info">You are viewing only the legs assigned to you.</Banner>}
      <div className="two-col">
        <Panel title="Plan" id="journey-plan">
          <KV
            items={[
              ["Plan version", plan.planVersion],
              ["Route mode", plan.routeMode],
              ["Status", <StatusBadge status={plan.status} />],
              ["Estimated delivery", fmtTime(plan.estimatedDeliveryAt)],
              ["Samples", (plan.sampleIds ?? []).map((s: string) => (
                <a key={s} href={`#/sample/${s}`} style={{ marginRight: 8 }}>
                  {s.slice(0, 8)}…
                </a>
              ))],
              ...(plan.parentJourneyId ? [["Parent journey", <a href={`#/journey/${plan.parentJourneyId}`}>{plan.parentJourneyId}</a>] as [string, React.ReactNode]] : []),
              ...(plan.totalCostUnits !== undefined ? [["Total cost units", plan.totalCostUnits] as [string, React.ReactNode]] : []),
              ...(plan.capacityUsed !== undefined ? [["Capacity used / available", `${plan.capacityUsed} / ${plan.capacityAvailable}`] as [string, React.ReactNode]] : []),
              ...(plan.valid !== undefined ? [["Plan valid", plan.valid ? "Yes" : "No"] as [string, React.ReactNode]] : []),
              ...(plan.replanStatus ? [["Replan status", plan.replanStatus] as [string, React.ReactNode]] : []),
              ...(plan.replacementJourney ? [["Replacement journey", <a href={`#/journey/${plan.replacementJourney.journeyId}`}>{plan.replacementJourney.journeyId}</a>] as [string, React.ReactNode]] : []),
              ...(plan.splitJourney ? [["Split journey", <a href={`#/journey/${plan.splitJourney.journeyId}`}>{plan.splitJourney.journeyId}</a>] as [string, React.ReactNode]] : []),
            ]}
          />
          {plan.collectionAssignmentIds?.length > 0 && (
            <p>
              Collection assignments: {plan.collectionAssignmentIds.map((id: string) => <Id key={id} value={id} />)}
            </p>
          )}
          {plan.nodeAssignmentIds?.length > 0 && (
            <p>
              Node assignments: {plan.nodeAssignmentIds.map((id: string) => <Id key={id} value={id} />)}
            </p>
          )}
          {plan.laboratoryAssignmentIds?.length > 0 && (
            <p>
              Laboratory assignments: {plan.laboratoryAssignmentIds.map((id: string) => <Id key={id} value={id} />)}
            </p>
          )}
        </Panel>
        <Panel title="Map" id="journey-map">
          <MapView locations={locations} routes={routeCoords.length > 1 ? [{ id: plan.journeyId, coordinates: routeCoords }] : []} height={320} />
        </Panel>
      </div>
      <Panel title="Ordered stops" id="journey-stops">
        <Table
          caption="Stops"
          rows={stops}
          rowKey={(s) => s.stopId}
          columns={[
            { header: "#", cell: (s) => s.sequence },
            { header: "Stop ID", cell: (s) => <Id value={s.stopId} /> },
            { header: "Location", cell: (s) => locName(s.locationId) },
            { header: "Type", cell: (s) => s.stopType },
            { header: "Estimated", cell: (s) => fmtTime(s.estimatedAt) },
            { header: "Dwell (min)", cell: (s) => s.dwellMinutes ?? 0 },
            { header: "Completed", cell: (s) => (s.completedAt ? fmtTime(s.completedAt) : "—") },
          ]}
        />
      </Panel>
      <Panel title="Transport legs" id="journey-legs">
        <Table
          caption="Legs"
          rows={legs}
          rowKey={(l) => l.assignmentId ?? String(l.sequence)}
          columns={[
            { header: "#", cell: (l) => l.sequence },
            { header: "Assignment", cell: (l) => <Id value={l.assignmentId} /> },
            { header: "From", cell: (l) => locName(l.fromLocationId) },
            { header: "To", cell: (l) => locName(l.toLocationId) },
            { header: "Worker", cell: (l) => (l.workerId ? <Id value={l.workerId} /> : "unassigned") },
            { header: "Status", cell: (l) => <StatusBadge status={l.status} /> },
          ]}
        />
      </Panel>
      {isSupervisor && !scoped && <DispatchControls plan={plan} onDone={() => setVersion((v) => v + 1)} locations={locations} />}
    </div>
  );
}

function DispatchControls({ plan, onDone, locations }: { plan: any; onDone: () => void; locations: OpsLocation[] }) {
  const { busy, run, feedback } = useAsyncAction();
  const [reason, setReason] = useState("");
  const [splitIds, setSplitIds] = useState("");
  const [mergeIds, setMergeIds] = useState("");
  const [changeType, setChangeType] = useState("replace_worker");
  const [changes, setChanges] = useState<Record<string, string>>({});
  const terminal = ["completed", "cancelled", "expired", "exception", "replaced"].includes(plan.status);
  const version = plan.planVersion;
  const ch = (k: string) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setChanges((c) => ({ ...c, [k]: e.target.value }));

  const buildChanges = (): Record<string, unknown> => {
    switch (changeType) {
      case "replace_worker":
      case "reassign_worker":
        return { assignmentId: changes.assignmentId, workerId: changes.workerId };
      case "add_stop":
        return { locationId: changes.locationId, ...(changes.afterStopId ? { afterStopId: changes.afterStopId } : {}), ...(changes.dwellMinutes ? { dwellMinutes: Number(changes.dwellMinutes) } : {}) };
      case "remove_stop":
        return { stopId: changes.stopId };
      case "reorder_stops":
        return { stopIds: (changes.stopIds ?? "").split(/[\s,]+/).filter(Boolean) };
      case "merge_samples":
        return { sourceJourneyIds: (changes.sourceJourneyIds ?? "").split(/[\s,]+/).filter(Boolean) };
      case "split_samples":
      case "split_batch":
        return { sampleIds: (changes.sampleIds ?? "").split(/[\s,]+/).filter(Boolean) };
      default:
        return { reason: changes.reason ?? "" };
    }
  };

  if (terminal) return <Banner kind="info">This journey is {plan.status}; completed work cannot be changed.</Banner>;

  return (
    <Panel title="Dispatcher controls" id="dispatch-controls">
      <p className="muted">All changes are checked against plan version {version}; outdated edits are rejected.</p>
      {feedback}
      <div className="actions">
        <button
          type="button"
          disabled={busy}
          onClick={() =>
            run(async () => {
              const r = await post("/api/reroute-journey", { journeyId: plan.journeyId, expectedPlanVersion: version, reason: reason || "dispatcher reroute", idempotencyKey: idempotencyKey() });
              onDone();
              return `Reroute result: ${r.replanStatus}${r.replacementPlanId ? ` — replacement ${r.replacementPlanId.slice(0, 8)}…` : ""}`;
            })
          }
        >
          Reroute journey
        </button>
        <button
          type="button"
          disabled={busy}
          onClick={() =>
            run(async () => {
              await post("/api/cancel-journey", { journeyId: plan.journeyId, expectedPlanVersion: version, reason: reason || "cancelled by dispatcher", idempotencyKey: idempotencyKey() });
              onDone();
              return "Journey cancelled.";
            })
          }
        >
          Cancel journey
        </button>
        <Field label="Reason">
          <input value={reason} onChange={(e) => setReason(e.target.value)} />
        </Field>
      </div>
      <div className="two-col">
        <Details summary="Split samples into a new journey">
          <Form
            busy={busy}
            submitLabel="Split journey"
            onSubmit={() =>
              run(async () => {
                const r = await post("/api/split-journey", { journeyId: plan.journeyId, expectedPlanVersion: version, sampleIds: splitIds.split(/[\s,]+/).filter(Boolean), idempotencyKey: idempotencyKey() });
                onDone();
                return `Split created journey ${r.splitJourney.journeyId.slice(0, 8)}…`;
              })
            }
          >
            <Field label="Sample IDs to split (comma separated)">
              <input value={splitIds} onChange={(e) => setSplitIds(e.target.value)} required />
            </Field>
          </Form>
        </Details>
        <Details summary="Merge other journeys into this one">
          <Form
            busy={busy}
            submitLabel="Merge journeys"
            onSubmit={() =>
              run(async () => {
                await post("/api/merge-journeys", { targetJourneyId: plan.journeyId, expectedPlanVersion: version, sourceJourneyIds: mergeIds.split(/[\s,]+/).filter(Boolean), idempotencyKey: idempotencyKey() });
                onDone();
                return "Journeys merged.";
              })
            }
          >
            <Field label="Source journey IDs (comma separated)">
              <input value={mergeIds} onChange={(e) => setMergeIds(e.target.value)} required />
            </Field>
          </Form>
        </Details>
      </div>
      <Details summary="Edit active plan">
        <Form
          busy={busy}
          submitLabel="Apply change"
          onSubmit={() =>
            run(async () => {
              await post("/api/edit-active-plan", { journeyId: plan.journeyId, expectedPlanVersion: version, changeType, changes: buildChanges(), idempotencyKey: idempotencyKey() });
              onDone();
              return `Change ${changeType} applied.`;
            })
          }
        >
          <Field label="Change type">
            <select value={changeType} onChange={(e) => setChangeType(e.target.value)}>
              {["replace_worker", "reassign_worker", "add_stop", "remove_stop", "reorder_stops", "merge_samples", "split_samples", "split_batch", "cancel_work", "reroute", "replace_route"].map((t) => (
                <option key={t} value={t}>
                  {t}
                </option>
              ))}
            </select>
          </Field>
          {(changeType === "replace_worker" || changeType === "reassign_worker") && (
            <>
              <Field label="Assignment ID">
                <select value={changes.assignmentId ?? ""} onChange={ch("assignmentId")} required>
                  <option value="">Select leg…</option>
                  {(plan.legs ?? []).map((l: any) => (
                    <option key={l.assignmentId} value={l.assignmentId}>
                      Leg {l.sequence} ({l.status})
                    </option>
                  ))}
                  {(plan.collectionAssignmentIds ?? []).map((id: string) => (
                    <option key={id} value={id}>
                      Collection {id.slice(0, 8)}…
                    </option>
                  ))}
                  {(plan.nodeAssignmentIds ?? []).map((id: string) => (
                    <option key={id} value={id}>
                      Node {id.slice(0, 8)}…
                    </option>
                  ))}
                  {(plan.laboratoryAssignmentIds ?? []).map((id: string) => (
                    <option key={id} value={id}>
                      Laboratory {id.slice(0, 8)}…
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="New worker ID">
                <input value={changes.workerId ?? ""} onChange={ch("workerId")} required />
              </Field>
            </>
          )}
          {changeType === "add_stop" && (
            <>
              <Field label="Location">
                <select value={changes.locationId ?? ""} onChange={ch("locationId")} required>
                  <option value="">Select location…</option>
                  {locations.map((l) => (
                    <option key={l.locationId} value={l.locationId}>
                      {l.name}
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="After stop ID (optional)">
                <input value={changes.afterStopId ?? ""} onChange={ch("afterStopId")} />
              </Field>
              <Field label="Dwell minutes (optional)">
                <input type="number" min={0} value={changes.dwellMinutes ?? ""} onChange={ch("dwellMinutes")} />
              </Field>
            </>
          )}
          {changeType === "remove_stop" && (
            <Field label="Stop ID">
              <input value={changes.stopId ?? ""} onChange={ch("stopId")} required />
            </Field>
          )}
          {changeType === "reorder_stops" && (
            <Field label="Intermediate stop IDs in new order (comma separated)">
              <input value={changes.stopIds ?? ""} onChange={ch("stopIds")} required />
            </Field>
          )}
          {changeType === "merge_samples" && (
            <Field label="Source journey IDs">
              <input value={changes.sourceJourneyIds ?? ""} onChange={ch("sourceJourneyIds")} required />
            </Field>
          )}
          {(changeType === "split_samples" || changeType === "split_batch") && (
            <Field label="Sample IDs">
              <input value={changes.sampleIds ?? ""} onChange={ch("sampleIds")} required />
            </Field>
          )}
          {(changeType === "cancel_work" || changeType === "reroute" || changeType === "replace_route") && (
            <Field label="Reason">
              <input value={changes.reason ?? ""} onChange={ch("reason")} />
            </Field>
          )}
        </Form>
      </Details>
    </Panel>
  );
}

