  const locById = useMemo(() => new Map(locations.map((l) => [l.locationId, l])), [locations]);
  const locName = (id?: string) => (id ? (locById.get(id)?.name ?? `${id.slice(0, 8)}…`) : "—");

  if (error) return <Banner kind="error">{error}</Banner>;
  if (!plan) return <p className="muted">Loading journey…</p>;

  const stops: any[] = plan.orderedStops ?? [];
  const legs: any[] = plan.legs ?? [];
  const routeCoords = stops.map((s) => s.coordinate ?? locById.get(s.locationId)?.coordinate).filter(Boolean);
  const scoped = plan.scope === "assigned_legs";

  return (
    <div className="page">
      <h1>
        Journey <Id value={plan.journeyId} /> <StatusBadge status={plan.status} />
