      <div className="two-col">
        <Panel title="Plan" id="journey-plan">
          <KV
            items={[
              ["Plan version", plan.planVersion],
              ["Route mode", plan.routeMode],
              ["Status", <StatusBadge status={plan.status} />],
              ["Estimated delivery", fmtTime(plan.estimatedDeliveryAt)],
              ["Samples", (plan.sampleIds ?? []).map((s: string) => (
                <a key={s} href={`#/sample/${s}`} style={{ marginRight: 8 }}>
                  {s.slice(0, 8)}…
                </a>
              ))],
              ...(plan.parentJourneyId ? [["Parent journey", <a href={`#/journey/${plan.parentJourneyId}`}>{plan.parentJourneyId}</a>] as [string, React.ReactNode]] : []),
              ...(plan.totalCostUnits !== undefined ? [["Total cost units", plan.totalCostUnits] as [string, React.ReactNode]] : []),
              ...(plan.capacityUsed !== undefined ? [["Capacity used / available", `${plan.capacityUsed} / ${plan.capacityAvailable}`] as [string, React.ReactNode]] : []),
