              ...(plan.replanStatus ? [["Replan status", plan.replanStatus] as [string, React.ReactNode]] : []),
              ...(plan.replacementJourney ? [["Replacement journey", <a href={`#/journey/${plan.replacementJourney.journeyId}`}>{plan.replacementJourney.journeyId}</a>] as [string, React.ReactNode]] : []),
              ...(plan.splitJourney ? [["Split journey", <a href={`#/journey/${plan.splitJourney.journeyId}`}>{plan.splitJourney.journeyId}</a>] as [string, React.ReactNode]] : []),
            ]}
          />
          {plan.collectionAssignmentIds?.length > 0 && (
