  const [changes, setChanges] = useState<Record<string, string>>({});
  const terminal = ["completed", "cancelled", "expired", "exception", "replaced"].includes(plan.status);
  const version = plan.planVersion;
  const ch = (k: string) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => setChanges((c) => ({ ...c, [k]: e.target.value }));

