    switch (changeType) {
      case "replace_worker":
      case "reassign_worker":
        return { assignmentId: changes.assignmentId, workerId: changes.workerId };
      case "add_stop":
        return { locationId: changes.locationId, ...(changes.afterStopId ? { afterStopId: changes.afterStopId } : {}), ...(changes.dwellMinutes ? { dwellMinutes: Number(changes.dwellMinutes) } : {}) };
      case "remove_stop":
        return { stopId: changes.stopId };
      case "reorder_stops":
        return { stopIds: (changes.stopIds ?? "").split(/[\s,]+/).filter(Boolean) };
      case "merge_samples":
        return { sourceJourneyIds: (changes.sourceJourneyIds ?? "").split(/[\s,]+/).filter(Boolean) };
      case "split_samples":
      case "split_batch":
        return { sampleIds: (changes.sampleIds ?? "").split(/[\s,]+/).filter(Boolean) };
      default:
        return { reason: changes.reason ?? "" };
    }
  };

  if (terminal) return <Banner kind="info">This journey is {plan.status}; completed work cannot be changed.</Banner>;

  return (
    <Panel title="Dispatcher controls" id="dispatch-controls">
      <p className="muted">All changes are checked against plan version {version}; outdated edits are rejected.</p>
      {feedback}
      <div className="actions">
        <button
          type="button"
          disabled={busy}
          onClick={() =>
            run(async () => {
              const r = await post("/api/reroute-journey", { journeyId: plan.journeyId, expectedPlanVersion: version, reason: reason || "dispatcher reroute", idempotencyKey: idempotencyKey() });
              onDone();
              return `Reroute result: ${r.replanStatus}${r.replacementPlanId ? ` — replacement ${r.replacementPlanId.slice(0, 8)}…` : ""}`;
            })
          }
        >
          Reroute journey
        </button>
        <button
          type="button"
          disabled={busy}
          onClick={() =>
            run(async () => {
              await post("/api/cancel-journey", { journeyId: plan.journeyId, expectedPlanVersion: version, reason: reason || "cancelled by dispatcher", idempotencyKey: idempotencyKey() });
              onDone();
              return "Journey cancelled.";
