        <Details summary="Merge other journeys into this one">
          <Form
            busy={busy}
            submitLabel="Merge journeys"
            onSubmit={() =>
              run(async () => {
                await post("/api/merge-journeys", { targetJourneyId: plan.journeyId, expectedPlanVersion: version, sourceJourneyIds: mergeIds.split(/[\s,]+/).filter(Boolean), idempotencyKey: idempotencyKey() });
                onDone();
                return "Journeys merged.";
              })
            }
          >
            <Field label="Source journey IDs (comma separated)">
              <input value={mergeIds} onChange={(e) => setMergeIds(e.target.value)} required />
            </Field>
          </Form>
        </Details>
      </div>
      <Details summary="Edit active plan">
        <Form
          busy={busy}
          submitLabel="Apply change"
          onSubmit={() =>
            run(async () => {
              await post("/api/edit-active-plan", { journeyId: plan.journeyId, expectedPlanVersion: version, changeType, changes: buildChanges(), idempotencyKey: idempotencyKey() });
              onDone();
              return `Change ${changeType} applied.`;
            })
          }
        >
          <Field label="Change type">
            <select value={changeType} onChange={(e) => setChangeType(e.target.value)}>
              {["replace_worker", "reassign_worker", "add_stop", "remove_stop", "reorder_stops", "merge_samples", "split_samples", "split_batch", "cancel_work", "reroute", "replace_route"].map((t) => (
                <option key={t} value={t}>
                  {t}
                </option>
              ))}
            </select>
          </Field>
          {(changeType === "replace_worker" || changeType === "reassign_worker") && (
            <>
              <Field label="Assignment ID">
                <select value={changes.assignmentId ?? ""} onChange={ch("assignmentId")} required>
                  <option value="">Select leg…</option>
                  {(plan.legs ?? []).map((l: any) => (
                    <option key={l.assignmentId} value={l.assignmentId}>
                      Leg {l.sequence} ({l.status})
                    </option>
                  ))}
                  {(plan.collectionAssignmentIds ?? []).map((id: string) => (
                    <option key={id} value={id}>
                      Collection {id.slice(0, 8)}…
                    </option>
                  ))}
                  {(plan.nodeAssignmentIds ?? []).map((id: string) => (
                    <option key={id} value={id}>
                      Node {id.slice(0, 8)}…
                    </option>
                  ))}
                  {(plan.laboratoryAssignmentIds ?? []).map((id: string) => (
                    <option key={id} value={id}>
                      Laboratory {id.slice(0, 8)}…
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="New worker ID">
                <input value={changes.workerId ?? ""} onChange={ch("workerId")} required />
              </Field>
            </>
          )}
          {changeType === "add_stop" && (
            <>
              <Field label="Location">
                <select value={changes.locationId ?? ""} onChange={ch("locationId")} required>
                  <option value="">Select location…</option>
                  {locations.map((l) => (
                    <option key={l.locationId} value={l.locationId}>
                      {l.name}
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="After stop ID (optional)">
                <input value={changes.afterStopId ?? ""} onChange={ch("afterStopId")} />
              </Field>
              <Field label="Dwell minutes (optional)">
                <input type="number" min={0} value={changes.dwellMinutes ?? ""} onChange={ch("dwellMinutes")} />
              </Field>
            </>
          )}
          {changeType === "remove_stop" && (
            <Field label="Stop ID">
              <input value={changes.stopId ?? ""} onChange={ch("stopId")} required />
            </Field>
          )}
          {changeType === "reorder_stops" && (
            <Field label="Intermediate stop IDs in new order (comma separated)">
              <input value={changes.stopIds ?? ""} onChange={ch("stopIds")} required />
            </Field>
          )}
          {changeType === "merge_samples" && (
            <Field label="Source journey IDs">
              <input value={changes.sourceJourneyIds ?? ""} onChange={ch("sourceJourneyIds")} required />
            </Field>
          )}
          {(changeType === "split_samples" || changeType === "split_batch") && (
            <Field label="Sample IDs">
              <input value={changes.sampleIds ?? ""} onChange={ch("sampleIds")} required />
            </Field>
          )}
          {(changeType === "cancel_work" || changeType === "reroute" || changeType === "replace_route") && (
            <Field label="Reason">
              <input value={changes.reason ?? ""} onChange={ch("reason")} />
            </Field>
          )}
        </Form>
      </Details>
    </Panel>
  );
}

