import { useEffect, useMemo, useState } from "react";
import { fmtTime, idempotencyKey, nowIso, post, sampleTypeName, DEFAULT_SAMPLE_TYPES } from "../api";
import { useSession } from "../session";
import { Banner, Details, errorText, Field, Form, Freshness, Id, Panel, StatusBadge, Table, useAsyncAction } from "../components/ui";
import MapView from "../components/MapView";
import type { OperationsState } from "../types";

export default function MonitorPage() {
  const { eventTick } = useSession();
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [typeFilter, setTypeFilter] = useState("");
  const [version, setVersion] = useState(0);

  useEffect(() => {
    post<OperationsState>("/api/read-operations-state", typeFilter ? { filters: { sampleTypeId: typeFilter } } : {})
      .then((o) => {
        setOps(o);
        setError(null);
      })
      .catch((e) => setError(errorText(e)));
  }, [eventTick, typeFilter, version]);

  const locById = useMemo(() => new Map((ops?.locations ?? []).map((l) => [l.locationId, l])), [ops]);
  const locName = (id?: string) => (id ? (locById.get(id)?.name ?? `${id.slice(0, 8)}…`) : "—");
  const workerById = useMemo(() => new Map((ops?.workers ?? []).map((w) => [w.workerId, w])), [ops]);
  const workerName = (id?: string) => (id ? (workerById.get(id)?.fullName ?? `${id.slice(0, 8)}…`) : "—");
  const bump = () => setVersion((v) => v + 1);

  if (error) return <Banner kind="error">{error}</Banner>;
  if (!ops) return <p className="muted">Loading operations…</p>;

  const activeRoutes = ops.routes.filter((r) => r.active !== false);
  const routeLines = activeRoutes
    .map((r) => ({ id: r.journeyId as string, coordinates: (r.orderedStops ?? []).map((s: any) => s.coordinate ?? locById.get(s.locationId)?.coordinate).filter(Boolean) }))
    .filter((r) => r.coordinates.length > 1);

  return (
    <div className="page">
      <h1>Operations monitor</h1>
      <div className="stat-row" aria-label="Summary">
        <Stat label="Samples" value={ops.samples.length} />
        <Stat label="Workers" value={ops.workers.length} />
        <Stat label="Locations" value={ops.locations.length} />
        <Stat label="Laboratories" value={ops.locations.filter((l) => l.functions.laboratory).length} />
        <Stat label="Active routes" value={activeRoutes.length} />
        <Stat label="Exceptions" value={ops.exceptions.length} />
        <Stat label="Delays" value={ops.delays.length} />
        <Stat label="Assignment spread" value={ops.assignmentCountSpread} />
        <Stat label="Ineligible assignments" value={ops.ineligibleAssignmentCount} />
      </div>
      <Panel title="Live map" id="monitor-map">
        <MapView locations={ops.locations} connections={ops.connections} workers={ops.workers} samples={ops.samples} routes={routeLines} height={440} onSelectSample={(id) => (location.hash = `#/sample/${id}`)} />
      </Panel>
      <div className="two-col">
        <Panel
          title={`Samples (${ops.samples.length})`}
          id="monitor-samples"
          actions={
            <label>
              Sample type{" "}
              <select value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)}>
                <option value="">All</option>
                {DEFAULT_SAMPLE_TYPES.map((t) => (
                  <option key={t.id} value={t.id}>
                    {t.name}
                  </option>
                ))}
              </select>
            </label>
          }
        >
          <Table
            caption="Samples"
            rows={ops.samples}
            rowKey={(s) => s.sampleId}
            columns={[
              { header: "Sample", cell: (s) => <a href={`#/sample/${s.sampleId}`}>{s.sampleId.slice(0, 8)}…</a> },
              { header: "Status", cell: (s) => <StatusBadge status={s.status} /> },
              { header: "Holder", cell: (s) => (s.currentHolderId ? workerName(s.currentHolderId) : "—") },
              { header: "Deadline", cell: (s) => fmtTime(s.deliveryDeadline) },
              { header: "Journey", cell: (s) => (s.activeJourneyId ? <a href={`#/journey/${s.activeJourneyId}`}>{s.activeJourneyId.slice(0, 8)}…</a> : "—") },
              { header: "Location", cell: (s) => <Freshness stale={s.locationStale} recordedAt={s.locationRecordedAt} /> },
            ]}
          />
        </Panel>
        <Panel title={`Workers (${ops.workers.length})`} id="monitor-workers">
          <Table
            caption="Workers"
            rows={ops.workers}
            rowKey={(w) => w.workerId}
            columns={[
              { header: "Worker", cell: (w) => w.fullName ?? <Id value={w.workerId} /> },
              { header: "Roles", cell: (w) => (w.roles ?? []).join(", ") },
              { header: "Status", cell: (w) => <StatusBadge status={w.status} /> },
              { header: "Assignments", cell: (w) => w.assignmentCount },
              { header: "Capacity", cell: (w) => w.capacityUnits },
              { header: "Location", cell: (w) => <Freshness stale={w.locationStale} recordedAt={w.locationRecordedAt} /> },
              { header: "", cell: (w) => <AvailabilityToggle worker={w} onDone={bump} /> },
            ]}
          />
        </Panel>
      </div>
      <div className="two-col">
        <Panel title={`Collection nodes & laboratories (${ops.locations.length})`} id="monitor-locations">
          <Table
            caption="Locations"
            rows={ops.locations}
            rowKey={(l) => l.locationId}
            columns={[
              { header: "Name", cell: (l) => l.name },
              { header: "Functions", cell: (l) => Object.entries(l.functions).filter(([, v]) => v).map(([k]) => k.replace("_", " ")).join(", ") || "none" },
              { header: "Active", cell: (l) => (l.active ? "yes" : "no") },
              { header: "Capacity (regular / cooled avail.)", cell: (l) => (l.capacity ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits} · ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}` : "—") },
              { header: "Accepts", cell: (l) => (l.acceptedSampleTypeIds ?? []).map(sampleTypeName).join(", ") || "—" },
            ]}
          />
        </Panel>
        <Panel title={`Connections (${ops.connections.length})`} id="monitor-connections">
          <Table
            caption="Connections"
            rows={ops.connections}
            rowKey={(c) => c.connectionId}
            columns={[
              { header: "From", cell: (c) => locName(c.fromLocationId) },
              { header: "To", cell: (c) => locName(c.toLocationId) },
              { header: "Travel (min)", cell: (c) => c.travelMinutes },
              { header: "Cooled", cell: (c) => (c.cooled ? "yes" : "no") },
              { header: "Active", cell: (c) => (c.active ? "yes" : "no") },
              { header: "Capacity", cell: (c) => (c.capacity ? `${c.capacity.availableUnits}/${c.capacity.capacityUnits} · ${c.capacity.cooledAvailableUnits}/${c.capacity.cooledCapacityUnits}` : "—") },
            ]}
          />
        </Panel>
      </div>
      <Panel title={`Routes (${ops.routes.length})`} id="monitor-routes">
        <Table
          caption="Routes"
          rows={ops.routes}
          rowKey={(r) => r.journeyId}
          columns={[
            { header: "Journey", cell: (r) => <a href={`#/journey/${r.journeyId}`}>{String(r.journeyId).slice(0, 8)}…</a> },
            { header: "Status", cell: (r) => <StatusBadge status={r.status} /> },
            { header: "Mode", cell: (r) => r.routeMode },
            { header: "v", cell: (r) => r.planVersion },
            { header: "Samples", cell: (r) => (r.sampleIds ?? []).length },
            { header: "Stops", cell: (r) => (r.stopLocationIds ?? []).map(locName).join(" → ") },
            { header: "Legs", cell: (r) => (r.legs ?? []).map((l: any) => l.status).join(", ") },
            { header: "ETA", cell: (r) => fmtTime(r.estimatedDeliveryAt) },
          ]}
        />
      </Panel>
      <div className="two-col">
        <Panel title={`Exceptions (${ops.exceptions.length})`} id="monitor-exceptions">
          <Table
            caption="Exceptions"
            rows={ops.exceptions}
            rowKey={(e) => e.sampleId}
            empty="No exceptions."
            columns={[
              { header: "Sample", cell: (e) => <a href={`#/sample/${e.sampleId}`}>{String(e.sampleId).slice(0, 8)}…</a> },
              { header: "Status", cell: (e) => <StatusBadge status={e.status} /> },
              { header: "Code", cell: (e) => e.exception?.code ?? "—" },
              { header: "Reason", cell: (e) => e.exception?.reason ?? "—" },
            ]}
          />
        </Panel>
        <Panel title={`Delays (${ops.delays.length})`} id="monitor-delays">
          <Table
            caption="Delays"
            rows={ops.delays}
            rowKey={(d) => `${d.sampleId}-${d.reason}`}
            empty="No delays."
            columns={[
              { header: "Sample", cell: (d) => <a href={`#/sample/${d.sampleId}`}>{String(d.sampleId).slice(0, 8)}…</a> },
              { header: "Reason", cell: (d) => d.reason },
              { header: "Deadline", cell: (d) => fmtTime(d.deliveryDeadline) },
              { header: "ETA", cell: (d) => fmtTime(d.estimatedDeliveryAt) },
            ]}
          />
        </Panel>
      </div>
      <Panel title={`Handoffs (${ops.handoffs.length})`} id="monitor-handoffs">
        <Table
          caption="Handoffs"
          rows={ops.handoffs}
          rowKey={(h) => h.handoffId}
          empty="No handoffs."
          columns={[
            { header: "Sample", cell: (h) => <a href={`#/sample/${h.sampleId}`}>{String(h.sampleId).slice(0, 8)}…</a> },
            { header: "Sender", cell: (h) => workerName(h.senderId) },
            { header: "Receiver", cell: (h) => workerName(h.receiverId) },
            { header: "Status", cell: (h) => <StatusBadge status={h.status} /> },
            { header: "Sender ✓", cell: (h) => (h.senderConfirmed ? "yes" : "no") },
            { header: "Receiver ✓", cell: (h) => (h.receiverConfirmed ? "yes" : "no") },
            { header: "Initiated", cell: (h) => fmtTime(h.initiatedAt) },
          ]}
        />
      </Panel>
      <DisruptionForm ops={ops} onDone={bump} />
    </div>
  );
}

function Stat({ label, value }: { label: string; value: number }) {
  return (
    <div className="stat">
      <span className="stat-value">{value}</span>
      <span className="stat-label">{label}</span>
    </div>
  );
}

function AvailabilityToggle({ worker, onDone }: { worker: { workerId: string; available: boolean; capacityUnits: number }; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  return (
    <>
      <button
        type="button"
        disabled={busy}
        onClick={() =>
          run(async () => {
            await post("/api/set-worker-availability", { workerId: worker.workerId, available: !worker.available, capacityUnits: worker.capacityUnits });
            onDone();
          })
        }
      >
        {worker.available ? "Set unavailable" : "Set available"}
      </button>
      {feedback}
    </>
  );
}

function DisruptionForm({ ops, onDone }: { ops: OperationsState; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [resourceType, setResourceType] = useState("location");
  const [resourceId, setResourceId] = useState("");
  const [reason, setReason] = useState("");
  const options =
    resourceType === "connection"
      ? ops.connections.map((c) => ({ id: c.connectionId, label: `${c.fromLocationId.slice(0, 8)} → ${c.toLocationId.slice(0, 8)}` }))
      : resourceType === "worker"
        ? ops.workers.map((w) => ({ id: w.workerId, label: w.fullName ?? w.workerId }))
        : resourceType === "route"
          ? ops.routes.map((r) => ({ id: r.journeyId as string, label: `Journey ${String(r.journeyId).slice(0, 8)}…` }))
          : ops.locations.map((l) => ({ id: l.locationId, label: l.name }));
  return (
    <Panel title="Report disruption & replan" id="report-disruption">
      <p className="muted">Replans only unfinished work; completed assignments, stops and confirmed custody are preserved.</p>
      {feedback}
      <Form
        busy={busy}
        submitLabel="Report disruption"
        onSubmit={() =>
          run(async () => {
            const r = await post("/api/report-disruption", { resourceType, resourceId, reason, occurredAt: nowIso(), idempotencyKey: idempotencyKey() });
            onDone();
            return `Disruption recorded: ${r.affectedSampleIds.length} sample(s) affected, replan status ${r.replanStatus}, ${r.replacementPlanIds.length} replacement plan(s).`;
          })
        }
      >
        <Field label="Resource type">
          <select value={resourceType} onChange={(e) => { setResourceType(e.target.value); setResourceId(""); }}>
            {["location", "node", "laboratory", "connection", "route", "worker", "capacity"].map((t) => (
              <option key={t} value={t}>
                {t}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Resource">
          <select value={resourceId} onChange={(e) => setResourceId(e.target.value)} required>
            <option value="">Select…</option>
            {options.map((o) => (
              <option key={o.id} value={o.id}>
                {o.label}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Reason">
          <input value={reason} onChange={(e) => setReason(e.target.value)} />
        </Field>
      </Form>
      <Details summary="How replanning works">
        <ul>
          <li>The current sample holder is never changed by a replan.</li>
          <li>Only one replacement plan may be active for a journey at a time.</li>
          <li>Worker eligibility, compatibility, capacity and deadlines are rechecked.</li>
          <li>If no valid route can meet the deadline, the sample is marked expired.</li>
        </ul>
      </Details>
    </Panel>
  );
}

