import { useEffect, useState } from "react";
import { fmtTime, post } from "../api";
import { Banner, errorText, Field, Form, Id, Panel, Table } from "../components/ui";

interface AuditEntry {
  auditId: string;
  actorId: string;
  role: string;
  action: string;
  entityType: string;
  entityId: string;
  success: boolean;
  occurredAt: string;
  details: Record<string, any>;
}

interface AuditResult {
  entries: AuditEntry[];
  total: number;
  returned: number;
  offset: number;
  limit: number;
  order: string;
  hasMore: boolean;
  nextOffset?: number;
}

export default function AuditPage() {
  const [query, setQuery] = useState("");
  const [entityType, setEntityType] = useState("");
  const [entityId, setEntityId] = useState("");
  const [action, setAction] = useState("");
  const [actorId, setActorId] = useState("");
  const [success, setSuccess] = useState("");
  const [order, setOrder] = useState<"newest_first" | "oldest_first">("newest_first");
  const [offset, setOffset] = useState(0);
  const [result, setResult] = useState<AuditResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const limit = 100;

  const search = async (off = offset) => {
    setBusy(true);
    try {
      const body: Record<string, unknown> = { limit, offset: off, order };
      if (query) body.query = query;
      if (entityType) body.entityType = entityType;
      if (entityId) body.entityId = entityId;
      if (action) body.action = action;
      if (actorId) body.actorId = actorId;
