import { useEffect, useState } from "react";
import { post, sampleTypeName, fmtTime } from "../api";
import { useSession } from "../session";
import { Banner, Field, Form, KV, Panel, StatusBadge, Table, useAsyncAction } from "../components/ui";
import MapView from "../components/MapView";
import type { RoleWork, WorkItem } from "../types";

export default function FacilityPage() {
  const { boot, eventTick, refresh } = useSession();
  const role = boot!.user.activeRole;
  const facility = (boot!.operations?.locations ?? []).find((l) => l.capacity);
  const { busy, run, feedback } = useAsyncAction();
  const [regular, setRegular] = useState("");
  const [cooled, setCooled] = useState("");
  const [work, setWork] = useState<RoleWork | null>(null);

  useEffect(() => {
    if (facility) {
      setRegular(String(facility.capacity!.capacityUnits));
      setCooled(String(facility.capacity!.cooledCapacityUnits));
    }
  }, [facility?.locationId, facility?.capacity?.capacityUnits, facility?.capacity?.cooledCapacityUnits]);

  useEffect(() => {
    post<RoleWork>("/api/list-role-work", { role }).then(setWork).catch(() => setWork(null));
  }, [role, eventTick]);

  if (!facility) {
    return (
      <div className="page">
        <h1>My facility</h1>
        <Banner kind="warning">You are not assigned to a node or laboratory. Ask an administrator to assign you.</Banner>
      </div>
    );
  }
  const cap = facility.capacity!;
  const expected: WorkItem[] = [...(work?.pending ?? []), ...(work?.inProgress ?? [])];
  const isLab = role === "laboratory_team";

  return (
    <div className="page">
      <h1>
        {isLab ? "Laboratory" : "Node"}: {facility.name}
      </h1>
      <div className="two-col">
        <Panel title="Capacity" id="facility-capacity">
          <KV
            items={[
              ["Regular capacity", `${cap.capacityUnits} configured · ${cap.reservedUnits} reserved · ${cap.availableUnits} available`],
              ["Cooled capacity", `${cap.cooledCapacityUnits} configured · ${cap.cooledReservedUnits} reserved · ${cap.cooledAvailableUnits} available`],
              ["Functions", Object.entries(facility.functions).filter(([, v]) => v).map(([k]) => k.replace("_", " ")).join(", ")],
              ["Active", facility.active ? "yes" : "no"],
              ["Handling minutes", facility.handlingMinutes],
              ...(isLab ? ([["Accepted sample types", (facility.acceptedSampleTypeIds ?? []).map(sampleTypeName).join(", ") || "none"]] as [string, React.ReactNode][]) : []),
            ]}
          />
          {feedback}
          <Form
            busy={busy}
            submitLabel="Save capacity"
            onSubmit={() =>
              run(async () => {
                await post("/api/configure-capacity", { resourceId: facility.locationId, capacityUnits: Number(regular), cooledCapacityUnits: Number(cooled) });
                await refresh();
                return "Capacity updated.";
              })
            }
          >
            <Field label="Regular capacity units">
              <input type="number" min={0} value={regular} onChange={(e) => setRegular(e.target.value)} required />
            </Field>
            <Field label="Cooled capacity units">
              <input type="number" min={0} value={cooled} onChange={(e) => setCooled(e.target.value)} required />
            </Field>
          </Form>
        </Panel>
        <Panel title="Location" id="facility-map">
          <MapView locations={[facility]} height={300} />
        </Panel>
      </div>
      <Panel title={isLab ? `Expected samples (${expected.length})` : `Samples arriving / leaving (${expected.length})`} id="facility-expected">
        <Table
          caption="Expected samples"
          rows={expected}
          rowKey={(r) => r.assignmentId}
          empty="No samples expected."
          columns={[
            { header: "Sample", cell: (r) => <a href={`#/sample/${r.sampleId}`}>{String(r.sampleId).slice(0, 8)}…</a> },
            { header: "Assignment status", cell: (r) => <StatusBadge status={r.status} /> },
            { header: "Sample type", cell: (r) => sampleTypeName(r.expectedSampleTypeId) },
            { header: "Incoming from", cell: (r) => (r.incomingFromLocationId ? String(r.incomingFromLocationId).slice(0, 8) + "…" : "collection") },
            { header: "Outgoing to", cell: (r) => (r.outgoingToLocationId ? String(r.outgoingToLocationId).slice(0, 8) + "…" : "—") },
            { header: "Offer expires", cell: (r) => fmtTime(r.offerExpiresAt) },
          ]}
        />
        <p>
          <a href="#/work">Go to my work to accept assignments and confirm handoffs →</a>
        </p>
      </Panel>
    </div>
  );
}

