import { useState } from "react";
import { ALL_ROLES, DEFAULT_SAMPLE_TYPES, get, post, ROLE_LABELS, sampleTypeName } from "../api";
import { useSession } from "../session";
import { Details, Field, Form, Id, KV, Panel, Table, useAsyncAction } from "../components/ui";
import type { OpsConnection, OpsLocation } from "../types";

const FUNCTIONS = ["collection_point", "transfer_point", "hub", "laboratory"] as const;

export default function AdminPage() {
  const { boot, refresh } = useSession();
  const ops = boot!.operations!;
  const [tab, setTab] = useState<"users" | "network" | "types">("users");
  const done = () => void refresh();

  return (
    <div className="page">
      <h1>Administration</h1>
      <nav className="tabs" aria-label="Administration sections">
        {(["users", "network", "types"] as const).map((t) => (
          <button key={t} type="button" className={tab === t ? "active" : ""} aria-pressed={tab === t} onClick={() => setTab(t)}>
            {t === "users" ? "Users & roles" : t === "network" ? "Network" : "Sample types"}
          </button>
        ))}
      </nav>
      {tab === "users" && <UsersTab locations={ops.locations} />}
      {tab === "network" && <NetworkTab locations={ops.locations} connections={ops.connections} onDone={done} />}
      {tab === "types" && <TypesTab />}
    </div>
  );
}

function parseList(s: string) {
  return s.split(/[\s,]+/).filter(Boolean);
}

function UsersTab({ locations }: { locations: OpsLocation[] }) {
  const create = useAsyncAction();
  const update = useAsyncAction();
  const lookup = useAsyncAction();
  const [created, setCreated] = useState<any[]>([]);
  const [form, setForm] = useState({ username: "", initialPassword: "", fullName: "", email: "", phone: "", roles: [] as string[], qualifications: "", certifications: "", active: true, assignedLocationId: "" });
  const [upd, setUpd] = useState({ userId: "", roles: [] as string[], qualifications: "", certifications: "", active: true, assignedLocationId: "" });
  const [lookupId, setLookupId] = useState("");
  const [found, setFound] = useState<any>(null);
  const toggle = (list: string[], r: string) => (list.includes(r) ? list.filter((x) => x !== r) : [...list, r]);
  const certs = (s: string) => parseList(s).map((code) => ({ code, active: true }));

  return (
    <div className="two-col">
      <Panel title="Create user" id="admin-create-user">
        {create.feedback}
        <Form
          busy={create.busy}
          submitLabel="Create user"
          onSubmit={() =>
            create.run(async () => {
              const r = await post("/api/create-user", {
                username: form.username,
                initialPassword: form.initialPassword,
                ...(form.fullName ? { fullName: form.fullName } : {}),
                ...(form.email ? { email: form.email } : {}),
                ...(form.phone ? { phone: form.phone } : {}),
                roles: form.roles,
                qualifications: parseList(form.qualifications),
                certifications: certs(form.certifications),
                active: form.active,
                ...(form.assignedLocationId ? { assignedLocationId: form.assignedLocationId } : {}),
              });
              setCreated((c) => [r, ...c]);
              return `User ${r.username} created with ID ${r.userId}.`;
            })
          }
        >
          <Field label="Username">
            <input value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} required />
          </Field>
          <Field label="Initial password">
            <input type="password" value={form.initialPassword} onChange={(e) => setForm({ ...form, initialPassword: e.target.value })} required />
          </Field>
          <Field label="Full name">
            <input value={form.fullName} onChange={(e) => setForm({ ...form, fullName: e.target.value })} />
          </Field>
          <Field label="Email">
            <input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
          </Field>
          <Field label="Phone">
            <input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} />
          </Field>
          <RoleChecks label="Roles" value={form.roles} onChange={(r) => setForm({ ...form, roles: toggle(form.roles, r) })} />
          <Field label="Qualifications (comma separated, e.g. amber, frost)">
            <input value={form.qualifications} onChange={(e) => setForm({ ...form, qualifications: e.target.value })} />
          </Field>
          <Field label="Certifications (codes, comma separated)">
            <input value={form.certifications} onChange={(e) => setForm({ ...form, certifications: e.target.value })} />
          </Field>
          <Field label="Assigned node / laboratory">
            <LocationSelect locations={locations} value={form.assignedLocationId} onChange={(v) => setForm({ ...form, assignedLocationId: v })} allowEmpty />
          </Field>
          <label className="check">
            <input type="checkbox" checked={form.active} onChange={(e) => setForm({ ...form, active: e.target.checked })} /> Active
          </label>
        </Form>
        {created.length > 0 && (
          <Table
            caption="Recently created users"
            rows={created}
            rowKey={(u) => u.userId}
            columns={[
              { header: "Username", cell: (u) => u.username },
              { header: "User ID", cell: (u) => <Id value={u.userId} /> },
              { header: "Roles", cell: (u) => u.roles.join(", ") },
            ]}
          />
        )}
      </Panel>
      <div>
        <Panel title="Update user access" id="admin-update-user">
          {update.feedback}
          <Form
            busy={update.busy}
            submitLabel="Update access"
            onSubmit={() =>
              update.run(async () => {
                await post("/api/update-user-access", {
                  userId: upd.userId,
                  roles: upd.roles,
                  qualifications: parseList(upd.qualifications),
                  certifications: certs(upd.certifications),
                  active: upd.active,
                  ...(upd.assignedLocationId ? { assignedLocationId: upd.assignedLocationId } : {}),
                });
                return "User access updated.";
              })
            }
          >
            <Field label="User ID">
              <input value={upd.userId} onChange={(e) => setUpd({ ...upd, userId: e.target.value })} required />
            </Field>
            <RoleChecks label="Roles" value={upd.roles} onChange={(r) => setUpd({ ...upd, roles: toggle(upd.roles, r) })} />
            <Field label="Qualifications">
              <input value={upd.qualifications} onChange={(e) => setUpd({ ...upd, qualifications: e.target.value })} />
            </Field>
            <Field label="Certifications">
              <input value={upd.certifications} onChange={(e) => setUpd({ ...upd, certifications: e.target.value })} />
            </Field>
            <Field label="Assigned node / laboratory">
              <LocationSelect locations={locations} value={upd.assignedLocationId} onChange={(v) => setUpd({ ...upd, assignedLocationId: v })} allowEmpty />
            </Field>
            <label className="check">
              <input type="checkbox" checked={upd.active} onChange={(e) => setUpd({ ...upd, active: e.target.checked })} /> Active
            </label>
          </Form>
        </Panel>
        <Panel title="Look up user" id="admin-read-user">
          {lookup.feedback}
          <Form
            busy={lookup.busy}
            submitLabel="Look up"
            onSubmit={() =>
              lookup.run(async () => {
                const u = await get(`/api/read-user/${lookupId}`);
                setFound(u);
                setUpd({ userId: u.userId, roles: u.roles, qualifications: u.qualifications.join(", "), certifications: u.certifications.map((c: any) => c.code).join(", "), active: u.active, assignedLocationId: "" });
              })
            }
          >
            <Field label="User ID">
              <input value={lookupId} onChange={(e) => setLookupId(e.target.value)} required />
            </Field>
          </Form>
          {found && (
            <KV
              items={[
                ["Username", found.username],
                ["Full name", found.fullName ?? "—"],
                ["Roles", found.roles.join(", ")],
                ["Qualifications", found.qualifications.join(", ") || "—"],
                ["Certifications", found.certifications.map((c: any) => `${c.code}${c.active ? "" : " (inactive)"}`).join(", ") || "—"],
                ["Active", found.active ? "yes" : "no"],
              ]}
            />
          )}
        </Panel>
      </div>
    </div>
  );
}

function RoleChecks({ label, value, onChange }: { label: string; value: string[]; onChange: (r: string) => void }) {
  return (
    <fieldset>
      <legend>{label}</legend>
      {ALL_ROLES.map((r) => (
        <label key={r} className="check">
          <input type="checkbox" checked={value.includes(r)} onChange={() => onChange(r)} /> {ROLE_LABELS[r]}
        </label>
      ))}
    </fieldset>
  );
}

function LocationSelect({ locations, value, onChange, allowEmpty, filter }: { locations: OpsLocation[]; value: string; onChange: (v: string) => void; allowEmpty?: boolean; filter?: (l: OpsLocation) => boolean }) {
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} required={!allowEmpty}>
      <option value="">{allowEmpty ? "None" : "Select location…"}</option>
      {locations.filter(filter ?? (() => true)).map((l) => (
        <option key={l.locationId} value={l.locationId}>
          {l.name}
        </option>
      ))}
    </select>
  );
}

function NetworkTab({ locations, connections, onDone }: { locations: OpsLocation[]; connections: OpsConnection[]; onDone: () => void }) {
  const loc = useAsyncAction();
  const conn = useAsyncAction();
  const cap = useAsyncAction();
  const acc = useAsyncAction();
  const [lf, setLf] = useState({ locationId: "", name: "", latitude: "", longitude: "", coverageKm: "5", handlingMinutes: "0", active: true, functions: ["collection_point"] as string[] });
  const [cf, setCf] = useState({ fromLocationId: "", toLocationId: "", travelMinutes: "30", costUnits: "1", cooled: false, active: true });
  const [capf, setCapf] = useState({ resourceId: "", capacityUnits: "10", cooledCapacityUnits: "0" });
  const [accf, setAccf] = useState({ laboratoryId: "", sampleTypeId: DEFAULT_SAMPLE_TYPES[0].id, accepts: true });
  const locName = (id: string) => locations.find((l) => l.locationId === id)?.name ?? id.slice(0, 8) + "…";

  const editLocation = (l: OpsLocation) =>
    setLf({ locationId: l.locationId, name: l.name, latitude: String(l.coordinate.latitude), longitude: String(l.coordinate.longitude), coverageKm: String(l.coverageKm), handlingMinutes: String(l.handlingMinutes), active: l.active, functions: FUNCTIONS.filter((f) => l.functions[f]) });

  return (
    <>
      <Panel title={`Locations (${locations.length})`} id="admin-locations">
        <Table
          caption="Locations"
          rows={locations}
          rowKey={(l) => l.locationId}
          columns={[
            { header: "Name", cell: (l) => l.name },
            { header: "ID", cell: (l) => <Id value={l.locationId} /> },
            { header: "Coordinate", cell: (l) => `${l.coordinate.latitude.toFixed(4)}, ${l.coordinate.longitude.toFixed(4)}` },
            { header: "Coverage km", cell: (l) => l.coverageKm },
            {
              header: "Functions",
              cell: (l) => (
                <span className="actions">
                  {FUNCTIONS.map((f) => (
                    <FunctionToggle key={f} location={l} fn={f} onDone={onDone} />
                  ))}
                </span>
              ),
            },
            { header: "Capacity", cell: (l) => (l.capacity ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits} · cooled ${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}` : "—") },
            { header: "Accepts", cell: (l) => (l.acceptedSampleTypeIds ?? []).map(sampleTypeName).join(", ") || "—" },
            {
              header: "",
              cell: (l) => (
                <span className="actions">
                  <ActiveToggle path="/api/set-location-status" idField="locationId" id={l.locationId} active={l.active} onDone={onDone} />
                  <button type="button" onClick={() => editLocation(l)}>
                    Edit
                  </button>
                </span>
              ),
            },
          ]}
        />
      </Panel>
      <div className="two-col">
        <Panel title={lf.locationId ? `Update location ${locName(lf.locationId)}` : "Create location"} id="admin-location-form">
          {loc.feedback}
          <Form
            busy={loc.busy}
            submitLabel={lf.locationId ? "Update location" : "Create location"}
            onSubmit={() =>
              loc.run(async () => {
                const body: Record<string, unknown> = {
                  name: lf.name,
                  coordinate: { latitude: Number(lf.latitude), longitude: Number(lf.longitude) },
                  coverageKm: Number(lf.coverageKm),
                  handlingMinutes: Number(lf.handlingMinutes),
                  functions: lf.functions,
                };
                if (lf.locationId) {
                  await post("/api/update-location", { locationId: lf.locationId, ...body });
                } else {
                  await post("/api/create-location", { ...body, active: lf.active });
                }
                onDone();
                setLf({ ...lf, locationId: "" });
                return lf.locationId ? "Location updated." : "Location created.";
              })
            }
          >
            <Field label="Name">
              <input value={lf.name} onChange={(e) => setLf({ ...lf, name: e.target.value })} required />
            </Field>
            <Field label="Latitude">
              <input type="number" step="any" value={lf.latitude} onChange={(e) => setLf({ ...lf, latitude: e.target.value })} required />
            </Field>
            <Field label="Longitude">
              <input type="number" step="any" value={lf.longitude} onChange={(e) => setLf({ ...lf, longitude: e.target.value })} required />
            </Field>
            <Field label="Coverage km (0–5)">
              <input type="number" step="0.1" min={0.1} max={5} value={lf.coverageKm} onChange={(e) => setLf({ ...lf, coverageKm: e.target.value })} required />
            </Field>
            <Field label="Handling minutes">
              <input type="number" min={0} max={1440} value={lf.handlingMinutes} onChange={(e) => setLf({ ...lf, handlingMinutes: e.target.value })} required />
            </Field>
            <fieldset>
              <legend>Functions</legend>
              {FUNCTIONS.map((f) => (
                <label key={f} className="check">
                  <input type="checkbox" checked={lf.functions.includes(f)} onChange={() => setLf({ ...lf, functions: lf.functions.includes(f) ? lf.functions.filter((x) => x !== f) : [...lf.functions, f] })} /> {f.replace("_", " ")}
                </label>
              ))}
            </fieldset>
            {!lf.locationId && (
              <label className="check">
                <input type="checkbox" checked={lf.active} onChange={(e) => setLf({ ...lf, active: e.target.checked })} /> Active
              </label>
            )}
            {lf.locationId && (
              <button type="button" onClick={() => setLf({ ...lf, locationId: "", name: "" })}>
                Cancel edit
              </button>
            )}
          </Form>
        </Panel>
        <div>
          <Panel title="Configure capacity" id="admin-capacity">
            {cap.feedback}
            <Form
              busy={cap.busy}
              submitLabel="Set capacity"
              onSubmit={() =>
                cap.run(async () => {
                  await post("/api/configure-capacity", { resourceId: capf.resourceId, capacityUnits: Number(capf.capacityUnits), cooledCapacityUnits: Number(capf.cooledCapacityUnits) });
                  onDone();
                  return "Capacity configured.";
                })
              }
            >
              <Field label="Node, laboratory or connection">
                <select value={capf.resourceId} onChange={(e) => setCapf({ ...capf, resourceId: e.target.value })} required>
                  <option value="">Select…</option>
                  {locations.map((l) => (
                    <option key={l.locationId} value={l.locationId}>
                      {l.name}
                    </option>
                  ))}
                  {connections.map((c) => (
                    <option key={c.connectionId} value={c.connectionId}>
                      Connection {locName(c.fromLocationId)} → {locName(c.toLocationId)}
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="Regular units">
                <input type="number" min={0} value={capf.capacityUnits} onChange={(e) => setCapf({ ...capf, capacityUnits: e.target.value })} required />
              </Field>
              <Field label="Cooled units">
                <input type="number" min={0} value={capf.cooledCapacityUnits} onChange={(e) => setCapf({ ...capf, cooledCapacityUnits: e.target.value })} required />
              </Field>
            </Form>
          </Panel>
          <Panel title="Laboratory acceptance" id="admin-acceptance">
            {acc.feedback}
            <Form
              busy={acc.busy}
              submitLabel="Save acceptance"
              onSubmit={() =>
                acc.run(async () => {
                  await post("/api/configure-laboratory-acceptance", accf);
                  onDone();
                  return "Laboratory acceptance updated.";
                })
              }
            >
              <Field label="Laboratory">
                <LocationSelect locations={locations} value={accf.laboratoryId} onChange={(v) => setAccf({ ...accf, laboratoryId: v })} filter={(l) => l.functions.laboratory} />
              </Field>
              <Field label="Sample type">
                <select value={accf.sampleTypeId} onChange={(e) => setAccf({ ...accf, sampleTypeId: e.target.value })}>
                  {DEFAULT_SAMPLE_TYPES.map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.name}
                    </option>
                  ))}
                </select>
              </Field>
              <Field label="Or custom sample type ID">
                <input value={accf.sampleTypeId} onChange={(e) => setAccf({ ...accf, sampleTypeId: e.target.value })} />
              </Field>
              <label className="check">
                <input type="checkbox" checked={accf.accepts} onChange={(e) => setAccf({ ...accf, accepts: e.target.checked })} /> Accepts
              </label>
            </Form>
          </Panel>
        </div>
      </div>
      <Panel title={`Connections (${connections.length})`} id="admin-connections">
        <Table
          caption="Connections"
          rows={connections}
          rowKey={(c) => c.connectionId}
          columns={[
            { header: "From", cell: (c) => locName(c.fromLocationId) },
            { header: "To", cell: (c) => locName(c.toLocationId) },
            { header: "ID", cell: (c) => <Id value={c.connectionId} /> },
            { header: "Travel min", cell: (c) => c.travelMinutes },
            { header: "Cost", cell: (c) => c.costUnits },
            { header: "Cooled", cell: (c) => (c.cooled ? "yes" : "no") },
            { header: "Capacity", cell: (c) => (c.capacity ? `${c.capacity.availableUnits}/${c.capacity.capacityUnits} · cooled ${c.capacity.cooledAvailableUnits}/${c.capacity.cooledCapacityUnits}` : "—") },
            { header: "", cell: (c) => <ActiveToggle path="/api/set-connection-status" idField="connectionId" id={c.connectionId} active={c.active} onDone={onDone} /> },
          ]}
        />
        <Details summary="Create connection">
          {conn.feedback}
          <Form
            busy={conn.busy}
            submitLabel="Create connection"
            onSubmit={() =>
              conn.run(async () => {
                await post("/api/create-connection", { fromLocationId: cf.fromLocationId, toLocationId: cf.toLocationId, travelMinutes: Number(cf.travelMinutes), costUnits: Number(cf.costUnits), cooled: cf.cooled, active: cf.active });
                onDone();
                return "Connection created.";
              })
            }
          >
            <Field label="From">
              <LocationSelect locations={locations} value={cf.fromLocationId} onChange={(v) => setCf({ ...cf, fromLocationId: v })} />
            </Field>
            <Field label="To">
