import { useEffect, useMemo, useState } from "react";
import { fmtTime, idempotencyKey, nowIso, post, ROLE_LABELS, sampleTypeName, toLocalInput, fromLocalInput } from "../api";
import { useSession } from "../session";
import { Banner, Details, Field, Form, Id, KV, Panel, StatusBadge, Table, Timeline, useAsyncAction } from "../components/ui";
import MapView from "../components/MapView";
import type { OpsLocation, RoleWork, WorkItem } from "../types";

interface LegContext {
  journeyId: string;
  assignmentId: string;
  kind: string;
  status: string;
  sampleIds: string[];
  fromLocationId?: string;
  toLocationId?: string;
  previousAssignmentId?: string;
  previousWorkerId?: string;
  previousWorkerName?: string;
  previousKind?: string;
  nextAssignmentId?: string;
  nextWorkerId?: string;
  nextWorkerName?: string;
  nextKind?: string;
  nextStatus?: string;
}

interface PendingHandoff {
  handoffId: string;
  sampleId: string;
  fromAssignmentId: string;
  toAssignmentId: string;
  senderId: string;
  senderName?: string;
  receiverId: string;
  receiverName?: string;
  senderConfirmed: boolean;
  receiverConfirmed: boolean;
  initiatedAt?: string;
}

export default function RoleWorkPage() {
  const { boot, eventTick, refresh } = useSession();
  const role = boot!.user.activeRole;
  const [work, setWork] = useState<RoleWork | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [version, setVersion] = useState(0);

  const load = async () => {
    try {
      setWork(await post<RoleWork>("/api/list-role-work", { role }));
      setError(null);
    } catch (e: any) {
      setError(e.message);
    }
  };

  useEffect(() => {
    void load();
  }, [role, eventTick, version]);

  useEffect(() => {
    if (eventTick > 0) void refresh();
  }, [eventTick]);

  const ops = boot!.operations;
  const locations = ops?.locations ?? [];
  const locById = useMemo(() => new Map(locations.map((l) => [l.locationId, l])), [locations]);
  const legContext = useMemo(() => new Map(((ops?.routes ?? []) as LegContext[]).map((r) => [r.assignmentId, r])), [ops]);
  const handoffs = (ops?.handoffs ?? []) as PendingHandoff[];
  const me = boot!.user.userId;

  const bump = () => {
    setVersion((v) => v + 1);
    void refresh();
  };

  const current = [...(work?.pending ?? []), ...(work?.inProgress ?? [])];
  const past = work?.completed ?? [];
  const myLocation = locations.find((l) => l.capacity);

  return (
    <div className="page">
      <h1>My work — {ROLE_LABELS[role] ?? role}</h1>
      {error && <Banner kind="error">{error}</Banner>}
      {myLocation && (
        <Banner kind="info">
          Assigned to <strong>{myLocation.name}</strong>. Capacity: {myLocation.capacity!.availableUnits}/{myLocation.capacity!.capacityUnits} regular, {myLocation.capacity!.cooledAvailableUnits}/{myLocation.capacity!.cooledCapacityUnits} cooled available.{" "}
          <a href="#/facility">Manage facility</a>
        </Banner>
      )}
      {handoffs.filter((h) => h.receiverId === me && !h.receiverConfirmed).length > 0 && (
        <Panel title="Incoming handoffs awaiting your confirmation" id="incoming-handoffs">
          {handoffs
            .filter((h) => h.receiverId === me && !h.receiverConfirmed)
            .map((h) => (
              <HandoffRow key={h.handoffId} h={h} side="receiver" onDone={bump} />
            ))}
        </Panel>
      )}
      <Panel title={`Current work (${current.length})`} id="current-work">
        {current.length === 0 && <p className="muted">No current work.</p>}
        {current.map((item) => (
          <WorkCard key={item.assignmentId ?? item.journeyId ?? item.sampleId} item={item} locById={locById} ctx={legContext.get(item.assignmentId)} handoffs={handoffs} me={me} role={role} onDone={bump} />
        ))}
      </Panel>
      <Panel title={`Past work (${past.length})`} id="past-work">
        <Table
          caption="Completed work"
          rows={past}
          rowKey={(r) => r.assignmentId ?? r.journeyId ?? r.sampleId}
          empty="No completed work yet."
          columns={[
            { header: "Kind", cell: (r) => r.kind },
            { header: "Assignment", cell: (r) => <Id value={r.assignmentId} /> },
            { header: "Sample", cell: (r) => (r.sampleId ? <a href={`#/sample/${r.sampleId}`}>{r.sampleId.slice(0, 8)}…</a> : "—") },
            { header: "Status", cell: (r) => <StatusBadge status={r.status} /> },
            { header: "Route", cell: (r) => routeText(r, locById) },
            {
              header: "Timeline",
              cell: (r) => (
                <Details summary={`${r.history.length} status changes`}>
                  <Timeline entries={r.history} />
                </Details>
              ),
            },
          ]}
        />
      </Panel>
      <PresealedForm locations={locations} assigned={myLocation} onDone={bump} />
      {(role === "collection_professional" || role === "delivery_partner") && (
        <Panel title="Network map" id="work-map">
          <MapView locations={locations} connections={ops?.connections ?? []} height={360} />
        </Panel>
      )}
    </div>
  );
}

function routeText(r: WorkItem, locById: Map<string, OpsLocation>) {
  const name = (id?: string) => (id ? (locById.get(id)?.name ?? id.slice(0, 8)) : null);
  if (r.kind === "node") return name(r.nodeId) ?? "—";
  if (r.kind === "laboratory") return name(r.laboratoryId) ?? "—";
  const from = name(r.fromLocationId) ?? (r.kind === "collection" ? "Origin" : "—");
  const to = name(r.toLocationId) ?? "—";
  return `${from} → ${to}`;
}

function WorkCard({ item, locById, ctx, handoffs, me, role, onDone }: { item: WorkItem; locById: Map<string, OpsLocation>; ctx?: LegContext; handoffs: PendingHandoff[]; me: string; role: string; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const myPending = handoffs.filter((h) => (h.fromAssignmentId === item.assignmentId || h.toAssignmentId === item.assignmentId) && h.sampleId === item.sampleId);
  const outgoing = myPending.find((h) => h.senderId === me);
  const cap = item.destinationCapacity;
  const accepted = item.status !== "pending";

  const simple = (label: string, path: string, body: Record<string, unknown>, done: string) => (
    <button
      type="button"
      disabled={busy}
      onClick={() =>
        run(async () => {
          await post(path, { ...body, idempotencyKey: idempotencyKey() });
          onDone();
          return done;
        })
      }
    >
      {label}
    </button>
  );

  return (
    <article className="work-card" aria-label={`${item.kind} assignment ${item.assignmentId?.slice(0, 8)}`}>
      <header>
        <h3>
          {item.kind.charAt(0).toUpperCase() + item.kind.slice(1)} assignment <Id value={item.assignmentId} />
        </h3>
        <StatusBadge status={item.status} />
      </header>
      <KV
        items={[
          ["Sample", item.sampleId ? <a href={`#/sample/${item.sampleId}`}>{item.sampleId}</a> : "—"],
          ["Route", routeText(item, locById)],
          ["Journey", item.journeyId ? <a href={`#/journey/${item.journeyId}`}>{item.journeyId.slice(0, 8)}…</a> : "—"],
          ...(item.offerExpiresAt ? ([["Offer expires", fmtTime(item.offerExpiresAt)]] as [string, React.ReactNode][]) : []),
          ...(item.expectedSampleTypeId ? ([["Expected sample type", sampleTypeName(item.expectedSampleTypeId)]] as [string, React.ReactNode][]) : []),
          ...(cap ? ([["Destination capacity", `${cap.availableUnits}/${cap.capacityUnits} regular · ${cap.cooledAvailableUnits}/${cap.cooledCapacityUnits} cooled available`]] as [string, React.ReactNode][]) : []),
        ]}
      />
      {feedback}
      <div className="actions">
        {item.status === "pending" && (
          <>
            {simple("Accept assignment", "/api/accept-assignment", { assignmentId: item.assignmentId }, "Assignment accepted.")}
            {simple("Decline assignment", "/api/decline-assignment", { assignmentId: item.assignmentId, declinedAt: nowIso() }, "Assignment declined.")}
          </>
        )}
        {accepted && item.kind === "transport" && (
          <>
            {["at_pickup", "picked_up", "in_transit", "arrived", "delivered"].map((s) => (
              <span key={s}>{simple(`Mark ${s.replace("_", " ")}`, "/api/update-assignment-progress", { assignmentId: item.assignmentId, status: s, occurredAt: nowIso() }, `Progress recorded: ${s}.`)}</span>
            ))}
          </>
        )}
        {accepted && (item.kind === "node" || item.kind === "laboratory") && (
          <>
            {simple("Mark in progress", "/api/update-assignment-progress", { assignmentId: item.assignmentId, status: "in_progress", occurredAt: nowIso() }, "Progress recorded.")}
            {item.kind === "node" && simple("Mark completed", "/api/update-assignment-progress", { assignmentId: item.assignmentId, status: "completed", occurredAt: nowIso() }, "Assignment completed.")}
          </>
        )}
      </div>
      {accepted && (
        <div className="work-forms">
          {item.kind === "collection" && item.status === "accepted" && <CollectForm item={item} onDone={onDone} />}
          {(item.kind === "collection" || item.kind === "transport") && <LocationForm item={item} onDone={onDone} />}
          <CheckpointForm item={item} onDone={onDone} />
          {item.kind === "laboratory" && <LabForms item={item} onDone={onDone} />}
          {ctx?.nextAssignmentId && !outgoing && item.kind !== "laboratory" && <InitiateHandoffForm item={item} ctx={ctx} onDone={onDone} />}
          {myPending.map((h) => (
            <HandoffRow key={h.handoffId} h={h} side={h.senderId === me ? "sender" : "receiver"} onDone={onDone} />
          ))}
        </div>
      )}
      <Details summary={`Status timeline (${item.history.length})`}>
        <Timeline entries={item.history} />
      </Details>
    </article>
  );
}

function CollectForm({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [collectedAt, setCollectedAt] = useState(toLocalInput(nowIso()));
  const [containerType, setContainerType] = useState("");
  const [temp, setTemp] = useState("");
  return (
    <Details summary="Record collection and sealing">
      {feedback}
      <Form
        busy={busy}
        submitLabel="Record collected & sealed"
        onSubmit={() =>
          run(async () => {
            const r = await post("/api/collect-and-seal-sample", {
              sampleId: item.sampleId,
              assignmentId: item.assignmentId,
              collectedAt: fromLocalInput(collectedAt),
              containerType,
              observedTemperatureC: Number(temp),
              idempotencyKey: idempotencyKey(),
            });
            onDone();
            return `Sample sealed${r.handlingCompliant ? "" : " — handling non-compliant, flagged as exception"}.`;
          })
        }
      >
        <Field label="Collected at">
          <input type="datetime-local" value={collectedAt} onChange={(e) => setCollectedAt(e.target.value)} required />
        </Field>
        <Field label="Container type">
          <input value={containerType} onChange={(e) => setContainerType(e.target.value)} required />
        </Field>
        <Field label="Observed temperature (°C)">
          <input type="number" step="0.1" value={temp} onChange={(e) => setTemp(e.target.value)} required />
        </Field>
      </Form>
    </Details>
  );
}

function LocationForm({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [lat, setLat] = useState("");
  const [lon, setLon] = useState("");
  const [seq, setSeq] = useState(1);
  const useDevice = () => {
    navigator.geolocation?.getCurrentPosition((p) => {
      setLat(String(p.coords.latitude));
      setLon(String(p.coords.longitude));
    });
  };
  return (
    <Details summary="Record my location">
      {feedback}
      <Form
        busy={busy}
        submitLabel="Record location"
        onSubmit={() =>
          run(async () => {
            await post("/api/record-worker-location", {
              assignmentId: item.assignmentId,
              coordinate: { latitude: Number(lat), longitude: Number(lon) },
              sequence: seq,
              recordedAt: nowIso(),
            });
            setSeq((s) => s + 1);
            onDone();
            return "Location recorded.";
          })
        }
      >
        <Field label="Latitude">
          <input type="number" step="any" value={lat} onChange={(e) => setLat(e.target.value)} required />
        </Field>
        <Field label="Longitude">
          <input type="number" step="any" value={lon} onChange={(e) => setLon(e.target.value)} required />
        </Field>
        <Field label="Sequence">
          <input type="number" min={1} value={seq} onChange={(e) => setSeq(Number(e.target.value))} required />
        </Field>
        <button type="button" onClick={useDevice}>
          Use device location
        </button>
      </Form>
    </Details>
  );
}

function CheckpointForm({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [containerType, setContainerType] = useState("");
  const [temp, setTemp] = useState("");
  return (
    <Details summary="Record handling checkpoint">
      {feedback}
      <Form
        busy={busy}
        submitLabel="Record checkpoint"
        onSubmit={() =>
          run(async () => {
            const r = await post("/api/record-handling-checkpoint", {
              sampleId: item.sampleId,
              assignmentId: item.assignmentId,
              ...(item.nodeId || item.laboratoryId ? { locationId: item.nodeId || item.laboratoryId } : {}),
              containerType,
              observedTemperatureC: Number(temp),
              recordedAt: nowIso(),
              idempotencyKey: idempotencyKey(),
            });
            onDone();
            return r.compliant ? "Checkpoint recorded: compliant." : `Checkpoint recorded: NOT compliant — sample marked ${r.sampleStatus}.`;
          })
        }
      >
        <Field label="Observed container type">
          <input value={containerType} onChange={(e) => setContainerType(e.target.value)} required />
        </Field>
        <Field label="Observed temperature (°C)">
          <input type="number" step="0.1" value={temp} onChange={(e) => setTemp(e.target.value)} required />
        </Field>
      </Form>
    </Details>
  );
}

function LabForms({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [reason, setReason] = useState("");
  return (
    <Details summary="Laboratory receipt">
      {feedback}
      <div className="actions">
        <button
          type="button"
          disabled={busy}
          onClick={() =>
            run(async () => {
              await post("/api/confirm-laboratory-receipt", { sampleId: item.sampleId, laboratoryId: item.laboratoryId, receivedAt: nowIso(), idempotencyKey: idempotencyKey() });
              onDone();
              return "Sample receipt confirmed.";
            })
          }
        >
          Confirm sample received
        </button>
      </div>
      <Form
        busy={busy}
        submitLabel="Record laboratory exception"
        onSubmit={() =>
          run(async () => {
            await post("/api/record-laboratory-exception", { sampleId: item.sampleId, laboratoryId: item.laboratoryId, reason, observedAt: nowIso(), idempotencyKey: idempotencyKey() });
            onDone();
            return "Exception recorded.";
          })
        }
      >
        <Field label="Exception reason">
          <input value={reason} onChange={(e) => setReason(e.target.value)} required />
        </Field>
      </Form>
    </Details>
  );
}

function InitiateHandoffForm({ item, ctx, onDone }: { item: WorkItem; ctx: LegContext; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const ready = !!ctx.nextWorkerId;
  return (
    <div className="handoff-box">
      <p>
        Next in chain: <strong>{ctx.nextKind}</strong> assignment <Id value={ctx.nextAssignmentId} />
        {ctx.nextWorkerName ? ` — ${ctx.nextWorkerName}` : ready ? "" : " — not yet accepted by a worker"}
      </p>
      {feedback}
      <button
        type="button"
        disabled={busy || !ready}
        onClick={() =>
          run(async () => {
            await post("/api/initiate-handoff", {
              sampleId: item.sampleId,
              fromAssignmentId: item.assignmentId,
              toAssignmentId: ctx.nextAssignmentId,
              receiverId: ctx.nextWorkerId,
              initiatedAt: nowIso(),
              idempotencyKey: idempotencyKey(),
            });
            onDone();
            return "Handoff initiated — both sides must confirm.";
          })
        }
      >
        Hand off sample to {ctx.nextWorkerName || "next worker"}
      </button>
    </div>
  );
}

export function HandoffRow({ h, side, onDone }: { h: PendingHandoff; side: "sender" | "receiver"; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const confirmed = side === "sender" ? h.senderConfirmed : h.receiverConfirmed;
  return (
    <div className="handoff-box">
      <p>
        Handoff <Id value={h.handoffId} /> of sample <a href={`#/sample/${h.sampleId}`}>{h.sampleId.slice(0, 8)}…</a>: {h.senderName || h.senderId.slice(0, 8)} → {h.receiverName || h.receiverId.slice(0, 8)} · sender {h.senderConfirmed ? "confirmed" : "pending"}, receiver {h.receiverConfirmed ? "confirmed" : "pending"}
      </p>
      {feedback}
      {!confirmed && (
        <button
          type="button"
          disabled={busy}
          onClick={() =>
            run(async () => {
              const r = await post("/api/confirm-handoff", { handoffId: h.handoffId, confirmationSide: side, confirmedAt: nowIso(), idempotencyKey: idempotencyKey() });
              onDone();
              return r.status === "confirmed" ? "Handoff complete — custody transferred." : "Confirmation recorded; waiting for the other party.";
            })
          }
        >
          Confirm handoff as {side}
        </button>
      )}
    </div>
  );
}

observation.new_content:
import { useEffect, useMemo, useState } from "react";
import { fmtTime, idempotencyKey, nowIso, post, ROLE_LABELS, sampleTypeName, toLocalInput, fromLocalInput } from "../api";
import { useSession } from "../session";
import { Banner, Details, Field, Form, Id, KV, Panel, StatusBadge, Table, Timeline, useAsyncAction } from "../components/ui";
import MapView from "../components/MapView";
import type { OpsLocation, RoleWork, WorkItem } from "../types";

interface LegContext {
  journeyId: string;
  assignmentId: string;
  kind: string;
  status: string;
  sampleIds: string[];
  fromLocationId?: string;
  toLocationId?: string;
  previousAssignmentId?: string;
  previousWorkerId?: string;
  previousWorkerName?: string;
  previousKind?: string;
  nextAssignmentId?: string;
  nextWorkerId?: string;
  nextWorkerName?: string;
  nextKind?: string;
  nextStatus?: string;
}

interface PendingHandoff {
  handoffId: string;
  sampleId: string;
  fromAssignmentId: string;
  toAssignmentId: string;
  senderId: string;
  senderName?: string;
  receiverId: string;
  receiverName?: string;
  senderConfirmed: boolean;
  receiverConfirmed: boolean;
  initiatedAt?: string;
}

export default function RoleWorkPage() {
  const { boot, eventTick, refresh } = useSession();
  const role = boot!.user.activeRole;
  const [work, setWork] = useState<RoleWork | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [version, setVersion] = useState(0);

  const load = async () => {
    try {
      setWork(await post<RoleWork>("/api/list-role-work", { role }));
      setError(null);
    } catch (e: any) {
      setError(e.message);
    }
  };

  useEffect(() => {
    void load();
  }, [role, eventTick, version]);

  useEffect(() => {
    if (eventTick > 0) void refresh();
  }, [eventTick]);

  const ops = boot!.operations;
  const locations = ops?.locations ?? [];
  const locById = useMemo(() => new Map(locations.map((l) => [l.locationId, l])), [locations]);
  const legContext = useMemo(() => new Map(((ops?.routes ?? []) as LegContext[]).map((r) => [r.assignmentId, r])), [ops]);
  const handoffs = (ops?.handoffs ?? []) as PendingHandoff[];
  const me = boot!.user.userId;

  const bump = () => {
    setVersion((v) => v + 1);
    void refresh();
  };

  const current = [...(work?.pending ?? []), ...(work?.inProgress ?? [])];
  const past = work?.completed ?? [];
  const myLocation = locations.find((l) => l.capacity);

  return (
    <div className="page">
      <h1>My work — {ROLE_LABELS[role] ?? role}</h1>
      {error && <Banner kind="error">{error}</Banner>}
      {myLocation && (
        <Banner kind="info">
          Assigned to <strong>{myLocation.name}</strong>. Capacity: {myLocation.capacity!.availableUnits}/{myLocation.capacity!.capacityUnits} regular, {myLocation.capacity!.cooledAvailableUnits}/{myLocation.capacity!.cooledCapacityUnits} cooled available.{" "}
          <a href="#/facility">Manage facility</a>
        </Banner>
      )}
      {handoffs.filter((h) => h.receiverId === me && !h.receiverConfirmed).length > 0 && (
        <Panel title="Incoming handoffs awaiting your confirmation" id="incoming-handoffs">
          {handoffs
            .filter((h) => h.receiverId === me && !h.receiverConfirmed)
            .map((h) => (
              <HandoffRow key={h.handoffId} h={h} side="receiver" onDone={bump} />
            ))}
        </Panel>
      )}
      <Panel title={`Current work (${current.length})`} id="current-work">
        {current.length === 0 && <p className="muted">No current work.</p>}
        {current.map((item) => (
          <WorkCard key={item.assignmentId ?? item.journeyId ?? item.sampleId} item={item} locById={locById} ctx={legContext.get(item.assignmentId)} handoffs={handoffs} me={me} role={role} onDone={bump} />
        ))}
      </Panel>
      <Panel title={`Past work (${past.length})`} id="past-work">
        <Table
          caption="Completed work"
          rows={past}
          rowKey={(r) => r.assignmentId ?? r.journeyId ?? r.sampleId}
          empty="No completed work yet."
          columns={[
            { header: "Kind", cell: (r) => r.kind },
            { header: "Assignment", cell: (r) => <Id value={r.assignmentId} /> },
            { header: "Sample", cell: (r) => (r.sampleId ? <a href={`#/sample/${r.sampleId}`}>{r.sampleId.slice(0, 8)}…</a> : "—") },
            { header: "Status", cell: (r) => <StatusBadge status={r.status} /> },
            { header: "Route", cell: (r) => routeText(r, locById) },
            {
              header: "Timeline",
              cell: (r) => (
                <Details summary={`${r.history.length} status changes`}>
                  <Timeline entries={r.history} />
                </Details>
              ),
            },
          ]}
        />
      </Panel>
      <PresealedForm locations={locations} assigned={myLocation} onDone={bump} />
      {(role === "collection_professional" || role === "delivery_partner") && (
        <Panel title="Network map" id="work-map">
          <MapView locations={locations} connections={ops?.connections ?? []} height={360} />
        </Panel>
      )}
    </div>
  );
}

const TYPE_DEFAULTS: Record<string, { containerType: string; min: number; max: number }> = {
  "00000000-0000-4000-8000-000000000a01": { containerType: "standard_tube", min: 15, max: 25 },
  "00000000-0000-4000-8000-000000000a02": { containerType: "indigo_vial", min: 15, max: 25 },
  "00000000-0000-4000-8000-000000000a03": { containerType: "cooled_box", min: 2, max: 8 },
  "00000000-0000-4000-8000-000000000a04": { containerType: "pulse_tube", min: 15, max: 25 },
};

function PresealedForm({ locations, assigned, onDone }: { locations: OpsLocation[]; assigned?: OpsLocation; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const first = DEFAULT_SAMPLE_TYPES[0].id;
  const [f, setF] = useState({
    originType: assigned ? "node" : "clinic",
    originNodeId: assigned?.locationId ?? "",
    latitude: assigned ? String(assigned.coordinate.latitude) : "",
    longitude: assigned ? String(assigned.coordinate.longitude) : "",
    sampleTypeId: first,
    containerType: TYPE_DEFAULTS[first].containerType,
    temperatureMinC: String(TYPE_DEFAULTS[first].min),
    temperatureMaxC: String(TYPE_DEFAULTS[first].max),
    deliveryDeadline: toLocalInput(new Date(Date.now() + 6 * 3600000).toISOString()),
  });
  const onNode = (id: string) => {
    const l = locations.find((x) => x.locationId === id);
    setF({ ...f, originNodeId: id, ...(l ? { latitude: String(l.coordinate.latitude), longitude: String(l.coordinate.longitude) } : {}) });
  };
  const onType = (id: string) => {
    const d = TYPE_DEFAULTS[id];
    setF({ ...f, sampleTypeId: id, ...(d ? { containerType: d.containerType, temperatureMinC: String(d.min), temperatureMaxC: String(d.max) } : {}) });
  };
  return (
    <Panel title="Register a pre-sealed sample" id="presealed">
      <p className="muted">For samples already collected and sealed before entering the system. You must currently hold the sample; only the remaining transport legs are created.</p>
      {feedback}
      <Form
        busy={busy}
        submitLabel="Register pre-sealed sample"
        onSubmit={() =>
          run(async () => {
            const r = await post("/api/ingest-presealed-sample", {
              origin: { latitude: Number(f.latitude), longitude: Number(f.longitude) },
              originType: f.originType,
              ...(f.originType === "node" && f.originNodeId ? { originNodeId: f.originNodeId } : {}),
              requestedAt: nowIso(),
              deliveryDeadline: fromLocalInput(f.deliveryDeadline),
              sampleTypeId: f.sampleTypeId,
              containerType: f.containerType,
              temperatureMinC: Number(f.temperatureMinC),
              temperatureMaxC: Number(f.temperatureMaxC),
              idempotencyKey: idempotencyKey(),
            });
            onDone();
            return `Sample ${r.sampleId.slice(0, 8)}… registered (${r.serviceability}${r.serviceabilityReason ? `: ${r.serviceabilityReason}` : ""}).`;
          })
        }
      >
        <Field label="Origin type">
          <select value={f.originType} onChange={(e) => setF({ ...f, originType: e.target.value })}>
            <option value="clinic">Clinic</option>
            <option value="node">Network node</option>
          </select>
        </Field>
        {f.originType === "node" && (
          <Field label="Origin node">
            <select value={f.originNodeId} onChange={(e) => onNode(e.target.value)} required>
              <option value="">Select node…</option>
              {locations.map((l) => (
                <option key={l.locationId} value={l.locationId}>
                  {l.name}
                </option>
              ))}
            </select>
          </Field>
        )}
        <Field label="Latitude">
          <input type="number" step="any" value={f.latitude} onChange={(e) => setF({ ...f, latitude: e.target.value })} required />
        </Field>
        <Field label="Longitude">
          <input type="number" step="any" value={f.longitude} onChange={(e) => setF({ ...f, longitude: e.target.value })} required />
        </Field>
        <Field label="Sample type">
          <select value={f.sampleTypeId} onChange={(e) => onType(e.target.value)}>
            {DEFAULT_SAMPLE_TYPES.map((t) => (
              <option key={t.id} value={t.id}>
                {t.name}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Container type">
          <input value={f.containerType} onChange={(e) => setF({ ...f, containerType: e.target.value })} required />
        </Field>
        <Field label="Temperature min (°C)">
          <input type="number" step="0.1" value={f.temperatureMinC} onChange={(e) => setF({ ...f, temperatureMinC: e.target.value })} required />
        </Field>
        <Field label="Temperature max (°C)">
          <input type="number" step="0.1" value={f.temperatureMaxC} onChange={(e) => setF({ ...f, temperatureMaxC: e.target.value })} required />
        </Field>
        <Field label="Delivery deadline">
          <input type="datetime-local" value={f.deliveryDeadline} onChange={(e) => setF({ ...f, deliveryDeadline: e.target.value })} required />
        </Field>
      </Form>
    </Panel>
  );
}

function routeText(r: WorkItem, locById: Map<string, OpsLocation>) {
  const name = (id?: string) => (id ? (locById.get(id)?.name ?? id.slice(0, 8)) : null);
  if (r.kind === "node") return name(r.nodeId) ?? "—";
  if (r.kind === "laboratory") return name(r.laboratoryId) ?? "—";
  const from = name(r.fromLocationId) ?? (r.kind === "collection" ? "Origin" : "—");
  const to = name(r.toLocationId) ?? "—";
  return `${from} → ${to}`;
}

function WorkCard({ item, locById, ctx, handoffs, me, role, onDone }: { item: WorkItem; locById: Map<string, OpsLocation>; ctx?: LegContext; handoffs: PendingHandoff[]; me: string; role: string; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const myPending = handoffs.filter((h) => (h.fromAssignmentId === item.assignmentId || h.toAssignmentId === item.assignmentId) && h.sampleId === item.sampleId);
  const outgoing = myPending.find((h) => h.senderId === me);
  const cap = item.destinationCapacity;
  const accepted = item.status !== "pending";

  const simple = (label: string, path: string, body: Record<string, unknown>, done: string) => (
    <button
      type="button"
      disabled={busy}
      onClick={() =>
        run(async () => {
          await post(path, { ...body, idempotencyKey: idempotencyKey() });
          onDone();
          return done;
        })
      }
    >
      {label}
    </button>
  );

  return (
    <article className="work-card" aria-label={`${item.kind} assignment ${item.assignmentId?.slice(0, 8)}`}>
      <header>
        <h3>
          {item.kind.charAt(0).toUpperCase() + item.kind.slice(1)} assignment <Id value={item.assignmentId} />
        </h3>
        <StatusBadge status={item.status} />
      </header>
      <KV
        items={[
          ["Sample", item.sampleId ? <a href={`#/sample/${item.sampleId}`}>{item.sampleId}</a> : "—"],
          ["Route", routeText(item, locById)],
          ["Journey", item.journeyId ? <a href={`#/journey/${item.journeyId}`}>{item.journeyId.slice(0, 8)}…</a> : "—"],
          ...(item.offerExpiresAt ? ([["Offer expires", fmtTime(item.offerExpiresAt)]] as [string, React.ReactNode][]) : []),
          ...(item.expectedSampleTypeId ? ([["Expected sample type", sampleTypeName(item.expectedSampleTypeId)]] as [string, React.ReactNode][]) : []),
          ...(cap ? ([["Destination capacity", `${cap.availableUnits}/${cap.capacityUnits} regular · ${cap.cooledAvailableUnits}/${cap.cooledCapacityUnits} cooled available`]] as [string, React.ReactNode][]) : []),
        ]}
      />
      {feedback}
      <div className="actions">
        {item.status === "pending" && (
          <>
            {simple("Accept assignment", "/api/accept-assignment", { assignmentId: item.assignmentId }, "Assignment accepted.")}
            {simple("Decline assignment", "/api/decline-assignment", { assignmentId: item.assignmentId, declinedAt: nowIso() }, "Assignment declined.")}
          </>
        )}
        {accepted && item.kind === "transport" && (
          <>
            {["at_pickup", "picked_up", "in_transit", "arrived", "delivered"].map((s) => (
              <span key={s}>{simple(`Mark ${s.replace("_", " ")}`, "/api/update-assignment-progress", { assignmentId: item.assignmentId, status: s, occurredAt: nowIso() }, `Progress recorded: ${s}.`)}</span>
            ))}
          </>
        )}
        {accepted && (item.kind === "node" || item.kind === "laboratory") && (
          <>
            {simple("Mark in progress", "/api/update-assignment-progress", { assignmentId: item.assignmentId, status: "in_progress", occurredAt: nowIso() }, "Progress recorded.")}
            {item.kind === "node" && simple("Mark completed", "/api/update-assignment-progress", { assignmentId: item.assignmentId, status: "completed", occurredAt: nowIso() }, "Assignment completed.")}
          </>
        )}
      </div>
      {accepted && (
        <div className="work-forms">
          {item.kind === "collection" && item.status === "accepted" && <CollectForm item={item} onDone={onDone} />}
          {(item.kind === "collection" || item.kind === "transport") && <LocationForm item={item} onDone={onDone} />}
          <CheckpointForm item={item} onDone={onDone} />
          {item.kind === "laboratory" && <LabForms item={item} onDone={onDone} />}
          {ctx?.nextAssignmentId && !outgoing && item.kind !== "laboratory" && <InitiateHandoffForm item={item} ctx={ctx} onDone={onDone} />}
          {myPending.map((h) => (
            <HandoffRow key={h.handoffId} h={h} side={h.senderId === me ? "sender" : "receiver"} onDone={onDone} />
          ))}
        </div>
      )}
      <Details summary={`Status timeline (${item.history.length})`}>
        <Timeline entries={item.history} />
      </Details>
    </article>
  );
}

function CollectForm({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [collectedAt, setCollectedAt] = useState(toLocalInput(nowIso()));
  const [containerType, setContainerType] = useState("");
  const [temp, setTemp] = useState("");
  return (
    <Details summary="Record collection and sealing">
      {feedback}
      <Form
        busy={busy}
        submitLabel="Record collected & sealed"
        onSubmit={() =>
          run(async () => {
            const r = await post("/api/collect-and-seal-sample", {
              sampleId: item.sampleId,
              assignmentId: item.assignmentId,
              collectedAt: fromLocalInput(collectedAt),
              containerType,
              observedTemperatureC: Number(temp),
              idempotencyKey: idempotencyKey(),
            });
            onDone();
            return `Sample sealed${r.handlingCompliant ? "" : " — handling non-compliant, flagged as exception"}.`;
          })
        }
      >
        <Field label="Collected at">
          <input type="datetime-local" value={collectedAt} onChange={(e) => setCollectedAt(e.target.value)} required />
        </Field>
        <Field label="Container type">
          <input value={containerType} onChange={(e) => setContainerType(e.target.value)} required />
        </Field>
        <Field label="Observed temperature (°C)">
          <input type="number" step="0.1" value={temp} onChange={(e) => setTemp(e.target.value)} required />
        </Field>
      </Form>
    </Details>
  );
}

function LocationForm({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [lat, setLat] = useState("");
  const [lon, setLon] = useState("");
  const [seq, setSeq] = useState(1);
  const useDevice = () => {
    navigator.geolocation?.getCurrentPosition((p) => {
      setLat(String(p.coords.latitude));
      setLon(String(p.coords.longitude));
    });
  };
  return (
    <Details summary="Record my location">
      {feedback}
      <Form
        busy={busy}
        submitLabel="Record location"
        onSubmit={() =>
          run(async () => {
            await post("/api/record-worker-location", {
              assignmentId: item.assignmentId,
              coordinate: { latitude: Number(lat), longitude: Number(lon) },
              sequence: seq,
              recordedAt: nowIso(),
            });
            setSeq((s) => s + 1);
            onDone();
            return "Location recorded.";
          })
        }
      >
        <Field label="Latitude">
          <input type="number" step="any" value={lat} onChange={(e) => setLat(e.target.value)} required />
        </Field>
        <Field label="Longitude">
          <input type="number" step="any" value={lon} onChange={(e) => setLon(e.target.value)} required />
        </Field>
        <Field label="Sequence">
          <input type="number" min={1} value={seq} onChange={(e) => setSeq(Number(e.target.value))} required />
        </Field>
        <button type="button" onClick={useDevice}>
          Use device location
        </button>
      </Form>
    </Details>
  );
}

function CheckpointForm({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [containerType, setContainerType] = useState("");
  const [temp, setTemp] = useState("");
  return (
    <Details summary="Record handling checkpoint">
      {feedback}
      <Form
        busy={busy}
        submitLabel="Record checkpoint"
        onSubmit={() =>
          run(async () => {
            const r = await post("/api/record-handling-checkpoint", {
              sampleId: item.sampleId,
              assignmentId: item.assignmentId,
              ...(item.nodeId || item.laboratoryId ? { locationId: item.nodeId || item.laboratoryId } : {}),
              containerType,
              observedTemperatureC: Number(temp),
              recordedAt: nowIso(),
              idempotencyKey: idempotencyKey(),
            });
            onDone();
            return r.compliant ? "Checkpoint recorded: compliant." : `Checkpoint recorded: NOT compliant — sample marked ${r.sampleStatus}.`;
          })
        }
      >
        <Field label="Observed container type">
          <input value={containerType} onChange={(e) => setContainerType(e.target.value)} required />
        </Field>
        <Field label="Observed temperature (°C)">
          <input type="number" step="0.1" value={temp} onChange={(e) => setTemp(e.target.value)} required />
        </Field>
      </Form>
    </Details>
  );
}

function LabForms({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const [reason, setReason] = useState("");
  return (
    <Details summary="Laboratory receipt">
      {feedback}
      <div className="actions">
        <button
          type="button"
          disabled={busy}
          onClick={() =>
            run(async () => {
              await post("/api/confirm-laboratory-receipt", { sampleId: item.sampleId, laboratoryId: item.laboratoryId, receivedAt: nowIso(), idempotencyKey: idempotencyKey() });
              onDone();
              return "Sample receipt confirmed.";
            })
          }
        >
          Confirm sample received
        </button>
      </div>
      <Form
        busy={busy}
        submitLabel="Record laboratory exception"
        onSubmit={() =>
          run(async () => {
            await post("/api/record-laboratory-exception", { sampleId: item.sampleId, laboratoryId: item.laboratoryId, reason, observedAt: nowIso(), idempotencyKey: idempotencyKey() });
            onDone();
            return "Exception recorded.";
          })
        }
      >
        <Field label="Exception reason">
          <input value={reason} onChange={(e) => setReason(e.target.value)} required />
        </Field>
      </Form>
    </Details>
  );
}

function InitiateHandoffForm({ item, ctx, onDone }: { item: WorkItem; ctx: LegContext; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const ready = !!ctx.nextWorkerId;
  return (
    <div className="handoff-box">
      <p>
        Next in chain: <strong>{ctx.nextKind}</strong> assignment <Id value={ctx.nextAssignmentId} />
        {ctx.nextWorkerName ? ` — ${ctx.nextWorkerName}` : ready ? "" : " — not yet accepted by a worker"}
      </p>
      {feedback}
      <button
        type="button"
        disabled={busy || !ready}
        onClick={() =>
          run(async () => {
            await post("/api/initiate-handoff", {
              sampleId: item.sampleId,
              fromAssignmentId: item.assignmentId,
              toAssignmentId: ctx.nextAssignmentId,
              receiverId: ctx.nextWorkerId,
              initiatedAt: nowIso(),
              idempotencyKey: idempotencyKey(),
            });
            onDone();
            return "Handoff initiated — both sides must confirm.";
          })
        }
      >
        Hand off sample to {ctx.nextWorkerName || "next worker"}
      </button>
    </div>
  );
}

export function HandoffRow({ h, side, onDone }: { h: PendingHandoff; side: "sender" | "receiver"; onDone: () => void }) {
  const { busy, run, feedback } = useAsyncAction();
  const confirmed = side === "sender" ? h.senderConfirmed : h.receiverConfirmed;
  return (
    <div className="handoff-box">
      <p>
        Handoff <Id value={h.handoffId} /> of sample <a href={`#/sample/${h.sampleId}`}>{h.sampleId.slice(0, 8)}…</a>: {h.senderName || h.senderId.slice(0, 8)} → {h.receiverName || h.receiverId.slice(0, 8)} · sender {h.senderConfirmed ? "confirmed" : "pending"}, receiver {h.receiverConfirmed ? "confirmed" : "pending"}
      </p>
      {feedback}
      {!confirmed && (
        <button
          type="button"
          disabled={busy}
          onClick={() =>
            run(async () => {
              const r = await post("/api/confirm-handoff", { handoffId: h.handoffId, confirmationSide: side, confirmedAt: nowIso(), idempotencyKey: idempotencyKey() });
              onDone();
              return r.status === "confirmed" ? "Handoff complete — custody transferred." : "Confirmation recorded; waiting for the other party.";
            })
          }
        >
          Confirm handoff as {side}
        </button>
      )}
    </div>
  );
}

