export function StatusBadge({ status }: { status?: string }) {
  if (!status) return null;
  const tone = /exception|expired|cancel|unservice|declined|fail/i.test(status)
    ? "bad"
    : /received|completed|confirmed|delivered|sealed|accepted/i.test(status)
      ? "good"
      : /pending|offered|planned|created/i.test(status)
        ? "neutral"
        : "active";
  return <span className={`badge ${tone}`}>{status.replace(/_/g, " ")}</span>;
}

