:root {
  --bg: #f4f6f8;
  --panel: #ffffff;
  --border: #d9dee5;
  --text: #1a2330;
  --muted: #5d6b7c;
  --accent: #0b5fff;
  --accent-dark: #0847bf;
  --good: #137a3a;
  --bad: #b42318;
  --warn: #9a6700;
  --info: #0b5fff;
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  color: var(--text);
  background: var(--bg);
  font-size: 15px;
  line-height: 1.45;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
}

a {
  color: var(--accent);
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 1rem;
}

h2 {
  font-size: 1.1rem;
  margin: 0;
}

h3 {
  font-size: 1rem;
  margin: 0;
}

button {
  font: inherit;
  padding: 0.4rem 0.8rem;
  border-radius: 6px;
  border: 1px solid var(--accent);
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

button:hover:not(:disabled) {
  background: var(--accent-dark);
}

button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

button.chip {
  background: #eef2f7;
  color: var(--muted);
  border-color: var(--border);
  padding: 0.15rem 0.5rem;
  font-size: 0.8rem;
}

button.chip.on {
  background: #e3efff;
  color: var(--accent-dark);
  border-color: var(--accent);
}

input,
select,
textarea {
  font: inherit;
  padding: 0.4rem 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #fff;
  color: var(--text);
  min-width: 0;
  width: 100%;
}

fieldset {
  border: 1px solid var(--border);
  border-radius: 6px;
  margin: 0 0 0.75rem;
  padding: 0.5rem 0.75rem;
}

legend {
  color: var(--muted);
  font-size: 0.85rem;
  padding: 0 0.3rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.muted {
  color: var(--muted);
}

.centered {
  display: grid;
  place-items: center;
  min-height: 100vh;
}

.shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 0.6rem 1.25rem;
  background: #10203a;
  color: #fff;
}

.topbar .brand {
  color: #fff;
  font-weight: 700;
  text-decoration: none;
}

.topbar nav {
  display: flex;
  gap: 0.25rem;
  flex: 1;
  flex-wrap: wrap;
}

.topbar nav a {
  color: #cfe0ff;
  text-decoration: none;
  padding: 0.3rem 0.7rem;
  border-radius: 6px;
}

.topbar nav a[aria-current="page"] {
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
}

.session {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.session .user {
  color: #cfe0ff;
}

.role-select select {
  width: auto;
}

.session button {
  background: transparent;
  border-color: #cfe0ff;
}

.content {
  flex: 1;
  padding: 1.25rem;
  max-width: 1400px;
  width: 100%;
  margin: 0 auto;
}

.page {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.two-col {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(380px, 1fr));
  gap: 1rem;
  align-items: start;
}

.two-col > div {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.7rem 1rem;
  border-bottom: 1px solid var(--border);
}

.panel-actions {
  display: flex;
  gap: 0.5rem;
  align-items: center;
}

.panel-body {
  padding: 0.9rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.banner {
  padding: 0.6rem 0.9rem;
  border-radius: 8px;
  border: 1px solid;
}

.banner.error {
  background: #fdecea;
  border-color: #f5b5ad;
  color: var(--bad);
}

.banner.success {
  background: #e8f6ed;
  border-color: #a6dcb8;
  color: var(--good);
}

.banner.info {
  background: #e9f1ff;
  border-color: #b6cfff;
  color: var(--accent-dark);
}

.banner.warning {
  background: #fff6e0;
  border-color: #f2d58c;
  color: var(--warn);
}

.badge {
  display: inline-block;
  padding: 0.1rem 0.55rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: capitalize;
  background: #eef2f7;
  color: var(--muted);
}

.badge.good {
  background: #e3f5e9;
  color: var(--good);
}

.badge.bad {
  background: #fdecea;
  color: var(--bad);
}

.badge.active {
  background: #e3efff;
  color: var(--accent-dark);
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

caption {
  text-align: left;
  color: var(--muted);
  font-size: 0.8rem;
  padding-bottom: 0.3rem;
}

th,
td {
  text-align: left;
  padding: 0.45rem 0.5rem;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

th {
  color: var(--muted);
  font-weight: 600;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.kv {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 0.35rem 1rem;
  margin: 0;
}

.kv dt {
  color: var(--muted);
}

.kv dd {
  margin: 0;
  word-break: break-all;
}

.id {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.85em;
  background: #eef2f7;
  padding: 0 0.3rem;
  border-radius: 4px;
}

.timeline {
  list-style: none;
  margin: 0;
  padding: 0 0 0 1rem;
  border-left: 2px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.timeline li {
  position: relative;
  font-size: 0.9rem;
}

.timeline li::before {
  content: "";
  position: absolute;
  left: -1.42rem;
  top: 0.4rem;
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 50%;
  background: var(--accent);
}

.timeline li.failed::before {
  background: var(--bad);
}

.timeline time {
  color: var(--muted);
  font-size: 0.8rem;
  display: block;
}

.timeline .details {
  display: block;
  color: var(--muted);
  font-size: 0.78rem;
  word-break: break-all;
}

code.details {
  font-size: 0.75rem;
  word-break: break-all;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.form.inline-form {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  align-items: end;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.field-label {
  font-size: 0.85rem;
  color: var(--muted);
}

.hint {
  font-size: 0.78rem;
  color: var(--muted);
}

.form-actions {
  display: flex;
  gap: 0.5rem;
}

.check {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-right: 0.75rem;
}

.check input {
  width: auto;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}

.actions .field {
  flex-direction: row;
  align-items: center;
  gap: 0.4rem;
}

.work-card {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.8rem 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  background: #fbfcfe;
}

.work-card header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.work-forms {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 0.6rem;
}

.handoff-box {
  border: 1px dashed var(--accent);
  border-radius: 8px;
  padding: 0.6rem 0.8rem;
  background: #f3f7ff;
}

.handoff-box p {
  margin: 0 0 0.4rem;
}

details {
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 0.4rem 0.7rem;
  background: #fff;
}

details > summary {
  cursor: pointer;
