import { useEffect, useRef } from "react";
import maplibregl from "maplibre-gl";
import { Protocol } from "pmtiles";
import "maplibre-gl/dist/maplibre-gl.css";
import type { Coordinate, OpsConnection, OpsLocation, OpsSample, OpsWorker } from "../types";

let protocolRegistered = false;
function ensureProtocol() {
  if (protocolRegistered) return;
  const protocol = new Protocol();
  maplibregl.addProtocol("pmtiles", protocol.tile);
  protocolRegistered = true;
}

export interface MapRoute {
  id: string;
  coordinates: Coordinate[];
  color?: string;
}

interface Props {
  locations?: OpsLocation[];
  connections?: OpsConnection[];
  workers?: OpsWorker[];
  samples?: OpsSample[];
  routes?: MapRoute[];
  points?: { id: string; coordinate: Coordinate; label: string; color?: string }[];
  height?: number | string;
  onSelectLocation?: (id: string) => void;
  onSelectSample?: (id: string) => void;
}

const DEFAULT_CENTER: [number, number] = [77.5946, 12.9716];

export default function MapView({ locations = [], connections = [], workers = [], samples = [], routes = [], points = [], height = 420, onSelectLocation, onSelectSample }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);
  const readyRef = useRef(false);

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;
    ensureProtocol();
    const map = new maplibregl.Map({
      container: containerRef.current,
      style: "/map-assets/style.json",
      center: DEFAULT_CENTER,
      zoom: 11,
      attributionControl: false,
      // The supplied style uses root-relative sprite/glyph paths, which MapLibre rejects; anchor them to this origin.
      transformStyle: (_prev, next) => ({
        ...next,
        sprite: typeof next.sprite === "string" && next.sprite.startsWith("/") ? window.location.origin + next.sprite : next.sprite,
        glyphs: typeof next.glyphs === "string" && next.glyphs.startsWith("/") ? window.location.origin + next.glyphs : next.glyphs,
      }),
    });
    map.addControl(new maplibregl.AttributionControl({ compact: false }), "bottom-right");
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), "top-right");
    map.on("load", () => {
      readyRef.current = true;
      map.addSource("network-lines", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
      map.addLayer({
        id: "network-lines",
        type: "line",
        source: "network-lines",
        paint: {
          "line-color": ["get", "color"],
          "line-width": ["get", "width"],
          "line-opacity": ["get", "opacity"],
          "line-dasharray": [2, 1],
        },
      });
      map.addSource("coverage", { type: "geojson", data: { type: "FeatureCollection", features: [] } });
      map.addLayer({
        id: "coverage",
        type: "fill",
        source: "coverage",
        paint: { "fill-color": "#2563eb", "fill-opacity": 0.07 },
      });
      map.addLayer({
        id: "coverage-outline",
        type: "line",
        source: "coverage",
        paint: { "line-color": "#2563eb", "line-opacity": 0.35, "line-width": 1 },
      });
      map.fire("labsample:ready");
    });
    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
      readyRef.current = false;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const apply = () => {
      markersRef.current.forEach((m) => m.remove());
      markersRef.current = [];
      const bounds = new maplibregl.LngLatBounds();
      let any = false;
      const extend = (c?: Coordinate) => {
        if (!c) return;
        bounds.extend([c.longitude, c.latitude]);
        any = true;
      };
      const locById = new Map(locations.map((l) => [l.locationId, l]));
      const lineFeatures: any[] = [];
      for (const c of connections) {
        const a = locById.get(c.fromLocationId);
        const b = locById.get(c.toLocationId);
        if (!a || !b) continue;
        lineFeatures.push({
          type: "Feature",
          properties: { color: c.active ? (c.cooled ? "#0891b2" : "#64748b") : "#dc2626", width: 2, opacity: c.active ? 0.8 : 0.4 },
          geometry: {
            type: "LineString",
            coordinates: [
              [a.coordinate.longitude, a.coordinate.latitude],
              [b.coordinate.longitude, b.coordinate.latitude],
            ],
          },
        });
      }
      for (const r of routes) {
        if (r.coordinates.length < 2) continue;
        lineFeatures.push({
          type: "Feature",
          properties: { color: r.color ?? "#d97706", width: 4, opacity: 0.9 },
          geometry: { type: "LineString", coordinates: r.coordinates.map((c) => [c.longitude, c.latitude]) },
        });
        r.coordinates.forEach(extend);
      }
      (map.getSource("network-lines") as maplibregl.GeoJSONSource | undefined)?.setData({ type: "FeatureCollection", features: lineFeatures });
      const coverageFeatures = locations
        .filter((l) => l.active && l.functions?.collection_point)
        .map((l) => ({ type: "Feature", properties: {}, geometry: circlePolygon(l.coordinate, l.coverageKm || 5) }));
      (map.getSource("coverage") as maplibregl.GeoJSONSource | undefined)?.setData({ type: "FeatureCollection", features: coverageFeatures as any });

      for (const l of locations) {
        extend(l.coordinate);
        const el = document.createElement("button");
        el.type = "button";
        const fns = Object.entries(l.functions || {})
          .filter(([, v]) => v)
          .map(([k]) => k.replace("_", " "))
          .join(", ");
        el.className = `map-marker location ${l.active ? "" : "inactive"} ${l.functions?.laboratory ? "lab" : ""}`;
        el.setAttribute("aria-label", `Location ${l.name} (${fns || "no functions"})${l.active ? "" : ", inactive"}`);
        el.title = `${l.name} — ${fns}`;
        el.textContent = l.functions?.laboratory ? "L" : l.functions?.hub ? "H" : "C";
        el.onclick = () => onSelectLocation?.(l.locationId);
        markersRef.current.push(new maplibregl.Marker({ element: el }).setLngLat([l.coordinate.longitude, l.coordinate.latitude]).addTo(map));
      }
      for (const w of workers) {
        if (!w.latestLocation) continue;
        extend(w.latestLocation);
        const el = document.createElement("div");
        el.className = `map-marker worker ${w.locationStale ? "stale" : ""}`;
        const name = w.fullName || w.workerId.slice(0, 8);
        el.setAttribute("aria-label", `Worker ${name}${w.locationStale ? ", stale location" : ""}`);
        el.title = `${name}${w.locationStale ? " (stale)" : ""}`;
        el.textContent = "W";
        markersRef.current.push(new maplibregl.Marker({ element: el }).setLngLat([w.latestLocation.longitude, w.latestLocation.latitude]).addTo(map));
      }
      for (const s of samples) {
        const c = s.latestLocation ?? s.origin;
        if (!c) continue;
        extend(c);
        const el = document.createElement("button");
        el.type = "button";
        el.className = `map-marker sample ${s.locationStale ? "stale" : ""}`;
        el.setAttribute("aria-label", `Sample ${s.sampleId.slice(0, 8)} ${s.status}${s.locationStale ? ", stale location" : ""}`);
        el.title = `Sample ${s.sampleId.slice(0, 8)} — ${s.status}`;
        el.textContent = "S";
        el.onclick = () => onSelectSample?.(s.sampleId);
        markersRef.current.push(new maplibregl.Marker({ element: el }).setLngLat([c.longitude, c.latitude]).addTo(map));
      }
      for (const p of points) {
        extend(p.coordinate);
        const el = document.createElement("div");
        el.className = "map-marker point";
        if (p.color) el.style.background = p.color;
        el.setAttribute("aria-label", p.label);
        el.title = p.label;
        el.textContent = "•";
        markersRef.current.push(new maplibregl.Marker({ element: el }).setLngLat([p.coordinate.longitude, p.coordinate.latitude]).addTo(map));
      }
      if (any) {
        try {
          map.fitBounds(bounds, { padding: 48, maxZoom: 13, duration: 0 });
        } catch {
          /* ignore degenerate bounds */
        }
      }
    };
    if (readyRef.current) apply();
    else map.once("labsample:ready", apply);
  }, [locations, connections, workers, samples, routes, points]);

  return (
    <div className="map-wrap" style={{ height }}>
      <div ref={containerRef} className="map-container" role="region" aria-label="Live map" />
      <div className="map-legend" aria-label="Map legend">
        <span><i className="map-marker location">C</i> Collection / transfer point</span>
        <span><i className="map-marker location">H</i> Hub</span>
        <span><i className="map-marker location lab">L</i> Laboratory</span>
        <span><i className="map-marker worker">W</i> Worker</span>
        <span><i className="map-marker sample">S</i> Sample</span>
      </div>
    </div>
  );
}

function circlePolygon(center: Coordinate, km: number, steps = 48) {
  const coords: [number, number][] = [];
  const latR = km / 110.574;
  const lonR = km / (111.32 * Math.cos((center.latitude * Math.PI) / 180));
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * Math.PI * 2;
    coords.push([center.longitude + lonR * Math.cos(t), center.latitude + latR * Math.sin(t)]);
  }
  return { type: "Polygon", coordinates: [coords] };
}

