      for (const c of connections) {
        const a = locById.get(c.fromLocationId);
        const b = locById.get(c.toLocationId);
        if (!a || !b) continue;
        lineFeatures.push({
          type: "Feature",
          properties: { color: c.active ? (c.cooled ? "#0891b2" : "#64748b") : "#dc2626", width: 2, opacity: c.active ? 0.8 : 0.4 },
          geometry: {
            type: "LineString",
            coordinates: [
              [a.coordinate.longitude, a.coordinate.latitude],
              [b.coordinate.longitude, b.coordinate.latitude],
